/**
 * Convierte una firma a PNG transparente, removiendo fondo claro automáticamente.
 * Está optimizado para firmas oscuras sobre fondo blanco.
 */
async function convertirFirmaAPngSinFondo(bufferEntrada) {
    const { data, info } = await sharp(bufferEntrada)
        .rotate()
        .ensureAlpha()
        .raw()
        .toBuffer({ resolveWithObject: true });

    const pixeles = Buffer.from(data);
    const total = pixeles.length;

    for (let i = 0; i < total; i += 4) {
        const r = pixeles[i];
        const g = pixeles[i + 1];
        const b = pixeles[i + 2];
        const alphaOriginal = pixeles[i + 3];

        const max = Math.max(r, g, b);
        const min = Math.min(r, g, b);
        const saturacion = max - min;
        const luminancia = 0.2126 * r + 0.7152 * g + 0.0722 * b;

        // Fondo casi blanco o gris muy claro: hacerlo transparente.
        if (luminancia > 242 && saturacion < 22) {
            pixeles[i + 3] = 0;
            continue;
        }

        // Borde suavizado para evitar halo blanco.
        if (luminancia > 220 && saturacion < 28) {
            const factor = Math.max(0, Math.min(1, (242 - luminancia) / 22));
            pixeles[i + 3] = Math.round(alphaOriginal * factor);
        }
    }

    return sharp(pixeles, {
        raw: {
            width: info.width,
            height: info.height,
            channels: 4
        }
    })
        .png({ compressionLevel: 9, quality: 100 })
        .toBuffer();
}

/**
 * Normaliza la firma para DC-3 respetando PNG + color original.
 * Solo limpia fondo claro y halos semitransparentes que pueden ensuciarse al exportar PDF en Drive.
 */
async function normalizarFirmaParaDc3(bufferEntrada) {
    const { data, info } = await sharp(bufferEntrada)
        .rotate()
        .ensureAlpha()
        .raw()
        .toBuffer({ resolveWithObject: true });

    const pixeles = Buffer.from(data);
    const total = pixeles.length;

    for (let i = 0; i < total; i += 4) {
        const r = pixeles[i];
        const g = pixeles[i + 1];
        const b = pixeles[i + 2];
        const a = pixeles[i + 3];

        // Píxeles totalmente transparentes: forzar RGB blanco para evitar cajas oscuras en renderizadores problemáticos.
        if (a <= 4) {
            pixeles[i] = 255;
            pixeles[i + 1] = 255;
            pixeles[i + 2] = 255;
            pixeles[i + 3] = 0;
            continue;
        }

        const max = Math.max(r, g, b);
        const min = Math.min(r, g, b);
        const saturacion = max - min;
        const luminancia = 0.2126 * r + 0.7152 * g + 0.0722 * b;

        // Fondo blanco/gris muy claro: hacerlo transparente.
        if (luminancia > 246 && saturacion < 18) {
            pixeles[i] = 255;
            pixeles[i + 1] = 255;
            pixeles[i + 2] = 255;
            pixeles[i + 3] = 0;
            continue;
        }

        // Halos de borde: blanquear RGB progresivamente en alfa bajo, preservando color de trazos sólidos.
        if (a < 96) {
            const blend = (96 - a) / 96; // 0..1
            pixeles[i] = Math.round(r + (255 - r) * blend);
            pixeles[i + 1] = Math.round(g + (255 - g) * blend);
            pixeles[i + 2] = Math.round(b + (255 - b) * blend);
        }
    }

    return sharp(pixeles, {
        raw: {
            width: info.width,
            height: info.height,
            channels: 4
        }
    })
        .png({ compressionLevel: 9, adaptiveFiltering: true })
        .toBuffer();
}

async function prepararFirmaInformeFinalParaExportPdf(bufferEntrada) {
    const { data, info } = await sharp(bufferEntrada)
        .rotate()
        .ensureAlpha()
        .raw()
        .toBuffer({ resolveWithObject: true });

    const pixeles = Buffer.from(data);
    const total = pixeles.length;

    for (let i = 0; i < total; i += 4) {
        const r = pixeles[i];
        const g = pixeles[i + 1];
        const b = pixeles[i + 2];
        const a = pixeles[i + 3];

        if (a <= 2) {
            pixeles[i] = 255;
            pixeles[i + 1] = 255;
            pixeles[i + 2] = 255;
            pixeles[i + 3] = 0;
            continue;
        }

        if (a < 96) {
            const blend = (96 - a) / 96;
            pixeles[i] = Math.round(r + (255 - r) * blend);
            pixeles[i + 1] = Math.round(g + (255 - g) * blend);
            pixeles[i + 2] = Math.round(b + (255 - b) * blend);
        }
    }

    return await sharp(pixeles, {
        raw: {
            width: info.width,
            height: info.height,
            channels: 4
        }
    })
        .png({ compressionLevel: 9, adaptiveFiltering: true })
        .toBuffer();
}

