/**
 * Resuelve la carpeta de Drive de un curso programado.
 * Primero busca el ID almacenado en BD (drive_folder_id).
 * Si no existe, la crea usando fecha_inicio y guarda el ID para uso futuro.
 * Esto garantiza que todos los archivos de un curso vayan siempre a la misma carpeta,
 * organizada por año/mes según la fecha de inicio real del curso.
 */
async function resolverCarpetaCursoProgramado(programadoId) {
    const [rows] = await pool.query(
        `SELECT cp.drive_folder_id, cp.fecha_inicio, c.nombre_curso, e.nombre_empresa
         FROM curso_programado cp
         JOIN curso c ON c.curso_id = cp.curso_id
         JOIN empresa e ON e.empresa_id = cp.empresa_id
         WHERE cp.programado_id = ?
         LIMIT 1`,
        [programadoId]
    );

    if (!rows.length) {
        return { success: false, error: 'Curso programado no encontrado' };
    }

    const { drive_folder_id, fecha_inicio, nombre_curso, nombre_empresa } = rows[0];

    // Si ya tenemos el ID guardado, usarlo directamente
    if (drive_folder_id && esDriveIdValido(drive_folder_id)) {
        return { success: true, folderId: drive_folder_id };
    }

    // Crear usando fecha_inicio para organización correcta por año/mes
    const carpetaResult = await driveService.crearCarpetaCapacitacion(nombre_empresa, nombre_curso, fecha_inicio);
    if (!carpetaResult.success) return carpetaResult;

    // Guardar para uso futuro
    await pool.query(
        'UPDATE curso_programado SET drive_folder_id = ? WHERE programado_id = ?',
        [carpetaResult.folderId, programadoId]
    );

    return { success: true, folderId: carpetaResult.folderId, path: carpetaResult.path };
}

function sanitizarSegmentoNombre(valor, fallback = 'sin_nombre') {
    const limpio = String(valor || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-zA-Z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '')
        .replace(/_+/g, '_');
    return limpio || fallback;
}

function esDriveIdValido(valor) {
    return !!valor && !String(valor).includes('/') && !String(valor).includes('\\');
}

function formatearFechaISO(fecha) {
    const d = new Date(fecha);
    if (Number.isNaN(d.getTime())) return new Date().toISOString().split('T')[0];
    return d.toISOString().split('T')[0];
}

function parseBoolDb(value, defaultValue = null) {
    if (value === undefined || value === null || value === '') return defaultValue;
    if (typeof value === 'boolean') return value ? 1 : 0;
    if (typeof value === 'number') return value > 0 ? 1 : 0;
    const normalized = String(value).trim().toLowerCase();
    if (['1', 'true', 'si', 'sí', 'on', 'yes'].includes(normalized)) return 1;
    if (['0', 'false', 'no', 'off'].includes(normalized)) return 0;
    return defaultValue;
}

function normalizarNombreDocumentoBasico(valor = '') {
    return String(valor || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, '_')
        .replace(/_+/g, '_')
        .replace(/^_|_$/g, '');
}

function obtenerClaveDocumentoBasico(nombre = '') {
    const nombreBase = normalizarNombreDocumentoBasico(nombre);
    const esEvaluacionOExamen = nombreBase.includes('evaluacion') || nombreBase.includes('examen');

    if (!esEvaluacionOExamen) {
        return null;
    }

    if (nombreBase.includes('diagnostico')) {
        return 'diagnostico';
    }

    if (nombreBase.includes('final')) {
        return 'final';
    }

    return null;
}

async function construirMapaBasicosPorCurso(cursosIds = []) {
    const mapa = new Map();
    if (!Array.isArray(cursosIds) || !cursosIds.length) {
        return mapa;
    }

    const [documentos] = await pool.query(
        `SELECT curso_id, nombre
         FROM documento_curso
         WHERE activo = TRUE AND curso_id IN (?)`,
        [cursosIds]
    );

    for (const doc of documentos) {
        const clave = obtenerClaveDocumentoBasico(doc.nombre);
        if (!clave) continue;
        mapa.set(`${doc.curso_id}:${clave}`, true);
    }

    return mapa;
}

function fetchJsonHttps(url) {
    return new Promise((resolve, reject) => {
        https
            .get(url, (response) => {
                let rawData = '';

                response.on('data', (chunk) => {
                    rawData += chunk;
                });

                response.on('end', () => {
                    if (response.statusCode && response.statusCode >= 400) {
                        return reject(new Error(`HTTP ${response.statusCode}`));
                    }

                    try {
                        const parsed = JSON.parse(rawData || '{}');
                        resolve(parsed);
                    } catch (parseError) {
                        reject(parseError);
                    }
                });
            })
            .on('error', (error) => reject(error));
    });
}

function construirNombreDocProgramado({ nombreEmpresa, nombreCurso, fechaInicio, tipoBase, extension = 'pdf', indice = null }) {
    const empresa = sanitizarSegmentoNombre(nombreEmpresa, 'empresa');
    const curso = sanitizarSegmentoNombre(nombreCurso, 'curso');
    const fecha = sanitizarSegmentoNombre(formatearFechaISO(fechaInicio), 'fecha');
    const tipo = sanitizarSegmentoNombre(tipoBase, 'documento');
    const ext = sanitizarSegmentoNombre(extension.toLowerCase(), 'pdf');
    const sufijoIndice = Number.isInteger(indice) ? `_${String(indice).padStart(2, '0')}` : '';
    return `${empresa}_${curso}_${fecha}_${tipo}${sufijoIndice}.${ext}`;
}

function resolverSubcarpetaDocumentoProgramado(tipoDocumento, descripcion) {
    const texto = `${tipoDocumento || ''} ${descripcion || ''}`.toLowerCase();
    if (texto.includes('entrega_documentos') || texto.includes('sp-f-03') || texto.includes('spf03')) {
        return 'Acuse';
    }
    return null;
}

async function combinarPdfs(buffers = []) {
    const buffersValidos = (Array.isArray(buffers) ? buffers : []).filter((b) => Buffer.isBuffer(b) && b.length > 0);
    if (buffersValidos.length === 0) {
        throw new Error('No hay PDFs válidos para combinar.');
    }

    const { PDFDocument } = require('pdf-lib');
    const mergedPdf = await PDFDocument.create();

    for (const buffer of buffersValidos) {
        const sourcePdf = await PDFDocument.load(buffer, { ignoreEncryption: true });
        const pageIndexes = sourcePdf.getPageIndices();
        if (pageIndexes.length === 0) continue;

        const pages = await mergedPdf.copyPages(sourcePdf, pageIndexes);
        pages.forEach((page) => mergedPdf.addPage(page));
    }

    if (mergedPdf.getPageCount() === 0) {
        throw new Error('No se pudieron combinar páginas PDF.');
    }

    const output = await mergedPdf.save();
    return Buffer.from(output);
}

async function sincronizarDocumentosProgramadoConDrive(programadoId) {
    const [docs] = await pool.query(
        `SELECT documento_prog_id, drive_file_id, nombre_archivo
         FROM documento_curso_programado
         WHERE programado_id = ? AND drive_file_id IS NOT NULL AND drive_file_id != ''`,
        [programadoId]
    );

    if (docs.length === 0) {
        return { verificados: 0, eliminados: 0, archivosEliminados: [] };
    }

    const idsValidos = docs.map(d => d.drive_file_id).filter(esDriveIdValido);
    const existencia = await driveService.verificarArchivosLote(idsValidos);
    const eliminados = [];

    for (const doc of docs) {
        const debeEliminar = !esDriveIdValido(doc.drive_file_id)
            || existencia.get(doc.drive_file_id) === false;

        if (debeEliminar) {
            await pool.query(
                'DELETE FROM documento_curso_programado WHERE documento_prog_id = ?',
                [doc.documento_prog_id]
            );
            eliminados.push(doc.nombre_archivo);
        }
    }

    return {
        verificados: docs.length,
        eliminados: eliminados.length,
        archivosEliminados: eliminados
    };
}

async function eliminarDocsProgramadoPorFiltro(programadoId, whereSql, params = []) {
    const filtroNormalizado = String(whereSql || '').trim().replace(/\s+/g, ' ');
    if (filtroNormalizado !== 'descripcion = ?') {
        throw new Error('Filtro no permitido en eliminarDocsProgramadoPorFiltro');
    }
    if (!Array.isArray(params) || params.length !== 1) {
        throw new Error('Parámetros inválidos para eliminarDocsProgramadoPorFiltro');
    }

    const descripcion = params[0];
    const [docs] = await pool.query(
        `SELECT documento_prog_id, drive_file_id, nombre_archivo
         FROM documento_curso_programado
         WHERE programado_id = ? AND descripcion = ?`,
        [programadoId, descripcion]
    );

    for (const doc of docs) {
        if (esDriveIdValido(doc.drive_file_id)) {
            try {
                await driveService.eliminarArchivo(doc.drive_file_id);
            } catch (e) {
                // silenced
            }
        }
    }

    await pool.query(
        'DELETE FROM documento_curso_programado WHERE programado_id = ? AND descripcion = ?',
        [programadoId, descripcion]
    );

    return docs.length;
}

const ESTATUS_CURSO_NO_FINALIZADOS = ['programado', 'en_curso', 'pospuesto', 'cancelado'];
const ESTATUS_CURSO_FINALIZADOS = ['completado', 'finalizado', 'cerrado', 'terminado'];

function sqlCursoProgramadoImpartido(alias = 'cp') {
    const noFinal = ESTATUS_CURSO_NO_FINALIZADOS.map((s) => `'${s}'`).join(', ');
    const finalizados = ESTATUS_CURSO_FINALIZADOS.map((s) => `'${s}'`).join(', ');
    return `(
        LOWER(TRIM(COALESCE(${alias}.estatus, ''))) IN (${finalizados})
        OR (
            LOWER(TRIM(COALESCE(${alias}.estatus, ''))) NOT IN (${noFinal})
            AND DATE(COALESCE(${alias}.fecha_fin, ${alias}.fecha_inicio)) <= CURDATE()
        )
    )`;
}

async function armarHistorialProgramadosConDocumentos(rows = []) {
    const historial = [];
    for (const row of rows) {
        const [docs] = await pool.query(
            `SELECT documento_prog_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion, fecha_subida
             FROM documento_curso_programado
             WHERE programado_id = ?
             ORDER BY tipo_documento, fecha_subida DESC`,
            [row.programado_id]
        );
        historial.push({
            ...row,
            documentos: docs
        });
    }
    return historial;
}

