app.disable('x-powered-by');

// Confiar en proxies reversos (Tailscale Funnel, nginx, etc.)
app.set('trust proxy', 1);

// =====================================================
// MIDDLEWARE
// =====================================================
const corsOrigins = process.env.CORS_ORIGINS
    ? process.env.CORS_ORIGINS.split(',').map(s => s.trim())
    : ['http://localhost:4200', 'http://localhost:4201'];
if (!process.env.CORS_ORIGINS) {
    // CORS_ORIGINS not set, using localhost defaults
}
// Chrome Private Network Access (PNA): permite requests desde sitios públicos
// hacia el backend expuesto via Tailscale Funnel.
// DEBE ir ANTES de cors() para que el preflight OPTIONS reciba el header.
app.use((req, res, next) => {
    res.setHeader('Access-Control-Allow-Private-Network', 'true');
    next();
});

// Cabeceras anti-clickjacking.
// Evita que sitios externos incrusten esta app en iframes/marcos maliciosos.
app.use((req, res, next) => {
    const esPreviewEmbebible = /^\/api\/drive-preview\/[a-zA-Z0-9_-]+$/.test(req.path);
    if (!esPreviewEmbebible) {
        res.setHeader('X-Frame-Options', 'DENY');
        res.setHeader('Content-Security-Policy', "frame-ancestors 'none';");
    }
    // Prevenir MIME sniffing
    res.setHeader('X-Content-Type-Options', 'nosniff');
    // Referrer policy
    res.setHeader('Referrer-Policy', 'strict-origin-when-cross-origin');
    // DNS prefetch control
    res.setHeader('X-DNS-Prefetch-Control', 'off');
    // Permissions policy
    res.setHeader('Permissions-Policy', 'camera=(), microphone=(), geolocation=()');
    // HSTS: forzar HTTPS por 1 año (incluye subdominios)
    res.setHeader('Strict-Transport-Security', 'max-age=31536000; includeSubDomains');
    // Evitar que Adobe Flash/Acrobat carguen contenido cross-domain
    res.setHeader('X-Permitted-Cross-Domain-Policies', 'none');
    // Cache-Control: las respuestas API no deben cachearse
    res.setHeader('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
    res.setHeader('Pragma', 'no-cache');
    res.setHeader('Expires', '0');
    next();
});

