// =====================================================
// CONFIGURACIÓN DE BASE DE DATOS (Local y Remota)
// =====================================================
const dbConfig = {
    local: {
        host: process.env.DB_HOST_LOCAL,
        port: Number(process.env.DB_PORT_LOCAL || process.env.DB_PORT)
    },
    lan: {
        host: process.env.DB_HOST_LAN,
        port: Number(process.env.DB_PORT_LAN || process.env.DB_PORT_LOCAL || process.env.DB_PORT)
    },
    remote: {
        host: process.env.DB_HOST_REMOTE,
        port: Number(process.env.DB_PORT_REMOTE || process.env.DB_PORT)
    },
    user: process.env.DB_USER,
    password: process.env.DB_PASS,
    database: process.env.DB_NAME
};

const poolReinitHandlers = {};

function createMysqlPool(config, { database, connectionLimit = 10, label = 'pool', poolKey, getPool }) {
    const poolInstance = mysql.createPool(buildMysqlPoolOptions({
        host: config.host,
        port: config.port,
        user: dbConfig.user,
        password: dbConfig.password,
        database,
        connectionLimit
    }));

    if (typeof poolInstance.on === 'function') {
        poolInstance.on('error', (err) => {
            console.warn(`[DB] ${label}:`, err?.code || err?.message || err);
        });
    }

    return wrapPoolWithRetry(poolInstance, {
        getPool,
        label,
        reinit: (code) => {
            const handler = poolReinitHandlers[poolKey];
            return handler ? handler(code) : Promise.resolve();
        }
    });
}

async function verificarPool(poolInstance) {
    const conn = await poolInstance.getConnection();
    conn.release();
}

async function cerrarPoolAnterior(poolAnterior) {
    if (poolAnterior && typeof poolAnterior.end === 'function') {
        try {
            await poolAnterior.end();
        } catch (_e) {
            // silenced
        }
    }
}

function probarPuertoTcp(host, port, timeoutMs = 5000) {
    const net = require('net');
    return new Promise((resolve) => {
        if (!host || !Number.isFinite(port) || port <= 0) {
            resolve(false);
            return;
        }

        const socket = new net.Socket();
        let settled = false;

        const finish = (ok) => {
            if (settled) return;
            settled = true;
            try { socket.destroy(); } catch (_e) { /* ignore */ }
            resolve(ok);
        };

        socket.setTimeout(timeoutMs);
        socket.once('connect', () => finish(true));
        socket.once('timeout', () => finish(false));
        socket.once('error', () => finish(false));
        try {
            socket.connect(port, host);
        } catch (_e) {
            finish(false);
        }
    });
}

/**
 * Verifica que el MySQL acepte usuario/contraseña del .env.
 * Evita quedarse en un MySQL ajeno en localhost:3306 (puerto abierto pero Access denied).
 */
async function probarMysqlAuth(host, port, timeoutMs = 5000) {
    if (!host || !Number.isFinite(port) || port <= 0) return false;
    const tcpOk = await probarPuertoTcp(host, port, Math.min(timeoutMs, 3000));
    if (!tcpOk) return false;

    let conn = null;
    try {
        conn = await mysql.createConnection({
            host,
            port,
            user: dbConfig.user,
            password: dbConfig.password,
            connectTimeout: timeoutMs
        });
        await conn.query('SELECT 1');
        return true;
    } catch (_err) {
        return false;
    } finally {
        if (conn) {
            try { await conn.end(); } catch (_e) { /* ignore */ }
        }
    }
}

let localNetworkProbe = null;
/** 'local' | 'lan' | 'remote' — resultado de las dos variables DB_HOST_LOCAL / DB_HOST_LAN */
let mysqlDestinoTipo = 'remote';

/**
 * Detecta MySQL una sola vez y reutiliza el resultado en todos los pools.
 * 1) DB_HOST_LOCAL (esta PC / Docker local) con login válido
 * 2) DB_HOST_LAN (contenedor en otra PC de la misma red) con login válido
 * Si ambas fallan, el arranque usa DB_HOST_REMOTE.
 */
async function isLocalNetwork() {
    if (!localNetworkProbe) {
        localNetworkProbe = (async () => {
            const port = Number(dbConfig.local.port || 3306);
            const candidatos = [...new Set([
                dbConfig.local.host,
                '127.0.0.1',
                'localhost'
            ].filter(Boolean))];

            for (const host of candidatos) {
                const ok = await probarMysqlAuth(host, port, 5000);
                if (ok) {
                    if (host !== dbConfig.local.host) {
                        dbConfig.local.host = host;
                    }
                    mysqlDestinoTipo = 'local';
                    return true;
                }
            }

            const lanHost = dbConfig.lan.host && String(dbConfig.lan.host).trim();
            const lanPort = Number(dbConfig.lan.port || port);
            if (lanHost) {
                const okLan = await probarMysqlAuth(lanHost, lanPort, 5000);
                if (okLan) {
                    dbConfig.local.host = lanHost;
                    dbConfig.local.port = lanPort;
                    mysqlDestinoTipo = 'lan';
                    return true;
                }
                console.warn(
                    `  MySQL del contenedor LAN no aceptó login en ${lanHost}:${lanPort} ` +
                    `(usuario ${dbConfig.user}).`
                );
            }

            console.warn(
                `  MySQL local no aceptó login en ${candidatos.join(' / ')}:${port}` +
                (lanHost ? ` ni en LAN ${lanHost}:${lanPort}` : '') +
                ` con ${dbConfig.user}. Se usará el host remoto.`
            );
            mysqlDestinoTipo = 'remote';
            return false;
        })();
    }
    return localNetworkProbe;
}

function esperarMs(ms) {
    return new Promise((resolve) => setTimeout(resolve, ms));
}

async function intentarConexionMysql(config, {
    database,
    connectionLimit,
    label,
    poolKey,
    bootstrapDb,
    getPool,
    etiquetaOk
}) {
    let bootstrapConn = null;
    let poolInstance = null;

    try {
        if (bootstrapDb && process.env.NODE_ENV !== 'production') {
            bootstrapConn = await mysql.createConnection({
                host: config.host,
                port: config.port,
                user: dbConfig.user,
                password: dbConfig.password,
                connectTimeout: 15000
            });
            await bootstrapConn.query(
                `CREATE DATABASE IF NOT EXISTS \`${database}\` CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci`
            );
            await bootstrapConn.end();
            bootstrapConn = null;
        }

        poolInstance = createMysqlPool(config, {
            database,
            connectionLimit,
            label,
            poolKey,
            getPool
        });
        await verificarPool(poolInstance);
        startupLog.dbOk(database);
        return poolInstance;
    } catch (err) {
        if (bootstrapConn) {
            try { await bootstrapConn.end(); } catch (_e) { /* ignore */ }
        }
        await cerrarPoolAnterior(poolInstance);
        throw err;
    }
}

async function conectarPool(isLocal, {
    database,
    connectionLimit = 10,
    label,
    poolKey,
    bootstrapDb = false,
    getPool,
    allowRemoteFallback
}) {
    const permitirRemoto = allowRemoteFallback === true
        || (allowRemoteFallback !== false && String(process.env.DB_ALLOW_REMOTE_FALLBACK || '').toLowerCase() === 'true');
    const intentosLocales = isLocal ? 4 : 1;
    let ultimoError = null;

    for (let intento = 1; intento <= intentosLocales; intento++) {
        const config = isLocal ? dbConfig.local : dbConfig.remote;
        const etiquetaOk = isLocal
            ? `MySQL ${database} conectado`
            : `MySQL ${database} conectado (remoto)`;
        try {
            return await intentarConexionMysql(config, {
                database,
                connectionLimit,
                label,
                poolKey,
                bootstrapDb,
                getPool,
                etiquetaOk
            });
        } catch (err) {
            ultimoError = err;
            startupLog.detail(
                `  MySQL ${database}${intento > 1 ? ` (intento ${intento}/${intentosLocales})` : ''}: ${err.message}`
            );
            if (intento < intentosLocales) {
                await esperarMs(1500 * intento);
            }
        }
    }

    if (isLocal && permitirRemoto) {
        startupLog.detail(`  Reintentando ${database} remoto...`);
        try {
            return await intentarConexionMysql(dbConfig.remote, {
                database,
                connectionLimit,
                label,
                poolKey,
                bootstrapDb: false,
                getPool,
                etiquetaOk: `MySQL ${database} conectado (remoto)`
            });
        } catch (err) {
            startupLog.dbFail(database, err);
            throw err;
        }
    }

    startupLog.dbFail(database, ultimoError);
    throw ultimoError;
}

function registrarFalloPool(promesa, etiqueta) {
    promesa.catch((err) => {
        startupLog.detail(`  [ERROR] ${etiqueta}: ${err.message}`);
    });
    return promesa;
}

