// POOL DE CONEXIONES MySQL
// =====================================================
let pool;
let isOnLocalNetwork = false; // Se actualiza al inicializar el pool

async function initializePool() {
    const isLocal = await isLocalNetwork();
    isOnLocalNetwork = isLocal;

    const cfg = isLocal ? dbConfig.local : dbConfig.remote;
    const etiquetaDestino = mysqlDestinoTipo === 'lan'
        ? 'contenedor LAN'
        : (isLocal ? 'local' : 'remota');
    startupLog.setMysqlInfo(`${etiquetaDestino} ${cfg.host}:${cfg.port}`);

    pool = await conectarPool(isLocal, {
        database: dbConfig.database,
        connectionLimit: 10,
        label: 'biznaga',
        poolKey: 'main',
        getPool: () => pool
    });
}

const poolReady = registrarFalloPool(initializePool(), 'Pool principal no disponible');

async function exigirPoolPrincipal() {
    try {
        await poolReady;
    } catch (_e) {
        // silenced
    }
    if (!pool || typeof pool.query !== 'function') {
        const err = new Error(
            'MySQL no está disponible. Confirme Docker local (127.0.0.1:3306) o DB_HOST_LAN en backend/.env.'
        );
        err.statusCode = 503;
        throw err;
    }
    return pool;
}

let poolReinitPromise = null;

async function reinicializarPoolPrincipal(motivo = '') {
    if (poolReinitPromise) {
        return poolReinitPromise;
    }

    poolReinitPromise = (async () => {
        const poolAnterior = pool;
        const motivoTxt = motivo ? ` (${motivo})` : '';
        console.warn(`[DB] Reinicializando pool principal${motivoTxt}...`);

        pool = await conectarPool(isOnLocalNetwork, {
            database: dbConfig.database,
            connectionLimit: 10,
            label: 'biznaga',
            poolKey: 'main',
            getPool: () => pool,
            allowRemoteFallback: false
        });
        await cerrarPoolAnterior(poolAnterior);
    })().finally(() => {
        poolReinitPromise = null;
    });

    return poolReinitPromise;
}

poolReinitHandlers.main = reinicializarPoolPrincipal;

async function queryMain(sql, params = [], options = {}) {
    await exigirPoolPrincipal();
    return pool.query(sql, params);
}

function esErrorColumnaUsarPuestoRealDc3(error) {
    if (!error) return false;
    const mensaje = `${error.sqlMessage || error.message || ''}`;
    return error.code === 'ER_BAD_FIELD_ERROR' && mensaje.includes('usar_puesto_real_dc3');
}

async function obtenerCursosProgramadosConFlagDc3Seguro() {
    await exigirPoolPrincipal();
    const sqlConColumna = `
                SELECT v.*,
                       cp.pasos_completados,
                       cp.usar_puesto_real_dc3,
                       COALESCE(dcp_spf03.tiene_entrega_documentos, 0) AS tiene_entrega_documentos,
                       COALESCE((SELECT COUNT(*) FROM inscripcion_curso ic WHERE ic.programado_id = v.programado_id), 0) as inscritos
                FROM v_cursos_programados v
                INNER JOIN curso_programado cp ON cp.programado_id = v.programado_id
                LEFT JOIN (
                    SELECT programado_id, 1 AS tiene_entrega_documentos
                    FROM documento_curso_programado
                    WHERE descripcion = 'entrega_documentos_spf03_firmado'
                       OR descripcion LIKE 'entrega_documentos_spf03%'
                       OR tipo_documento = 'entrega_documentos'
                       OR LOWER(nombre_archivo) LIKE '%sp-f-03%'
                       OR LOWER(nombre_archivo) LIKE '%sp_f_03%'
                       OR LOWER(nombre_archivo) LIKE '%sp f 03%'
                       OR LOWER(nombre_archivo) LIKE '%spf03%'
                       OR LOWER(descripcion) LIKE '%sp-f-03%'
                       OR LOWER(descripcion) LIKE '%sp_f_03%'
                       OR LOWER(descripcion) LIKE '%sp f 03%'
                       OR LOWER(descripcion) LIKE '%spf03%'
                       OR LOWER(descripcion) LIKE '%entrega_documentos%'
                    GROUP BY programado_id
                ) dcp_spf03 ON dcp_spf03.programado_id = v.programado_id
                ORDER BY v.fecha_inicio DESC
            `;

    const sqlSinColumna = `
                SELECT v.*,
                       cp.pasos_completados,
                       0 AS usar_puesto_real_dc3,
                       COALESCE(dcp_spf03.tiene_entrega_documentos, 0) AS tiene_entrega_documentos,
                       COALESCE((SELECT COUNT(*) FROM inscripcion_curso ic WHERE ic.programado_id = v.programado_id), 0) as inscritos
                FROM v_cursos_programados v
                INNER JOIN curso_programado cp ON cp.programado_id = v.programado_id
                LEFT JOIN (
                    SELECT programado_id, 1 AS tiene_entrega_documentos
                    FROM documento_curso_programado
                    WHERE descripcion = 'entrega_documentos_spf03_firmado'
                       OR descripcion LIKE 'entrega_documentos_spf03%'
                       OR tipo_documento = 'entrega_documentos'
                       OR LOWER(nombre_archivo) LIKE '%sp-f-03%'
                       OR LOWER(nombre_archivo) LIKE '%sp_f_03%'
                       OR LOWER(nombre_archivo) LIKE '%sp f 03%'
                       OR LOWER(nombre_archivo) LIKE '%spf03%'
                       OR LOWER(descripcion) LIKE '%sp-f-03%'
                       OR LOWER(descripcion) LIKE '%sp_f_03%'
                       OR LOWER(descripcion) LIKE '%sp f 03%'
                       OR LOWER(descripcion) LIKE '%spf03%'
                       OR LOWER(descripcion) LIKE '%entrega_documentos%'
                    GROUP BY programado_id
                ) dcp_spf03 ON dcp_spf03.programado_id = v.programado_id
                ORDER BY v.fecha_inicio DESC
            `;

    try {
        const [rows] = await pool.query(sqlConColumna);
        return rows;
    } catch (error) {
        if (!esErrorColumnaUsarPuestoRealDc3(error)) {
            throw error;
        }
        const [rows] = await pool.query(sqlSinColumna);
        return rows;
    }
}

