async function iniciarKeepAliveDbPools() {
    const pools = [
        { getPool: () => pool, ready: poolReady },
        { getPool: () => poolMedicos, ready: poolMedicosReady },
        { getPool: () => poolProteccionCivil, ready: poolProteccionCivilReady },
        { getPool: () => poolBiznagaSgc, ready: poolBiznagaSgcReady },
        { getPool: () => poolSensores, ready: poolSensoresReady },
        { getPool: () => poolNormativas, ready: poolNormativasReady }
    ];

    setInterval(async () => {
        for (const { getPool, ready } of pools) {
            try {
                await ready;
                const dbPool = getPool();
                if (dbPool?.query) {
                    await dbPool.query('SELECT 1');
                }
            } catch (_e) {
                // El wrapper con retry se encarga de reconectar.
            }
        }
    }, 4 * 60 * 1000);
}

iniciarKeepAliveDbPools();

/** Compatible con MySQL estándar (MariaDB admite ADD COLUMN IF NOT EXISTS en ALTER). */
async function columnExists(dbPool, tableName, columnName) {
    const [rows] = await dbPool.query(
        `SELECT 1 FROM information_schema.COLUMNS
         WHERE TABLE_SCHEMA = DATABASE() AND TABLE_NAME = ? AND COLUMN_NAME = ?
         LIMIT 1`,
        [tableName, columnName]
    );
    return rows.length > 0;
}

async function addColumnIfNotExists(dbPool, tableName, columnName, columnDef) {
    if (await columnExists(dbPool, tableName, columnName)) return false;
    await dbPool.query(`ALTER TABLE \`${tableName}\` ADD COLUMN \`${columnName}\` ${columnDef}`);
    return true;
}

async function dropColumnIfExists(dbPool, tableName, columnName) {
    if (!(await columnExists(dbPool, tableName, columnName))) return false;
    await dbPool.query(`ALTER TABLE \`${tableName}\` DROP COLUMN \`${columnName}\``);
    return true;
}

const CATEGORIAS_PC_CATALOGO = [
    { slug: 'pipc', nombre: '1. Programa Interno de Protección Civil (PIPC)', orden: 1 },
    { slug: 'opinion_tecnica', nombre: '2. Opinión Técnica', orden: 2 },
    { slug: 'uso_suelo', nombre: '3. Uso de Suelo', orden: 3 }
];

function normalizarCategoriaPC(valor = '') {
    return String(valor)
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/[^a-zA-Z0-9]+/g, '_')
        .replace(/^_+|_+$/g, '')
        .toLowerCase();
}

function mapearSlugCategoriaPC(nombre) {
    const n = normalizarCategoriaPC(nombre);
    if (n.includes('pipc')) return 'pipc';
    if (n.includes('opinion_tecnica') || n.includes('opinion') || n.includes('tecnica')) return 'opinion_tecnica';
    if (n.includes('uso_suelo') || (n.includes('uso') && n.includes('suelo'))) return 'uso_suelo';
    return n;
}

function formatDateOnly(fecha) {
    if (!fecha) return null;
    const d = new Date(fecha);
    if (Number.isNaN(d.getTime())) return null;
    return d.toISOString().split('T')[0];
}

async function resolverCarpetaCatalogoPCDrive() {
    const rootPrincipal = driveService.ROOT_FOLDER_ID || 'root';
    const padresRaiz = [rootPrincipal, 'root'].filter((v, i, arr) => !!v && arr.indexOf(v) === i);

    const buscarPorNombres = async (nombres, parentId) => {
        for (const nombre of nombres) {
            const id = await driveService.buscarCarpeta(nombre, parentId);
            if (id) return id;
        }
        return null;
    };

    let carpetaPcId = null;
    const nombresPc = [
        'Protección_Civil', 'protección_civil', 'Protección_civil', 'proteccion_civil',
        'Proteccion_civil', 'ProteccionCivil', 'Proteccion Civil', 'Protección Civil', 'proteccion civil'
    ];

    for (const parentId of padresRaiz) {
        carpetaPcId = await buscarPorNombres(nombresPc, parentId);
        if (carpetaPcId) break;
    }

    if (!carpetaPcId) {
        carpetaPcId = await driveService.crearCarpeta('Protección_Civil', rootPrincipal);
    }

    let carpetaCatalogoId = await buscarPorNombres(['Catalogo', 'Catálogo', 'catalogo', 'catálogo'], carpetaPcId);
    if (!carpetaCatalogoId) {
        carpetaCatalogoId = await driveService.crearCarpeta('Catalogo', carpetaPcId);
    }

    return { carpetaPcId, carpetaCatalogoId };
}

async function resolverCarpetaCategoriaPCDrive(nombreCategoria) {
    const { carpetaCatalogoId } = await resolverCarpetaCatalogoPCDrive();

    let carpetaCategoriaId = await driveService.buscarCarpeta(nombreCategoria, carpetaCatalogoId);
    if (carpetaCategoriaId) {
        return carpetaCategoriaId;
    }

    const subcarpetas = await driveService.listarSubcarpetas(carpetaCatalogoId);
    const nombreNormalizado = normalizarCategoriaPC(nombreCategoria);
    const equivalente = subcarpetas.find((folder) => normalizarCategoriaPC(folder.name) === nombreNormalizado);
    if (equivalente?.id) {
        return equivalente.id;
    }

    return await driveService.crearCarpeta(nombreCategoria, carpetaCatalogoId);
}

async function buscarCarpetaCategoriaPCDrive(nombreCategoria) {
    const { carpetaCatalogoId } = await resolverCarpetaCatalogoPCDrive();

    let carpetaCategoriaId = await driveService.buscarCarpeta(nombreCategoria, carpetaCatalogoId);
    if (carpetaCategoriaId) {
        return carpetaCategoriaId;
    }

    const subcarpetas = await driveService.listarSubcarpetas(carpetaCatalogoId);
    const nombreNormalizado = normalizarCategoriaPC(nombreCategoria);
    const equivalente = subcarpetas.find((folder) => normalizarCategoriaPC(folder.name) === nombreNormalizado);
    return equivalente?.id || null;
}

function normalizarNombreHojaPipc(valor = '') {
    return String(valor)
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .replace(/\s+/g, ' ')
        .trim()
        .toLowerCase();
}

async function listarHojasWorkbookDesdeDrive(driveFileId, mimeTypeHint = '') {
    if (!driveFileId) {
        return [];
    }

    if (!(await driveService.verificarArchivoExiste(driveFileId))) {
        throw new Error(`File not found: ${driveFileId}.`);
    }

    const mime = String(mimeTypeHint || '').toLowerCase();

    if (mime === 'application/vnd.google-apps.spreadsheet') {
        try {
            const titulos = await driveService.listarHojasGoogleSheet(driveFileId);
            if (titulos.length) {
                return titulos;
            }
        } catch (sheetErr) {
            console.warn(`[PC-CATALOGO] Sheets API falló para ${driveFileId}:`, sheetErr.message);
        }
    } else if (!mime) {
        try {
            const info = await driveService.obtenerInfoArchivo(driveFileId);
            const mimeReal = String(info?.mimeType || '').toLowerCase();
            if (mimeReal === 'application/vnd.google-apps.spreadsheet') {
                const titulos = await driveService.listarHojasGoogleSheet(driveFileId);
                if (titulos.length) {
                    return titulos;
                }
            }
        } catch (infoErr) {
            console.warn(`[PC-CATALOGO] No se pudo leer mime de ${driveFileId}:`, infoErr.message);
        }
    }

    const ExcelJS = require('exceljs');
    const buffer = await driveService.exportarArchivoXLSX(driveFileId);
    const workbook = new ExcelJS.Workbook();
    await workbook.xlsx.load(buffer);
    return workbook.worksheets.map((ws) => String(ws.name || '').trim()).filter(Boolean);
}

function resolverWorksheetPipc(workbook, hojaNombre = '') {
    if (!workbook?.worksheets?.length) {
        return null;
    }

    const objetivo = normalizarNombreHojaPipc(hojaNombre);
    if (objetivo) {
        const hoja = workbook.worksheets.find((ws) => normalizarNombreHojaPipc(ws.name) === objetivo);
        if (hoja) {
            return hoja;
        }
    }

    return workbook.worksheets[0] || null;
}

function esArchivoExcelCatalogo(mimeType = '', nombre = '') {
    const mime = String(mimeType || '').toLowerCase();
    const nombreArchivo = String(nombre || '');
    return mime.includes('spreadsheetml')
        || mime.includes('ms-excel')
        || mime.includes('google-apps.spreadsheet')
        || /\.xlsx?$/i.test(nombreArchivo);
}

function esNombreArchivoMaestroPipc(nombre = '') {
    return /archivos\s*pipc/i.test(String(nombre || '').trim());
}

function esArchivoExcluidoCatalogoPipc(nombre = '') {
    const limpio = String(nombre || '').trim();
    return /sp[\s_-]*f[\s_-]*29|control\s+de\s+resolutivos/i.test(limpio);
}

function esArchivoPipcIndividualPorNombre(nombre = '') {
    const limpio = String(nombre || '').trim().replace(/\.xlsx?$/i, '');
    return /^pipc\s+.+$/i.test(limpio)
        && !esNombreArchivoMaestroPipc(nombre)
        && !esArchivoExcluidoCatalogoPipc(nombre);
}

function esArchivoPipcIndividualLegacy(nombre = '') {
    return esArchivoPipcIndividualPorNombre(nombre);
}

async function repararDriveFileIdCatalogoPipc(doc = {}) {
    const resultadoDrive = await driveService.obtenerCatalogoProteccionCivilDesdeDrive();
    if (!resultadoDrive.success) {
        return null;
    }

    const pipcCat = (resultadoDrive.categorias || []).find(
        (categoria) => mapearSlugCategoriaPC(categoria.nombre) === 'pipc'
    );
    if (!pipcCat?.folderId) {
        return null;
    }

    const archivos = await driveService.listarArchivosCarpeta(pipcCat.folderId);
    const candidatos = [
        doc.hoja_nombre,
        doc.nombre,
        doc.archivo_maestro_nombre,
        doc.hoja_nombre ? `${doc.hoja_nombre}.xlsx` : '',
        doc.archivo_maestro_nombre || 'Archivos PIPC.xlsx'
    ]
        .map((nombre) => String(nombre || '').trim())
        .filter(Boolean);

    const normalizarArchivo = (nombre = '') => normalizarNombreHojaPipc(
        String(nombre).replace(/\.xlsx?$/i, '').trim()
    );

    for (const candidato of candidatos) {
        const objetivo = normalizarArchivo(candidato);
        const match = archivos.find((archivo) => normalizarArchivo(archivo.name) === objetivo);
        if (match?.id) {
            return {
                fileId: match.id,
                mimeType: match.mimeType || null,
                webViewLink: match.webViewLink || null,
                webContentLink: match.webContentLink || null,
                nombre: match.name || candidato
            };
        }
    }

    return null;
}

async function resolverEntradasCatalogoPipc(documentosDrive = []) {
    const xlsxDocs = (documentosDrive || []).filter(
        (doc) => esArchivoExcelCatalogo(doc.mimeType, doc.nombre)
            && doc.id
            && !esArchivoExcluidoCatalogoPipc(doc.nombre)
    );

    // Modelo actual: un Google Sheet / Excel por ubicación (PIPC Pachuca, etc.).
    // Si hay individuales en Drive, tienen prioridad sobre cualquier workbook multi-hoja
    // (evita que SP-F-29 u otros archivos ajenos sustituyan el catálogo).
    const individualesPorNombre = xlsxDocs.filter((doc) => esArchivoPipcIndividualPorNombre(doc.nombre));
    if (individualesPorNombre.length) {
        const entradas = individualesPorNombre.map((doc) => {
            const nombreLimpio = String(doc.nombre || '').replace(/\.xlsx?$/i, '').trim();
            return {
                doc,
                entrada: {
                    nombre: nombreLimpio,
                    hoja_nombre: nombreLimpio,
                    archivo_maestro_nombre: null
                }
            };
        });
        startupLog.detail(
            `[PC-CATALOGO] PIPC: ${entradas.length} formato(s) individual(es) en carpeta Drive`
        );
        return entradas;
    }

    const maestroDriveIdEnv = String(process.env.PIPC_CATALOGO_MAESTRO_DRIVE_ID || '').trim();
    let maestroDriveId = '';

    if (maestroDriveIdEnv) {
        if (await driveService.verificarArchivoExiste(maestroDriveIdEnv)) {
            maestroDriveId = maestroDriveIdEnv;
        } else {
            console.warn(
                `[PC-CATALOGO] PIPC_CATALOGO_MAESTRO_DRIVE_ID inválido o eliminado (${maestroDriveIdEnv}); `
                + 'se buscará el maestro en la carpeta de Drive'
            );
        }
    }

    const maestroEnCarpeta = xlsxDocs.find((doc) => esNombreArchivoMaestroPipc(doc.nombre));
    if (!maestroDriveId && maestroEnCarpeta?.id) {
        maestroDriveId = String(maestroEnCarpeta.id);
    }

    const maestroYaListado = maestroDriveId
        ? xlsxDocs.some((doc) => String(doc.id) === maestroDriveId)
        : false;

    if (maestroDriveId && !maestroYaListado) {
        try {
            const info = await driveService.obtenerInfoArchivo(maestroDriveId);
            if (!esArchivoExcluidoCatalogoPipc(info.name)) {
                xlsxDocs.unshift({
                    id: maestroDriveId,
                    nombre: info.name || 'Archivos PIPC.xlsx',
                    mimeType: info.mimeType || 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
                    webViewLink: info.webViewLink || null,
                    webContentLink: info.webContentLink || null,
                    size: info.size || null,
                    modifiedTime: info.modifiedTime || null
                });
            }
        } catch (infoErr) {
            console.warn(`[PC-CATALOGO] No se pudo cargar maestro PIPC ${maestroDriveId}:`, infoErr.message);
        }
    }

    const masters = [];
    const individuales = [];

    for (const doc of xlsxDocs) {
        try {
            const nombresHojas = await listarHojasWorkbookDesdeDrive(doc.id, doc.mimeType);
            const esMaestro = (
                esNombreArchivoMaestroPipc(doc.nombre)
                || (maestroDriveId && String(doc.id) === maestroDriveId)
            ) && nombresHojas.length > 1;

            if (esMaestro) {
                masters.push({ doc, nombresHojas });
                continue;
            }

            if (esArchivoPipcIndividualPorNombre(doc.nombre)) {
                individuales.push(doc);
                continue;
            }

            if (!esNombreArchivoMaestroPipc(doc.nombre)) {
                individuales.push(doc);
            }
        } catch (hojaErr) {
            console.warn(`[PC-CATALOGO] No se pudieron leer hojas de "${doc.nombre}":`, hojaErr.message);
            if (esArchivoPipcIndividualPorNombre(doc.nombre)) {
                individuales.push(doc);
            } else if (!esNombreArchivoMaestroPipc(doc.nombre)) {
                individuales.push(doc);
            }
        }
    }

    const entradas = [];

    if (masters.length) {
        for (const master of masters) {
            for (const hojaNombre of master.nombresHojas) {
                entradas.push({
                    doc: master.doc,
                    entrada: {
                        nombre: hojaNombre.trim() || hojaNombre,
                        hoja_nombre: hojaNombre,
                        archivo_maestro_nombre: master.doc.nombre
                    }
                });
            }
        }
        startupLog.detail(
            `[PC-CATALOGO] PIPC: ${masters.length} archivo(s) maestro(s), ${entradas.length} hoja(s); `
            + `${individuales.length} archivo(s) individual(es) omitido(s)`
        );
        return entradas;
    }

    for (const doc of individuales) {
        const nombreLimpio = String(doc.nombre || '').replace(/\.xlsx?$/i, '').trim();
        const esIndividualPipc = esArchivoPipcIndividualPorNombre(doc.nombre);
        entradas.push({
            doc,
            entrada: {
                nombre: esIndividualPipc ? nombreLimpio : doc.nombre,
                hoja_nombre: esIndividualPipc ? nombreLimpio : '',
                archivo_maestro_nombre: null
            }
        });
    }

    if (entradas.length) {
        const conHoja = entradas.filter((item) => String(item?.entrada?.hoja_nombre || '').trim()).length;
        startupLog.detail(
            `[PC-CATALOGO] PIPC: ${conHoja} entrada(s) con hoja; `
            + `${individuales.length} archivo(s) individual(es) en carpeta`
        );
    }

    return entradas;
}

async function actualizarDriveFileMaestroCatalogo(pool, oldFileId, nuevo) {
    const [result] = await pool.query(
        `UPDATE pc_catalogo_documento SET
            drive_file_id = ?,
            mime_type = ?,
            drive_web_view_link = ?,
            drive_download_link = ?,
            drive_sheet_gid = NULL,
            fecha_actualizacion = NOW()
         WHERE drive_file_id = ? AND activo = 1`,
        [
            nuevo.fileId,
            nuevo.mimeType,
            nuevo.webViewLink || null,
            nuevo.webContentLink || null,
            oldFileId
        ]
    );
    return result.affectedRows || 0;
}

async function sincronizarCatalogoProteccionCivilDesdeDrive() {
    await poolProteccionCivilReady;

    // Sincronizar categorías base (solo actualiza orden/activo, NO el nombre para permitir ediciones de usuario)
    for (const categoria of CATEGORIAS_PC_CATALOGO) {
        await poolProteccionCivil.query(
            `INSERT INTO pc_catalogo_categoria (slug, nombre, orden, activo)
             VALUES (?, ?, ?, 1)
             ON DUPLICATE KEY UPDATE orden = VALUES(orden), activo = 1`,
            [categoria.slug, categoria.nombre, categoria.orden]
        );
    }

    const resultadoDrive = await driveService.obtenerCatalogoProteccionCivilDesdeDrive();
    if (!resultadoDrive.success) {
        console.error('[PC-CATALOGO] Error desde Drive:', resultadoDrive.message);
        return { success: false, message: resultadoDrive.message || 'No se pudo leer catálogo de Drive' };
    }

    await poolProteccionCivil.query('UPDATE pc_catalogo_documento SET activo = 0');

    let totalSincronizados = 0;
    for (const categoriaDrive of resultadoDrive.categorias || []) {
        const slug = mapearSlugCategoriaPC(categoriaDrive.nombre);
        if (!CATEGORIAS_PC_CATALOGO.some((c) => c.slug === slug)) {
            continue;
        }

        const [catRows] = await poolProteccionCivil.query(
            'SELECT categoria_id FROM pc_catalogo_categoria WHERE slug = ? LIMIT 1',
            [slug]
        );
        if (!catRows.length) continue;
        const categoriaId = catRows[0].categoria_id;

        await poolProteccionCivil.query(
            'UPDATE pc_catalogo_categoria SET drive_folder_id = ?, fecha_actualizacion = NOW() WHERE categoria_id = ?',
            [categoriaDrive.folderId || null, categoriaId]
        );

        if (slug === 'pipc') {
            const entradasPipc = await resolverEntradasCatalogoPipc(categoriaDrive.documentos || []);
            const entradasConHoja = entradasPipc.filter((item) => String(item?.entrada?.hoja_nombre || '').trim());

            if (!entradasConHoja.length) {
                console.warn(
                    '[PC-CATALOGO] Sync PIPC: no se detectaron hojas workbook en Drive. '
                    + 'Se conservan los registros PIPC ya existentes en BD (sin SP-F-29).'
                );
                await poolProteccionCivil.query(
                    `UPDATE pc_catalogo_documento d
                     INNER JOIN pc_catalogo_categoria c ON c.categoria_id = d.categoria_id AND c.slug = 'pipc'
                     SET d.activo = 1, d.fecha_actualizacion = NOW()
                     WHERE TRIM(COALESCE(d.hoja_nombre, '')) <> ''
                       AND COALESCE(d.archivo_maestro_nombre, '') NOT REGEXP 'sp[[:space:]_-]*f[[:space:]_-]*29|resolutivos'
                       AND COALESCE(d.nombre, '') NOT REGEXP 'sp[[:space:]_-]*f[[:space:]_-]*29|resolutivos'`
                );
                continue;
            }

            for (const { doc, entrada } of entradasPipc) {
                await poolProteccionCivil.query(
                    `INSERT INTO pc_catalogo_documento
                        (categoria_id, nombre, jurisdiccion, drive_file_id, drive_web_view_link, drive_download_link, mime_type, size_bytes, fecha_actualizacion_drive, hoja_nombre, archivo_maestro_nombre, activo)
                     VALUES (?, ?, 'General', ?, ?, ?, ?, ?, ?, ?, ?, 1)
                     ON DUPLICATE KEY UPDATE
                        categoria_id = VALUES(categoria_id),
                        nombre = VALUES(nombre),
                        drive_web_view_link = VALUES(drive_web_view_link),
                        drive_download_link = VALUES(drive_download_link),
                        mime_type = VALUES(mime_type),
                        size_bytes = VALUES(size_bytes),
                        fecha_actualizacion_drive = VALUES(fecha_actualizacion_drive),
                        archivo_maestro_nombre = VALUES(archivo_maestro_nombre),
                        activo = 1,
                        fecha_actualizacion = NOW()`,
                    [
                        categoriaId,
                        entrada.nombre,
                        doc.id,
                        doc.webViewLink || null,
                        doc.webContentLink || null,
                        doc.mimeType || null,
                        doc.size || null,
                        doc.modifiedTime ? new Date(doc.modifiedTime) : null,
                        entrada.hoja_nombre || '',
                        entrada.archivo_maestro_nombre || null
                    ]
                );
                totalSincronizados += 1;
            }
            continue;
        }

        for (const doc of categoriaDrive.documentos || []) {
            const entradasDocumento = [{
                nombre: doc.nombre,
                hoja_nombre: '',
                archivo_maestro_nombre: null
            }];

            for (const entrada of entradasDocumento) {
                await poolProteccionCivil.query(
                    `INSERT INTO pc_catalogo_documento
                        (categoria_id, nombre, jurisdiccion, drive_file_id, drive_web_view_link, drive_download_link, mime_type, size_bytes, fecha_actualizacion_drive, hoja_nombre, archivo_maestro_nombre, activo)
                     VALUES (?, ?, 'General', ?, ?, ?, ?, ?, ?, ?, ?, 1)
                     ON DUPLICATE KEY UPDATE
                        categoria_id = VALUES(categoria_id),
                        nombre = VALUES(nombre),
                        drive_web_view_link = VALUES(drive_web_view_link),
                        drive_download_link = VALUES(drive_download_link),
                        mime_type = VALUES(mime_type),
                        size_bytes = VALUES(size_bytes),
                        fecha_actualizacion_drive = VALUES(fecha_actualizacion_drive),
                        archivo_maestro_nombre = VALUES(archivo_maestro_nombre),
                        activo = 1,
                        fecha_actualizacion = NOW()`,
                    [
                        categoriaId,
                        entrada.nombre,
                        doc.id,
                        doc.webViewLink || null,
                        doc.webContentLink || null,
                        doc.mimeType || null,
                        doc.size || null,
                        doc.modifiedTime ? new Date(doc.modifiedTime) : null,
                        entrada.hoja_nombre || '',
                        entrada.archivo_maestro_nombre || null
                    ]
                );
                totalSincronizados += 1;
            }
        }
    }

    return {
        success: true,
        message: `${totalSincronizados} documentos sincronizados`
    };
}

