// HELPER FUNCTIONS
// =====================================================

// SEGURIDAD: roles que NUNCA deben poder asignarse via API
// (solo se asignan manualmente en BD por un DBA).
const ROLES_PRIVILEGIADOS_PROTEGIDOS = new Set(['root', 'super_admin', 'superadmin']);

/**
 * Sanitiza el campo `roles_adicionales` para evitar escalada de privilegios.
 * Devuelve { ok: true, value } o { ok: false, message }.
 *  - Quita espacios.
 *  - Bloquea cualquier intento de incluir un rol privilegiado (root, super_admin).
 *  - Permite cadena vacía/null.
 */
function sanitizarRolesAdicionales(valor) {
    if (valor === undefined || valor === null) return { ok: true, value: null };
    const lista = String(valor)
        .split(',')
        .map((r) => r.trim().toLowerCase())
        .filter(Boolean);

    for (const rol of lista) {
        if (ROLES_PRIVILEGIADOS_PROTEGIDOS.has(rol)) {
            return {
                ok: false,
                message: 'No se puede asignar el rol root/super_admin como rol adicional'
            };
        }
    }

    return { ok: true, value: lista.length > 0 ? lista.join(',') : null };
}

const handleError = (res, error, message = 'Error en el servidor') => {
    if (error?.statusCode) {
        console.error(message, error.message);
        return res.status(error.statusCode).json({
            success: false,
            message: error.message || message
        });
    }

    if (esErrorConexionDb(error)) {
        const code = error?.code || 'DB_CONNECTION_ERROR';
        console.error(`[DB][${code}] ${message}: ${error?.message || 'sin detalle'}`);
        return res.status(503).json({
            success: false,
            message: 'Base de datos temporalmente no disponible. Intenta nuevamente en unos segundos.',
            code
        });
    }

    console.error(message, error);
    res.status(500).json({ success: false, message, error: error.message });
};

