/**
 * Middleware que verifica que el usuario tenga uno de los roles permitidos.
 * Debe usarse DESPUÉS de authMiddleware (req.user ya existe).
 * @param  {...string} rolesPermitidos - Roles que tienen acceso (ej: 'root', 'administrador')
 */
function requireRole(...rolesPermitidos) {
    return (req, res, next) => {
        // Soporta multi-rol: req.user.roles (array) o req.user.rol (string)
        const userRoles = Array.isArray(req.user?.roles)
            ? req.user.roles.map(r => r.toLowerCase())
            : (req.user?.rol ? [req.user.rol.toLowerCase()] : []);

        if (userRoles.length === 0) {
            return res.status(403).json({
                success: false,
                message: 'No se pudo determinar el rol del usuario'
            });
        }

        // root siempre tiene acceso total
        if (userRoles.includes('root')) {
            return next();
        }

        const tienePermiso = rolesPermitidos.some(r => userRoles.includes(r.toLowerCase()));

        if (!tienePermiso) {
            return res.status(403).json({
                success: false,
                message: 'No tiene permisos para realizar esta acción'
            });
        }

        next();
    };
}

