const sgcEditoresDelegadosService = require('./sgcEditoresDelegadosService');

/** Username del perfil Calidad (Sergio): desarrollo sergio56, producción calidad. */
function esGestorCalidadSgc(req) {
    const username = String(req.user?.username || '').toLowerCase().trim();
    return username === 'sergio56' || username === 'calidad';
}

function extraerFormatoCodigoSgcDeRuta(req) {
    const raw = String(req.originalUrl || req.url || req.path || '');
    const pathOnly = raw.split('?')[0];
    const match = pathOnly.match(/\/sgc\/formatos\/([^\/\?]+)/i);
    if (!match) return '';
    return sgcEditoresDelegadosService.normalizarFormatoCodigo(match[1]);
}

/**
 * Acceso al módulo SGC y formatos:
 * root | administrador | sgc | perfil calidad | editores delegados.
 * En escrituras de un formato concreto, el delegado debe estar asignado a ese formato.
 */
async function requireAdminOrSgc(req, res, next) {
    try {
        const userRoles = Array.isArray(req.user?.roles)
            ? req.user.roles.map((r) => String(r).toLowerCase())
            : (req.user?.rol ? [String(req.user.rol).toLowerCase()] : []);

        if (userRoles.includes('root') || userRoles.includes('administrador') || userRoles.includes('sgc')) {
            return next();
        }
        if (esGestorCalidadSgc(req)) {
            return next();
        }

        const userId = Number(req.user?.id || req.user?.usuario_id || 0);
        const username = String(req.user?.username || '').toLowerCase().trim();
        const method = String(req.method || 'GET').toUpperCase();
        const isMutating = method === 'POST' || method === 'PUT' || method === 'PATCH' || method === 'DELETE';
        const formatoCodigo = extraerFormatoCodigoSgcDeRuta(req);

        // Todos los perfiles internos pueden consultar el Centro SGC y sus formatos.
        // La escritura continúa limitada a los gestores y delegados del formato.
        if (!isMutating && !userRoles.includes('empresa')) {
            return next();
        }

        if (formatoCodigo === 'ath-f-08' && username === 'mafer295') {
            return next();
        }

        if (userId > 0 && formatoCodigo && isMutating) {
            if (await sgcEditoresDelegadosService.esEditorDelegadoFormato(pool, userId, formatoCodigo)) {
                return next();
            }
            return res.status(403).json({
                success: false,
                message: 'No tiene permisos para editar este formato SGC'
            });
        }

        if (userId > 0 && await sgcEditoresDelegadosService.esEditorDelegado(pool, userId)) {
            return next();
        }

        return res.status(403).json({
            success: false,
            message: 'No tiene permisos para realizar esta acción'
        });
    } catch (error) {
        return handleError(res, error, 'Error al verificar permisos SGC');
    }
}

