function getUserRolesLower(req) {
    return Array.isArray(req.user?.roles)
        ? req.user.roles.map(r => String(r).toLowerCase())
        : (req.user?.rol ? [String(req.user.rol).toLowerCase()] : []);
}

function tieneAlgunRol(req, ...roles) {
    const userRoles = getUserRolesLower(req);
    return roles.some((rol) => userRoles.includes(String(rol).toLowerCase()));
}

function esPerfilEmpresa(req) {
    return getUserRolesLower(req).includes('empresa');
}

/** Acceso para cualquier perfil autenticado excepto empresa (Mis empresas, Control de Proyectos, Control de Oficios, etc.) */
function denyEmpresa(req, res, next) {
    if (esPerfilEmpresa(req)) {
        return res.status(403).json({
            success: false,
            message: 'Esta accion no esta disponible para perfiles de empresa'
        });
    }
    next();
}

function obtenerNombreUsuarioAccion(req) {
    const nombre = String(req.user?.nombre || '').trim();
    const apellido = String(req.user?.apellido || '').trim();
    const nombreCompleto = [nombre, apellido].filter(Boolean).join(' ').trim();

    if (nombreCompleto) return nombreCompleto;

    const username = String(req.user?.username || '').trim();
    if (username) return username;

    return 'Usuario';
}

function obtenerFechaHoraMexicoMySQL(fechaBase = new Date()) {
    const parts = new Intl.DateTimeFormat('en-CA', {
        timeZone: 'America/Mexico_City',
        year: 'numeric',
        month: '2-digit',
        day: '2-digit',
        hour: '2-digit',
        minute: '2-digit',
        second: '2-digit',
        hourCycle: 'h23'
    }).formatToParts(fechaBase);

    const get = (type) => parts.find((p) => p.type === type)?.value || '';
    return `${get('year')}-${get('month')}-${get('day')} ${get('hour')}:${get('minute')}:${get('second')}`;
}

function serializarFechaHoraMexicoMySQL(valor) {
    if (valor == null || valor === '') {
        return null;
    }

    if (valor instanceof Date && !Number.isNaN(valor.getTime())) {
        return obtenerFechaHoraMexicoMySQL(valor);
    }

    const texto = String(valor).trim();
    const matchNaive = texto.match(/^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})/);
    if (matchNaive) {
        return matchNaive[1];
    }

    const fecha = new Date(texto);
    if (!Number.isNaN(fecha.getTime())) {
        return obtenerFechaHoraMexicoMySQL(fecha);
    }

    return texto || null;
}

function normalizarClaveEnvCorreo(correo) {
    return String(correo || '')
        .trim()
        .toUpperCase()
        .replace(/[^A-Z0-9]/g, '_');
}

function obtenerDominioCorreo(correo) {
    const partes = String(correo || '').split('@');
    return partes.length === 2 ? partes[1].trim().toLowerCase() : '';
}

function obtenerPasswordImapParaCorreo(correo) {
    const claveCorreo = normalizarClaveEnvCorreo(correo);
    return process.env[`IMAP_PASSWORD_${claveCorreo}`]
        || process.env[`MAILBOX_PASSWORD_${claveCorreo}`]
        || process.env.IMAP_PASSWORD
        || process.env.MAILBOX_PASSWORD
        || process.env.IMAP_PASS
        || process.env.MAILBOX_PASS
        || '';
}

function obtenerFuentePasswordImap(correo) {
    const claveCorreo = normalizarClaveEnvCorreo(correo);
    if (process.env[`IMAP_PASSWORD_${claveCorreo}`]) return `IMAP_PASSWORD_${claveCorreo}`;
    if (process.env[`MAILBOX_PASSWORD_${claveCorreo}`]) return `MAILBOX_PASSWORD_${claveCorreo}`;
    if (process.env.IMAP_PASSWORD) return 'IMAP_PASSWORD';
    if (process.env.MAILBOX_PASSWORD) return 'MAILBOX_PASSWORD';
    if (process.env.IMAP_PASS) return 'IMAP_PASS';
    if (process.env.MAILBOX_PASS) return 'MAILBOX_PASS';
    return '';
}

function obtenerFuenteHostImap(correo) {
    const dominio = obtenerDominioCorreo(correo);
    if (process.env.IMAP_HOST) return 'IMAP_HOST';
    if (process.env.MAILBOX_HOST) return 'MAILBOX_HOST';
    if (process.env.SMTP_HOST) return 'SMTP_HOST';
    if (dominio) return `mail.${dominio}`;
    return '';
}

function obtenerConfigImap(correo) {
    const dominio = obtenerDominioCorreo(correo);
    const host = process.env.IMAP_HOST
        || process.env.MAILBOX_HOST
        || process.env.SMTP_HOST
        || (dominio ? `mail.${dominio}` : '');

    return {
        host,
        port: Number(process.env.IMAP_PORT || process.env.MAILBOX_PORT || 993),
        secure: String(process.env.IMAP_SECURE || process.env.MAILBOX_SECURE || 'true').toLowerCase() !== 'false',
        rejectUnauthorized: String(process.env.IMAP_REJECT_UNAUTHORIZED || 'true').toLowerCase() !== 'false',
        pass: obtenerPasswordImapParaCorreo(correo)
    };
}

function obtenerConfigSmtp(correo) {
    const dominio = obtenerDominioCorreo(correo);
    const host = process.env.MAILBOX_SMTP_HOST
        || process.env.MAILBOX_HOST
        || process.env.IMAP_HOST
        || (dominio ? `mail.${dominio}` : '');
    const port = Number(process.env.MAILBOX_SMTP_PORT || 465);
    const secureRaw = process.env.MAILBOX_SMTP_SECURE;
    const secure = secureRaw !== undefined
        ? String(secureRaw).toLowerCase() === 'true'
        : port === 465;

    return {
        host,
        port,
        secure,
        requireTLS: String(process.env.MAILBOX_SMTP_REQUIRE_TLS || 'false').toLowerCase() === 'true',
        rejectUnauthorized: String(process.env.SMTP_TLS_REJECT_UNAUTHORIZED || 'true').toLowerCase() !== 'false',
        pass: obtenerPasswordImapParaCorreo(correo)
    };
}

function esEnvioCorreoViaBrevo() {
    return String(process.env.CORREO_ENVIO_VIA_BREVO || 'true').toLowerCase() === 'true';
}

function escaparHtmlCorreo(texto = '') {
    return String(texto || '')
        .replace(/&/g, '&amp;')
        .replace(/</g, '&lt;')
        .replace(/>/g, '&gt;')
        .replace(/"/g, '&quot;')
        .replace(/'/g, '&#39;');
}

function convertirTextoCorreoHtml(texto = '') {
    return escaparHtmlCorreo(texto).replace(/\r?\n/g, '<br>');
}

function esCorreoValido(correo) {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(String(correo || '').trim());
}

const imapConfigWarnAt = new Map();

function warnImapIncompleto(tag, payload) {
    const key = `${tag}:${payload?.correo || ''}`;
    const now = Date.now();
    const last = imapConfigWarnAt.get(key) || 0;
    if (now - last < 5 * 60 * 1000) return;
    imapConfigWarnAt.set(key, now);
    console.warn(tag, payload);
}

async function obtenerContextoCorreoPerfil(req, res) {
    if (esPerfilEmpresa(req)) {
        res.status(403).json({
            success: false,
            message: 'El modulo de correo no esta disponible para perfiles de empresa'
        });
        return null;
    }

    const usuarioId = Number(req.user?.id || 0);
    if (!usuarioId) {
        res.status(401).json({ success: false, message: 'Usuario autenticado no valido' });
        return null;
    }

    await exigirPoolPrincipal();
    const [usuarios] = await pool.query(
        'SELECT email, nombre, apellido FROM usuario WHERE id = ? AND activo = TRUE LIMIT 1',
        [usuarioId]
    );
    const correoPerfil = String(usuarios[0]?.email || '').trim().toLowerCase();
    const nombrePerfil = `${usuarios[0]?.nombre || ''} ${usuarios[0]?.apellido || ''}`.trim() || correoPerfil;

    if (!correoPerfil) {
        res.status(400).json({
            success: false,
            message: 'El perfil no tiene un correo configurado'
        });
        return null;
    }

    const configImap = obtenerConfigImap(correoPerfil);
    if (!configImap.host || !configImap.pass) {
        const faltantes = [];
        if (!configImap.host) faltantes.push('host');
        if (!configImap.pass) faltantes.push('pass');
        warnImapIncompleto('[correo] Config IMAP incompleta', {
            correo: correoPerfil,
            faltantes,
            hostSource: obtenerFuenteHostImap(correoPerfil) || 'sin_host',
            passSource: obtenerFuentePasswordImap(correoPerfil) || 'sin_pass'
        });
        res.status(503).json({
            success: false,
            message: `Falta configurar el acceso IMAP para ${correoPerfil}`,
            cuenta: correoPerfil
        });
        return null;
    }

    return { correoPerfil, configImap, nombrePerfil };
}

const CORREO_EMPRESA_CUENTA = String(process.env.CORREO_EMPRESA_CUENTA || 'contacto@biznaga.com.mx').trim().toLowerCase();
const CORREO_EMPRESA_NOMBRE = String(process.env.CORREO_EMPRESA_NOMBRE || 'Biznaga Risk&Tech').trim();

async function obtenerContextoCorreoEmpresa(req, res) {
    if (!tieneAlgunRol(req, 'root', 'administrador')) {
        res.status(403).json({
            success: false,
            message: 'Solo administradores pueden acceder al correo de empresa'
        });
        return null;
    }

    const correoPerfil = CORREO_EMPRESA_CUENTA;
    const nombrePerfil = CORREO_EMPRESA_NOMBRE;
    const configImap = obtenerConfigImap(correoPerfil);

    if (!configImap.host || !configImap.pass) {
        const faltantes = [];
        if (!configImap.host) faltantes.push('host');
        if (!configImap.pass) faltantes.push('pass');
        warnImapIncompleto('[correo-empresa] Config IMAP incompleta', {
            correo: correoPerfil,
            faltantes,
            hostSource: obtenerFuenteHostImap(correoPerfil) || 'sin_host',
            passSource: obtenerFuentePasswordImap(correoPerfil) || 'sin_pass'
        });
        res.status(503).json({
            success: false,
            message: `Falta configurar el acceso IMAP para ${correoPerfil}`,
            cuenta: correoPerfil
        });
        return null;
    }

    return { correoPerfil, configImap, nombrePerfil };
}

function esErrorConectividadCorreo(error) {
    const code = String(error?.code || '');
    const message = String(error?.message || '');
    return /ENOTFOUND|ETIMEDOUT|ECONNABORTED|ECONNREFUSED|EAI_AGAIN|EHOSTUNREACH|ENETUNREACH|getaddrinfo/i.test(`${code} ${message}`);
}

function responderErrorCorreo(res, error, accion = 'procesar') {
    const message = String(error?.message || '');
    const status = /auth|login|password|credentials/i.test(message)
        ? 401
        : (esErrorConectividadCorreo(error) ? 503 : 500);
    console.error(`[CORREO] Error al ${accion}:`, message);
    return res.status(status).json({
        success: false,
        message: status === 401
            ? 'No se pudo iniciar sesion en el buzon. Verifica la contrasena IMAP configurada.'
            : status === 503
                ? 'El servidor de correo no esta disponible por ahora.'
                : `No se pudo ${accion} el correo`,
        error: message
    });
}

