function normalizarTextoCorreo(texto = '') {
    return String(texto || '')
        .replace(/\r/g, '')
        .replace(/\n{3,}/g, '\n\n')
        .trim();
}

function crearResumenCorreo(texto = '') {
    const limpio = normalizarTextoCorreo(texto).replace(/\s+/g, ' ');
    return limpio.length > 220 ? `${limpio.slice(0, 217)}...` : limpio;
}

/**
 * Middleware que verifica que un usuario empresa solo acceda a sus propios datos.
 * Se usa después de requireAdminOrEmpresa. Compara req.params.empresaId con req.user.empresa_id.
 * Si el usuario es admin/root, pasa sin restricción.
 */
async function verificarEmpresaPropia(req, res, next) {
    if (tieneAlgunRol(req, 'root', 'administrador', 'proteccion_civil')) {
        return next();
    }
    // Usuario empresa: solo puede acceder a su propia empresa
    const empresaIdParam = Number(req.params.empresaId || 0);
    const empresaIdUsuario = Number(req.user?.empresa_id || 0);

    if (empresaIdUsuario && empresaIdUsuario === empresaIdParam) {
        try {
            await asegurarColumnaServicioProteccionCivilEmpresa(pool);
            const [empresaRows] = await pool.query(
                'SELECT servicio_proteccion_civil FROM empresa WHERE empresa_id = ? AND activo = TRUE LIMIT 1',
                [empresaIdParam]
            );
            if (!empresaRows.length || Number(empresaRows[0].servicio_proteccion_civil) !== 1) {
                return res.status(403).json({
                    success: false,
                    message: 'La empresa no tiene habilitado el servicio de Protección Civil'
                });
            }
        } catch (error) {
            return res.status(500).json({ success: false, message: 'Error al validar servicio de Protección Civil' });
        }
        return next();
    }
    return res.status(403).json({ success: false, message: 'No tiene permiso para acceder a esta empresa' });
}

async function verificarServicioProteccionCivilEmpresa(req, res, next) {
    if (tieneAlgunRol(req, 'root', 'administrador', 'proteccion_civil')) {
        return next();
    }

    try {
        await asegurarColumnaServicioProteccionCivilEmpresa(pool);

        const empresaId = Number(req.user.empresa_id || 0);
        if (!empresaId) {
            return res.status(403).json({ success: false, message: 'No se encontró empresa asociada al usuario' });
        }

        const [rows] = await pool.query(
            'SELECT servicio_proteccion_civil FROM empresa WHERE empresa_id = ? AND activo = TRUE LIMIT 1',
            [empresaId]
        );

        if (!rows.length || Number(rows[0].servicio_proteccion_civil) !== 1) {
            return res.status(403).json({
                success: false,
                message: 'La empresa no tiene habilitado el servicio de Protección Civil'
            });
        }

        return next();
    } catch (error) {
        return res.status(500).json({ success: false, message: 'Error al validar servicio de Protección Civil' });
    }
}

/**
 * Middleware que verifica que un documento pertenezca a la empresa del usuario (para empresa).
 * Se usa en endpoints con :documentoId (sin empresaId en URL).
 */
async function verificarDocumentoEmpresa(req, res, next) {
    if (tieneAlgunRol(req, 'root', 'administrador', 'proteccion_civil')) {
        return next();
    }
    try {
        const documentoId = parseInt(req.params.documentoId, 10);
        const [docs] = await poolProteccionCivil.query(
            'SELECT empresa_id FROM documento_proteccion_civil WHERE documento_id = ?',
            [documentoId]
        );
        if (docs.length === 0) {
            return res.status(404).json({ success: false, message: 'Documento no encontrado' });
        }
        const empresaIdUsuario = Number(req.user?.empresa_id || 0);
        const empresaIdDocumento = Number(docs[0].empresa_id || 0);

        if (empresaIdUsuario && empresaIdUsuario === empresaIdDocumento) {
            await asegurarColumnaServicioProteccionCivilEmpresa(pool);
            const [empresaRows] = await pool.query(
                'SELECT servicio_proteccion_civil FROM empresa WHERE empresa_id = ? AND activo = TRUE LIMIT 1',
                [empresaIdDocumento]
            );
            if (!empresaRows.length || Number(empresaRows[0].servicio_proteccion_civil) !== 1) {
                return res.status(403).json({
                    success: false,
                    message: 'La empresa no tiene habilitado el servicio de Protección Civil'
                });
            }
            return next();
        }
        return res.status(403).json({ success: false, message: 'No tiene permiso para acceder a este documento' });
    } catch (error) {
        return res.status(500).json({ success: false, message: 'Error de verificación' });
    }
}

/** Admin, root o proteccion_civil pueden auto-aprobar al subir (no pasan a revisión). */
function puedeAutoAprobarSubidaPC(req) {
    return tieneAlgunRol(req, 'root', 'administrador', 'proteccion_civil');
}

/** Lista adjuntos de un requerimiento PC (multi-archivo). */
async function listarArchivosDocumentoPC(documentoId) {
    const [rows] = await poolProteccionCivil.query(
        `SELECT archivo_id, documento_id, drive_file_id, nombre_archivo, mime_type, orden, fecha_subida
         FROM documento_proteccion_civil_archivo
         WHERE documento_id = ?
         ORDER BY orden ASC, archivo_id ASC`,
        [documentoId]
    );
    return rows || [];
}

/**
 * Sincroniza columnas legacy archivo_url/nombre_archivo/fecha_subida
 * con el adjunto más reciente (compatibilidad con UI/API existentes).
 */
async function sincronizarCamposLegacyArchivoPC(documentoId) {
    const archivos = await listarArchivosDocumentoPC(documentoId);
    if (!archivos.length) {
        await poolProteccionCivil.query(
            `UPDATE documento_proteccion_civil
             SET archivo_url = NULL, nombre_archivo = NULL, fecha_subida = NULL, fecha_actualizacion = NOW()
             WHERE documento_id = ?`,
            [documentoId]
        );
        return null;
    }
    const principal = archivos[archivos.length - 1];
    await poolProteccionCivil.query(
        `UPDATE documento_proteccion_civil
         SET archivo_url = ?, nombre_archivo = ?, fecha_subida = COALESCE(?, fecha_subida, NOW()), fecha_actualizacion = NOW()
         WHERE documento_id = ?`,
        [principal.drive_file_id, principal.nombre_archivo, principal.fecha_subida, documentoId]
    );
    return principal;
}

/** Adjunta archivos[] a cada fila de documento (padres e hijos). */
async function adjuntarArchivosADocumentosPC(docs) {
    if (!Array.isArray(docs) || docs.length === 0) return docs;
    const ids = docs.map((d) => Number(d.documento_id)).filter((id) => id > 0);
    if (!ids.length) {
        return docs.map((d) => ({ ...d, archivos: [] }));
    }
    const [rows] = await poolProteccionCivil.query(
        `SELECT archivo_id, documento_id, drive_file_id, nombre_archivo, mime_type, orden, fecha_subida
         FROM documento_proteccion_civil_archivo
         WHERE documento_id IN (?)
         ORDER BY orden ASC, archivo_id ASC`,
        [ids]
    );
    const porDoc = new Map();
    for (const row of rows || []) {
        const key = Number(row.documento_id);
        if (!porDoc.has(key)) porDoc.set(key, []);
        porDoc.get(key).push(row);
    }
    return docs.map((d) => {
        const archivos = porDoc.get(Number(d.documento_id)) || [];
        // Compatibilidad: si no hay filas en la tabla nueva pero sí legacy, exponer uno
        if (!archivos.length && d.archivo_url && String(d.archivo_url).trim().length > 10) {
            return {
                ...d,
                archivos: [{
                    archivo_id: null,
                    documento_id: d.documento_id,
                    drive_file_id: d.archivo_url,
                    nombre_archivo: d.nombre_archivo || 'archivo',
                    mime_type: null,
                    orden: 0,
                    fecha_subida: d.fecha_subida || null
                }]
            };
        }
        return { ...d, archivos };
    });
}

/** Registra en historial un documento de PC recién aprobado (archivo o texto). */
async function registrarHistorialDocumentoAprobadoPC(documentoId) {
    const [docs] = await poolProteccionCivil.query(`
        SELECT dpc.archivo_url, dpc.nombre_archivo, dpc.nombre_documento, dpc.documento_padre_id,
               dpc.empresa_id, dpc.tipo_entrada, dpc.valor_texto, dpc.fecha_subida,
               padre.nombre_documento as nombre_padre,
               padre.especificacion as espec_padre,
               dpc.especificacion as espec_propia
        FROM documento_proteccion_civil dpc
        LEFT JOIN documento_proteccion_civil padre ON dpc.documento_padre_id = padre.documento_id
        WHERE dpc.documento_id = ?
    `, [documentoId]);

    if (docs.length === 0) return;

    const doc = docs[0];
    const esEntradaTexto = String(doc.tipo_entrada || '').toLowerCase() === 'texto';
    const valorTextoCapturado = String(doc.valor_texto || '').trim();
    const fechaCaptura = doc.fecha_subida || null;

    if (esEntradaTexto && valorTextoCapturado) {
        await poolProteccionCivil.query(`
            INSERT INTO historial_textos_pc (
                empresa_id, documento_id, documento_padre_id,
                nombre_documento_padre, nombre_campo, valor_texto,
                fecha_creacion, fecha_actualizacion
            )
            VALUES (?, ?, ?, ?, ?, ?, COALESCE(?, NOW()), COALESCE(?, NOW()))
            ON DUPLICATE KEY UPDATE
                documento_padre_id = VALUES(documento_padre_id),
                nombre_documento_padre = VALUES(nombre_documento_padre),
                nombre_campo = VALUES(nombre_campo),
                valor_texto = VALUES(valor_texto),
                fecha_actualizacion = COALESCE(?, NOW())
        `, [
            doc.empresa_id,
            documentoId,
            doc.documento_padre_id || null,
            doc.nombre_padre || doc.nombre_documento,
            doc.nombre_documento,
            valorTextoCapturado,
            fechaCaptura,
            fechaCaptura,
            fechaCaptura
        ]);
        return;
    }

    const especP = doc.espec_padre || doc.espec_propia || '';
    const tituloDocumento = especP.startsWith('carpeta_drive:')
        ? especP.replace('carpeta_drive:', '')
        : (doc.nombre_padre || doc.nombre_documento);
    const _ahora = new Date();
    const _dd = String(_ahora.getDate()).padStart(2, '0');
    const _mm = String(_ahora.getMonth() + 1).padStart(2, '0');
    const _yyyy = _ahora.getFullYear();
    const fallbackNombre = 'Documento_' + _dd + '-' + _mm + '-' + _yyyy;
    const nombreHistorialBase = String(tituloDocumento || doc.nombre_padre || doc.nombre_documento || fallbackNombre)
        .replace(/\+/g, '_')
        .trim() || fallbackNombre;

    let archivos = await listarArchivosDocumentoPC(documentoId);
    if (!archivos.length && doc.archivo_url && esDriveIdValido(doc.archivo_url)) {
        archivos = [{
            drive_file_id: doc.archivo_url,
            nombre_archivo: doc.nombre_archivo,
            mime_type: null
        }];
    }

    const mimeMap = { 'pdf': 'application/pdf', 'jpg': 'image/jpeg', 'jpeg': 'image/jpeg', 'png': 'image/png' };
    for (const archivo of archivos) {
        if (!archivo.drive_file_id || !esDriveIdValido(archivo.drive_file_id)) continue;
        const ext = (archivo.nombre_archivo || '').split('.').pop() || 'pdf';
        const mimeType = archivo.mime_type || mimeMap[ext.toLowerCase()] || 'application/octet-stream';
        await poolProteccionCivil.query(`
            INSERT INTO historial_documentos_pc (empresa_id, documento_id, nombre_documento, nombre_archivo, drive_file_id, mime_type)
            VALUES (?, ?, ?, ?, ?, ?)
            ON DUPLICATE KEY UPDATE documento_id = VALUES(documento_id), nombre_documento = VALUES(nombre_documento), nombre_archivo = VALUES(nombre_archivo), mime_type = VALUES(mime_type), fecha_actualizacion = NOW()
        `, [doc.empresa_id, documentoId, nombreHistorialBase, archivo.nombre_archivo, archivo.drive_file_id, mimeType]);
    }
}

/**
 * Notificación única de Protección Civil: avisa a admins y usuarios PC
 * que una empresa subió archivos pendientes de revisión.
 * Solo crea UNA notificación por empresa (no se repite si ya existe una sin descartar).
 */
async function notificarRevisionPC(empresaId, nombreEmpresa) {
    try {
        // Buscar usuarios administradores y proteccion_civil
        const [usuarios] = await pool.query(
            `SELECT u.id FROM usuario u
             JOIN roles r ON u.rol_id = r.rol_id
             WHERE r.nombre_rol IN ('administrador', 'proteccion_civil')`
        );
        if (!usuarios.length) return;

        const titulo = 'Protección Civil - Revisión pendiente';
        const mensaje = `Revisa los archivos de ${nombreEmpresa}`;

        for (const usr of usuarios) {
            // Verificar si ya tiene una notificación sin descartar para esta empresa
            const [existente] = await pool.query(
                `SELECT notif_id FROM notificacion_usuario
                 WHERE usuario_id = ? AND titulo = ? AND mensaje = ? AND descartada = 0
                 LIMIT 1`,
                [usr.id, titulo, mensaje]
            );
            if (existente.length > 0) continue;

            await pool.query(
                `INSERT INTO notificacion_usuario (usuario_id, tipo, icono, titulo, mensaje, ruta)
                 VALUES (?, 'warning', 'fa-shield-alt', ?, ?, '/proteccion-civil')`,
                [usr.id, titulo, mensaje]
            );
        }
    } catch (e) {
        console.error('[NOTIF] Error notif revisión PC:', e.message);
    }
}

/**
 * Notifica SOLO a usuarios de empresa cuando se asignan documentos padre de PC.
 * Crea una notificacion por cada documento padre asignado.
 */
async function notificarAsignacionPadresPCAEmpresa(empresaId, nombresPadre) {
    try {
        if (!Array.isArray(nombresPadre) || nombresPadre.length === 0) return;

        const [usuariosEmpresa] = await pool.query(
            `SELECT DISTINCT u.id
             FROM usuario u
             LEFT JOIN roles r ON u.rol_id = r.rol_id
             WHERE u.empresa_id = ?
               AND (
                    LOWER(COALESCE(r.nombre_rol, '')) = 'empresa'
                    OR LOWER(COALESCE(u.roles_adicionales, '')) LIKE '%empresa%'
               )`,
            [empresaId]
        );

        if (!usuariosEmpresa.length) return;

        for (const usr of usuariosEmpresa) {
            for (const nombrePadre of nombresPadre) {
                if (!nombrePadre) continue;
                const mensaje = `Se te asigno ${nombrePadre} para subir`;

                await pool.query(
                    `INSERT INTO notificacion_usuario (usuario_id, tipo, icono, titulo, mensaje, ruta)
                     VALUES (?, 'info', 'fa-shield-alt', 'Proteccion Civil - Documento asignado', ?, '/proteccion-civil')`,
                    [usr.id, mensaje]
                );
            }
        }
    } catch (e) {
        console.error('[NOTIF] Error notif asignacion PC empresa:', e.message);
    }
}

async function obtenerCorreosEmpresaPC(empresaId) {
    const correos = new Set();
    const rolesInternos = new Set(['root', 'administrador', 'proteccion_civil', 'admin']);

    const esRolEmpresa = (nombreRol = '', rolesAdicionales = '') => {
        const rol = String(nombreRol || '').trim().toLowerCase();
        const adicionales = String(rolesAdicionales || '').trim().toLowerCase();
        if (rolesInternos.has(rol)) return false;
        if (rolesInternos.has(adicionales)) return false;
        if (adicionales.includes('proteccion_civil') || adicionales.includes('administrador') || adicionales.includes('root')) {
            return false;
        }
        return rol === 'empresa' || adicionales.includes('empresa');
    };

    try {
        const [empresaRows] = await pool.query(
            'SELECT email, contacto_email FROM empresa WHERE empresa_id = ? LIMIT 1',
            [empresaId]
        );
        const emailEmpresa = String(empresaRows?.[0]?.email || '').trim();
        const emailContacto = String(empresaRows?.[0]?.contacto_email || '').trim();
        if (emailEmpresa) {
            correos.add(emailEmpresa.toLowerCase());
        }
        if (emailContacto) {
            correos.add(emailContacto.toLowerCase());
        }
    } catch (e) {
        // silenced
    }

    try {
        const [usuariosEmpresa] = await pool.query(
            `SELECT DISTINCT u.email, r.nombre_rol, u.roles_adicionales
             FROM usuario u
             LEFT JOIN roles r ON u.rol_id = r.rol_id
             WHERE u.empresa_id = ?
               AND u.activo = 1
               AND u.email IS NOT NULL
               AND TRIM(u.email) <> ''`,
            [empresaId]
        );

        for (const row of usuariosEmpresa) {
            if (!esRolEmpresa(row?.nombre_rol, row?.roles_adicionales)) continue;
            const email = String(row?.email || '').trim();
            if (email) {
                correos.add(email.toLowerCase());
            }
        }
    } catch (e) {
        // silenced
    }

    return Array.from(correos);
}

async function notificarAsignadorSiPadreCompletoPC(documentoId) {
    try {
        const [baseRows] = await poolProteccionCivil.query(
            `SELECT documento_id, documento_padre_id
             FROM documento_proteccion_civil
             WHERE documento_id = ?
             LIMIT 1`,
            [documentoId]
        );

        if (baseRows.length === 0) return;

        const padreId = baseRows[0].documento_padre_id || baseRows[0].documento_id;

        const [grupoRows] = await poolProteccionCivil.query(
            `SELECT documento_id, documento_padre_id, empresa_id, tipo_entrada, archivo_url, valor_texto,
                    fecha_notificacion_completado, asignado_por_usuario_id, fecha_asignacion, nombre_documento
             FROM documento_proteccion_civil
             WHERE documento_id = ? OR documento_padre_id = ?`,
            [padreId, padreId]
        );

        if (!grupoRows.length) return;

        const padre = grupoRows.find((r) => Number(r.documento_id) === Number(padreId));
        if (!padre) return;
        if (padre.fecha_notificacion_completado) return;

        const hijos = grupoRows.filter((r) => Number(r.documento_padre_id) === Number(padreId));
        const documentosObjetivo = hijos.length > 0 ? hijos : [padre];

        const todosCompletos = documentosObjetivo.every((doc) => {
            if (doc.tipo_entrada === 'texto') {
                return String(doc.valor_texto || '').trim().length > 0;
            }
            return String(doc.archivo_url || '').trim().length > 5;
        });

        if (!todosCompletos) return;

        const [updateResult] = await poolProteccionCivil.query(
            `UPDATE documento_proteccion_civil
             SET fecha_notificacion_completado = NOW(), fecha_actualizacion = NOW()
             WHERE documento_id = ? AND fecha_notificacion_completado IS NULL`,
            [padreId]
        );

        if (!updateResult || updateResult.affectedRows === 0) return;
        if (!padre.asignado_por_usuario_id) return;

        const [usuarioRows] = await pool.query(
            `SELECT u.email, u.nombre, u.apellido, r.nombre_rol
             FROM usuario u
             LEFT JOIN roles r ON u.rol_id = r.rol_id
             WHERE u.id = ?
             LIMIT 1`,
            [padre.asignado_por_usuario_id]
        );

        if (!usuarioRows.length) return;

        const emailAsignador = String(usuarioRows[0].email || '').trim();
        if (!emailAsignador) return;

        const nombreAsignador = [
            usuarioRows[0].nombre,
            usuarioRows[0].apellido
        ].filter(Boolean).join(' ').trim() || 'Equipo de Proteccion Civil';

        const [empresaRows] = await pool.query(
            'SELECT nombre_empresa FROM empresa WHERE empresa_id = ? LIMIT 1',
            [padre.empresa_id]
        );
        const nombreEmpresa = empresaRows.length > 0
            ? empresaRows[0].nombre_empresa
            : `Empresa #${padre.empresa_id}`;

        await emailService.notificarPerfilAsignadorPCDocumentosCompletados({
            perfilEmail: emailAsignador,
            perfilNombre: nombreAsignador,
            perfilRol: usuarioRows[0].nombre_rol || null,
            empresaNombre: nombreEmpresa,
            documentoPadre: padre.nombre_documento,
            totalSubdocumentos: documentosObjetivo.length,
            fechaAsignacion: padre.fecha_asignacion,
            fechaCompletado: new Date()
        });
    } catch (e) {
        console.error('[EMAIL][PC] Error notificando completado al asignador:', e.message);
    }
}

// =====================================================
// RUTAS DE AUTENTICACIÓN
// =====================================================

function usuarioTieneRolInstructor(roles = []) {
    return roles.some((rol) => String(rol).toLowerCase() === 'instructor');
}

async function buscarInstructorIdPorUsuario(db, usuarioId, instructorIdActual = null) {
    if (instructorIdActual) {
        const [validRows] = await db.query(
            'SELECT instructor_id FROM instructor WHERE instructor_id = ? AND usuario_id = ? AND activo = 1 LIMIT 1',
            [instructorIdActual, usuarioId]
        );
        if (validRows.length > 0) {
            return instructorIdActual;
        }
    }

    const [instRows] = await db.query(
        'SELECT instructor_id FROM instructor WHERE usuario_id = ? AND activo = 1 ORDER BY instructor_id DESC LIMIT 1',
        [usuarioId]
    );
    return instRows[0]?.instructor_id || null;
}

async function asignarAreasInstructorPorDefecto(db, instructorId) {
    const [areaRows] = await db.query(
        'SELECT COUNT(*) AS total FROM instructor_areas WHERE instructor_id = ?',
        [instructorId]
    );
    if (Number(areaRows[0]?.total || 0) > 0) {
        return;
    }

    const [todasAreas] = await db.query('SELECT area_id FROM area_tematica');
    if (!todasAreas.length) {
        return;
    }

    const areaValues = todasAreas.map((area) => [instructorId, area.area_id, false, new Date()]);
    await db.query(
        'INSERT INTO instructor_areas (instructor_id, area_id, certificado, created_at) VALUES ?',
        [areaValues]
    );
}

async function asegurarInstructorIdUsuario(db, usuario, roles = []) {
    if (!usuario?.id || !usuarioTieneRolInstructor(roles)) {
        return usuario?.instructor_id || null;
    }

    let instructorId = await buscarInstructorIdPorUsuario(db, usuario.id, usuario.instructor_id);

    if (!instructorId) {
        const [instResult] = await db.query(
            `INSERT INTO instructor (nombre, apellido_paterno, email, telefono, activo, usuario_id, created_at)
             VALUES (?, ?, ?, ?, TRUE, ?, NOW())`,
            [
                usuario.nombre || usuario.username || 'Instructor',
                usuario.apellido || '',
                usuario.email || '',
                usuario.telefono || '',
                usuario.id
            ]
        );
        instructorId = instResult.insertId;
        await asignarAreasInstructorPorDefecto(db, instructorId);
    }

    if (instructorId !== usuario.instructor_id) {
        await db.query('UPDATE usuario SET instructor_id = ? WHERE id = ?', [instructorId, usuario.id]);
    }

    return instructorId;
}

// Login con soporte para contraseñas hasheadas (bcrypt)
app.post('/api/login', loginLimiter, async (req, res) => {
    try {
        const { usuario, contrasena } = req.body;
        await exigirPoolPrincipal();
        await asegurarColumnaServicioProteccionCivilEmpresa(pool);

        if (!usuario || !contrasena) {
            return res.status(400).json({
                success: false,
                message: 'Usuario y contraseña son requeridos'
            });
        }

        // Buscar usuario por username (sin verificar contraseña en query)
        const [rows] = await pool.query(
            `SELECT u.id, u.username, u.clave, u.nombre, u.apellido, u.email,
                    u.telefono, u.activo, u.bloqueado, u.intentos_fallidos, u.empresa_id,
                    u.instructor_id, u.foto_drive_id, u.roles_adicionales,
                                        COALESCE(e.servicio_proteccion_civil, 1) AS empresa_servicio_proteccion_civil,
                    r.nombre_rol as rol, r.permisos
             FROM usuario u
             JOIN roles r ON u.rol_id = r.rol_id
                         LEFT JOIN empresa e ON e.empresa_id = COALESCE(
                                u.empresa_id,
                                (
                                        SELECT ex.empresa_id
                                        FROM empresa ex
                                        WHERE ex.usuario_id = u.id AND ex.activo = TRUE
                                        ORDER BY ex.empresa_id ASC
                                        LIMIT 1
                                )
                         )
             WHERE u.username = ?`,
            [usuario]
        );

        if (rows.length === 0) {
            return res.json({ success: false, message: 'Usuario o contraseña incorrectos' });
        }

        const user = rows[0];

        // Verificar si está bloqueado
        if (user.bloqueado) {
            return res.json({ success: false, message: 'Usuario bloqueado. Contacte al administrador.' });
        }

        // Verificar si está activo
        if (!user.activo) {
            return res.json({ success: false, message: 'Usuario inactivo' });
        }

        // Verificar contraseña (soporta hash bcrypt y texto plano para migración)
        let passwordValid = false;

        if (user.clave.startsWith('$2a$') || user.clave.startsWith('$2b$')) {
            passwordValid = await bcrypt.compare(contrasena, user.clave);
        } else {
            passwordValid = (user.clave === contrasena);

            if (passwordValid) {
                const hashedPassword = await bcrypt.hash(contrasena, SALT_ROUNDS);
                await pool.query('UPDATE usuario SET clave = ? WHERE id = ?', [hashedPassword, user.id]);
            }
        }

        if (!passwordValid) {
            const newAttempts = (user.intentos_fallidos || 0) + 1;
            const shouldBlock = newAttempts >= 5;

            await pool.query(
                'UPDATE usuario SET intentos_fallidos = ?, bloqueado = ? WHERE id = ?',
                [newAttempts, shouldBlock, user.id]
            );

            if (shouldBlock) {
                return res.json({
                    success: false,
                    message: 'Usuario bloqueado por múltiples intentos fallidos. Contacte al administrador.'
                });
            }

            return res.json({
                success: false,
                message: `Usuario o contraseña incorrectos. Intentos restantes: ${5 - newAttempts}`
            });
        }

        // Login exitoso - resetear intentos y actualizar último acceso
        await pool.query(
            'UPDATE usuario SET ultimo_acceso = NOW(), intentos_fallidos = 0 WHERE id = ?',
            [user.id]
        );

        // Auto-derivar empresa_id si el usuario es empresa pero no tiene empresa_id (datos legacy)
        if (!user.empresa_id && user.rol && user.rol.toLowerCase() === 'empresa') {
            // Intento 1: buscar por usuario_id en tabla empresa
            let [empresaRows] = await pool.query(
                'SELECT empresa_id FROM empresa WHERE usuario_id = ? AND activo = TRUE',
                [user.id]
            );
            // Intento 2: buscar por coincidencia de nombre (username = nombre_empresa)
            if (empresaRows.length === 0) {
                [empresaRows] = await pool.query(
                    'SELECT empresa_id FROM empresa WHERE LOWER(REPLACE(nombre_empresa, " ", "_")) = LOWER(?) AND activo = TRUE',
                    [user.username]
                );
            }
            // Intento 3: buscar por coincidencia parcial (nombre_empresa LIKE username)
            if (empresaRows.length === 0) {
                [empresaRows] = await pool.query(
                    'SELECT empresa_id FROM empresa WHERE LOWER(nombre_empresa) = LOWER(?) AND activo = TRUE',
                    [user.username]
                );
            }
            if (empresaRows.length > 0) {
                user.empresa_id = empresaRows[0].empresa_id;
                // Corregir el registro en la BD para que no pase de nuevo
                await pool.query('UPDATE usuario SET empresa_id = ? WHERE id = ?', [user.empresa_id, user.id]);
                const [empresaInfoRows] = await pool.query(
                    'SELECT COALESCE(servicio_proteccion_civil, 1) AS servicio_proteccion_civil FROM empresa WHERE empresa_id = ? LIMIT 1',
                    [user.empresa_id]
                );
                user.empresa_servicio_proteccion_civil = empresaInfoRows[0]?.servicio_proteccion_civil ?? 1;
            } else {
                // silenced
            }
        }

        // Construir array de roles (multi-rol)
        const rolesArray = [user.rol.toLowerCase()];
        if (user.roles_adicionales) {
            const adicionales = user.roles_adicionales.split(',').map(r => r.trim().toLowerCase()).filter(r => r && !rolesArray.includes(r));
            rolesArray.push(...adicionales);
        }

        // Vincular instructor_id si el usuario tiene rol instructor (principal o adicional)
        user.instructor_id = await asegurarInstructorIdUsuario(pool, user, rolesArray);

        let sgcEditorDelegado = false;
        try {
            sgcEditorDelegado = await sgcEditoresDelegadosService.esEditorDelegado(pool, user.id);
        } catch (_e) {
            sgcEditorDelegado = false;
        }

        // Generar JWT
        const tokenPayload = {
            id: user.id,
            username: user.username,
            nombre: user.nombre || null,
            apellido: user.apellido || null,
            rol: user.rol,
            roles: rolesArray,
            empresa_id: user.empresa_id || null,
            empresa_servicio_proteccion_civil: Number(user.empresa_servicio_proteccion_civil ?? 1),
            instructor_id: user.instructor_id || null
        };
        const token = jwt.sign(tokenPayload, process.env.JWT_SECRET, {
            algorithm: 'HS256',
            expiresIn: '7d' // Sesión persistente en el dispositivo (coincide con SESSION_DURATION del frontend)
        });

        res.json({
            success: true,
            message: 'Login exitoso',
            token: token,
            usuario: {
                id: user.id,
                username: user.username,
                nombre: user.nombre,
                apellido: user.apellido,
                email: user.email,
                rol: user.rol,
                roles: rolesArray,
                permisos: user.permisos,
                empresa_id: user.empresa_id,
                empresa_servicio_proteccion_civil: Number(user.empresa_servicio_proteccion_civil ?? 1),
                instructor_id: user.instructor_id || null,
                foto_drive_id: user.foto_drive_id || null,
                sgc_editor_delegado: sgcEditorDelegado
            }
        });
    } catch (error) {
        handleError(res, error, 'Error en login');
    }
});

