// Servir archivo PDF directamente desde Google Drive (requiere JWT)
app.get('/api/documentos/:documentoId/archivo', authMiddleware, async (req, res) => {
    try {
        const { documentoId } = req.params;

        // Obtener información del documento
        const [documento] = await pool.query(
            `SELECT d.archivo_nombre, d.archivo_url, c.nombre_curso, a.nombre_area
             FROM documento_curso d
             INNER JOIN curso c ON d.curso_id = c.curso_id
             INNER JOIN area_tematica a ON c.area_id = a.area_id
             WHERE d.documento_id = ?`,
            [documentoId]
        );

        if (documento.length === 0 || !documento[0].archivo_url) {
            return res.status(404).json({
                success: false,
                message: 'Archivo no encontrado'
            });
        }

        const { archivo_url, archivo_nombre } = documento[0];

        // Verificar que archivo_url sea un ID válido de Google Drive
        const esIdDriveValido = archivo_url && !archivo_url.includes('/') && !archivo_url.includes('\\');
        if (!esIdDriveValido) {
            return res.status(404).json({
                success: false,
                message: 'Este archivo tiene una referencia antigua (no está en Google Drive). Elimínelo y vuelva a subirlo.'
            });
        }

        // Obtener el archivo desde Google Drive (archivo_url ahora es drive_file_id)
        const fileBuffer = await driveService.descargarArchivo(archivo_url);

        // Determinar Content-Type según extensión del archivo
        const ext = (archivo_nombre || '').split('.').pop().toLowerCase();
        const contentTypeMap = {
            'pdf': 'application/pdf',
            'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'doc': 'application/msword',
            'xls': 'application/vnd.ms-excel',
            'png': 'image/png',
            'jpg': 'image/jpeg',
            'jpeg': 'image/jpeg'
        };
        const contentType = contentTypeMap[ext] || 'application/octet-stream';

        // Configurar headers para visualización en navegador
        res.setHeader('Content-Type', contentType);
        res.setHeader('Content-Disposition', `inline; filename="${encodeURIComponent(archivo_nombre)}"`);

        // Enviar el archivo
        res.send(fileBuffer);
    } catch (error) {
        console.error('[ERROR] Servir archivo:', error.message);
        res.status(500).json({
            success: false,
            message: 'Error al obtener el archivo',
            error: error.message
        });
    }
});

