// =====================================================
// ENDPOINT PARA IMPRIMIR ARCHIVO DE DRIVE POR fileId
// =====================================================
app.get('/api/drive/:fileId/imprimir-pdf', authMiddleware, async (req, res) => {
    try {
        const { fileId } = req.params;
        const nombreArchivo = String(req.query.filename || 'documento').trim();
        const forceLandscape = String(req.query.landscape || '').toLowerCase() === '1'
            || String(req.query.landscape || '').toLowerCase() === 'true';

        if (!fileId) {
            return res.status(400).json({
                success: false,
                message: 'fileId es requerido'
            });
        }

        let pdfBuffer = await driveService.exportarArchivoPDF(fileId, {
            landscape: forceLandscape
        });

        if (forceLandscape) {
            const { PDFDocument } = require('pdf-lib');
            const sourcePdf = await PDFDocument.load(pdfBuffer);
            const fixedPdf = await PDFDocument.create();
            const sourcePages = sourcePdf.getPages();

            for (let i = 0; i < sourcePages.length; i++) {
                const page = sourcePages[i];
                const { width, height } = page.getSize();

                if (width >= height) {
                    const [copiedPage] = await fixedPdf.copyPages(sourcePdf, [i]);
                    fixedPdf.addPage(copiedPage);
                    continue;
                }

                // Mantener contenido en orientación normal (no de lado) y cambiar lienzo a horizontal.
                const targetW = height;
                const targetH = width;
                const scale = Math.min(targetW / width, targetH / height);
                const drawW = width * scale;
                const drawH = height * scale;
                const offsetX = (targetW - drawW) / 2;
                const offsetY = (targetH - drawH) / 2;

                const targetPage = fixedPdf.addPage([targetW, targetH]);
                const embeddedPage = await fixedPdf.embedPage(page);
                targetPage.drawPage(embeddedPage, {
                    x: offsetX,
                    y: offsetY,
                    width: drawW,
                    height: drawH
                });
            }

            const fixedBytes = await fixedPdf.save();
            pdfBuffer = Buffer.from(fixedBytes);
        }
        const nombrePDF = nombreArchivo.replace(/\.[^.]+$/, '') + '.pdf';

        res.setHeader('Content-Type', 'application/pdf');
        res.setHeader('Content-Disposition', `inline; filename="${encodeURIComponent(nombrePDF)}"`);
        res.send(pdfBuffer);
    } catch (error) {
        console.error('[ERROR] Imprimir archivo Drive como PDF:', error.message);
        res.status(500).json({
            success: false,
            message: 'Error al convertir el archivo de Drive para impresión',
            error: error.message
        });
    }
});

// Descargar archivo de Drive en su formato nativo (xlsx, pdf, png, etc.)
app.get('/api/drive/:fileId/descargar', authMiddleware, async (req, res) => {
    try {
        const fileId = String(req.params.fileId || '').trim();
        if (!fileId || !/^[a-zA-Z0-9_-]{10,}$/.test(fileId)) {
            return res.status(400).json({ success: false, message: 'fileId inválido' });
        }

        const nombreRaw = String(req.query.filename || req.query.nombre || 'archivo').trim();
        const descargado = await driveService.descargarArchivoNativo(fileId, nombreRaw);
        const nombreSeguro = String(descargado.filename || nombreRaw || 'archivo')
            .replace(/[\r\n"\\/:*?<>|]+/g, '_')
            .replace(/[^a-zA-Z0-9._\- \u00C0-\u024F]+/g, '_')
            || 'archivo';

        res.setHeader('Content-Type', descargado.contentType || 'application/octet-stream');
        res.setHeader('Content-Disposition', `attachment; filename="${nombreSeguro}"`);
        res.setHeader('Cache-Control', 'private, max-age=60');
        return res.send(Buffer.from(descargado.buffer));
    } catch (error) {
        console.error('[ERROR] Descargar archivo Drive:', error.message);
        return res.status(500).json({
            success: false,
            message: error.message || 'No se pudo descargar el archivo solicitado.'
        });
    }
});

// Asegura Google Sheet nativo (convierte XLSX de Office si hace falta) para editor integrado
app.post('/api/drive/:fileId/asegurar-google-sheet', authMiddleware, async (req, res) => {
    try {
        const fileId = String(req.params.fileId || '').trim();
        if (!fileId || !/^[a-zA-Z0-9_-]{10,}$/.test(fileId)) {
            return res.status(400).json({ success: false, message: 'fileId inválido' });
        }

        const nombreSugerido = String(req.body?.nombre || req.body?.filename || '').trim();
        const programadoId = Number(req.body?.programado_id || req.body?.programadoId || 0) || null;

        const convertido = await driveService.convertirOfficeExcelAGoogleSheet(fileId, {
            nombre: nombreSugerido || undefined,
            eliminarOriginal: true
        });

        const nuevoId = String(convertido?.id || fileId).trim();
        const mimeType = String(convertido?.mimeType || 'application/vnd.google-apps.spreadsheet');
        const webViewLink = convertido?.webViewLink
            || `https://docs.google.com/spreadsheets/d/${nuevoId}/edit`;
        const editorUrl = `https://docs.google.com/spreadsheets/d/${encodeURIComponent(nuevoId)}/edit?usp=sharing`;
        const convertidoAhora = nuevoId !== fileId;

        if (convertidoAhora) {
            try {
                const params = [nuevoId, webViewLink, fileId];
                let sql = `UPDATE documento_curso_programado
                           SET drive_file_id = ?, archivo_url = ?
                           WHERE drive_file_id = ?`;
                if (programadoId) {
                    sql += ' AND programado_id = ?';
                    params.push(programadoId);
                }
                await pool.query(sql, params);
            } catch (dbErr) {
                console.warn('[WARN] No se pudo actualizar drive_file_id tras conversión a Google Sheet:', dbErr.message);
            }
        }

        return res.json({
            success: true,
            convertido: convertidoAhora,
            fileId: nuevoId,
            drive_file_id: nuevoId,
            mimeType,
            nombre: convertido?.name || nombreSugerido || null,
            webViewLink,
            editorUrl
        });
    } catch (error) {
        console.error('[ERROR] Asegurar Google Sheet:', error.message);
        return res.status(500).json({
            success: false,
            message: error.message || 'No se pudo preparar el Google Sheet para edición.'
        });
    }
});

// Obtener examen diagnóstico de un curso programado (requiere JWT)
app.get('/api/cursos-programados/:programadoId/examen-diagnostico', authMiddleware, async (req, res) => {
    try {
        const { programadoId } = req.params;

        // Obtener el curso_id del curso programado
        const [cursoProgramado] = await pool.query(
            'SELECT curso_id FROM curso_programado WHERE programado_id = ?',
            [programadoId]
        );

        if (cursoProgramado.length === 0) {
            return res.status(404).json({
                success: false,
                message: 'Curso programado no encontrado'
            });
        }

        const cursoId = cursoProgramado[0].curso_id;

        // Buscar el examen diagnóstico de ese curso
        const [examen] = await pool.query(`
            SELECT
                dc.documento_id,
                dc.curso_id,
                dc.nombre,
                dc.descripcion,
                dc.tipo_aceptado,
                dc.archivo_nombre,
                dc.archivo_url,
                dc.fecha_subida,
                dc.tamano,
                c.nombre_curso,
                a.nombre_area
            FROM documento_curso dc
            JOIN curso c ON dc.curso_id = c.curso_id
            JOIN area_tematica a ON c.area_id = a.area_id
            WHERE dc.curso_id = ?
            AND dc.nombre LIKE '%Examen Diagnostico%'
            AND dc.activo = TRUE
        `, [cursoId]);

        if (examen.length === 0) {
            return res.json({
                success: false,
                message: 'No se encontró examen diagnóstico para este curso',
                existe: false
            });
        }

        const examenDoc = examen[0];
        const tieneArchivo = examenDoc.archivo_url != null && examenDoc.archivo_url !== '';

        res.json({
            success: true,
            existe: true,
            tieneArchivo: tieneArchivo,
            examen: {
                documento_id: examenDoc.documento_id,
                curso_id: examenDoc.curso_id,
                nombre: examenDoc.nombre,
                descripcion: examenDoc.descripcion,
                archivo_nombre: examenDoc.archivo_nombre,
                archivo_url: examenDoc.archivo_url,
                fecha_subida: examenDoc.fecha_subida,
                tamano: examenDoc.tamano,
                nombre_curso: examenDoc.nombre_curso,
                nombre_area: examenDoc.nombre_area
            }
        });
    } catch (error) {
        handleError(res, error, 'Error al obtener examen diagnóstico');
    }
});

// Obtener documento de un curso programado por tipo/nombre (requiere JWT)
app.get('/api/cursos-programados/:programadoId/documento', authMiddleware, async (req, res) => {
    try {
        const { programadoId } = req.params;
        const { tipo } = req.query; // ej: "Examen Diagnostico", "Lista de Verificación", etc.

        if (!tipo) {
            return res.status(400).json({ success: false, message: 'Parámetro "tipo" requerido' });
        }

        // Obtener el curso_id del curso programado
        const [cursoProgramado] = await pool.query(
            'SELECT curso_id FROM curso_programado WHERE programado_id = ?',
            [programadoId]
        );

        if (cursoProgramado.length === 0) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
        }

        const cursoId = cursoProgramado[0].curso_id;

        // Buscar el documento que coincida con el tipo solicitado
        // Normalizamos quitando tildes para búsqueda flexible
        const tipoNormalizado = tipo.normalize('NFD').replace(/[\u0300-\u036f]/g, '');
        const [docs] = await pool.query(`
            SELECT
                dc.documento_id, dc.curso_id, dc.nombre, dc.descripcion,
                dc.tipo_aceptado, dc.archivo_nombre, dc.archivo_url,
                dc.fecha_subida, dc.tamano,
                c.nombre_curso, a.nombre_area
            FROM documento_curso dc
            JOIN curso c ON dc.curso_id = c.curso_id
            JOIN area_tematica a ON c.area_id = a.area_id
            WHERE dc.curso_id = ? AND dc.activo = TRUE
        `, [cursoId]);

        // Buscar coincidencia flexible por nombre
        const doc = docs.find(d => {
            const nombreNorm = d.nombre.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase();
            return nombreNorm.includes(tipoNormalizado.toLowerCase());
        });

        if (!doc) {
            return res.json({
                success: false,
                existe: false,
                message: `No se encontró documento "${tipo}" para este curso`,
                documentosDisponibles: docs.map(d => d.nombre)
            });
        }

        const tieneArchivo = doc.archivo_url != null && doc.archivo_url !== '';
        res.json({
            success: true,
            existe: true,
            tieneArchivo,
            documento: {
                documento_id: doc.documento_id,
                curso_id: doc.curso_id,
                nombre: doc.nombre,
                descripcion: doc.descripcion,
                archivo_nombre: doc.archivo_nombre,
                archivo_url: doc.archivo_url,
                fecha_subida: doc.fecha_subida,
                tamano: doc.tamano,
                nombre_curso: doc.nombre_curso,
                nombre_area: doc.nombre_area
            }
        });
    } catch (error) {
        handleError(res, error, 'Error al obtener documento del curso');
    }
});

