// Obtener historial de cursos completados para un curso_id (para la pestaña Historial en info general)
app.get('/api/cursos/:cursoId/historial-completados', authMiddleware, async (req, res) => {
    try {
        const { cursoId } = req.params;

        const [rows] = await pool.query(`
            SELECT cp.programado_id, cp.curso_id, cp.empresa_id, cp.instructor_id,
                   cp.fecha_inicio, cp.fecha_fin, cp.modalidad, cp.ubicacion,
                   cp.estado, cp.ciudad, cp.localidad, cp.estatus,
                   e.nombre_empresa,
                   c.nombre_curso,
                   CONCAT_WS(' ', i.nombre, i.apellido_paterno) AS instructor_nombre,
                   (SELECT COUNT(*) FROM inscripcion_curso ins WHERE ins.programado_id = cp.programado_id) AS total_participantes
            FROM curso_programado cp
            INNER JOIN empresa e ON e.empresa_id = cp.empresa_id
            INNER JOIN curso c ON c.curso_id = cp.curso_id
            LEFT JOIN instructor i ON i.instructor_id = cp.instructor_id
            WHERE cp.curso_id = ?
              AND ${sqlCursoProgramadoImpartido('cp')}
            ORDER BY cp.fecha_inicio DESC
        `, [cursoId]);

        const historial = await armarHistorialProgramadosConDocumentos(rows);
        res.json({ success: true, historial });
    } catch (error) {
        handleError(res, error, 'Error al obtener historial de cursos completados');
    }
});

