app.get('/api/cursos-programados/:programadoId/documentos-drive', authMiddleware, async (req, res) => {
    try {
        const { programadoId } = req.params;

        // Obtener datos del curso para construir el nombre de la carpeta
        const [rows] = await pool.query(`
            SELECT cp.fecha_inicio, c.nombre_curso, e.nombre_empresa
            FROM curso_programado cp
            INNER JOIN curso c ON c.curso_id = cp.curso_id
            INNER JOIN empresa e ON e.empresa_id = cp.empresa_id
            WHERE cp.programado_id = ?
            LIMIT 1
        `, [programadoId]);

        if (rows.length === 0) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
        }

        const { nombre_empresa, nombre_curso, fecha_inicio } = rows[0];

        const resultado = await driveService.crearCarpetaCapacitacion(nombre_empresa, nombre_curso, fecha_inicio);
        if (!resultado.success) {
            return res.json({ success: true, carpetas: [], message: 'No se encontró la carpeta en Drive' });
        }

        const subcarpetas = await driveService.listarSubcarpetas(resultado.folderId);
        const carpetasConArchivos = [];
        const nombreRegistrosBorrados = 'registros borrados';

        for (const sub of subcarpetas) {
            const nombreNorm = String(sub.name || '')
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .toLowerCase()
                .trim();
            // No exponer archivos dados de baja en Información General
            if (nombreNorm === nombreRegistrosBorrados) {
                continue;
            }

            const archivos = await driveService.listarArchivosCarpeta(sub.id);
            if (archivos.length > 0) {
                carpetasConArchivos.push({
                    nombre: sub.name,
                    folderId: sub.id,
                    archivos: archivos.map(a => ({
                        id: a.id,
                        nombre: a.name,
                        mimeType: a.mimeType,
                        size: a.size,
                        fechaModificacion: a.modifiedTime,
                        webViewLink: a.webViewLink,
                        webContentLink: a.webContentLink
                    }))
                });
            }
        }

        // También listar archivos en la raíz de la carpeta (si hay)
        const archivosRaiz = await driveService.listarArchivosCarpeta(resultado.folderId);
        if (archivosRaiz.length > 0) {
            carpetasConArchivos.unshift({
                nombre: 'General',
                folderId: resultado.folderId,
                archivos: archivosRaiz.map(a => ({
                    id: a.id,
                    nombre: a.name,
                    mimeType: a.mimeType,
                    size: a.size,
                    fechaModificacion: a.modifiedTime,
                    webViewLink: a.webViewLink,
                    webContentLink: a.webContentLink
                }))
            });
        }

        res.json({
            success: true,
            carpetaDrive: resultado.path,
            carpetas: carpetasConArchivos,
            totalArchivos: carpetasConArchivos.reduce((sum, c) => sum + c.archivos.length, 0)
        });
    } catch (error) {
        handleError(res, error, 'Error al listar documentos de Drive');
    }
});

// Proxy para servir firma de doctor desde Google Drive (evita CORS en html2canvas)
// Se coloca ANTES del authMiddleware para que <img> pueda acceder sin JWT.
// SEGURIDAD: solo se sirven driveId que estén registrados en BD como firma de
// un usuario/instructor activo. Esto impide enumerar archivos arbitrarios de Drive.
app.get('/api/firma-doctor/:driveId', async (req, res) => {
    try {
        const driveId = String(req.params.driveId || '').trim();
        if (!driveId || !/^[a-zA-Z0-9_-]+$/.test(driveId)) {
            return res.status(400).json({ success: false, message: 'driveId inválido' });
        }

        // Whitelist: el driveId debe ser una firma conocida en BD
        const [registrado] = await pool.query(
            `SELECT 1 AS ok FROM (
                SELECT firma_drive_id FROM usuario WHERE firma_drive_id = ?
                UNION ALL
                SELECT firma_drive_id FROM instructor WHERE firma_drive_id = ?
             ) t LIMIT 1`,
            [driveId, driveId]
        );

        if (!registrado || registrado.length === 0) {
            return res.status(404).json({ success: false, message: 'Firma no encontrada' });
        }

        const buffer = await driveService.descargarArchivo(driveId);
        res.set('Content-Type', 'image/png');
        res.set('Cache-Control', 'no-store, no-cache, must-revalidate, proxy-revalidate');
        res.set('Pragma', 'no-cache');
        res.set('Expires', '0');
        res.send(buffer);
    } catch (error) {
        console.error('[ERROR] Proxy firma doctor:', error.message);
        res.status(404).json({ success: false, message: 'Firma no encontrada' });
    }
});

// Cache en memoria para drive-preview (TTL 60s) que reduce queries repetidas
// para imágenes que aparecen muchas veces en una pantalla.
const drivePreviewWhitelistCache = new Map();
const DRIVE_PREVIEW_CACHE_TTL_MS = 60 * 1000;

async function esDriveIdConocido(driveId) {
    const cached = drivePreviewWhitelistCache.get(driveId);
    if (cached && cached.expiresAt > Date.now()) {
        return cached.value;
    }

    // Limpiar cache demasiado grande
    if (drivePreviewWhitelistCache.size > 5000) {
        drivePreviewWhitelistCache.clear();
    }

    let conocido = false;

    // Tablas BD principal
    try {
        const likeId   = `%id=${driveId}%`;
        const likePath1 = `%/d/${driveId}/%`;
        const likePath2 = `%/d/${driveId}?%`;
        const likePath3 = `%/d/${driveId}%`;
        const [r1] = await pool.query(
            `SELECT 1 AS ok FROM (
                SELECT foto_drive_id AS d FROM usuario WHERE foto_drive_id = ?
                UNION ALL SELECT firma_drive_id FROM usuario WHERE firma_drive_id = ?
                UNION ALL SELECT firma_drive_id FROM instructor WHERE firma_drive_id = ?
                UNION ALL SELECT 1 FROM empresa WHERE
                    logo = ? OR logo LIKE ? OR logo LIKE ? OR logo LIKE ? OR logo LIKE ?
                UNION ALL SELECT drive_file_id FROM documento_curso_programado WHERE drive_file_id = ?
                UNION ALL SELECT archivo_url FROM documento_curso WHERE archivo_url = ?
             ) t LIMIT 1`,
            [driveId, driveId, driveId, driveId, likeId, likePath1, likePath2, likePath3, driveId, driveId]
        );
        if (r1 && r1.length > 0) conocido = true;
    } catch (_e) {
        console.warn('[DRIVE-WHITELIST] Error en query whitelist:', _e.message);
    }

    // Tabla de Protección Civil (BD independiente)
        if (!conocido && poolProteccionCivil) {
        try {
            const likeDriveId = `%${driveId}%`;
            const [r2] = await poolProteccionCivil.query(
                `SELECT 1 FROM documento_proteccion_civil
                 WHERE archivo_url = ? OR archivo_url LIKE ?
                 UNION ALL SELECT 1 FROM pc_catalogo_documento WHERE drive_file_id = ?
                 LIMIT 1`,
                [driveId, likeDriveId, driveId]
            );
            if (r2 && r2.length > 0) conocido = true;
        } catch (_e) {
            // silenced
        }
    }

    if (!conocido && poolBiznagaSgc) {
        try {
            const [r3] = await poolBiznagaSgc.query(
                `SELECT 1 FROM ambiental_control_oficios
                 WHERE documento_drive_id = ? AND activo = 1
                 LIMIT 1`,
                [driveId]
            );
            if (r3 && r3.length > 0) conocido = true;
        } catch (_e) {
            // silenced
        }
        if (!conocido) {
            try {
                const [r4] = await poolBiznagaSgc.query(
                    `SELECT 1 FROM ambiental_control_tramites
                     WHERE activo = 1 AND documento_drive_id = ?
                     LIMIT 1`,
                    [driveId]
                );
                if (r4 && r4.length > 0) conocido = true;
            } catch (_e) {
                // silenced
            }
        }
        if (!conocido) {
            try {
                const [r5] = await poolBiznagaSgc.query(
                    `SELECT 1 FROM ambiental_control_tramites
                     WHERE activo = 1 AND contestacion_drive_id = ?
                     LIMIT 1`,
                    [driveId]
                );
                if (r5 && r5.length > 0) conocido = true;
            } catch (_e) {
                // silenced (columna puede no existir aún)
            }
        }
        if (!conocido) {
            try {
                const [r6] = await poolBiznagaSgc.query(
                    `SELECT 1 FROM ambiental_tramite_archivos
                     WHERE drive_file_id = ?
                     LIMIT 1`,
                    [driveId]
                );
                if (r6 && r6.length > 0) conocido = true;
            } catch (_e) {
                // silenced (la tabla se crea al iniciar el módulo ambiental)
            }
        }
    }

    // Evidencias de Mantenimiento (carpeta Drive, sin fila en BD)
    if (!conocido) {
        const carpetaMant =
            process.env.MANTENIMIENTO_DRIVE_FOLDER_ID || '1PSzlU-LIr4wkCZANDgDIchY6lASsPue8';
        try {
            conocido = await driveService.perteneceACarpetaAncestral(driveId, carpetaMant);
        } catch (_e) {
            // silenced
        }
    }

    drivePreviewWhitelistCache.set(driveId, {
        value: conocido,
        expiresAt: Date.now() + DRIVE_PREVIEW_CACHE_TTL_MS
    });

    return conocido;
}

// Proxy para previsualizar imágenes de evidencia desde Google Drive
// Se expone antes de auth para permitir <img src="..."> sin JWT explícito.
// SEGURIDAD: solo se sirve si el driveId está registrado en BD (whitelist).
app.get('/api/drive-preview/:driveId', async (req, res) => {
    try {
        const driveId = String(req.params.driveId || '').trim();
        if (!driveId || !/^[a-zA-Z0-9_-]+$/.test(driveId)) {
            return res.status(400).json({ success: false, message: 'driveId inválido' });
        }

        const conocido = await esDriveIdConocido(driveId);
        if (!conocido) {
            return res.status(404).json({ success: false, message: 'Recurso no encontrado' });
        }

        const buffer = await driveService.descargarArchivo(driveId);
        if (!buffer || buffer.length === 0) {
            return res.status(404).json({ success: false, message: 'Archivo no encontrado' });
        }

        let mimeType = 'application/octet-stream';
        if (buffer.length >= 8 && buffer[0] === 0x89 && buffer[1] === 0x50 && buffer[2] === 0x4e && buffer[3] === 0x47) {
            mimeType = 'image/png';
        } else if (buffer.length >= 3 && buffer[0] === 0xff && buffer[1] === 0xd8 && buffer[2] === 0xff) {
            mimeType = 'image/jpeg';
        } else if (buffer.length >= 4 && buffer.toString('ascii', 0, 4) === '%PDF') {
            mimeType = 'application/pdf';
        } else if (buffer.length >= 6) {
            const header6 = buffer.toString('ascii', 0, 6);
            if (header6 === 'GIF87a' || header6 === 'GIF89a') {
                mimeType = 'image/gif';
            }
        }

        res.set('Content-Type', mimeType);
        const esImagenOPdf = mimeType.startsWith('image/') || mimeType === 'application/pdf';
        res.set('Cache-Control', esImagenOPdf ? 'private, max-age=3600' : 'no-store, no-cache, must-revalidate');
        if (esImagenOPdf) {
            res.set('Content-Disposition', 'inline');
            // Permitir iframe desde el frontend; no enviar X-Frame-Options (usa CSP).
            res.removeHeader('X-Frame-Options');
            const frameAncestors = (process.env.CORS_ORIGINS || 'http://localhost:4200,http://localhost:4201')
                .split(',')
                .map((s) => s.trim())
                .filter(Boolean)
                .join(' ');
            res.set('Content-Security-Policy', `frame-ancestors 'self' ${frameAncestors}`);
        } else {
            res.set('X-Frame-Options', 'DENY');
            res.set('Content-Security-Policy', "frame-ancestors 'none'");
        }
        if (!esImagenOPdf) {
            res.set('Pragma', 'no-cache');
            res.set('Expires', '0');
        }
        return res.send(buffer);
    } catch (error) {
        // 404 en drive-preview es esperado (logos eliminados, archivos borrados, etc.) — no loguear
        if (error?.code !== 404 && !error?.message?.includes('404') && !error?.message?.includes('not found')) {
            console.error('[ERROR] Proxy drive-preview:', error.message);
        }
        return res.status(404).json({ success: false, message: 'No se pudo previsualizar el archivo' });
    }
});

