// Versión de la app (pública): permite al frontend detectar despliegues nuevos
// y avisar al usuario que actualice la página.
// En producción solo se despliega /backend, así que la versión canónica va en
// app-version.json (generado por deploy.ps1 desde el package.json raíz).
let cachedAppVersion = null;
let appVersionResolved = false;

function resolveAppVersion() {
    if (appVersionResolved) {
        return cachedAppVersion;
    }
    appVersionResolved = true;

    const candidates = [
        path.join(__dirname, 'app-version.json'),
        path.join(__dirname, '..', 'package.json')
    ];

    for (const candidate of candidates) {
        try {
            if (!fs.existsSync(candidate)) {
                continue;
            }
            const pkg = JSON.parse(fs.readFileSync(candidate, 'utf8'));
            const version = String(pkg.version || '').trim();
            if (version) {
                cachedAppVersion = version;
                return cachedAppVersion;
            }
        } catch (error) {
            console.error('[VERSION] Error leyendo', candidate + ':', error?.message || error);
        }
    }

    console.error('[VERSION] No se pudo resolver la versión (app-version.json / package.json raíz)');
    return null;
}

app.get('/api/version', (_req, res) => {
    const version = resolveAppVersion();
    if (!version) {
        return res.status(500).json({
            success: false,
            message: 'No se pudo obtener la versión'
        });
    }
    return res.json({
        success: true,
        version
    });
});

