// Obtener aviso de privacidad para perfil empresa (Google Drive inline preview)
app.get('/api/empresa/aviso-privacidad', requireRole('empresa'), async (req, res) => {
    try {
        const userRoles = Array.isArray(req.user?.roles)
            ? req.user.roles.map(r => String(r).toLowerCase())
            : (req.user?.rol ? [String(req.user.rol).toLowerCase()] : []);

        if (!userRoles.includes('empresa')) {
            return res.status(403).json({
                success: false,
                message: 'Este recurso solo esta disponible para el perfil empresa'
            });
        }

        const NOMBRE_ARCHIVO = 'SGC-F-23 Aviso de privacidad de datos personales (Biznaga)';
        const AVISO_PRIVACIDAD_URL_DEFAULT = 'https://drive.google.com/file/d/1aUgJAt-rxPH5BYP5zsO1PcfTbc1bvetQ/view?usp=drive_link';

        const avisoConfiguradoId = extraerDriveIdDesdeUrl(
            process.env.DRIVE_AVISO_PRIVACIDAD_ID
            || process.env.DRIVE_AVISO_PRIVACIDAD_URL
            || AVISO_PRIVACIDAD_URL_DEFAULT
        );

        // Si hay ID configurado, se usa directo para desacoplar el flujo de una carpeta fija en Drive.
        if (avisoConfiguradoId) {
            return res.json({
                success: true,
                driveFileId: avisoConfiguradoId,
                nombre: NOMBRE_ARCHIVO,
                mimeType: 'application/pdf',
                size: null,
                previewUrl: `https://drive.google.com/file/d/${avisoConfiguradoId}/preview`
            });
        }

        // Respaldo: búsqueda global por nombre para soportar cambios de ubicación (ej. carpeta "Documentación").
        let archivoAviso = await driveService.buscarArchivoGlobal(NOMBRE_ARCHIVO);

        // Fallback por si en Drive está guardado con extensión
        if (!archivoAviso || !archivoAviso.id) {
            archivoAviso = await driveService.buscarArchivoGlobal(`${NOMBRE_ARCHIVO}.pdf`);
        }

        if (!archivoAviso || !archivoAviso.id) {
            return res.status(404).json({
                success: false,
                message: `No se encontro el archivo ${NOMBRE_ARCHIVO} en Google Drive (ni por configuracion directa ni por busqueda global)`
            });
        }

        return res.json({
            success: true,
            driveFileId: archivoAviso.id,
            nombre: archivoAviso.name,
            mimeType: archivoAviso.mimeType,
            size: archivoAviso.size,
            previewUrl: `https://drive.google.com/file/d/${archivoAviso.id}/preview`
        });
    } catch (error) {
        return handleError(res, error, 'Error al obtener aviso de privacidad de Google Drive');
    }
});

