// Verificar contraseña del usuario actual (para confirmaciones de acciones críticas)
app.post('/api/verificar-password', loginLimiter, async (req, res) => {
    try {
        const { password } = req.body;

        if (!password) {
            return res.status(400).json({
                success: false,
                message: 'La contraseña es requerida'
            });
        }

        // Solo verificar la contraseña del usuario autenticado (req.user viene del authMiddleware)
        const [rows] = await pool.query(
            'SELECT id, clave FROM usuario WHERE id = ?',
            [req.user.id]
        );

        if (rows.length === 0) {
            return res.json({ success: false, message: 'Usuario no encontrado' });
        }

        const user = rows[0];
        let passwordValid = false;

        if (user.clave.startsWith('$2a$') || user.clave.startsWith('$2b$')) {
            passwordValid = await bcrypt.compare(password, user.clave);
        } else {
            passwordValid = (user.clave === password);
        }

        if (passwordValid) {
            res.json({ success: true, message: 'Contraseña verificada' });
        } else {
            res.json({ success: false, message: 'Contraseña incorrecta' });
        }
    } catch (error) {
        handleError(res, error, 'Error al verificar contraseña');
    }
});

