// Sugerencias de correos (usuarios + correos personales del usuario actual)
app.get('/api/usuarios/correos-sugeridos', async (req, res) => {
    try {
        await asegurarColumnaCorreosPersonales(pool);

        const limitRaw = Number(req.query.limit);
        const limit = Number.isFinite(limitRaw)
            ? Math.min(Math.max(limitRaw, 10), 500)
            : 200;

                const [rows] = await pool.query(
                        `SELECT u.email, u.nombre, u.apellido, u.foto_drive_id, u.foto_url, u.avatar_url,
                                        e.logo AS empresa_logo, e.nombre_empresa
                         FROM usuario u
                         LEFT JOIN empresa e ON e.empresa_id = COALESCE(
                                u.empresa_id,
                                (
                                        SELECT ex.empresa_id
                                        FROM empresa ex
                                        WHERE ex.usuario_id = u.id AND ex.activo = TRUE
                                        ORDER BY ex.empresa_id ASC
                                        LIMIT 1
                                )
                         )
                         WHERE u.email IS NOT NULL
                             AND TRIM(u.email) <> ''
                         ORDER BY u.nombre, u.apellido
                         LIMIT ?`,
                        [limit]
                );

        const sugerenciasMap = new Map();

        for (const row of rows) {
            const email = String(row?.email || '').trim().toLowerCase();
            if (!email || sugerenciasMap.has(email)) continue;
            const nombreCompleto = `${row?.nombre || ''} ${row?.apellido || ''}`.trim();
            sugerenciasMap.set(email, {
                email,
                nombre: nombreCompleto || null,
                origen: 'usuario',
                foto_drive_id: row?.foto_drive_id || null,
                foto_url: row?.foto_url || row?.avatar_url || null,
                empresa_logo: row?.empresa_logo || null,
                empresa_nombre: row?.nombre_empresa || null
            });
        }

        const usuarioId = Number(req.user?.id || 0);
        if (usuarioId) {
            const [personalRows] = await pool.query(
                'SELECT correos_personales FROM usuario WHERE id = ? LIMIT 1',
                [usuarioId]
            );
            const correosPersonales = parseCorreosCredencialesExtra(personalRows?.[0]?.correos_personales);
            for (const correo of correosPersonales) {
                if (!correo || sugerenciasMap.has(correo)) continue;
                sugerenciasMap.set(correo, {
                    email: correo,
                    nombre: null,
                    origen: 'personal'
                });
            }
        }

        const sugerencias = Array.from(sugerenciasMap.values()).sort((a, b) => {
            const aKey = `${a.nombre || ''} ${a.email}`.trim().toLowerCase();
            const bKey = `${b.nombre || ''} ${b.email}`.trim().toLowerCase();
            return aKey.localeCompare(bKey, 'es', { sensitivity: 'base' });
        });

        res.json({ success: true, sugerencias });
    } catch (error) {
        handleError(res, error, 'Error al obtener sugerencias de correo');
    }
});

// Guardar correos personales para el usuario autenticado
app.post('/api/usuarios/correos-personales', async (req, res) => {
    try {
        await asegurarColumnaCorreosPersonales(pool);

        const usuarioId = Number(req.user?.id || 0);
        if (!usuarioId) {
            return res.status(401).json({ success: false, message: 'Usuario autenticado no valido' });
        }

        const payloadCorreos = req.body?.correos ?? req.body?.emails ?? req.body?.correo ?? req.body;
        const correosNuevos = parseCorreosCredencialesExtra(payloadCorreos);
        if (correosNuevos.length === 0) {
            return res.json({ success: true, correos_personales: [] });
        }

        const [rows] = await pool.query(
            'SELECT correos_personales FROM usuario WHERE id = ? LIMIT 1',
            [usuarioId]
        );

        const correosActuales = parseCorreosCredencialesExtra(rows?.[0]?.correos_personales);
        const combinados = Array.from(new Set([...correosActuales, ...correosNuevos]));
        const valorGuardar = combinados.length > 0 ? combinados.join(',') : null;

        await pool.query(
            'UPDATE usuario SET correos_personales = ? WHERE id = ?',
            [valorGuardar, usuarioId]
        );

        res.json({ success: true, correos_personales: combinados });
    } catch (error) {
        handleError(res, error, 'Error al guardar correos personales');
    }
});

// Obtener todos los usuarios (excluye usuarios root por seguridad)
// Incluye las áreas temáticas para instructores y nombre de empresa para usuarios empresa
app.get('/api/usuarios', async (req, res) => {
    let puestoEmpresaExpr = 'NULL';
    try {
        await asegurarColumnaServicioProteccionCivilEmpresa(pool);
        await asegurarColumnaPuestoEmpresa(pool);
        await asegurarColumnaColaboradorEmpresa(pool);
        await asegurarColumnaOrganigramaUsuario(pool);
        await asegurarColumnaAreaDepartamentoUsuario(pool);
        puestoEmpresaExpr = await obtenerExpresionPuestoEmpresa(pool, 'e');
        const [rows] = await pool.query(
            `SELECT u.id, u.username, u.nombre, u.apellido, u.email, u.telefono,
                    u.organigrama,
                    u.area_departamento,
                    u.activo, u.bloqueado, u.ultimo_acceso, r.nombre_rol as rol, r.rol_id,
                    COALESCE(u.empresa_id, e.empresa_id) AS empresa_id, e.nombre_empresa, e.logo AS empresa_logo,
                    COALESCE(e.servicio_proteccion_civil, 1) AS empresa_servicio_proteccion_civil,
                    e.colaborador AS empresa_colaborador,
                    MAX(${puestoEmpresaExpr}) AS empresa_puesto,
                    u.roles_adicionales,
                    GROUP_CONCAT(DISTINCT at.nombre_area ORDER BY at.nombre_area SEPARATOR ', ') as areas,
                    GROUP_CONCAT(DISTINCT at.area_id ORDER BY at.area_id) as areas_ids,
                    i.instructor_id,
                    COALESCE(i.firma_url,  u.firma_url)      AS firma_url,
                    COALESCE(i.firma_drive_id, u.firma_drive_id) AS firma_drive_id,
                    u.foto_url, u.foto_drive_id
             FROM usuario u
             JOIN roles r ON u.rol_id = r.rol_id
             LEFT JOIN empresa e ON e.empresa_id = COALESCE(
                u.empresa_id,
                (
                    SELECT ex.empresa_id
                    FROM empresa ex
                    WHERE ex.usuario_id = u.id AND ex.activo = TRUE
                    ORDER BY ex.empresa_id ASC
                    LIMIT 1
                )
             )
             LEFT JOIN instructor i ON u.id = i.usuario_id AND i.activo = 1
             LEFT JOIN instructor_areas ia ON i.instructor_id = ia.instructor_id
             LEFT JOIN area_tematica at ON ia.area_id = at.area_id AND at.activo = 1
             WHERE r.nombre_rol != 'root' AND u.activo = 1
             GROUP BY u.id, u.username, u.nombre, u.apellido, u.email, u.telefono,
                      u.organigrama, u.area_departamento,
                      u.activo, u.bloqueado, u.ultimo_acceso, r.nombre_rol, r.rol_id,
                      COALESCE(u.empresa_id, e.empresa_id), e.nombre_empresa, e.logo, i.instructor_id, i.firma_url, i.firma_drive_id,
                      e.servicio_proteccion_civil, e.colaborador,
                      u.firma_url, u.firma_drive_id, u.foto_url, u.foto_drive_id, u.roles_adicionales
             ORDER BY u.nombre`
        );


        res.json({ success: true, usuarios: rows });
    } catch (error) {
        console.error('[ERROR] Error al obtener usuarios:', error.message);
        if (error.code === 'ER_NO_SUCH_TABLE') {
            const [rows] = await pool.query(
                `SELECT u.id, u.username, u.nombre, u.apellido, u.email, u.telefono,
                        u.activo, u.bloqueado, u.ultimo_acceso, r.nombre_rol as rol, r.rol_id,
                    COALESCE(u.empresa_id, e.empresa_id) AS empresa_id, e.nombre_empresa, e.logo AS empresa_logo,
                    COALESCE(e.servicio_proteccion_civil, 1) AS empresa_servicio_proteccion_civil,
                    e.colaborador AS empresa_colaborador,
                    ${puestoEmpresaExpr} AS empresa_puesto
                 FROM usuario u
                 JOIN roles r ON u.rol_id = r.rol_id
                 LEFT JOIN empresa e ON e.empresa_id = COALESCE(
                    u.empresa_id,
                    (
                        SELECT ex.empresa_id
                        FROM empresa ex
                        WHERE ex.usuario_id = u.id AND ex.activo = TRUE
                        ORDER BY ex.empresa_id ASC
                        LIMIT 1
                    )
                 )
                 WHERE r.nombre_rol != 'root' AND u.activo = 1
                 ORDER BY u.nombre`
            );
            res.json({ success: true, usuarios: rows });
        } else {
            handleError(res, error);
        }
    }
});

// Obtener usuario por ID (no permite obtener usuarios root)
// SEGURIDAD: solo admin/root o el propio usuario pueden ver el detalle.
// Nunca se expone el hash de la contraseña ni los intentos fallidos.
app.get('/api/usuarios/:id', async (req, res) => {
    try {
        const idObjetivo = parseInt(req.params.id, 10);
        if (!Number.isFinite(idObjetivo) || idObjetivo <= 0) {
            return res.status(400).json({ success: false, message: 'ID de usuario inválido' });
        }

        const userRolesLower = getUserRolesLower(req);
        const esAdmin = userRolesLower.includes('root')
            || userRolesLower.includes('administrador')
            || userRolesLower.includes('super_admin');
        const esPropio = idObjetivo === Number(req.user?.id);

        if (!esAdmin && !esPropio) {
            return res.status(403).json({ success: false, message: 'No tienes permiso para ver este usuario' });
        }

        const [rows] = await pool.query(
            `SELECT u.*, r.nombre_rol as rol,
                    u.roles_adicionales,
                    COALESCE(i.firma_drive_id, u.firma_drive_id) AS firma_drive_id,
                    COALESCE(i.firma_url, u.firma_url) AS firma_url
             FROM usuario u
             JOIN roles r ON u.rol_id = r.rol_id
             LEFT JOIN instructor i ON u.id = i.usuario_id AND i.activo = 1
             WHERE u.id = ? AND r.nombre_rol != 'root'`,
            [idObjetivo]
        );
        if (rows.length > 0) {
            // SEGURIDAD: sanear campos sensibles antes de responder.
            const usuario = { ...rows[0] };
            delete usuario.clave;
            delete usuario.intentos_fallidos;
            res.json({ success: true, usuario });
        } else {
            res.status(404).json({ success: false, message: 'Usuario no encontrado' });
        }
    } catch (error) {
        handleError(res, error);
    }
});

// Actualizar datos del usuario (sin contraseña)
app.put('/api/usuarios/:id', uploadFirmaDoctor.fields([{ name: 'firma', maxCount: 1 }, { name: 'foto', maxCount: 1 }, { name: 'logo', maxCount: 1 }]), async (req, res) => {
    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();
        await asegurarColumnaOrganigramaUsuario(conn);
        await asegurarColumnaAreaDepartamentoUsuario(conn);

        const { id } = req.params;
        const { nombre, apellidos, correo, email, telefono, empresa_id, rol_id, roles_adicionales, organigrama, area_departamento, servicio_proteccion_civil, empresa_puesto, empresa_colaborador, credenciales_correos_extra, nueva_password } = req.body;
        const servicioProteccionCivil = parseBoolDb(servicio_proteccion_civil, undefined);
        const puestoEmpresa = empresa_puesto !== undefined ? String(empresa_puesto || '').trim() : undefined;
        const colaboradorEmpresa = empresa_colaborador !== undefined
            ? parseColaboradorEmpresaId(empresa_colaborador)
            : undefined;
        // areas puede venir como JSON string cuando la petición es multipart/form-data
        let areas = req.body.areas;
        if (typeof areas === 'string') {
            try { areas = JSON.parse(areas); } catch (e) { areas = undefined; }
        }

        const userRoles = Array.isArray(req.user.roles) ? req.user.roles : [req.user.rol];
        const userRolesNormalizados = userRoles.map(r => String(r || '').toLowerCase());
        const esAdmin = userRolesNormalizados.includes('root') || userRolesNormalizados.includes('administrador') || userRolesNormalizados.includes('super_admin');
        const esPropio = parseInt(id, 10) === Number(req.user.id);

        // SEGURIDAD: Solo admin puede editar otros usuarios
        if (!esAdmin && !esPropio) {
            conn.release();
            return res.status(403).json({ success: false, message: 'No tienes permiso para editar este usuario' });
        }

        // SEGURIDAD: Solo admin puede cambiar rol, empresa o roles_adicionales (anti escalada de privilegios)
        if (!esAdmin && (rol_id || empresa_id || roles_adicionales !== undefined)) {
            conn.release();
            return res.status(403).json({ success: false, message: 'Solo un administrador puede cambiar el rol, empresa o roles adicionales' });
        }

        // SEGURIDAD: validar que roles_adicionales nunca incluya root/super_admin (incluso si viene de admin).
        // Solo el rol root real (asignado en BD por DBA) puede tener ese privilegio.
        let rolesAdicionalesSanitizados;
        if (roles_adicionales !== undefined) {
            const check = sanitizarRolesAdicionales(roles_adicionales);
            if (!check.ok) {
                conn.release();
                return res.status(403).json({ success: false, message: check.message });
            }
            rolesAdicionalesSanitizados = check.value;
        }

        const nuevaPasswordRaw = nueva_password !== undefined && nueva_password !== null
            ? String(nueva_password).trim()
            : '';
        const hayCambioPassword = Boolean(nuevaPasswordRaw);

        if (hayCambioPassword && !esAdmin) {
            conn.release();
            return res.status(403).json({ success: false, message: 'Solo un administrador puede cambiar la contraseña desde esta pantalla' });
        }

        if (hayCambioPassword && nuevaPasswordRaw.length < 8) {
            conn.release();
            return res.status(400).json({ success: false, message: 'La contraseña debe tener al menos 8 caracteres' });
        }

        // Usar correo o email (compatibilidad)
        const emailValue = correo || email;
        const correosCredencialesExtra = parseCorreosCredencialesExtra(credenciales_correos_extra);

        // Verificar que el usuario existe
        const [users] = await conn.query(
            `SELECT u.id, u.username, u.nombre, u.apellido, u.email, u.rol_id, u.empresa_id, r.nombre_rol
             FROM usuario u JOIN roles r ON u.rol_id = r.rol_id WHERE u.id = ?`, [id]
        );

        if (users.length === 0) {
            conn.release();
            return res.status(404).json({ success: false, message: 'Usuario no encontrado' });
        }

        const usuarioActual = users[0];
        const emailActual = String(usuarioActual.email || '').trim();
        const emailSolicitado = emailValue !== undefined && emailValue !== null
            ? String(emailValue).trim()
            : '';
        const huboCambioCorreo = Boolean(emailSolicitado) && emailSolicitado.toLowerCase() !== emailActual.toLowerCase();
        const debeNotificarCredenciales = esAdmin && (huboCambioCorreo || hayCambioPassword);
        let claveParaCredenciales = null;

        // SEGURIDAD: No permitir cambiar a rol root (por nombre, no por ID)
        if (rol_id) {
            const [rolCheck] = await conn.query('SELECT nombre_rol FROM roles WHERE rol_id = ?', [rol_id]);
            if (rolCheck[0]?.nombre_rol?.toLowerCase() === 'root') {
                conn.release();
                return res.status(403).json({ success: false, message: 'No se puede asignar el rol root' });
            }
        }

        // Construir actualización segura por objeto (mysql2 escapa columnas/valores)
        const updatePayload = {};

        if (nombre) {
            updatePayload.nombre = nombre;
        }
        if (apellidos) {
            updatePayload.apellido = apellidos;
        }
        if (emailValue) {
            updatePayload.email = emailValue;
        }
        if (telefono) {
            updatePayload.telefono = telefono;
        }
        // Permitir asignar/desasignar empresa_id (incluso null)
        if (empresa_id !== undefined) {
            updatePayload.empresa_id = empresa_id || null;
        }
        // Permitir cambiar rol_id (la validación de rol root ya se hizo arriba)
        if (rol_id) {
            updatePayload.rol_id = parseInt(rol_id);
        }
        // Actualizar roles adicionales si se proporcionan (ya saneados arriba)
        if (roles_adicionales !== undefined) {
            updatePayload.roles_adicionales = rolesAdicionalesSanitizados || null;
        }
        if (organigrama !== undefined) {
            const organigramaValor = String(organigrama || '').trim();
            updatePayload.organigrama = organigramaValor || null;
        }
        if (area_departamento !== undefined) {
            const areaValor = String(area_departamento || '').trim();
            if (areaValor && !normalizarAreaDepartamentoUsuario(areaValor)) {
                conn.release();
                return res.status(400).json({
                    success: false,
                    message: 'Área/Departamento inválida. Opciones: Seguridad, Innovación, Administración'
                });
            }
            updatePayload.area_departamento = normalizarAreaDepartamentoUsuario(areaValor);
        }

        if (hayCambioPassword) {
            const hashedPasswordNueva = await bcrypt.hash(nuevaPasswordRaw, SALT_ROUNDS);
            updatePayload.clave = hashedPasswordNueva;
            updatePayload.bloqueado = 0;
            updatePayload.intentos_fallidos = 0;
            claveParaCredenciales = nuevaPasswordRaw;
        }

        if (Object.keys(updatePayload).length > 0) {
            if (updatePayload.email !== undefined) {
                await asegurarEmailNoUnicoUsuario(conn);
            }
            await conn.query('UPDATE usuario SET ? WHERE id = ?', [updatePayload, id]);
            if (updatePayload.organigrama !== undefined) {
                rrhhColaboradoresService.invalidarCache();
            }
        }

        // ── Construir lista completa de roles efectivos ──
        // Determinar el rol efectivo (el nuevo si cambió, o el actual)
        const rolEfectivo = rol_id ? parseInt(rol_id) : usuarioActual.rol_id;
        const [rolInfo] = await conn.query('SELECT nombre_rol FROM roles WHERE rol_id = ?', [rolEfectivo]);
        const rolNombreEfectivo = rolInfo[0]?.nombre_rol?.toLowerCase();
        const rolesEfectivos = [rolNombreEfectivo];
        // Obtener roles_adicionales del usuario
        const [raRows] = await conn.query('SELECT roles_adicionales FROM usuario WHERE id = ?', [id]);
        const raVal = roles_adicionales !== undefined ? roles_adicionales : (raRows[0]?.roles_adicionales || '');
        if (raVal) {
            raVal.split(',').map(r => r.trim().toLowerCase()).filter(Boolean).forEach(r => {
                if (!rolesEfectivos.includes(r)) rolesEfectivos.push(r);
            });
        }
        const esInstructorODoctor = rolesEfectivos.includes('instructor') || rolesEfectivos.includes('doctor');
        const esUsuarioEmpresa = rolesEfectivos.includes('empresa') || rolesEfectivos.includes('usuario empresa');
        const esInstructor = rolesEfectivos.includes('instructor');

        if (esUsuarioEmpresa && (servicioProteccionCivil !== undefined || puestoEmpresa !== undefined || colaboradorEmpresa !== undefined)) {
            await asegurarColumnaServicioProteccionCivilEmpresa(conn);
            await asegurarColumnaPuestoEmpresa(conn);
            await asegurarColumnaColaboradorEmpresa(conn);
            let empresaObjetivoId = Number(empresa_id || usuarioActual.empresa_id || 0);
            if (empresaObjetivoId <= 0) {
                const [empresaRowsPorUsuario] = await conn.query(
                    'SELECT empresa_id FROM empresa WHERE usuario_id = ? ORDER BY empresa_id ASC LIMIT 1',
                    [id]
                );
                if (empresaRowsPorUsuario.length > 0) {
                    empresaObjetivoId = Number(empresaRowsPorUsuario[0].empresa_id || 0);
                }
            }
            if (empresaObjetivoId > 0) {
                const updatesEmpresa = [];
                const valoresEmpresa = [];

                if (servicioProteccionCivil !== undefined) {
                    updatesEmpresa.push('servicio_proteccion_civil = ?');
                    valoresEmpresa.push(servicioProteccionCivil);
                }
                if (puestoEmpresa !== undefined) {
                    updatesEmpresa.push('puesto = ?');
                    valoresEmpresa.push(puestoEmpresa || null);
                }
                if (colaboradorEmpresa !== undefined) {
                    updatesEmpresa.push('colaborador = ?');
                    valoresEmpresa.push(colaboradorEmpresa);
                }

                if (updatesEmpresa.length > 0) {
                    valoresEmpresa.push(empresaObjetivoId);
                    await conn.query(
                        `UPDATE empresa SET ${updatesEmpresa.join(', ')} WHERE empresa_id = ?`,
                        valoresEmpresa
                    );
                }
            }
        }

        // ── Sincronizar registro y áreas del instructor ──
        if (esInstructor) {
            const instructorId = await asegurarInstructorIdUsuario(conn, {
                id,
                username: usuarioActual.username,
                nombre: nombre || usuarioActual.nombre,
                apellido: apellidos || usuarioActual.apellido,
                email: emailValue || usuarioActual.email,
                telefono: telefono || usuarioActual.telefono,
                instructor_id: usuarioActual.instructor_id
            }, rolesEfectivos);

            if (areas !== undefined && Array.isArray(areas) && instructorId) {
                await conn.query('DELETE FROM instructor_areas WHERE instructor_id = ?', [instructorId]);

                if (areas.length > 0) {
                    const areaValues = areas.map(areaId => [instructorId, parseInt(areaId), false, new Date()]);
                    await conn.query(
                        'INSERT INTO instructor_areas (instructor_id, area_id, certificado, created_at) VALUES ?',
                        [areaValues]
                    );
                }
            }
        }

        // ── Actualizar firma digital si se subió una nueva ──
        const firmaFileEdit = req.files?.['firma']?.[0];
        const fotoFileEdit = req.files?.['foto']?.[0];
        const logoFileEdit = req.files?.['logo']?.[0];

        if (esInstructorODoctor && !firmaFileEdit) {
            const [firmaExistente] = await conn.query(
                `SELECT COALESCE(i.firma_drive_id, u.firma_drive_id) AS firma_drive_id
                 FROM usuario u
                 LEFT JOIN instructor i ON u.id = i.usuario_id AND i.activo = 1
                 WHERE u.id = ?`,
                [id]
            );
            if (!firmaExistente[0]?.firma_drive_id) {
                await conn.rollback();
                conn.release();
                return res.status(400).json({
                    success: false,
                    message: 'La firma digital es obligatoria para Instructor y Doctor'
                });
            }
        }

        if (firmaFileEdit && esInstructorODoctor) {
            const [instRows] = await conn.query(
                'SELECT instructor_id, firma_drive_id FROM instructor WHERE usuario_id = ? AND activo = 1', [id]
            );
            if (instRows.length > 0) {
                try {
                    const firmaPngBuffer = await convertirFirmaAPngSinFondo(firmaFileEdit.buffer);

                    // Eliminar firma anterior de Drive si existe
                    const oldFirmaId = instRows[0].firma_drive_id;
                    if (oldFirmaId) {
                        try { await driveService.eliminarArchivo(oldFirmaId); } catch (e) { console.warn('[WARN] No se pudo eliminar firma anterior:', e.message); }
                    }
                    const carpetaNombre = rolNombreEfectivo === 'doctor' ? 'Firmas_Doctores' : 'Firmas_Instructores';
                    const carpetaFirmas = await driveService.obtenerOCrearCarpeta(carpetaNombre);
                    const nombreFirma = `firma_${rolNombreEfectivo}_${usuarioActual.username}_${Date.now()}.png`;
                    const archivoSubido = await driveService.subirArchivo(
                        firmaPngBuffer, nombreFirma, 'image/png', carpetaFirmas
                    );
                    await conn.query(
                        'UPDATE instructor SET firma_url = ?, firma_drive_id = ? WHERE instructor_id = ?',
                        [`https://drive.google.com/uc?id=${archivoSubido.id}`, archivoSubido.id, instRows[0].instructor_id]
                    );
                    await conn.query(
                        'UPDATE usuario SET firma_url = ?, firma_drive_id = ? WHERE id = ?',
                        [`https://drive.google.com/uc?id=${archivoSubido.id}`, archivoSubido.id, id]
                    );
                } catch (driveError) {
                    console.error('[ERROR] Actualizar firma en edición:', driveError.message);
                    // No bloquear la actualización si falla Drive
                }
            }
        }

        // ── Firma opcional para cualquier rol (incluye administrador) ──
        if (firmaFileEdit && !esInstructorODoctor) {
            try {
                const firmaPngBuffer = await convertirFirmaAPngSinFondo(firmaFileEdit.buffer);

                // Eliminar firma anterior de Drive si existe
                const [oldAdminFirma] = await conn.query('SELECT firma_drive_id FROM usuario WHERE id = ?', [id]);
                const oldAdminFirmaId = oldAdminFirma[0]?.firma_drive_id;
                if (oldAdminFirmaId) {
                    try { await driveService.eliminarArchivo(oldAdminFirmaId); } catch (e) { console.warn('[WARN] No se pudo eliminar firma anterior:', e.message); }
                }
                const carpetaFirmas = await driveService.obtenerOCrearCarpeta(
                    rolesEfectivos.includes('administrador') ? 'Firmas_Calidad' : 'Firmas_Usuarios'
                );
                const nombreFirma = `firma_${rolNombreEfectivo || 'usuario'}_${usuarioActual.username}_${Date.now()}.png`;
                const archivoSubido = await driveService.subirArchivo(
                    firmaPngBuffer, nombreFirma, 'image/png', carpetaFirmas
                );
                const firmaUrl = `https://drive.google.com/uc?id=${archivoSubido.id}`;
                await conn.query(
                    'UPDATE usuario SET firma_url = ?, firma_drive_id = ? WHERE id = ?',
                    [firmaUrl, archivoSubido.id, id]
                );
            } catch (driveError) {
                console.error('[ERROR] Actualizar firma en edición:', driveError.message);
                console.error('[ERROR] Stack:', driveError.stack);
            }
        }

        // ── Fotografía (siempre opcional) ──
        if (fotoFileEdit) {
            try {
                // Eliminar foto anterior de Drive si existe
                const [oldFotoRow] = await conn.query('SELECT foto_drive_id FROM usuario WHERE id = ?', [id]);
                const oldFotoDriveId = oldFotoRow[0]?.foto_drive_id;
                if (oldFotoDriveId) {
                    try { await driveService.eliminarArchivo(oldFotoDriveId); } catch (e) { console.warn('[WARN] No se pudo eliminar foto anterior:', e.message); }
                }
                const FOTOS_FOLDER = process.env.GOOGLE_DRIVE_FOTOS_USUARIOS_FOLDER_ID;
                const ext = fotoFileEdit.originalname.split('.').pop() || 'jpg';
                const nombreFoto = `foto_${rolNombreEfectivo}_${usuarioActual.username}_${Date.now()}.${ext}`;
                const fotoSubida = await driveService.subirArchivo(
                    fotoFileEdit.buffer, nombreFoto, fotoFileEdit.mimetype, FOTOS_FOLDER
                );
                const fotoUrl = `https://drive.google.com/uc?id=${fotoSubida.id}`;
                await conn.query(
                    'UPDATE usuario SET foto_url = ?, foto_drive_id = ? WHERE id = ?',
                    [fotoUrl, fotoSubida.id, id]
                );
                // Si es instructor, actualizar también en la tabla instructor
                if (esInstructorODoctor) {
                    const [instRows] = await conn.query(
                        'SELECT instructor_id FROM instructor WHERE usuario_id = ? AND activo = 1', [id]
                    );
                    if (instRows.length > 0) {
                        await conn.query(
                            'UPDATE instructor SET foto_url = ? WHERE instructor_id = ?',
                            [fotoUrl, instRows[0].instructor_id]
                        );
                    }
                }
            } catch (driveError) {
                console.error('[ERROR] Actualizar foto en edición:', driveError.message);
                // No bloquear la actualización si falla Drive
            }
        }

        // ── Logo para usuario empresa en edición ──
        if (logoFileEdit && esUsuarioEmpresa) {
            try {
                const empresaObjetivoId = Number(empresa_id || usuarioActual.empresa_id || 0);
                if (empresaObjetivoId > 0) {
                    const [empresaRows] = await conn.query(
                        'SELECT empresa_id, nombre_empresa, logo, drive_folder_id FROM empresa WHERE empresa_id = ? LIMIT 1',
                        [empresaObjetivoId]
                    );

                    if (empresaRows.length > 0) {
                        const empresa = empresaRows[0];

                        const logoActualRaw = String(empresa.logo || '').trim();
                        const oldByIdParam = logoActualRaw.match(/[?&]id=([a-zA-Z0-9_-]+)/);
                        const oldByPath = logoActualRaw.match(/\/d\/([a-zA-Z0-9_-]+)/);
                        const oldLogoDriveId = oldByIdParam?.[1] || oldByPath?.[1] || (/^[a-zA-Z0-9_-]{10,}$/.test(logoActualRaw) ? logoActualRaw : null);
                        if (oldLogoDriveId) {
                            try { await driveService.eliminarArchivo(oldLogoDriveId); } catch (e) { console.warn('[WARN] No se pudo eliminar logo anterior de empresa:', e.message); }
                        }

                        const ext = logoFileEdit.originalname.split('.').pop() || 'png';
                        const nombreLogo = `logo_empresa_${empresaObjetivoId}_${Date.now()}.${ext}`;
                        const logoSubido = await driveService.subirArchivo(
                            logoFileEdit.buffer,
                            nombreLogo,
                            logoFileEdit.mimetype,
                            empresa.drive_folder_id || undefined
                        );

                        const logoUrl = logoSubido.id;
                        await conn.query('UPDATE empresa SET logo = ? WHERE empresa_id = ?', [logoUrl, empresaObjetivoId]);
                    }
                }
            } catch (driveError) {
                console.error('[ERROR] Actualizar logo de empresa en edición:', driveError.message);
            }
        }

        await conn.commit();

        let nombreEmpresaCredenciales = '';
        if (esUsuarioEmpresa) {
            const empresaIdDirecto = Number(empresa_id || usuarioActual.empresa_id || 0);
            if (empresaIdDirecto > 0) {
                try {
                    const [empresaRowsNombre] = await conn.query(
                        'SELECT nombre_empresa FROM empresa WHERE empresa_id = ? LIMIT 1',
                        [empresaIdDirecto]
                    );
                    nombreEmpresaCredenciales = String(empresaRowsNombre?.[0]?.nombre_empresa || '').trim();
                } catch (e) {
                    console.warn('[WARN] No se pudo obtener nombre de empresa para credenciales:', e.message);
                }
            } else {
                try {
                    const [empresaRowsPorUsuario] = await conn.query(
                        'SELECT nombre_empresa FROM empresa WHERE usuario_id = ? ORDER BY empresa_id ASC LIMIT 1',
                        [id]
                    );
                    nombreEmpresaCredenciales = String(empresaRowsPorUsuario?.[0]?.nombre_empresa || '').trim();
                } catch (e) {
                    console.warn('[WARN] No se pudo obtener nombre de empresa por usuario:', e.message);
                }
            }
        }
        const usernameParaCorreo = usuarioActual.username;

        if (esAdmin && huboCambioCorreo && !hayCambioPassword) {
            Promise.resolve(
                emailService.notificarCambioCorreoAcceso({
                    emailNuevo: emailSolicitado,
                    emailAnterior: emailActual,
                    nombre: nombre || usuarioActual.nombre,
                    apellido: apellidos || usuarioActual.apellido,
                    username: usuarioActual.username,
                    realizadoPor: req.user?.username || 'Administrador',
                    rolRealizadoPor: req.user?.rol || 'administrador',
                    fechaCambio: new Date()
                })
            )
                .catch((err) => {
                    console.error('[EMAIL] Error enviando aviso de cambio de correo:', err.message);
                });
        }

        if (debeNotificarCredenciales && claveParaCredenciales) {
            const correoDestino = huboCambioCorreo ? emailSolicitado : emailActual;
            const destinatariosCredenciales = construirDestinatariosCredenciales(
                correoDestino,
                correosCredencialesExtra
            );

            const esSoloCambioCorreo = huboCambioCorreo && !hayCambioPassword;
            const esSoloCambioPassword = hayCambioPassword && !huboCambioCorreo;
            const esCambioCorreoYPassword = huboCambioCorreo && hayCambioPassword;
            const nombreCompletoUsuario = `${nombre || usuarioActual.nombre || ''} ${apellidos || usuarioActual.apellido || ''}`.trim();
            const nombreUsuarioCredenciales = nombreEmpresaCredenciales || nombreCompletoUsuario || usuarioActual.username || 'usuario';

            let mensajeCredenciales = 'Estas son tus nuevas credenciales para ingresar al sistema.';
            let tituloBase = 'Actualización de Credenciales de Acceso';
            let asuntoBase = 'Actualización de Credenciales de Acceso - Biznaga Risk&Tech';

            if (esSoloCambioCorreo) {
                mensajeCredenciales = 'Tu dirección de correo ha sido actualizada en nuestro sistema. Estas son tus credenciales vigentes para iniciar sesión:';
                tituloBase = 'Cambio de Correo Exitoso';
                asuntoBase = 'Actualización de Correo - Biznaga Risk&Tech';
            } else if (esSoloCambioPassword) {
                mensajeCredenciales = 'Tu contraseña ha sido actualizada exitosamente. Estas son tus nuevas credenciales de acceso:';
                tituloBase = 'Nueva Contraseña Generada';
                asuntoBase = 'Actualización de Contraseña - Biznaga Risk&Tech';
            } else if (esCambioCorreoYPassword) {
                mensajeCredenciales = 'Tu correo electrónico y contraseña han sido actualizados en el sistema. Utiliza estas nuevas credenciales para ingresar:';
                tituloBase = 'Cambio de Datos de Acceso';
                asuntoBase = 'Actualización de Credenciales - Biznaga Risk&Tech';
            }

            const extrasNormalizados = new Set(correosCredencialesExtra.map(normalizarCorreoCredenciales));
            const principalNormalizado = normalizarCorreoCredenciales(correoDestino);
            const asuntoCopia = esSoloCambioCorreo
                ? `[Copia] Cambio de Correo - ${nombreUsuarioCredenciales}`
                : esSoloCambioPassword
                    ? `[Copia] Cambio de Contraseña - ${nombreUsuarioCredenciales}`
                    : `[Copia] Actualización de Credenciales - ${nombreUsuarioCredenciales}`;
            const tituloCopia = esSoloCambioCorreo
                ? 'Respaldo de Cambio de Correo'
                : esSoloCambioPassword
                    ? 'Respaldo de Actualización de Contraseña'
                    : 'Respaldo de Cambio de Credenciales';
            const mensajeCopia = esSoloCambioCorreo
                ? `El correo de acceso de ${nombreUsuarioCredenciales} ha sido modificado. Adjuntamos las credenciales actualizadas para tus registros:`
                : esSoloCambioPassword
                    ? `Se ha generado una nueva contraseña para la cuenta de ${nombreUsuarioCredenciales}. Adjuntamos una copia para tus registros:`
                    : `El correo y la contraseña de ${nombreUsuarioCredenciales} han sido actualizados. Adjuntamos las nuevas credenciales para su gestión:`;

            if (destinatariosCredenciales.length > 0) {
                Promise.allSettled(
                    destinatariosCredenciales.map((destino) => {
                        const destinoNormalizado = normalizarCorreoCredenciales(destino);
                        const esCopia = extrasNormalizados.has(destinoNormalizado) && destinoNormalizado !== principalNormalizado;
                        const mensajeFinal = esCopia ? mensajeCopia : mensajeCredenciales;
                        const tituloFinal = esCopia ? tituloCopia : tituloBase;
                        const asuntoFinal = esCopia ? asuntoCopia : asuntoBase;
                        return emailService.enviarCredencialesNuevoUsuario({
                            email: destino,
                            nombre: nombre || usuarioActual.nombre,
                            apellido: apellidos || usuarioActual.apellido,
                            username: usernameParaCorreo,
                            clave: claveParaCredenciales,
                            mensajeBienvenida: mensajeFinal,
                            tituloCorreo: tituloFinal,
                            asuntoCorreo: asuntoFinal
                        });
                    })
                )
                    .then((resultados) => {
                        const fallos = resultados.filter((resultado) => resultado.status === 'rejected');
                        if (fallos.length > 0) {
                            console.error('[EMAIL] No se pudo completar al menos uno de los envios de credenciales en edicion de usuario');
                        }
                    })
                    .catch((err) => {
                        console.error('[EMAIL] Error enviando credenciales en edicion de usuario:', err.message);
                    });
            }
        }

        res.json({ success: true, message: 'Usuario actualizado exitosamente' });
    } catch (error) {
        await conn.rollback();
        if (error.code === 'ER_DUP_ENTRY') {
            const detalle = String(error?.message || '').toLowerCase();
            if (detalle.includes('username')) {
                res.status(409).json({ success: false, message: 'El nombre de usuario ya está en uso' });
            } else {
                res.status(409).json({ success: false, message: 'Conflicto de datos únicos al actualizar el usuario' });
            }
        } else {
            handleError(res, error, 'Error al actualizar usuario');
        }
    } finally {
        conn.release();
    }
});

// Crear usuario (con contraseña hasheada) - solo admin/root
// NOTA: Solo para crear administradores, instructores y consulta
// No se puede crear usuarios con rol 'root' ni 'empresa'
// Para instructores, se pueden asociar áreas temáticas
// Para doctores, acepta firma digital (imagen) vía multipart/form-data
app.post('/api/usuarios', requireAdmin, uploadFirmaDoctor.fields([{ name: 'firma', maxCount: 1 }, { name: 'foto', maxCount: 1 }]), async (req, res) => {
    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();
        await asegurarEmailNoUnicoUsuario(conn);

        const { username, email, clave, nombre, apellido, telefono, rol_id, organigrama, area_departamento } = req.body;
        await asegurarColumnaOrganigramaUsuario(conn);
        await asegurarColumnaAreaDepartamentoUsuario(conn);
        const organigramaValor = String(organigrama || '').trim() || null;
        const areaDepartamentoRaw = String(area_departamento || '').trim();
        if (areaDepartamentoRaw && !normalizarAreaDepartamentoUsuario(areaDepartamentoRaw)) {
            conn.release();
            return res.status(400).json({
                success: false,
                message: 'Área/Departamento inválida. Opciones: Seguridad, Innovación, Administración'
            });
        }
        const areaDepartamentoValor = normalizarAreaDepartamentoUsuario(areaDepartamentoRaw);

        // SEGURIDAD: validar roles_adicionales para evitar escalada a root/super_admin.
        const rolesAdicionalesCheck = sanitizarRolesAdicionales(req.body.roles_adicionales);
        if (!rolesAdicionalesCheck.ok) {
            conn.release();
            return res.status(403).json({ success: false, message: rolesAdicionalesCheck.message });
        }
        const roles_adicionales = rolesAdicionalesCheck.value || '';
        const correosCredencialesExtra = parseCorreosCredencialesExtra(req.body.credenciales_correos_extra);
        // areas puede venir como JSON string en FormData
        let areas = req.body.areas;
        if (typeof areas === 'string') {
            try { areas = JSON.parse(areas); } catch (e) { areas = []; }
        }

        // Validaciones
        if (!username || !clave) {
            conn.release();
            return res.status(400).json({
                success: false,
                message: 'Username y contraseña son requeridos'
            });
        }

        // Validar longitud mínima de contraseña
        if (clave.length < 8) {
            conn.release();
            return res.status(400).json({
                success: false,
                message: 'La contraseña debe tener al menos 8 caracteres'
            });
        }

        // SEGURIDAD: Validar rol por nombre, no por ID numérico
        if (rol_id) {
            const [rolCheck] = await conn.query('SELECT nombre_rol FROM roles WHERE rol_id = ?', [rol_id]);
            const rolNombre = rolCheck[0]?.nombre_rol?.toLowerCase();

            if (rolNombre === 'root') {
                conn.release();
                return res.status(403).json({
                    success: false,
                    message: 'No tiene permisos para asignar este rol'
                });
            }

            // Las empresas se crean desde el módulo mis-empresas (que también setea empresa_id)
            if (rolNombre === 'empresa') {
                conn.release();
                return res.status(403).json({
                    success: false,
                    message: 'Los usuarios de empresa se crean desde el modulo de Empresas'
                });
            }
        }

        // Hashear la contraseña con bcrypt
        const hashedPassword = await bcrypt.hash(clave, SALT_ROUNDS);

        const [result] = await conn.query(
            `INSERT INTO usuario (username, email, clave, nombre, apellido, telefono, rol_id, roles_adicionales, organigrama, area_departamento)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [username, email, hashedPassword, nombre, apellido, telefono, rol_id, roles_adicionales || null, organigramaValor, areaDepartamentoValor]
        );

        const userId = result.insertId;
        if (organigramaValor) {
            rrhhColaboradoresService.invalidarCache();
        }
        let instructorId = null;

        // Construir lista de todos los roles (principal + adicionales) para decidir qué registros crear
        const [rolData] = await conn.query('SELECT nombre_rol FROM roles WHERE rol_id = ?', [rol_id]);
        const nombreRol = rolData[0]?.nombre_rol?.toLowerCase();
        const todosLosRoles = [nombreRol];
        if (roles_adicionales) {
            todosLosRoles.push(...roles_adicionales.split(',').map(r => r.trim().toLowerCase()).filter(r => r));
        }
        const esInstructorEnRoles = todosLosRoles.includes('instructor');
        const esDoctorEnRoles = todosLosRoles.includes('doctor');

        if (esInstructorEnRoles || esDoctorEnRoles) {
            // Parsear instructor data (puede venir como JSON string en FormData)
            let instructorData = req.body.instructor || {};
            if (typeof instructorData === 'string') {
                try { instructorData = JSON.parse(instructorData); } catch (e) { instructorData = {}; }
            }

            let curpInstructor = null;
            let cedulaMedica = null;

            // Extraer archivos del multipart request
            const firmaFile = req.files?.['firma']?.[0];
            const fotoFile  = req.files?.['foto']?.[0];

            if ((esInstructorEnRoles || esDoctorEnRoles) && !firmaFile) {
                await conn.rollback();
                conn.release();
                return res.status(400).json({
                    success: false,
                    message: 'La firma digital es obligatoria para Instructor y Doctor'
                });
            }

            if (esInstructorEnRoles) {
                // Obtener CURP del instructor del request (si existe)
                curpInstructor = instructorData.curp?.toUpperCase().trim() || null;
            }
            if (esDoctorEnRoles) {
                // Obtener cédula médica del doctor (requerida)
                cedulaMedica = instructorData.cedula_medica?.trim() || instructorData.cedula_profesional?.trim() || null;

                if (!cedulaMedica) {
                    conn.release();
                    return res.status(400).json({
                        success: false,
                        message: 'La cédula médica es requerida para el rol de doctor'
                    });
                }
            }

            // --- Firma digital del instructor/doctor: subir a Google Drive ---
            let firmaUrl = null;
            let firmaDriveId = null;

            if ((esInstructorEnRoles || esDoctorEnRoles) && firmaFile) {
                try {
                    const firmaPngBuffer = await convertirFirmaAPngSinFondo(firmaFile.buffer);
                    const carpetaNombre = esDoctorEnRoles ? 'Firmas_Doctores' : 'Firmas_Instructores';
                    const carpetaFirmas = await driveService.obtenerOCrearCarpeta(carpetaNombre);

                    const rolLabel = esDoctorEnRoles ? 'doctor' : 'instructor';
                    const nombreFirma = `firma_${rolLabel}_${username.trim()}_${Date.now()}.png`;

                    const archivoSubido = await driveService.subirArchivo(
                        firmaPngBuffer,
                        nombreFirma,
                        'image/png',
                        carpetaFirmas
                    );

                    firmaUrl = `https://drive.google.com/uc?id=${archivoSubido.id}`;
                    firmaDriveId = archivoSubido.id;
                } catch (driveError) {
                    console.error('[ERROR] Subir firma digital a Drive:', driveError.message);
                    // No fallar la creación del usuario por error en Drive
                }
            }

            // --- Fotografía (instructor / doctor): subir a carpeta de fotos de usuarios en Drive ---
            let fotoUrl = null;
            let fotoDriveId = null;
            if (fotoFile) {
                try {
                    const FOTOS_FOLDER = process.env.GOOGLE_DRIVE_FOTOS_USUARIOS_FOLDER_ID;
                    const ext = fotoFile.originalname.split('.').pop() || 'jpg';
                    const rolLabel2 = esDoctorEnRoles ? 'doctor' : (esInstructorEnRoles ? 'instructor' : nombreRol);
                    const nombreFoto = `foto_${rolLabel2}_${username.trim()}_${Date.now()}.${ext}`;
                    const fotoSubida = await driveService.subirArchivo(
                        fotoFile.buffer,
                        nombreFoto,
                        fotoFile.mimetype,
                        FOTOS_FOLDER
                    );
                    fotoUrl = `https://drive.google.com/uc?id=${fotoSubida.id}`;
                    fotoDriveId = fotoSubida.id;
                } catch (driveError) {
                    console.error('[ERROR] Subir foto a Drive:', driveError.message);
                    // No fallar la creación del usuario por error en Drive
                }
            }

            // Crear registro en la tabla instructor con los datos del formulario
            // Para doctor, se guarda la cédula médica en cedula_profesional y la firma
            // Para instructor, se guarda el CURP
            const [instructorResult] = await conn.query(
                `INSERT INTO instructor (
                    nombre, 
                    apellido_paterno, 
                    apellido_materno,
                    curp, 
                    rfc,
                    cedula_profesional,
                    especialidad,
                    certificaciones,
                    email, 
                    telefono, 
                    direccion,
                    banco,
                    cuenta_bancaria,
                    clabe,
                    cv_url,
                    foto_url,
                    firma_url,
                    firma_drive_id,
                    tarifa_hora,
                    notas,
                    activo, 
                    usuario_id,
                    created_at
                ) VALUES (?, ?, NULL, ?, NULL, ?, NULL, NULL, ?, ?, NULL, NULL, NULL, NULL, NULL, ?, ?, ?, NULL, NULL, TRUE, ?, NOW())`,
                [nombre, apellido, curpInstructor, cedulaMedica, email, telefono, fotoUrl, firmaUrl, firmaDriveId, userId]
            );

            instructorId = instructorResult.insertId;

            // Actualizar el usuario con el instructor_id para la relación bidireccional
            await conn.query(
                'UPDATE usuario SET instructor_id = ? WHERE id = ?',
                [instructorId, userId]
            );

            // Guardar foto en tabla usuario (para uso futuro)
            if (fotoUrl) {
                await conn.query(
                    'UPDATE usuario SET foto_url = ?, foto_drive_id = ? WHERE id = ?',
                    [fotoUrl, fotoDriveId, userId]
                );
            }

            // Insertar las áreas temáticas en instructor_areas
            // Para instructor, si no se especifican áreas se auto-asignan TODAS las activas
            // NOTA: Solo los instructores tienen áreas, los doctores NO
            if (esInstructorEnRoles) {
                if (!areas || !Array.isArray(areas) || areas.length === 0) {
                    const [todasAreas] = await conn.query('SELECT area_id FROM area_tematica');
                    areas = todasAreas.map(a => a.area_id);
                }
                if (areas && areas.length > 0) {
                    const areaValues = areas.map(areaId => [instructorId, areaId, false]);
                    await conn.query(
                        'INSERT INTO instructor_areas (instructor_id, area_id, certificado, created_at) VALUES ?',
                        [areaValues.map(v => [...v, new Date()])]
                    );
                }
            }
        }

        // ── Firma y fotografía opcionales para el resto de roles ──
        const firmaFileAlta = req.files?.['firma']?.[0];
        const fotoFileAlta = req.files?.['foto']?.[0];
        const yaEsInstructorODoctor = todosLosRoles.includes('instructor') || todosLosRoles.includes('doctor');

        if (firmaFileAlta && !yaEsInstructorODoctor) {
            try {
                const firmaPngBuffer = await convertirFirmaAPngSinFondo(firmaFileAlta.buffer);
                const carpetaFirmas = await driveService.obtenerOCrearCarpeta(
                    todosLosRoles.includes('administrador') ? 'Firmas_Calidad' : 'Firmas_Usuarios'
                );
                const nombreFirma = `firma_${nombreRol || 'usuario'}_${username.trim()}_${Date.now()}.png`;
                const archivoSubido = await driveService.subirArchivo(
                    firmaPngBuffer, nombreFirma, 'image/png', carpetaFirmas
                );
                const firmaUrl = `https://drive.google.com/uc?id=${archivoSubido.id}`;
                await conn.query(
                    'UPDATE usuario SET firma_url = ?, firma_drive_id = ? WHERE id = ?',
                    [firmaUrl, archivoSubido.id, userId]
                );
            } catch (driveError) {
                console.error('[ERROR] Subir firma de usuario a Drive:', driveError.message);
            }
        }

        if (fotoFileAlta && !yaEsInstructorODoctor) {
            try {
                const FOTOS_FOLDER = process.env.GOOGLE_DRIVE_FOTOS_USUARIOS_FOLDER_ID;
                const ext = fotoFileAlta.originalname.split('.').pop() || 'jpg';
                const nombreFoto = `foto_${nombreRol || 'usuario'}_${username.trim()}_${Date.now()}.${ext}`;
                const fotoSubida = await driveService.subirArchivo(
                    fotoFileAlta.buffer, nombreFoto, fotoFileAlta.mimetype, FOTOS_FOLDER
                );
                const fotoUrl = `https://drive.google.com/uc?id=${fotoSubida.id}`;
                await conn.query(
                    'UPDATE usuario SET foto_url = ?, foto_drive_id = ? WHERE id = ?',
                    [fotoUrl, fotoSubida.id, userId]
                );
            } catch (driveError) {
                console.error('[ERROR] Subir foto de usuario a Drive:', driveError.message);
            }
        }

        await conn.commit();

        const destinatariosCredenciales = construirDestinatariosCredenciales(email, correosCredencialesExtra);

        if (String(email || '').trim() && destinatariosCredenciales.length === 0) {
            console.warn('[EMAIL] No se resolvieron destinatarios para alta de usuario. email original:', email);
        }

        // Enviar correo con credenciales al nuevo usuario y correos adicionales (no bloquea la respuesta)
        if (destinatariosCredenciales.length > 0) {
            (async () => {
                const mensajeCredenciales = 'Estas son tus nuevas credenciales para ingresar al sistema.';
                const tituloBase = 'Actualización de Credenciales de Acceso';
                const asuntoBase = 'Actualización de Credenciales de Acceso - Biznaga Risk&Tech';
                const extrasNormalizados = new Set(correosCredencialesExtra.map(normalizarCorreoCredenciales));
                const principalNormalizado = normalizarCorreoCredenciales(email);
                const nombreReferenciaCredenciales = `${nombre || ''} ${apellido || ''}`.trim() || username;
                const tituloCopia = `Copia de Credenciales de Acceso - ${nombreReferenciaCredenciales}`;
                const asuntoCopia = tituloCopia;

                const tareas = destinatariosCredenciales.map((destino) => {
                    const destinoNormalizado = normalizarCorreoCredenciales(destino);
                    const esCopia = extrasNormalizados.has(destinoNormalizado) && destinoNormalizado !== principalNormalizado;
                    return emailService.enviarCredencialesNuevoUsuario({
                        email: destino,
                        nombre,
                        apellido,
                        username,
                        clave,
                        rol: rolData[0]?.nombre_rol || null,
                        mensajeBienvenida: mensajeCredenciales,
                        tituloCorreo: esCopia ? tituloCopia : tituloBase,
                        asuntoCorreo: esCopia ? asuntoCopia : asuntoBase
                    });
                });

                const resultados = await Promise.allSettled(tareas);
                const fallos = resultados.filter((item) => item.status === 'rejected' || (item.status === 'fulfilled' && !item.value?.success));
                if (fallos.length > 0) {
                    console.error('[EMAIL] No se pudo completar al menos uno de los envíos de credenciales para nuevo usuario');
                }
            })().catch(err => {
                console.error('[EMAIL] Error enviando credenciales a nuevo usuario:', err.message);
            });
        }

        // Preparar respuesta con información del instructor si aplica
        const responseData = {
            success: true,
            message: 'Usuario creado exitosamente',
            id: userId,
            destinatarios_credenciales: destinatariosCredenciales
        };

        if (instructorId) {
            responseData.instructor_id = instructorId;
            if (esDoctorEnRoles && esInstructorEnRoles) {
                responseData.message = 'Usuario con perfil de instructor y doctor creados exitosamente';
            } else if (esDoctorEnRoles) {
                responseData.message = 'Usuario y perfil de doctor creados exitosamente';
            } else {
                responseData.message = 'Usuario e instructor creados exitosamente';
            }
        }

        res.json(responseData);
    } catch (error) {
        await conn.rollback();
        console.error('[ERROR] Crear usuario:', error);

        if (error.code === 'ER_DUP_ENTRY') {
            // Determinar qué campo está duplicado
            let message = 'Conflicto de datos únicos al crear el usuario';
            if (error.message.includes('curp')) {
                message = 'Ya existe un instructor con ese CURP';
            } else if (error.message.includes('cedula_profesional')) {
                message = 'Ya existe un doctor con esa cédula médica';
            } else if (error.message.includes('username')) {
                message = 'El nombre de usuario ya existe';
            }
            res.json({ success: false, message });
        } else {
            handleError(res, error);
        }
    } finally {
        conn.release();
    }
});

// Cambiar contraseña (usuario autenticado)
app.put('/api/usuarios/:id/cambiar-password', async (req, res) => {
    try {
        const { id } = req.params;

        // Solo el propio usuario puede cambiar su contraseña
        if (parseInt(id) !== req.user.id) {
            return res.status(403).json({ success: false, message: 'Solo puedes cambiar tu propia contraseña' });
        }

        const { password_actual, password_nueva } = req.body;

        if (!password_actual || !password_nueva) {
            return res.status(400).json({
                success: false,
                message: 'Se requiere contraseña actual y nueva'
            });
        }

        if (password_nueva.length < 8) {
            return res.status(400).json({
                success: false,
                message: 'La nueva contraseña debe tener al menos 8 caracteres'
            });
        }

        // Obtener usuario actual
        const [users] = await pool.query('SELECT id, clave FROM usuario WHERE id = ?', [id]);

        if (users.length === 0) {
            return res.status(404).json({ success: false, message: 'Usuario no encontrado' });
        }

        const user = users[0];

        // Verificar contraseña actual
        let passwordValid = false;
        if (user.clave.startsWith('$2a$') || user.clave.startsWith('$2b$')) {
            passwordValid = await bcrypt.compare(password_actual, user.clave);
        } else {
            passwordValid = (user.clave === password_actual);
        }

        if (!passwordValid) {
            return res.json({ success: false, message: 'La contraseña actual es incorrecta' });
        }

        // Hashear y guardar nueva contraseña
        const hashedPassword = await bcrypt.hash(password_nueva, SALT_ROUNDS);
        await pool.query('UPDATE usuario SET clave = ? WHERE id = ?', [hashedPassword, id]);

        res.json({ success: true, message: 'Contraseña actualizada exitosamente' });
    } catch (error) {
        handleError(res, error, 'Error al cambiar contraseña');
    }
});

// Resetear contraseña (solo admin/super admin)
app.post('/api/usuarios/:id/resetear-password', requireRole('root', 'administrador', 'super_admin'), async (req, res) => {
    try {
        const { id } = req.params;
        const { nueva_password, credenciales_correos_extra } = req.body;

        if (!nueva_password) {
            return res.status(400).json({
                success: false,
                message: 'Se requiere la nueva contraseña'
            });
        }

        if (nueva_password.length < 8) {
            return res.status(400).json({
                success: false,
                message: 'La contraseña debe tener al menos 8 caracteres'
            });
        }

        // Verificar que el usuario existe
        const [users] = await pool.query(
            'SELECT u.id, u.username, u.nombre, u.apellido, u.email, u.empresa_id, r.nombre_rol FROM usuario u JOIN roles r ON u.rol_id = r.rol_id WHERE u.id = ?',
            [id]
        );

        if (users.length === 0) {
            return res.status(404).json({ success: false, message: 'Usuario no encontrado' });
        }

        const usuarioObjetivo = users[0];

        // Hashear y guardar nueva contraseña, desbloquear usuario
        const hashedPassword = await bcrypt.hash(nueva_password, SALT_ROUNDS);
        await pool.query(
            'UPDATE usuario SET clave = ?, bloqueado = FALSE, intentos_fallidos = 0 WHERE id = ?',
            [hashedPassword, id]
        );

        const correosCredencialesExtra = parseCorreosCredencialesExtra(credenciales_correos_extra);
        const destinatariosCredenciales = construirDestinatariosCredenciales(
            usuarioObjetivo.email,
            correosCredencialesExtra
        );

        let nombreEmpresaCredenciales = '';
        const rolObjetivo = String(usuarioObjetivo?.nombre_rol || '').trim().toLowerCase();
        const esUsuarioEmpresa = rolObjetivo === 'empresa' || rolObjetivo === 'usuario empresa';

        if (esUsuarioEmpresa) {
            const empresaIdDirecto = Number(usuarioObjetivo.empresa_id || 0);
            if (empresaIdDirecto > 0) {
                try {
                    const [empresaRowsNombre] = await pool.query(
                        'SELECT nombre_empresa FROM empresa WHERE empresa_id = ? LIMIT 1',
                        [empresaIdDirecto]
                    );
                    nombreEmpresaCredenciales = String(empresaRowsNombre?.[0]?.nombre_empresa || '').trim();
                } catch (e) {
                    console.warn('[WARN] No se pudo obtener nombre de empresa para credenciales:', e.message);
                }
            } else {
                try {
                    const [empresaRowsPorUsuario] = await pool.query(
                        'SELECT nombre_empresa FROM empresa WHERE usuario_id = ? ORDER BY empresa_id ASC LIMIT 1',
                        [id]
                    );
                    nombreEmpresaCredenciales = String(empresaRowsPorUsuario?.[0]?.nombre_empresa || '').trim();
                } catch (e) {
                    console.warn('[WARN] No se pudo obtener nombre de empresa por usuario:', e.message);
                }
            }
        }

        if (destinatariosCredenciales.length > 0) {
            const nombreCompletoUsuario = `${usuarioObjetivo.nombre || ''} ${usuarioObjetivo.apellido || ''}`.trim();
            const nombreUsuarioCredenciales = nombreEmpresaCredenciales || nombreCompletoUsuario || usuarioObjetivo.username || 'usuario';
            const usernameParaCorreo = usuarioObjetivo.username;
            const mensajeCredenciales = 'Tu contraseña ha sido actualizada exitosamente. Estas son tus nuevas credenciales de acceso:';
            const tituloBase = 'Nueva Contraseña Generada';
            const asuntoBase = 'Actualización de Contraseña - Biznaga Risk&Tech';
            const extrasNormalizados = new Set(correosCredencialesExtra.map(normalizarCorreoCredenciales));
            const principalNormalizado = normalizarCorreoCredenciales(usuarioObjetivo.email);
            const tituloCopia = 'Respaldo de Actualización de Contraseña';
            const asuntoCopia = `[Copia] Cambio de Contraseña - ${nombreUsuarioCredenciales}`;
            const mensajeCopia = `Se ha generado una nueva contraseña para la cuenta de ${nombreUsuarioCredenciales}. Adjuntamos una copia para tus registros:`;

            Promise.allSettled(
                destinatariosCredenciales.map((destino) => {
                    const destinoNormalizado = normalizarCorreoCredenciales(destino);
                    const esCopia = extrasNormalizados.has(destinoNormalizado) && destinoNormalizado !== principalNormalizado;
                    const mensajeFinal = esCopia ? mensajeCopia : mensajeCredenciales;
                    const tituloFinal = esCopia ? tituloCopia : tituloBase;
                    const asuntoFinal = esCopia ? asuntoCopia : asuntoBase;
                    return emailService.enviarCredencialesNuevoUsuario({
                        email: destino,
                        nombre: usuarioObjetivo.nombre,
                        apellido: usuarioObjetivo.apellido,
                        username: usernameParaCorreo,
                        clave: nueva_password,
                        mensajeBienvenida: mensajeFinal,
                        tituloCorreo: tituloFinal,
                        asuntoCorreo: asuntoFinal
                    });
                })
            )
                .then((resultados) => {
                    const fallos = resultados.filter((resultado) => resultado.status === 'rejected');
                    if (fallos.length > 0) {
                        console.error('[EMAIL] No se pudo completar al menos uno de los envíos de credenciales por reseteo de contraseña');
                    }
                })
                .catch((err) => {
                    console.error('[EMAIL] Error enviando credenciales por reseteo de contraseña:', err.message);
                });
        }

        res.json({ success: true, message: 'Contraseña reseteada exitosamente' });
    } catch (error) {
        handleError(res, error, 'Error al resetear contraseña');
    }
});

// Verificar contraseña actual de un usuario (solo super_admin/root, no expone la contraseña)
app.post('/api/usuarios/:id/verificar-password-actual', requireRole('root', 'super_admin'), async (req, res) => {
    try {
        const { id } = req.params;
        const { password_actual } = req.body;

        if (!password_actual || String(password_actual).trim() === '') {
            return res.status(400).json({
                success: false,
                message: 'Se requiere la contraseña actual a verificar'
            });
        }

        const [users] = await pool.query(
            `SELECT u.id, u.clave
             FROM usuario u
             WHERE u.id = ?
             LIMIT 1`,
            [id]
        );

        if (users.length === 0) {
            return res.status(404).json({ success: false, message: 'Usuario no encontrado' });
        }

        const user = users[0];
        const claveGuardada = String(user.clave || '');
        let coincide = false;

        if (claveGuardada.startsWith('$2a$') || claveGuardada.startsWith('$2b$') || claveGuardada.startsWith('$2y$')) {
            coincide = await bcrypt.compare(password_actual, claveGuardada);
        } else {
            coincide = (claveGuardada === password_actual);
        }

        return res.json({
            success: true,
            coincide,
            message: coincide
                ? 'La contraseña actual coincide'
                : 'La contraseña actual no coincide'
        });
    } catch (error) {
        handleError(res, error, 'Error al verificar contraseña actual del usuario');
    }
});

