function esCursoActivoValor(valor) {
    return valor === true || valor === 1 || valor === '1';
}

// Obtener todos los cursos (con información del área)
// Por defecto solo activos. ?incluirInactivos=1 incluye ocultos (activo = 0) para administración.
app.get('/api/cursos', async (req, res) => {
    try {
        await asegurarCamposGestionCursos();
        const userRoles = Array.isArray(req.user?.roles)
            ? req.user.roles.map(r => String(r).toLowerCase())
            : (req.user?.rol ? [String(req.user.rol).toLowerCase()] : []);
        const puedeVerInactivos = userRoles.includes('root');
        const incluirInactivos = puedeVerInactivos && ['1', 'true', 'yes'].includes(
            String(req.query.incluirInactivos || '').toLowerCase()
        );
        const whereActivo = incluirInactivos ? '' : 'WHERE c.activo = TRUE';
        const orderBy = incluirInactivos
            ? 'ORDER BY c.activo DESC, c.nombre_curso ASC'
            : 'ORDER BY c.nombre_curso ASC';

        const [rows] = await pool.query(`
            SELECT c.*, a.nombre_area, a.nombre_area AS area_tematica,
                   a.slug AS area_slug, a.icono AS area_icono, a.color AS area_color
            FROM curso c
            LEFT JOIN area_tematica a ON c.area_id = a.area_id
            ${whereActivo}
            ${orderBy}
        `);

        res.json(rows.map(serializarCursoConImagen));
    } catch (error) {
        handleError(res, error);
    }
});

