// Crear nuevo documento requerido para un curso (o todos los cursos)
app.post('/api/cursos/:cursoId/documentos', async (req, res) => {
    try {
        const { cursoId } = req.params;
        const { nombre, descripcion, tipo_aceptado, aplicar_a_todos } = req.body;
        const claveBasico = obtenerClaveDocumentoBasico(nombre);

        if (!nombre || !tipo_aceptado) {
            return res.status(400).json({
                success: false,
                message: 'El nombre y tipo de documento son requeridos'
            });
        }

        let cursosAfectados = 0;
        let cursosOmitidos = 0;
        let errores = 0;

        if (aplicar_a_todos) {
            // Obtener todos los cursos activos
            const [cursos] = await pool.query(
                `SELECT curso_id FROM curso WHERE activo = 1`
            );

            const cursosIds = cursos.map((curso) => curso.curso_id);
            const mapaBasicos = claveBasico
                ? await construirMapaBasicosPorCurso(cursosIds)
                : new Map();

            for (const curso of cursos) {
                const cursoDestinoId = curso.curso_id;

                if (claveBasico && mapaBasicos.has(`${cursoDestinoId}:${claveBasico}`)) {
                    cursosOmitidos += 1;
                    continue;
                }

                try {
                    await pool.query(
                    `INSERT INTO documento_curso (curso_id, nombre, descripcion, tipo_aceptado) 
                     VALUES (?, ?, ?, ?)`,
                        [cursoDestinoId, nombre, descripcion || null, tipo_aceptado]
                    );

                    cursosAfectados += 1;
                    if (claveBasico) {
                        mapaBasicos.set(`${cursoDestinoId}:${claveBasico}`, true);
                    }
                } catch (insertError) {
                    console.error(
                        `[DOC-CURSO] Error insertando documento "${nombre}" en curso ${cursoDestinoId}:`,
                        insertError.message
                    );
                    errores += 1;
                }
            }

            return res.json({
                success: errores === 0,
                partial: errores > 0,
                message: errores > 0
                    ? `Documento procesado con incidencias. Creados: ${cursosAfectados}, omitidos: ${cursosOmitidos}, errores: ${errores}.`
                    : `Documento requerido procesado para todos los cursos. Creados: ${cursosAfectados}, omitidos: ${cursosOmitidos}.`,
                cursos_afectados: cursosAfectados,
                cursos_omitidos: cursosOmitidos,
                errores
            });
        } else {
            if (claveBasico) {
                const [existentesCurso] = await pool.query(
                    `SELECT nombre
                     FROM documento_curso
                     WHERE curso_id = ? AND activo = TRUE`,
                    [cursoId]
                );

                const yaExisteBasico = existentesCurso.some((doc) => {
                    return obtenerClaveDocumentoBasico(doc.nombre) === claveBasico;
                });

                if (yaExisteBasico) {
                    return res.json({
                        success: true,
                        skipped: true,
                        documento_clave: claveBasico,
                        message: 'Documento basico ya existente; no se creo duplicado.'
                    });
                }
            }

            // Crear solo para el curso actual
            const [result] = await pool.query(
                `INSERT INTO documento_curso (curso_id, nombre, descripcion, tipo_aceptado) 
                 VALUES (?, ?, ?, ?)`,
                [cursoId, nombre, descripcion || null, tipo_aceptado]
            );

            res.json({
                success: true,
                message: 'Documento requerido creado exitosamente',
                documento_id: result.insertId
            });
        }
    } catch (error) {
        handleError(res, error, 'Error al crear documento requerido');
    }
});

// Subir archivo de documento a Google Drive
app.post('/api/cursos/:cursoId/documentos/:documentoId/archivo', uploadDocumento.single('file'), async (req, res) => {
    try {
        const { cursoId, documentoId } = req.params;
        const file = req.file;

        if (!file) {
            return res.status(400).json({
                success: false,
                message: 'No se recibió ningún archivo'
            });
        }

        // Obtener información del curso, área y nombre del apartado
        const [cursoInfo] = await pool.query(
            `SELECT c.nombre_curso, a.nombre_area, d.nombre AS nombre_apartado
             FROM curso c 
             INNER JOIN area_tematica a ON c.area_id = a.area_id
             INNER JOIN documento_curso d ON d.documento_id = ? AND d.curso_id = c.curso_id
             WHERE c.curso_id = ?`,
            [documentoId, cursoId]
        );

        if (cursoInfo.length === 0) {
            return res.status(404).json({
                success: false,
                message: 'Curso o documento no encontrado'
            });
        }

        const { nombre_curso, nombre_area, nombre_apartado } = cursoInfo[0];

        // Construir nombre del archivo: NombreCurso_NombreApartado.extension
        // Ejemplo: "NOM 18 Sistema Globalmente Armonizado" + "Examen Diagnostico" → NOM18SistemaGlobalmenteArmonizado_ExamenDiagnostico.pdf
        const extensionOriginal = file.originalname.split('.').pop();
        const cursoLimpio = (nombre_curso || 'Curso').replace(/[<>:"/\\|?*]/g, '').replace(/\s+/g, '').trim();
        const apartadoLimpio = (nombre_apartado || 'Documento').replace(/[<>:"/\\|?*]/g, '').replace(/\s+/g, '').trim();
        const nombreArchivoDrive = `${cursoLimpio}_${apartadoLimpio}.${extensionOriginal}`;

        // Subir archivo a Google Drive en la carpeta del curso
        const driveFile = await driveService.subirDocumentoCurso(
            file.buffer, nombre_area, nombre_curso, nombreArchivoDrive, file.mimetype
        );

        // Formatear tamaño del archivo
        const tamanoFormateado = formatearTamano(file.size);

        // Actualizar registro en la BD (archivo_url = drive_file_id)
        await pool.query(
            `UPDATE documento_curso 
             SET archivo_nombre = ?, 
                 archivo_url = ?, 
                 fecha_subida = NOW(), 
                 tamano = ?
             WHERE documento_id = ?`,
            [nombreArchivoDrive, driveFile.id, tamanoFormateado, documentoId]
        );

        res.json({
            success: true,
            message: 'Archivo subido exitosamente',
            archivo: {
                nombre: nombreArchivoDrive,
                url: driveFile.id,
                drive_file_id: driveFile.id,
                tamano: tamanoFormateado
            }
        });
    } catch (error) {
        handleError(res, error, 'Error al subir archivo');
    }
});

