// Eliminar documento de todos los cursos que lo tengan
app.post('/api/documentos/:documentoId/eliminar-todos', requireAdminOrControlDocumental, async (req, res) => {
    try {
        const { documentoId } = req.params;

        // Obtener el nombre del documento para buscar todos los que tengan ese nombre
        const [docInfo] = await pool.query(
            `SELECT nombre FROM documento_curso WHERE documento_id = ? AND activo = TRUE LIMIT 1`,
            [documentoId]
        );

        if (docInfo.length === 0) {
            return res.status(404).json({
                success: false,
                message: 'Documento no encontrado'
            });
        }

        const nombreDocumento = docInfo[0].nombre;

        // Obtener todos los documentos con ese nombre y sus archivos
        const [documentos] = await pool.query(
            `SELECT d.documento_id, d.archivo_url, c.nombre_curso, a.nombre_area
             FROM documento_curso d
             INNER JOIN curso c ON d.curso_id = c.curso_id
             INNER JOIN area_tematica a ON c.area_id = a.area_id
             WHERE d.nombre = ? AND d.activo = TRUE`,
            [nombreDocumento]
        );

        // Eliminar archivos de Google Drive (tolerante a IDs inválidos/rutas legacy)
        for (const doc of documentos) {
            if (doc.archivo_url) {
                const esIdValido = !doc.archivo_url.includes('/') && !doc.archivo_url.includes('\\');
                if (esIdValido) {
                    try {
                        await driveService.eliminarArchivo(doc.archivo_url);
                    } catch (error) {
                        // silenced
                    }
                } else {
                    // silenced
                }
            }
        }

        // Eliminación permanente de la BD
        const [result] = await pool.query(
            `DELETE FROM documento_curso WHERE nombre = ? AND activo = TRUE`,
            [nombreDocumento]
        );

        res.json({
            success: true,
            message: `Documento eliminado de ${documentos.length} cursos`,
            cursos_afectados: documentos.length
        });
    } catch (error) {
        handleError(res, error, 'Error al eliminar documento de todos los cursos');
    }
});

// Eliminar documento requerido de un curso específico (soft delete)
app.delete('/api/cursos/:cursoId/documentos/:documentoId', async (req, res) => {
    try {
        const { cursoId, documentoId } = req.params;

        // Obtener información del documento antes de eliminar
        const [documento] = await pool.query(
            `SELECT d.archivo_url, d.nombre, c.nombre_curso, a.nombre_area
             FROM documento_curso d
             INNER JOIN curso c ON d.curso_id = c.curso_id
             INNER JOIN area_tematica a ON c.area_id = a.area_id
             WHERE d.documento_id = ? AND d.curso_id = ?`,
            [documentoId, cursoId]
        );

        if (documento.length === 0) {
            return res.status(404).json({
                success: false,
                message: 'Documento no encontrado en este curso'
            });
        }

        // Verificar si hay otros cursos con el mismo nombre de documento
        const [otrosCursos] = await pool.query(
            `SELECT COUNT(*) as total FROM documento_curso 
             WHERE nombre = ? AND curso_id != ?`,
            [documento[0].nombre, cursoId]
        );

        // Si hay archivo subido y NO hay otros cursos con este documento, eliminarlo de Google Drive
        if (documento[0].archivo_url && otrosCursos[0].total === 0) {
            const esIdValido = !documento[0].archivo_url.includes('/') && !documento[0].archivo_url.includes('\\');
            if (esIdValido) {
                try {
                    await driveService.eliminarArchivo(documento[0].archivo_url);
                } catch (error) {
                    // silenced
                }
            } else {
                // silenced
            }
        }

        // Eliminación SOLO de este curso específico
        await pool.query(
            `DELETE FROM documento_curso WHERE documento_id = ? AND curso_id = ?`,
            [documentoId, cursoId]
        );

        res.json({
            success: true,
            message: 'Documento eliminado del curso exitosamente'
        });
    } catch (error) {
        handleError(res, error, 'Error al eliminar documento');
    }
});

