// Eliminar solo el archivo del documento (mantiene el registro en BD)
app.delete('/api/cursos/:cursoId/documentos/:documentoId/archivo', async (req, res) => {
    try {
        const { cursoId, documentoId } = req.params;

        const [documento] = await pool.query(
            `SELECT archivo_url, archivo_nombre FROM documento_curso WHERE documento_id = ? AND curso_id = ?`,
            [documentoId, cursoId]
        );

        if (documento.length === 0) {
            return res.status(404).json({
                success: false,
                message: 'Documento no encontrado'
            });
        }

        if (!documento[0].archivo_url) {
            return res.status(400).json({
                success: false,
                message: 'Este documento no tiene archivo subido'
            });
        }

        // Intentar eliminar de Google Drive (si falla, limpiar BD de todos modos)
        let driveEliminado = false;
        const archivoUrl = documento[0].archivo_url;

        // Solo intentar eliminar de Drive si parece un ID válido de Google Drive
        // (los IDs de Drive NO contienen "/" ni "\")
        const esIdDriveValido = archivoUrl && !archivoUrl.includes('/') && !archivoUrl.includes('\\');

        if (esIdDriveValido) {
            try {
                await driveService.eliminarArchivo(archivoUrl);
                driveEliminado = true;
            } catch (driveError) {
                // silenced
            }
        } else {
            // silenced
        }

        // SIEMPRE limpiar campos del archivo en la BD (mantiene el documento)
        await pool.query(
            `UPDATE documento_curso
             SET archivo_nombre = NULL,
                 archivo_url = NULL,
                 fecha_subida = NULL,
                 tamano = NULL
             WHERE documento_id = ? AND curso_id = ?`,
            [documentoId, cursoId]
        );

        const mensaje = driveEliminado
            ? 'Archivo eliminado de Google Drive y base de datos exitosamente.'
            : 'Referencia del archivo limpiada de la base de datos. El documento está listo para subir un nuevo archivo.';

        res.json({
            success: true,
            message: mensaje,
            drive_eliminado: driveEliminado
        });
    } catch (error) {
        handleError(res, error, 'Error al eliminar archivo');
    }
});

// Reemplazar archivo de documento existente
app.put('/api/cursos/:cursoId/documentos/:documentoId/archivo', uploadDocumento.single('file'), async (req, res) => {
    try {
        const { cursoId, documentoId } = req.params;
        const file = req.file;

        if (!file) {
            return res.status(400).json({
                success: false,
                message: 'No se recibió ningún archivo'
            });
        }

        // Obtener información del documento y curso
        const [documentoInfo] = await pool.query(
            `SELECT d.archivo_url, c.nombre_curso, a.nombre_area
             FROM documento_curso d
             INNER JOIN curso c ON d.curso_id = c.curso_id
             INNER JOIN area_tematica a ON c.area_id = a.area_id
             WHERE d.documento_id = ? AND d.curso_id = ?`,
            [documentoId, cursoId]
        );

        if (documentoInfo.length === 0) {
            return res.status(404).json({
                success: false,
                message: 'Documento no encontrado'
            });
        }

        const { archivo_url, nombre_curso, nombre_area } = documentoInfo[0];

        // Obtener nombre del apartado para construir el nombre de archivo
        const [docNombre] = await pool.query('SELECT nombre FROM documento_curso WHERE documento_id = ?', [documentoId]);
        const nombre_apartado = docNombre.length > 0 ? docNombre[0].nombre : 'Documento';

        // Si existe un archivo anterior, intentar eliminarlo de Google Drive
        if (archivo_url) {
            const esIdValido = !archivo_url.includes('/') && !archivo_url.includes('\\');
            if (esIdValido) {
                try {
                    await driveService.eliminarArchivo(archivo_url);
                } catch (error) {
                    // silenced
                }
            } else {
                // silenced
            }
        }

        // Construir nombre del archivo: NombreCurso_NombreApartado.extension
        const extensionOriginal = file.originalname.split('.').pop();
        const cursoLimpio = (nombre_curso || 'Curso').replace(/[<>:"/\\|?*]/g, '').replace(/\s+/g, '').trim();
        const apartadoLimpio = (nombre_apartado || 'Documento').replace(/[<>:"/\\|?*]/g, '').replace(/\s+/g, '').trim();
        const nombreArchivoDrive = `${cursoLimpio}_${apartadoLimpio}.${extensionOriginal}`;

        // Subir nuevo archivo a Google Drive
        const driveFile = await driveService.subirDocumentoCurso(
            file.buffer, nombre_area, nombre_curso, nombreArchivoDrive, file.mimetype
        );

        const tamanoFormateado = formatearTamano(file.size);

        // Actualizar registro en la BD (archivo_url = drive_file_id)
        await pool.query(
            `UPDATE documento_curso 
             SET archivo_nombre = ?, 
                 archivo_url = ?, 
                 fecha_subida = NOW(), 
                 tamano = ?
             WHERE documento_id = ?`,
            [nombreArchivoDrive, driveFile.id, tamanoFormateado, documentoId]
        );

        res.json({
            success: true,
            message: 'Archivo reemplazado exitosamente',
            archivo: {
                nombre: nombreArchivoDrive,
                url: driveFile.id,
                drive_file_id: driveFile.id,
                tamano: tamanoFormateado
            }
        });
    } catch (error) {
        handleError(res, error, 'Error al reemplazar archivo');
    }
});

// Descargar archivo de documento desde Google Drive
app.get('/api/cursos/:cursoId/documentos/:documentoId/descargar', async (req, res) => {
    try {
        const { cursoId, documentoId } = req.params;
        const { preview } = req.query;

        const [documento] = await pool.query(
            `SELECT archivo_nombre, archivo_url FROM documento_curso WHERE documento_id = ? AND curso_id = ?`,
            [documentoId, cursoId]
        );

        if (documento.length === 0 || !documento[0].archivo_url) {
            return res.status(404).json({
                success: false,
                message: 'Archivo no encontrado'
            });
        }

        const { archivo_nombre, archivo_url } = documento[0];

        // Verificar que archivo_url sea un ID válido de Google Drive
        const esIdDriveValido = archivo_url && !archivo_url.includes('/') && !archivo_url.includes('\\');
        if (!esIdDriveValido) {
            return res.status(404).json({
                success: false,
                message: 'Este archivo tiene una referencia antigua (no está en Google Drive). Elimínelo y vuelva a subirlo.'
            });
        }

        // Obtener el archivo de Google Drive (archivo_url = drive_file_id)
        const fileBuffer = await driveService.descargarArchivo(archivo_url);

        // Determinar el tipo de contenido
        const extension = archivo_nombre.split('.').pop().toLowerCase();
        const contentType = {
            'pdf': 'application/pdf',
            'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'doc': 'application/msword',
            'xls': 'application/vnd.ms-excel',
            'png': 'image/png',
            'jpg': 'image/jpeg',
            'jpeg': 'image/jpeg',
            'gif': 'image/gif',
            'pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation',
            'ppt': 'application/vnd.ms-powerpoint'
        }[extension] || 'application/octet-stream';

        res.setHeader('Content-Type', contentType);
        res.setHeader('Cache-Control', 'public, max-age=3600');

        // Sanitizar nombre de archivo para evitar header injection
        const nombreSeguro = archivo_nombre.replace(/["\r\n]/g, '').replace(/[^a-zA-Z0-9._\- ]/g, '_');

        // Si preview=true, mostrar en el navegador; si no, forzar descarga
        if (preview === 'true') {
            res.setHeader('Content-Disposition', `inline; filename="${nombreSeguro}"`);
        } else {
            res.setHeader('Content-Disposition', `attachment; filename="${nombreSeguro}"`);
        }

        // Envolver en Buffer.from() para asegurar compatibilidad
        res.send(Buffer.from(fileBuffer));
    } catch (error) {
        console.error(`[ERROR] Error al descargar documento ${req.params.documentoId}:`, error.message);
        handleError(res, error, 'Error al descargar archivo');
    }
});

// Función helper para formatear tamaño de archivo
function formatearTamano(bytes) {
    if (bytes < 1024) return bytes + ' B';
    if (bytes < 1024 * 1024) return (bytes / 1024).toFixed(1) + ' KB';
    return (bytes / (1024 * 1024)).toFixed(1) + ' MB';
}

