// Sugerencia automática de Objetivos/Expectativas para un curso programado
app.get('/api/cursos-programados/:programadoId/informe-estructura-sugerida', async (req, res) => {
    try {
        const programadoId = Number(req.params.programadoId);
        if (!programadoId || Number.isNaN(programadoId)) {
            return res.status(400).json({ success: false, message: 'ID de curso programado inválido.' });
        }

        const [rows] = await pool.query(
            `SELECT c.nombre_curso, c.objetivo, c.objetivos_especificos, c.expectativas
             FROM curso_programado cp
             JOIN curso c ON c.curso_id = cp.curso_id
             WHERE cp.programado_id = ?
             LIMIT 1`,
            [programadoId]
        );

        if (!rows.length) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado.' });
        }

        const nombreCurso = rows[0].nombre_curso || '';
        const objetivoGeneral = String(rows[0].objetivo || '').trim();
        const objetivosEspecificos = parseListaTextoCurso(rows[0].objetivos_especificos);
        const expectativasCurso = parseListaTextoCurso(rows[0].expectativas);
        const objetivosCurso = [objetivoGeneral, ...objetivosEspecificos].filter(Boolean);
        const sugerencia = buscarSugerenciaPorCurso(nombreCurso);

        if (objetivosCurso.length || expectativasCurso.length) {
            const expectativas = expectativasCurso.length
                ? expectativasCurso
                : (Array.isArray(sugerencia?.estructura?.expectativas) ? sugerencia.estructura.expectativas : []);

            return res.json({
                success: true,
                programadoId,
                nombreCurso,
                matched: true,
                matchType: 'curso_catalogo',
                score: 100,
                source: 'curso',
                estructura: {
                    nombreCurso,
                    objetivos: objetivosCurso.length
                        ? objetivosCurso
                        : (Array.isArray(sugerencia?.estructura?.objetivos) ? sugerencia.estructura.objetivos : []),
                    expectativas,
                    expectativasTexto: expectativas.join('\n')
                }
            });
        }

        return res.json({
            success: true,
            programadoId,
            nombreCurso,
            ...sugerencia
        });
    } catch (error) {
        console.error('[INFORME-ESTRUCTURA] Error al generar sugerencia:', error);
        return res.status(500).json({ success: false, message: 'No se pudo resolver la sugerencia de estructura para el informe final.' });
    }
});

