async function asegurarColumnaPuestoEmpresa(db) {
    if (empresaPuestoColumnChecked) return;
    try {
        await db.query('ALTER TABLE empresa ADD COLUMN puesto VARCHAR(150) NULL AFTER contacto_nombre');
    } catch (error) {
        if (error.code !== 'ER_DUP_FIELDNAME') {
            throw error;
        }
    }

    // Migración compatible: copiar valores históricos desde contacto_puesto cuando exista.
    try {
        await db.query(`
            UPDATE empresa
            SET puesto = contacto_puesto
            WHERE (puesto IS NULL OR TRIM(puesto) = '')
              AND contacto_puesto IS NOT NULL
              AND TRIM(contacto_puesto) <> ''
        `);
    } catch (error) {
        if (error.code !== 'ER_BAD_FIELD_ERROR') {
            throw error;
        }
    }

    empresaPuestoColumnChecked = true;
}

