function parseColaboradorEmpresaId(value) {
    if (value === undefined || value === null || value === '' || value === 'null') {
        return null;
    }
    const parsed = Number(value);
    return Number.isInteger(parsed) && parsed > 0 ? parsed : null;
}

function parseCursosDocumentoIds(raw) {
    if (Array.isArray(raw)) {
        return [...new Set(raw.map(Number).filter((id) => Number.isFinite(id) && id > 0))];
    }
    if (typeof raw === 'string' && raw.trim()) {
        try {
            const parsed = JSON.parse(raw);
            if (Array.isArray(parsed)) {
                return [...new Set(parsed.map(Number).filter((id) => Number.isFinite(id) && id > 0))];
            }
        } catch (_) { /* ignore */ }
    }
    return [];
}

function claveDocumentoParticipante(p) {
    const inscripcionId = Number(p?.inscripcion_id);
    const cursoDocId = Number(p?.curso_documento_id) || 0;
    return `${inscripcionId}_${cursoDocId}`;
}

function descripcionDocumentoInscripcion(tipo, inscripcionId, cursoDocId, usaColaboradoras, cursoCatalogoId = null) {
    const ins = Number(inscripcionId);
    const curColab = Number(cursoDocId) || 0;
    const curCatalogo = Number(cursoCatalogoId) || 0;
    if (usaColaboradoras && curColab > 0) {
        return `${tipo}_inscripcion_${ins}_curso_${curColab}`;
    }
    // Generación multi-curso (cursoDestino): sufijo por catálogo para no pisar individuales
    // de otros cursos al regenerar en el mismo programado.
    if (curCatalogo > 0) {
        return `${tipo}_inscripcion_${ins}_curso_${curCatalogo}`;
    }
    return `${tipo}_inscripcion_${ins}`;
}

const RE_DOC_CONSTANCIA_DC3 = /^(constancia_inscripcion_|dc3_inscripcion_|constancias_lote_programado|dc3_lote_pdf_programado|dc3_lote_excel_programado)/i;

function esDescripcionConstanciaODc3(descripcion) {
    return RE_DOC_CONSTANCIA_DC3.test(String(descripcion || '').trim());
}

function clasificarDescripcionConstanciaDc3(descripcion) {
    const d = String(descripcion || '').trim();
    if (/^constancia_inscripcion_/i.test(d) || /^constancias_lote_programado/i.test(d)) {
        return 'constancia';
    }
    if (/^dc3_inscripcion_/i.test(d) || /^dc3_lote_/i.test(d)) {
        return 'dc3';
    }
    return null;
}

function extraerCursoCatalogoIdDeDescripcion(descripcion, cursoPrincipalId) {
    const d = String(descripcion || '').trim();
    if (!esDescripcionConstanciaODc3(d)) {
        return null;
    }
    const match = d.match(/_curso_(\d+)$/i);
    if (match) {
        return Number(match[1]);
    }
    const principal = Number(cursoPrincipalId);
    return Number.isFinite(principal) && principal > 0 ? principal : 0;
}

function extraerInscripcionIdDeDescripcion(descripcion) {
    const match = String(descripcion || '').match(/^(?:constancia|dc3)_inscripcion_(\d+)/i);
    return match ? Number(match[1]) : null;
}

let documentoCursoActivoColumnChecked = false;
let bajaConstanciaDc3TableChecked = false;

async function asegurarColumnasDocumentoCursoActivo(db) {
    if (documentoCursoActivoColumnChecked) return;
    await addColumnIfNotExists(db, 'documento_curso_programado', 'activo', 'TINYINT(1) NOT NULL DEFAULT 1');
    await addColumnIfNotExists(db, 'documento_curso_programado', 'desactivado_at', 'DATETIME NULL');
    await addColumnIfNotExists(db, 'documento_curso_programado', 'desactivado_por', 'INT NULL');
    documentoCursoActivoColumnChecked = true;
}

async function asegurarTablaBajaConstanciaDc3(db) {
    if (bajaConstanciaDc3TableChecked) return;
    await db.query(`
        CREATE TABLE IF NOT EXISTS baja_constancia_dc3 (
            baja_id INT AUTO_INCREMENT PRIMARY KEY,
            programado_id INT NOT NULL,
            curso_catalogo_id INT NULL,
            inscripcion_id INT NOT NULL,
            empleado_id INT NULL,
            empleado_nombre VARCHAR(255) NULL,
            curp VARCHAR(30) NULL,
            documentos_json JSON NULL,
            usuario_id INT NULL,
            usuario_nombre VARCHAR(200) NULL,
            created_at DATETIME DEFAULT CURRENT_TIMESTAMP,
            INDEX idx_baja_programado (programado_id),
            INDEX idx_baja_inscripcion (inscripcion_id),
            INDEX idx_baja_usuario (usuario_id)
        ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
    `);
    bajaConstanciaDc3TableChecked = true;
}

async function listarDocumentosConstanciasDc3Programado(programadoId, { incluirInactivos = false } = {}) {
    await asegurarColumnasDocumentoCursoActivo(pool);
    const filtroActivo = incluirInactivos ? '' : ' AND COALESCE(activo, 1) = 1';
    const [rows] = await pool.query(
        `SELECT documento_prog_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion, fecha_subida,
                COALESCE(activo, 1) AS activo
         FROM documento_curso_programado
         WHERE programado_id = ?
           AND (
             descripcion LIKE 'constancia_inscripcion_%'
             OR descripcion LIKE 'dc3_inscripcion_%'
             OR descripcion LIKE 'constancias_lote_programado%'
             OR descripcion LIKE 'dc3_lote_pdf_programado%'
             OR descripcion LIKE 'dc3_lote_excel_programado%'
           )${filtroActivo}
         ORDER BY fecha_subida DESC`,
        [programadoId]
    );
    return Array.isArray(rows) ? rows : [];
}

async function diagnosticarConstanciasDc3Programado(programadoId) {
    const [cursoRows] = await pool.query(
        `SELECT cp.programado_id, cp.curso_id, c.nombre_curso, emp.nombre_empresa
         FROM curso_programado cp
         JOIN curso c ON c.curso_id = cp.curso_id
         LEFT JOIN empresa emp ON emp.empresa_id = cp.empresa_id
         WHERE cp.programado_id = ?
         LIMIT 1`,
        [programadoId]
    );
    if (!Array.isArray(cursoRows) || cursoRows.length === 0) {
        return null;
    }

    const curso = cursoRows[0];
    const cursoPrincipalId = Number(curso.curso_id);
    const docs = await listarDocumentosConstanciasDc3Programado(programadoId);

    const idsDrive = [...new Set(
        docs.map((d) => d.drive_file_id).filter((id) => esDriveIdValido(id))
    )];
    let existencia = new Map();
    if (idsDrive.length > 0 && typeof driveService.verificarArchivosLote === 'function') {
        try {
            existencia = await driveService.verificarArchivosLote(idsDrive);
        } catch (err) {
            console.warn('[WARN] diagnostico constancias/DC-3: no se pudo verificar Drive:', err.message);
        }
    }

    const nombresCurso = new Map();
    nombresCurso.set(cursoPrincipalId, curso.nombre_curso || `Curso ${cursoPrincipalId}`);

    const gruposMap = new Map();
    const asegurarGrupo = (cursoCatalogoId) => {
        const id = Number(cursoCatalogoId) || 0;
        if (!gruposMap.has(id)) {
            gruposMap.set(id, {
                curso_catalogo_id: id,
                nombre_curso: nombresCurso.get(id) || `Curso ${id}`,
                total_constancias: 0,
                total_dc3: 0,
                huerfanos: 0,
                total: 0,
                documentos: []
            });
        }
        return gruposMap.get(id);
    };

    for (const doc of docs) {
        const cursoCatalogoId = extraerCursoCatalogoIdDeDescripcion(doc.descripcion, cursoPrincipalId);
        if (cursoCatalogoId == null) continue;

        const tipo = clasificarDescripcionConstanciaDc3(doc.descripcion);
        const driveOk = esDriveIdValido(doc.drive_file_id)
            && existencia.get(doc.drive_file_id) !== false;
        const esHuerfano = !driveOk;

        const grupo = asegurarGrupo(cursoCatalogoId);
        if (tipo === 'constancia') grupo.total_constancias += 1;
        if (tipo === 'dc3') grupo.total_dc3 += 1;
        if (esHuerfano) grupo.huerfanos += 1;
        grupo.total += 1;
        grupo.documentos.push({
            ...doc,
            curso_catalogo_id: cursoCatalogoId,
            tipo_doc: tipo,
            huerfano: esHuerfano
        });
    }

    const idsFaltantes = [...gruposMap.keys()].filter((id) => id > 0 && !nombresCurso.has(id));
    if (idsFaltantes.length > 0) {
        const [cursosExtra] = await pool.query(
            'SELECT curso_id, nombre_curso FROM curso WHERE curso_id IN (?)',
            [idsFaltantes]
        );
        for (const row of (Array.isArray(cursosExtra) ? cursosExtra : [])) {
            nombresCurso.set(Number(row.curso_id), row.nombre_curso || `Curso ${row.curso_id}`);
        }
        for (const [id, grupo] of gruposMap.entries()) {
            grupo.nombre_curso = nombresCurso.get(id) || grupo.nombre_curso;
        }
    }

    const grupos = [...gruposMap.values()]
        .map(({ documentos, ...rest }) => rest)
        .sort((a, b) => String(a.nombre_curso).localeCompare(String(b.nombre_curso), 'es'));

    return {
        curso: {
            programado_id: Number(curso.programado_id),
            curso_id: cursoPrincipalId,
            nombre_curso: curso.nombre_curso || '',
            nombre_empresa: curso.nombre_empresa || ''
        },
        diagnostico: {
            total_documentos: docs.length,
            grupos
        },
        // Interno para reutilizar en limpieza (no se expone en HTTP)
        _docsEnriquecidos: [...gruposMap.values()].flatMap((g) => g.documentos)
    };
}

async function limpiarConstanciasDc3Programado(programadoId, cursoCatalogoId, modo = 'curso') {
    const diag = await diagnosticarConstanciasDc3Programado(programadoId);
    if (!diag) {
        const err = new Error('Curso programado no encontrado');
        err.statusCode = 404;
        throw err;
    }

    const cursoId = Number(cursoCatalogoId);
    if (!Number.isFinite(cursoId) || cursoId <= 0) {
        const err = new Error('curso_catalogo_id inválido');
        err.statusCode = 400;
        throw err;
    }

    const grupo = (diag.diagnostico.grupos || []).find((g) => Number(g.curso_catalogo_id) === cursoId);
    const docsGrupo = (diag._docsEnriquecidos || []).filter((d) => Number(d.curso_catalogo_id) === cursoId);
    if (!grupo || docsGrupo.length === 0) {
        return {
            nombre_curso: diag.curso.nombre_curso,
            eliminados_bd: 0,
            eliminados_drive: 0,
            carpetas_drive_eliminadas: [],
            errores_drive: []
        };
    }

    const docsAEliminar = modo === 'huerfanos'
        ? docsGrupo.filter((d) => d.huerfano)
        : docsGrupo;

    if (docsAEliminar.length === 0) {
        return {
            nombre_curso: grupo.nombre_curso || diag.curso.nombre_curso,
            eliminados_bd: 0,
            eliminados_drive: 0,
            carpetas_drive_eliminadas: [],
            errores_drive: []
        };
    }

    const erroresDrive = [];
    const padresDrive = new Set();
    let eliminadosDrive = 0;

    for (const doc of docsAEliminar) {
        if (!esDriveIdValido(doc.drive_file_id)) {
            continue;
        }
        try {
            const meta = await driveService.obtenerMetadatosArchivo(doc.drive_file_id).catch(() => null);
            const parents = Array.isArray(meta?.parents) ? meta.parents : [];
            parents.forEach((p) => {
                if (p) padresDrive.add(String(p));
            });
        } catch (_) { /* ignore */ }

        try {
            const ok = await driveService.eliminarArchivo(doc.drive_file_id);
            if (ok) eliminadosDrive += 1;
        } catch (driveErr) {
            erroresDrive.push(`${doc.nombre_archivo || doc.drive_file_id}: ${driveErr.message || 'error Drive'}`);
        }
    }

    const idsBd = docsAEliminar.map((d) => Number(d.documento_prog_id)).filter((id) => Number.isFinite(id) && id > 0);
    let eliminadosBd = 0;
    if (idsBd.length > 0) {
        const [delResult] = await pool.query(
            'DELETE FROM documento_curso_programado WHERE programado_id = ? AND documento_prog_id IN (?)',
            [programadoId, idsBd]
        );
        eliminadosBd = Number(delResult?.affectedRows) || 0;
    }

    // Limpiar flags/folios en inscripciones afectadas (solo modo curso completo)
    if (modo === 'curso') {
        const inscConstancia = new Set();
        const inscDc3 = new Set();
        for (const doc of docsAEliminar) {
            const inscId = extraerInscripcionIdDeDescripcion(doc.descripcion);
            if (!Number.isFinite(inscId) || inscId <= 0) continue;
            if (doc.tipo_doc === 'constancia') inscConstancia.add(inscId);
            if (doc.tipo_doc === 'dc3') inscDc3.add(inscId);
        }

        if (inscConstancia.size > 0) {
            await pool.query(
                `UPDATE inscripcion_curso
                 SET certificado_generado = 0,
                     certificado_url = NULL,
                     folio_constancia = NULL,
                     fecha_certificado = NULL,
                     updated_at = NOW()
                 WHERE programado_id = ? AND inscripcion_id IN (?)`,
                [programadoId, [...inscConstancia]]
            );
        }
        if (inscDc3.size > 0) {
            await pool.query(
                `UPDATE inscripcion_curso
                 SET folio_dc3 = NULL, updated_at = NOW()
                 WHERE programado_id = ? AND inscripcion_id IN (?)`,
                [programadoId, [...inscDc3]]
            );
        }
    }

    const carpetasDriveEliminadas = [];
    for (const parentId of padresDrive) {
        try {
            const archivos = await driveService.listarArchivosCarpeta(parentId);
            const subcarpetas = await driveService.listarSubcarpetas(parentId);
            if ((archivos || []).length === 0 && (subcarpetas || []).length === 0) {
                const meta = await driveService.obtenerMetadatosArchivo(parentId).catch(() => null);
                const eliminada = await driveService.eliminarCarpetaPorId(parentId);
                if (eliminada) {
                    carpetasDriveEliminadas.push(meta?.name || parentId);
                }
            }
        } catch (_) { /* ignore */ }
    }

    return {
        nombre_curso: grupo.nombre_curso || diag.curso.nombre_curso,
        eliminados_bd: eliminadosBd,
        eliminados_drive: eliminadosDrive,
        carpetas_drive_eliminadas: carpetasDriveEliminadas,
        errores_drive: erroresDrive
    };
}

async function listarParticipantesConstanciasDc3(programadoId, cursoCatalogoId) {
    const diag = await diagnosticarConstanciasDc3Programado(programadoId);
    if (!diag) return null;

    const cursoPrincipalId = Number(diag.curso.curso_id);
    const cursoId = Number(cursoCatalogoId);
    const docs = (diag._docsEnriquecidos || []).filter((d) => {
        if (Number(d.curso_catalogo_id) !== cursoId) return false;
        const insc = extraerInscripcionIdDeDescripcion(d.descripcion);
        return Number.isFinite(insc) && insc > 0;
    });

    const porInscripcion = new Map();
    for (const doc of docs) {
        const inscId = extraerInscripcionIdDeDescripcion(doc.descripcion);
        if (!porInscripcion.has(inscId)) {
            porInscripcion.set(inscId, {
                inscripcion_id: inscId,
                total_constancias: 0,
                total_dc3: 0,
                documentos: []
            });
        }
        const item = porInscripcion.get(inscId);
        if (doc.tipo_doc === 'constancia') item.total_constancias += 1;
        if (doc.tipo_doc === 'dc3') item.total_dc3 += 1;
        item.documentos.push(doc);
    }

    const ids = [...porInscripcion.keys()];
    if (ids.length === 0) {
        return { curso: diag.curso, participantes: [] };
    }

    const [empleados] = await pool.query(
        `SELECT ic.inscripcion_id, ic.empleado_id,
                TRIM(CONCAT_WS(' ',
                    NULLIF(TRIM(e.apellido_paterno), ''),
                    NULLIF(TRIM(e.apellido_materno), ''),
                    NULLIF(TRIM(e.nombre), '')
                )) AS nombre_completo,
                e.curp, e.puesto
         FROM inscripcion_curso ic
         JOIN empleado e ON e.empleado_id = ic.empleado_id
         WHERE ic.programado_id = ? AND ic.inscripcion_id IN (?)`,
        [programadoId, ids]
    );

    const meta = new Map((Array.isArray(empleados) ? empleados : []).map((r) => [Number(r.inscripcion_id), r]));
    const participantes = [...porInscripcion.values()]
        .map((p) => {
            const info = meta.get(Number(p.inscripcion_id)) || {};
            return {
                inscripcion_id: p.inscripcion_id,
                empleado_id: info.empleado_id || null,
                nombre_completo: info.nombre_completo || `Inscripción ${p.inscripcion_id}`,
                curp: info.curp || '',
                puesto: info.puesto || '',
                total_constancias: p.total_constancias,
                total_dc3: p.total_dc3,
                total: p.total_constancias + p.total_dc3
            };
        })
        .sort((a, b) => String(a.nombre_completo).localeCompare(String(b.nombre_completo), 'es'));

    return {
        curso: diag.curso,
        curso_catalogo_id: cursoId,
        curso_principal_id: cursoPrincipalId,
        participantes
    };
}

async function bajaConstanciaDc3PorInscripcion(programadoId, cursoCatalogoId, inscripcionId, usuario = {}) {
    await asegurarColumnasDocumentoCursoActivo(pool);
    await asegurarTablaBajaConstanciaDc3(pool);

    const diag = await diagnosticarConstanciasDc3Programado(programadoId);
    if (!diag) {
        const err = new Error('Curso programado no encontrado');
        err.statusCode = 404;
        throw err;
    }

    const cursoId = Number(cursoCatalogoId);
    const inscId = Number(inscripcionId);
    if (!Number.isFinite(cursoId) || cursoId <= 0 || !Number.isFinite(inscId) || inscId <= 0) {
        const err = new Error('curso_catalogo_id o inscripcion_id inválidos');
        err.statusCode = 400;
        throw err;
    }

    const docs = (diag._docsEnriquecidos || []).filter((d) => {
        if (Number(d.curso_catalogo_id) !== cursoId) return false;
        return extraerInscripcionIdDeDescripcion(d.descripcion) === inscId;
    });

    if (docs.length === 0) {
        const err = new Error('No hay constancias/DC-3 activos para esa inscripción');
        err.statusCode = 404;
        throw err;
    }

    const [empRows] = await pool.query(
        `SELECT ic.inscripcion_id, ic.empleado_id,
                TRIM(CONCAT_WS(' ',
                    NULLIF(TRIM(e.apellido_paterno), ''),
                    NULLIF(TRIM(e.apellido_materno), ''),
                    NULLIF(TRIM(e.nombre), '')
                )) AS nombre_completo,
                e.curp
         FROM inscripcion_curso ic
         JOIN empleado e ON e.empleado_id = ic.empleado_id
         WHERE ic.programado_id = ? AND ic.inscripcion_id = ?
         LIMIT 1`,
        [programadoId, inscId]
    );
    const empleado = Array.isArray(empRows) && empRows[0] ? empRows[0] : {};

    const [cursoRows] = await pool.query(
        `SELECT cp.fecha_inicio, c.nombre_curso, e.nombre_empresa
         FROM curso_programado cp
         JOIN curso c ON c.curso_id = cp.curso_id
         JOIN empresa e ON e.empresa_id = cp.empresa_id
         WHERE cp.programado_id = ?
         LIMIT 1`,
        [programadoId]
    );
    const cursoInfo = Array.isArray(cursoRows) && cursoRows[0] ? cursoRows[0] : null;

    let carpetaBorradosId = null;
    if (cursoInfo) {
        try {
            const carpetaResult = await driveService.crearCarpetaCapacitacion(
                cursoInfo.nombre_empresa,
                cursoInfo.nombre_curso,
                cursoInfo.fecha_inicio
            );
            if (carpetaResult?.success && carpetaResult.folderId) {
                carpetaBorradosId = await driveService.obtenerOCrearCarpeta('Registros Borrados', carpetaResult.folderId);
            }
        } catch (driveErr) {
            console.warn('[WARN] No se pudo preparar carpeta Registros Borrados:', driveErr.message);
        }
    }

    const erroresDrive = [];
    const movidosDrive = [];
    const usuarioId = Number(usuario?.id || usuario?.usuario_id || 0) || null;
    const usuarioNombre = String(
        usuario?.nombre_completo
        || [usuario?.nombre, usuario?.apellido].filter(Boolean).join(' ')
        || usuario?.username
        || ''
    ).trim() || null;

    for (const doc of docs) {
        if (esDriveIdValido(doc.drive_file_id) && carpetaBorradosId) {
            try {
                await driveService.moverArchivoDrive(doc.drive_file_id, carpetaBorradosId);
                movidosDrive.push({
                    documento_prog_id: doc.documento_prog_id,
                    nombre_archivo: doc.nombre_archivo,
                    drive_file_id: doc.drive_file_id,
                    tipo: doc.tipo_doc
                });
            } catch (driveErr) {
                erroresDrive.push(`${doc.nombre_archivo || doc.drive_file_id}: ${driveErr.message || 'error al mover'}`);
            }
        } else if (esDriveIdValido(doc.drive_file_id) && !carpetaBorradosId) {
            erroresDrive.push(`${doc.nombre_archivo || doc.drive_file_id}: no se pudo resolver carpeta Registros Borrados`);
        }
    }

    const idsBd = docs.map((d) => Number(d.documento_prog_id)).filter((id) => Number.isFinite(id) && id > 0);
    let desactivadosBd = 0;
    if (idsBd.length > 0) {
        const [upd] = await pool.query(
            `UPDATE documento_curso_programado
             SET activo = 0,
                 desactivado_at = NOW(),
                 desactivado_por = ?
             WHERE programado_id = ? AND documento_prog_id IN (?) AND COALESCE(activo, 1) = 1`,
            [usuarioId, programadoId, idsBd]
        );
        desactivadosBd = Number(upd?.affectedRows) || 0;
    }

    const tieneConstancia = docs.some((d) => d.tipo_doc === 'constancia');
    const tieneDc3 = docs.some((d) => d.tipo_doc === 'dc3');
    if (tieneConstancia) {
        await pool.query(
            `UPDATE inscripcion_curso
             SET certificado_generado = 0,
                 certificado_url = NULL,
                 folio_constancia = NULL,
                 fecha_certificado = NULL,
                 updated_at = NOW()
             WHERE programado_id = ? AND inscripcion_id = ?`,
            [programadoId, inscId]
        );
    }
    if (tieneDc3) {
        await pool.query(
            `UPDATE inscripcion_curso
             SET folio_dc3 = NULL, updated_at = NOW()
             WHERE programado_id = ? AND inscripcion_id = ?`,
            [programadoId, inscId]
        );
    }

    const [bajaResult] = await pool.query(
        `INSERT INTO baja_constancia_dc3
         (programado_id, curso_catalogo_id, inscripcion_id, empleado_id, empleado_nombre, curp, documentos_json, usuario_id, usuario_nombre)
         VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?)`,
        [
            programadoId,
            cursoId,
            inscId,
            empleado.empleado_id || null,
            empleado.nombre_completo || null,
            empleado.curp || null,
            JSON.stringify(docs.map((d) => ({
                documento_prog_id: d.documento_prog_id,
                descripcion: d.descripcion,
                nombre_archivo: d.nombre_archivo,
                drive_file_id: d.drive_file_id,
                tipo: d.tipo_doc
            }))),
            usuarioId,
            usuarioNombre
        ]
    );

    return {
        nombre_curso: diag.curso.nombre_curso,
        inscripcion_id: inscId,
        empleado_nombre: empleado.nombre_completo || '',
        desactivados_bd: desactivadosBd,
        movidos_drive: movidosDrive.length,
        carpeta_registros_borrados: carpetaBorradosId ? 'Registros Borrados' : null,
        baja_id: bajaResult?.insertId || null,
        errores_drive: erroresDrive
    };
}

