/** Empresa principal + colaboradoras con datos para constancias/DC-3. */
async function obtenerGrupoEmpresasColaboradoras(db, empresaId) {
    const id = Number(empresaId);
    if (!Number.isInteger(id) || id <= 0) {
        return { empresaPrincipalId: null, empresas: [], tieneColaboradoras: false };
    }
    await asegurarColumnaColaboradorEmpresa(db);
    const [rows] = await db.query(
        `SELECT empresa_id, nombre_empresa, razon_social, rfc, colaborador, logo
         FROM empresa
         WHERE activo = TRUE AND (empresa_id = ? OR colaborador = ?)
         ORDER BY CASE WHEN colaborador IS NULL OR colaborador = 0 THEN 0 ELSE 1 END, nombre_empresa`,
        [id, id]
    );
    const empresas = (Array.isArray(rows) ? rows : []).map((row) => ({
        empresa_id: Number(row.empresa_id),
        nombre_empresa: row.nombre_empresa || '',
        razon_social: row.razon_social || row.nombre_empresa || '',
        rfc: row.rfc || '',
        colaborador: row.colaborador != null ? Number(row.colaborador) : null,
        logo: row.logo || null,
        es_principal: !row.colaborador || Number(row.colaborador) === 0
    }));
    const tieneColaboradoras = empresas.some((e) => !e.es_principal);
    const principal = empresas.find((e) => e.es_principal) || empresas[0] || null;
    return {
        empresaPrincipalId: principal?.empresa_id || id,
        empresas,
        tieneColaboradoras
    };
}

/** Enriquece participantes con empresa/curso de documento cuando hay empresas colaboradoras. */
async function enriquecerParticipantesDocumentosColaboradoras(db, programadoId, participantes, usaEmpresasColaboradoras) {
    if (!usaEmpresasColaboradoras || !Array.isArray(participantes) || participantes.length === 0) {
        return participantes;
    }

    await asegurarColumnasDocumentosColaboradoras(db);

    const mapaAsignaciones = new Map();

    participantes.forEach((p) => {
        const inscripcionId = Number(p?.inscripcion_id);
        if (!Number.isFinite(inscripcionId)) return;
        const empresaDocRaw = p?.empresa_documento_id;
        const cursoDocRaw = p?.curso_documento_id;
        const empresaDoc = empresaDocRaw != null && empresaDocRaw !== '' ? Number(empresaDocRaw) : null;
        const cursoDoc = cursoDocRaw != null && cursoDocRaw !== '' ? Number(cursoDocRaw) : null;
        if (Number.isFinite(empresaDoc) || Number.isFinite(cursoDoc)) {
            mapaAsignaciones.set(inscripcionId, {
                empresa_documento_id: Number.isFinite(empresaDoc) ? empresaDoc : null,
                curso_documento_id: Number.isFinite(cursoDoc) ? cursoDoc : null
            });
        }
    });

    const inscripcionIds = participantes
        .map((p) => Number(p?.inscripcion_id))
        .filter((id) => Number.isFinite(id));
    const faltantes = inscripcionIds.filter((id) => !mapaAsignaciones.has(id));

    if (faltantes.length > 0) {
        const [rows] = await db.query(
            `SELECT inscripcion_id, empresa_documento_id, curso_documento_id
             FROM inscripcion_curso
             WHERE programado_id = ? AND inscripcion_id IN (?)`,
            [programadoId, faltantes]
        );
        (Array.isArray(rows) ? rows : []).forEach((row) => {
            const id = Number(row.inscripcion_id);
            if (!mapaAsignaciones.has(id)) {
                mapaAsignaciones.set(id, {
                    empresa_documento_id: row.empresa_documento_id != null ? Number(row.empresa_documento_id) : null,
                    curso_documento_id: row.curso_documento_id != null ? Number(row.curso_documento_id) : null
                });
            }
        });
    }

    const empresaIds = new Set();
    const cursoIds = new Set();
    mapaAsignaciones.forEach((asign) => {
        if (asign.empresa_documento_id) empresaIds.add(asign.empresa_documento_id);
        if (asign.curso_documento_id) cursoIds.add(asign.curso_documento_id);
    });

    const mapaEmpresas = new Map();
    const mapaCursos = new Map();

    if (empresaIds.size > 0) {
        const [empRows] = await db.query(
            'SELECT empresa_id, nombre_empresa, razon_social, rfc, logo FROM empresa WHERE empresa_id IN (?)',
            [[...empresaIds]]
        );
        (Array.isArray(empRows) ? empRows : []).forEach((empresa) => {
            mapaEmpresas.set(Number(empresa.empresa_id), empresa);
        });
    }

    if (cursoIds.size > 0) {
        const [cursoRows] = await db.query(
            'SELECT curso_id, nombre_curso, area_id, folio FROM curso WHERE curso_id IN (?)',
            [[...cursoIds]]
        );
        (Array.isArray(cursoRows) ? cursoRows : []).forEach((curso) => {
            mapaCursos.set(Number(curso.curso_id), curso);
        });
    }

    return participantes.map((p) => {
        const inscripcionId = Number(p?.inscripcion_id);
        const asign = mapaAsignaciones.get(inscripcionId);
        if (!asign) return p;

        const empresa = asign.empresa_documento_id ? mapaEmpresas.get(asign.empresa_documento_id) : null;
        const cursoDoc = asign.curso_documento_id ? mapaCursos.get(asign.curso_documento_id) : null;

        return {
            ...p,
            empresa_documento_id: asign.empresa_documento_id,
            curso_documento_id: asign.curso_documento_id,
            nombre_empresa_doc: empresa ? (empresa.razon_social || empresa.nombre_empresa || '') : null,
            rfc_empresa_doc: empresa?.rfc || null,
            empresa_logo_doc: empresa?.logo || null,
            nombre_curso_doc: cursoDoc?.nombre_curso || null,
            area_id_doc: cursoDoc?.area_id ?? null,
            folio_curso_doc: cursoDoc?.folio || null
        };
    });
}

/** Empresa principal + empresas colaboradoras vinculadas (para cursos, etc.). */
async function obtenerIdsEmpresasConColaboradoras(db, empresaId) {
    const id = Number(empresaId);
    if (!Number.isInteger(id) || id <= 0) {
        return [];
    }
    await asegurarColumnaColaboradorEmpresa(db);
    const [rows] = await db.query(
        `SELECT empresa_id
         FROM empresa
         WHERE activo = TRUE AND (empresa_id = ? OR colaborador = ?)`,
        [id, id]
    );
    return rows.map((row) => Number(row.empresa_id)).filter((value) => value > 0);
}

let empresaRfcUniqueDropped = false;

/** Permite varias empresas con el mismo RFC (p. ej. razones sociales distintas). */
async function asegurarRfcNoUnicoEmpresa(db) {
    if (empresaRfcUniqueDropped) return;
    try {
        await db.query('ALTER TABLE empresa DROP INDEX rfc');
    } catch (error) {
        if (error.code !== 'ER_CANT_DROP_FIELD_OR_KEY' && error.code !== 'ER_DROP_INDEX_FK') {
            throw error;
        }
    }
    try {
        await db.query('CREATE INDEX idx_empresa_rfc ON empresa (rfc)');
    } catch (error) {
        if (error.code !== 'ER_DUP_KEYNAME') {
            throw error;
        }
    }
    empresaRfcUniqueDropped = true;
}

