function normalizarTextoComparacionEmpresa(valor) {
    return String(valor || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .trim();
}

function normalizarTelefonoComparacionEmpresa(valor) {
    return String(valor || '').replace(/\D/g, '');
}

/**
 * Detecta registros muy parecidos. Mismo RFC con datos distintos no genera advertencia;
 * RFC + nombre u otros campos repetidos sí.
 */
async function evaluarSimilitudRegistroEmpresa(db, datos) {
    const rfc = String(datos.rfc || '').trim().toUpperCase();
    if (!rfc) {
        return { advertencia_alta: false, coincidencias: [], mismo_rfc_existente: false };
    }

    const [existentes] = await db.query(
        `SELECT empresa_id, nombre_empresa, rfc, estado, ciudad, codigo_postal, email, telefono, contacto_email
         FROM empresa
         WHERE UPPER(TRIM(rfc)) = ? AND activo = TRUE`,
        [rfc]
    );

    if (!existentes.length) {
        return { advertencia_alta: false, coincidencias: [], mismo_rfc_existente: false };
    }

    const entrada = {
        nombre_empresa: normalizarTextoComparacionEmpresa(datos.nombre_empresa),
        estado: normalizarTextoComparacionEmpresa(datos.estado),
        ciudad: normalizarTextoComparacionEmpresa(datos.ciudad),
        codigo_postal: String(datos.codigo_postal || '').trim()
    };

    const coincidencias = [];

    for (const empresa of existentes) {
        const camposCoincidentes = [];
        const comparar = (campo, valorEntrada, valorExistente) => {
            if (!valorEntrada || !valorExistente) return;
            if (valorEntrada === valorExistente) {
                camposCoincidentes.push(campo);
            }
        };

        comparar(
            'nombre_empresa',
            entrada.nombre_empresa,
            normalizarTextoComparacionEmpresa(empresa.nombre_empresa)
        );
        comparar('estado', entrada.estado, normalizarTextoComparacionEmpresa(empresa.estado));
        comparar('ciudad', entrada.ciudad, normalizarTextoComparacionEmpresa(empresa.ciudad));
        comparar('codigo_postal', entrada.codigo_postal, String(empresa.codigo_postal || '').trim());

        const advertenciaAlta = camposCoincidentes.includes('nombre_empresa') || camposCoincidentes.length >= 2;

        if (advertenciaAlta) {
            coincidencias.push({
                empresa_id: empresa.empresa_id,
                nombre_empresa: empresa.nombre_empresa,
                rfc: empresa.rfc,
                campos_coincidentes: camposCoincidentes
            });
        }
    }

    return {
        advertencia_alta: coincidencias.length > 0,
        mismo_rfc_existente: existentes.length > 0,
        coincidencias
    };
}

