async function obtenerExpresionPuestoEmpresa(db, alias = 'e') {
    const safeAlias = /^[a-zA-Z_][a-zA-Z0-9_]*$/.test(alias) ? alias : 'e';

    if (!empresaPuestoExprCache) {
        let existePuesto = false;
        let existeContactoPuesto = false;

        try {
            const [rowsPuesto] = await db.query("SHOW COLUMNS FROM empresa LIKE 'puesto'");
            existePuesto = Array.isArray(rowsPuesto) && rowsPuesto.length > 0;
        } catch (_) {
            existePuesto = false;
        }

        try {
            const [rowsContactoPuesto] = await db.query("SHOW COLUMNS FROM empresa LIKE 'contacto_puesto'");
            existeContactoPuesto = Array.isArray(rowsContactoPuesto) && rowsContactoPuesto.length > 0;
        } catch (_) {
            existeContactoPuesto = false;
        }

        if (existePuesto && existeContactoPuesto) {
            empresaPuestoExprCache = "COALESCE(NULLIF(TRIM({ALIAS}.puesto), ''), NULLIF(TRIM({ALIAS}.contacto_puesto), ''))";
        } else if (existePuesto) {
            empresaPuestoExprCache = '{ALIAS}.puesto';
        } else if (existeContactoPuesto) {
            empresaPuestoExprCache = '{ALIAS}.contacto_puesto';
        } else {
            empresaPuestoExprCache = 'NULL';
        }
    }

    return empresaPuestoExprCache.replace(/\{ALIAS\}/g, safeAlias);
}

function generarPasswordTemporalEmpresa(length = 12) {
    const upper = 'ABCDEFGHJKLMNPQRSTUVWXYZ';
    const lower = 'abcdefghijkmnopqrstuvwxyz';
    const digits = '23456789';
    const symbols = '@#$%*!?';
    const all = `${upper}${lower}${digits}${symbols}`;

    const base = [
        upper[Math.floor(Math.random() * upper.length)],
        lower[Math.floor(Math.random() * lower.length)],
        digits[Math.floor(Math.random() * digits.length)],
        symbols[Math.floor(Math.random() * symbols.length)]
    ];

    while (base.length < length) {
        base.push(all[Math.floor(Math.random() * all.length)]);
    }

    for (let i = base.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [base[i], base[j]] = [base[j], base[i]];
    }

    return base.join('');
}

function normalizarCorreoCredenciales(correo = '') {
    return String(correo || '').trim().toLowerCase();
}

function esCorreoValidoCredenciales(correo = '') {
    return /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(normalizarCorreoCredenciales(correo));
}

function parseCorreosCredencialesExtra(raw) {
    let candidatos = [];

    if (Array.isArray(raw)) {
        candidatos = raw;
    } else if (typeof raw === 'string') {
        const valor = raw.trim();
        if (!valor) return [];

        try {
            const parsed = JSON.parse(valor);
            if (Array.isArray(parsed)) {
                candidatos = parsed;
            } else {
                candidatos = valor.split(',');
            }
        } catch (_) {
            candidatos = valor.split(',');
        }
    } else if (raw !== null && raw !== undefined) {
        candidatos = [raw];
    }

    const vistos = new Set();
    const resultado = [];

    for (const candidato of candidatos) {
        const correo = normalizarCorreoCredenciales(candidato);
        if (!correo || !esCorreoValidoCredenciales(correo) || vistos.has(correo)) {
            continue;
        }
        vistos.add(correo);
        resultado.push(correo);
    }

    return resultado;
}

function construirDestinatariosCredenciales(principal, extras = [], adicionales = []) {
    const lista = [principal, ...(Array.isArray(extras) ? extras : []), ...(Array.isArray(adicionales) ? adicionales : [])];
    const vistos = new Set();
    const destinatarios = [];

    for (const item of lista) {
        const correosParseados = parseCorreosCredencialesExtra(item);
        if (correosParseados.length > 0) {
            for (const correo of correosParseados) {
                if (vistos.has(correo)) continue;
                vistos.add(correo);
                destinatarios.push(correo);
            }
            continue;
        }

        // Fallback compatible: intentar envío si parece correo, incluso sin validación estricta.
        const correoFallback = normalizarCorreoCredenciales(item);
        if (!correoFallback || !correoFallback.includes('@') || vistos.has(correoFallback)) {
            continue;
        }

        vistos.add(correoFallback);
        destinatarios.push(correoFallback);
    }

    return destinatarios;
}

function clonarAdjuntosCorreo(adjuntos = []) {
    if (!Array.isArray(adjuntos) || adjuntos.length === 0) return [];

    return adjuntos.map((adjunto) => ({
        ...adjunto,
        content: Buffer.isBuffer(adjunto?.content)
            ? Buffer.from(adjunto.content)
            : adjunto?.content
    }));
}

const NOMBRE_MANUAL_EMPRESA = 'Manual de Usuario Empresa_BiznagaRisk&Tech.pdf';
const DRIVE_MANUAL_EMPRESA_URL_DEFAULT = 'https://drive.google.com/file/d/1YnAxhC6pvWcJ0fRhO8A9G_eYpsn4YAil/view?usp=sharing';
const REGISTRO_EMPRESA_FILE_1 = process.env.REGISTRO_EMPRESA_FILE_1 || 'https://drive.google.com/file/d/1tWYFyMNH9Z1Mr_Kiydw1HhLF1jk4BMXR/view?usp=drive_link';
const CURSO_INVITACION_FILE_1 = process.env.CURSO_INVITACION_FILE_1 || 'https://docs.google.com/spreadsheets/d/1Ot7q9QWlMyBr_TDIzAdtZRqe5JpU85p6/edit?usp=drive_link&ouid=103344182675934160095&rtpof=true&sd=true';
const CURSO_INVITACION_FILE_2 = process.env.CURSO_INVITACION_FILE_2 || 'https://drive.google.com/file/d/1tWYFyMNH9Z1Mr_Kiydw1HhLF1jk4BMXR/view?usp=drive_link';

function extraerDriveIdDesdeUrl(valor) {
    const raw = String(valor || '').trim();
    if (!raw) return '';
    if (/^[a-zA-Z0-9_-]{10,}$/.test(raw)) return raw;
    const byIdParam = raw.match(/[?&]id=([a-zA-Z0-9_-]+)/);
    const byPath = raw.match(/\/d\/([a-zA-Z0-9_-]+)/);
    return byIdParam?.[1] || byPath?.[1] || '';
}

const DRIVE_MANUAL_EMPRESA_ID = (() => {
    const envId = String(process.env.DRIVE_MANUAL_EMPRESA_ID || '').trim();
    const envUrl = String(process.env.DRIVE_MANUAL_EMPRESA_URL || '').trim();
    return extraerDriveIdDesdeUrl(envId)
        || extraerDriveIdDesdeUrl(envUrl)
        || extraerDriveIdDesdeUrl(DRIVE_MANUAL_EMPRESA_URL_DEFAULT);
})();

async function obtenerAdjuntoManualEmpresa() {
    try {
        let fileId = String(DRIVE_MANUAL_EMPRESA_ID || '').trim();
        let filename = NOMBRE_MANUAL_EMPRESA;

        if (!fileId) {
            const archivo = await driveService.buscarArchivoGlobal(NOMBRE_MANUAL_EMPRESA);
            if (!archivo?.id) return null;
            fileId = archivo.id;
            filename = archivo.name || NOMBRE_MANUAL_EMPRESA;
        }

        const fileBuffer = await driveService.descargarArchivo(fileId);
        if (!Buffer.isBuffer(fileBuffer) || fileBuffer.length === 0) return null;

        return {
            filename,
            content: fileBuffer,
            contentType: 'application/pdf'
        };
    } catch (error) {
        console.warn('[EMAIL] No se pudo adjuntar el manual de empresa:', error.message);
        return null;
    }
}

async function obtenerAdjuntoManualEmpresaConTimeout(timeoutMs = 12000) {
    const timeoutPromise = new Promise((resolve) => {
        setTimeout(() => resolve(null), timeoutMs);
    });

    try {
        const resultado = await Promise.race([
            obtenerAdjuntoManualEmpresa(),
            timeoutPromise
        ]);

        if (!resultado) {
            console.warn('[EMAIL] Manual de empresa no adjuntado por timeout o no disponible.');
        }

        return resultado;
    } catch (error) {
        console.warn('[EMAIL] Error al resolver adjunto del manual:', error.message);
        return null;
    }
}

function asegurarExtensionArchivo(nombreArchivo = '', extension = '') {
    const nombre = String(nombreArchivo || '').trim();
    const ext = String(extension || '').trim().replace(/^\./, '').toLowerCase();
    if (!nombre) return ext ? `archivo.${ext}` : 'archivo';
    if (!ext) return nombre;
    return nombre.toLowerCase().endsWith(`.${ext}`) ? nombre : `${nombre}.${ext}`;
}

async function construirAdjuntoDriveDesdeReferencia(fileRef, fallbackName = 'archivo') {
    try {
        const fileId = extraerDriveIdDesdeUrl(fileRef);
        if (!fileId) return null;

        const pareceSheet = /spreadsheets\/d\//i.test(String(fileRef || ''));
        let mimeType = '';
        let nombreBase = fallbackName;

        try {
            const info = await driveService.obtenerInfoArchivo(fileId);
            mimeType = String(info?.mimeType || '').trim();
            nombreBase = info?.name || fallbackName;
        } catch (infoError) {
            console.warn('[EMAIL] No se pudo obtener metadata del adjunto (se intentará fallback):', infoError.message);
        }

        const esGoogleSheetNativo = mimeType === 'application/vnd.google-apps.spreadsheet';
        const esExcelNativo = mimeType === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            || mimeType === 'application/vnd.ms-excel';
        const esHojaCalculo = esGoogleSheetNativo
            || esExcelNativo
            || (!mimeType && pareceSheet);
        const esSheet = esGoogleSheetNativo || (!mimeType && pareceSheet);

        if (esHojaCalculo) {
            try {
                const bufferXlsx = await driveService.exportarArchivoXLSX(fileId);
                if (Buffer.isBuffer(bufferXlsx) && bufferXlsx.length > 0) {
                    return {
                        filename: asegurarExtensionArchivo(nombreBase, 'xlsx'),
                        content: bufferXlsx,
                        contentType: 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
                    };
                }
            } catch (sheetError) {
                console.warn('[EMAIL] Export API de Google Sheet falló, se intenta descarga pública:', sheetError.message);
            }
        } else {
            try {
                const fileBuffer = await driveService.descargarArchivo(fileId);
                if (Buffer.isBuffer(fileBuffer) && fileBuffer.length > 0) {
                    return {
                        filename: nombreBase,
                        content: fileBuffer,
                        contentType: mimeType || 'application/octet-stream'
                    };
                }
            } catch (driveError) {
                console.warn('[EMAIL] Descarga API de Drive falló, se intenta descarga pública:', driveError.message);
            }
        }

        const urlsFallback = esSheet
            ? [`https://docs.google.com/spreadsheets/d/${fileId}/export?format=xlsx`]
            : [`https://drive.google.com/uc?export=download&id=${fileId}`];

        for (const url of urlsFallback) {
            try {
                const response = await axios.get(url, {
                    responseType: 'arraybuffer',
                    timeout: 30000,
                    maxRedirects: 5,
                    validateStatus: (status) => status >= 200 && status < 400
                });

                const contentTypeResp = String(response?.headers?.['content-type'] || '').toLowerCase();
                const fileBuffer = Buffer.from(response.data || []);

                if (!Buffer.isBuffer(fileBuffer) || fileBuffer.length === 0) {
                    continue;
                }

                // Evitar adjuntar una página HTML de login/error.
                if (contentTypeResp.includes('text/html')) {
                    continue;
                }

                return {
                    filename: esSheet ? asegurarExtensionArchivo(nombreBase, 'xlsx') : nombreBase,
                    content: fileBuffer,
                    contentType: esSheet
                        ? 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
                        : (mimeType || contentTypeResp || 'application/octet-stream')
                };
            } catch (fallbackError) {
                console.warn('[EMAIL] Fallback público de adjunto falló:', fallbackError.message);
            }
        }

        return null;
    } catch (error) {
        console.warn('[EMAIL] No se pudo preparar adjunto de invitacion de curso:', error.message);
        return null;
    }
}

async function obtenerAdjuntosInvitacionCurso() {
    const manualId = String(DRIVE_MANUAL_EMPRESA_ID || '').trim();
    const referencias = [
        { ref: CURSO_INVITACION_FILE_1, nombreFallback: 'formato-capacitacion' },
        { ref: CURSO_INVITACION_FILE_2, nombreFallback: 'material-capacitacion' }
    ].filter(({ ref }) => {
        const refId = extraerDriveIdDesdeUrl(ref);
        return !(manualId && refId && refId === manualId);
    });

    const adjuntos = await Promise.all(
        referencias.map(({ ref, nombreFallback }) => construirAdjuntoDriveDesdeReferencia(ref, nombreFallback))
    );

    const nombreManualNormalizado = String(NOMBRE_MANUAL_EMPRESA || '').trim().toLowerCase();
    return adjuntos.filter((adjunto) => {
        if (!adjunto) return false;
        const nombreAdjunto = String(adjunto.filename || '').trim().toLowerCase();
        return nombreAdjunto !== nombreManualNormalizado;
    });
}

async function obtenerAdjuntosInvitacionCursoConTimeout(timeoutMs = 45000) {
    const timeoutPromise = new Promise((resolve) => {
        setTimeout(() => resolve([]), timeoutMs);
    });

    try {
        const resultado = await Promise.race([
            obtenerAdjuntosInvitacionCurso(),
            timeoutPromise
        ]);

        if (!Array.isArray(resultado)) return [];
        return resultado;
    } catch (error) {
        console.warn('[EMAIL] Error al resolver adjuntos de invitacion de curso:', error.message);
        return [];
    }
}

async function obtenerAdjuntosRegistroEmpresa() {
    const manualId = String(DRIVE_MANUAL_EMPRESA_ID || '').trim();
    const referencias = [
        { ref: REGISTRO_EMPRESA_FILE_1, nombreFallback: 'material-registro-empresa' }
    ].filter(({ ref }) => {
        const refId = extraerDriveIdDesdeUrl(ref);
        return !(manualId && refId && refId === manualId);
    });

    const adjuntos = await Promise.all(
        referencias.map(({ ref, nombreFallback }) => construirAdjuntoDriveDesdeReferencia(ref, nombreFallback))
    );

    return adjuntos.filter(Boolean);
}

async function obtenerAdjuntosRegistroEmpresaConTimeout(timeoutMs = 25000) {
    const timeoutPromise = new Promise((resolve) => {
        setTimeout(() => resolve([]), timeoutMs);
    });

    try {
        const resultado = await Promise.race([
            obtenerAdjuntosRegistroEmpresa(),
            timeoutPromise
        ]);

        if (!Array.isArray(resultado)) return [];
        return resultado;
    } catch (error) {
        console.warn('[EMAIL] Error al resolver adjuntos de registro de empresa:', error.message);
        return [];
    }
}

function normalizarUsernameEmpresa(valor = '') {
    return String(valor || '')
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase()
        .replace(/[^a-z0-9]/g, '')
        .slice(0, 30);
}

function generarUsernameEmpresaDinamico(nombreEmpresa = '') {
    const base = normalizarUsernameEmpresa(nombreEmpresa).slice(0, 5) || 'empre';
    const random = Math.floor(Math.random() * 9000) + 1000;
    return `${base}${random}`;
}

async function generarUsernameEmpresaUnico(db, usernamePropuesto = '', nombreEmpresa = '') {
    const baseInicial = normalizarUsernameEmpresa(usernamePropuesto) || generarUsernameEmpresaDinamico(nombreEmpresa);
    const baseRecortada = baseInicial.slice(0, 30) || 'empre0000';

    for (let intento = 0; intento < 30; intento++) {
        const sufijo = intento === 0 ? '' : `${Math.floor(Math.random() * 9000) + 1000}`;
        const largoBase = Math.max(1, 30 - sufijo.length);
        const candidato = `${baseRecortada.slice(0, largoBase)}${sufijo}`;

        const [rows] = await db.query(
            'SELECT id FROM usuario WHERE LOWER(username) = LOWER(?) LIMIT 1',
            [candidato]
        );

        if (!rows.length) {
            return candidato;
        }
    }

    throw new Error('No fue posible generar un username único para la empresa');
}

