// Obtener empleados de la empresa asociada a un curso programado.
// Permite instructor SOLO si es el instructor asignado a ese curso.
app.get('/api/cursos-programados/:programadoId/empleados-empresa', requireAdminEmpresaInstructor, async (req, res) => {
    try {
        const programadoId = Number(req.params.programadoId);
        if (!Number.isInteger(programadoId) || programadoId <= 0) {
            return res.status(400).json({ success: false, message: 'programadoId inválido' });
        }

        const [cursoRows] = await pool.query(
            'SELECT programado_id, empresa_id, instructor_id FROM curso_programado WHERE programado_id = ? LIMIT 1',
            [programadoId]
        );

        if (cursoRows.length === 0) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
        }

        const curso = cursoRows[0];
        const empresaIdCurso = Number(curso.empresa_id || 0);
        const instructorIdCurso = Number(curso.instructor_id || 0);

        if (!tieneAlgunRol(req, 'root', 'administrador', 'proteccion_civil')) {
            if (esPerfilEmpresa(req)) {
                const empresaIdUsuario = Number(req.user?.empresa_id || 0);
                if (!empresaIdUsuario || empresaIdUsuario !== empresaIdCurso) {
                    return res.status(403).json({ success: false, message: 'No tiene permiso para consultar empleados de este curso' });
                }
            } else if (tieneAlgunRol(req, 'instructor')) {
                const instructorIdUsuario = Number(req.user?.instructor_id || 0);
                if (!instructorIdUsuario || !instructorIdCurso || instructorIdUsuario !== instructorIdCurso) {
                    return res.status(403).json({ success: false, message: 'No tiene permiso para consultar empleados de este curso' });
                }
            } else {
                return res.status(403).json({ success: false, message: 'No tiene permiso para realizar esta acción' });
            }
        }

        const [rows] = await pool.query(
            `SELECT * FROM empleado WHERE empresa_id = ? ORDER BY activo DESC, apellido_paterno, nombre`,
            [empresaIdCurso]
        );

        res.json({
            success: true,
            empresa_id: empresaIdCurso,
            empleados: rows
        });
    } catch (error) {
        handleError(res, error);
    }
});

