// Actualizar empleado
app.put('/api/empleados/:id', requireRole('root', 'administrador', 'empresa'), async (req, res) => {
    try {
        const empleadoId = Number(req.params.id);
        if (!Number.isInteger(empleadoId) || empleadoId <= 0) {
            return res.status(400).json({ success: false, message: 'empleado_id inválido' });
        }

        const [empleadoRows] = await pool.query(
            'SELECT empleado_id, empresa_id FROM empleado WHERE empleado_id = ? LIMIT 1',
            [empleadoId]
        );

        if (empleadoRows.length === 0) {
            return res.status(404).json({ success: false, message: 'Empleado no encontrado' });
        }

        if (esPerfilEmpresa(req) && Number(req.user?.empresa_id || 0) !== Number(empleadoRows[0].empresa_id)) {
            return res.status(403).json({ success: false, message: 'No tiene permiso para editar empleados de otra empresa' });
        }

        const fields = req.body;

        // Whitelist de campos permitidos (nunca permitir cambiar empresa_id, activo, etc.)
        const camposPermitidos = ['nombre', 'curp',
            'puesto', 'email', 'telefono', 'fecha_nacimiento', 'genero',
            'escolaridad', 'educacion', 'antiguedad', 'edad', 'cursos_tomados',
            'estado', 'ciudad', 'nombre_empleado', 'numero_empleado',
            'rfc_empleado', 'nss', 'departamento', 'fecha_ingreso'];

        const fieldMap = { 'nombre_empleado': 'nombre' };

        const updatePayload = {};

        Object.keys(fields).forEach(key => {
            if (camposPermitidos.includes(key) && fields[key] !== undefined) {
                const dbField = fieldMap[key] || key;
                if (dbField === 'curp' || dbField === 'rfc_empleado') {
                    updatePayload[dbField] = String(fields[key] || '').toUpperCase().trim();
                } else if (dbField === 'nombre') {
                    updatePayload[dbField] = String(fields[key] || '').trim().toUpperCase();
                    // Regla funcional: para empleados el nombre completo se guarda en `nombre`.
                    updatePayload.apellido_paterno = '';
                    updatePayload.apellido_materno = '';
                } else {
                    updatePayload[dbField] = fields[key];
                }
            }
        });

        if (Object.keys(updatePayload).length === 0) {
            return res.json({ success: false, message: 'No hay campos para actualizar' });
        }

        await pool.query('UPDATE empleado SET ? WHERE empleado_id = ?', [updatePayload, empleadoId]);

        res.json({ success: true, message: 'Empleado actualizado' });
    } catch (error) {
        handleError(res, error);
    }
});

