// Obtener todos los instructores con sus áreas
app.get('/api/instructores', async (req, res) => {
    try {
        const { area_id } = req.query;

        let query, params = [];

        // Si se proporciona area_id, filtrar solo instructores de esa área
        if (area_id) {
            query = `SELECT i.*,
                   COALESCE(NULLIF(TRIM(u.email), ''), NULLIF(TRIM(i.email), '')) AS usuario_email,
                   u.foto_drive_id,
                        GROUP_CONCAT(DISTINCT a.nombre_area ORDER BY a.nombre_area SEPARATOR ', ') as areas,
                        GROUP_CONCAT(DISTINCT ia.area_id) as area_ids
                 FROM instructor i
                 INNER JOIN instructor_areas ia ON i.instructor_id = ia.instructor_id
               LEFT JOIN usuario u ON u.id = i.usuario_id AND u.activo = 1
                                LEFT JOIN roles r ON u.rol_id = r.rol_id
                 LEFT JOIN area_tematica a ON ia.area_id = a.area_id
                 WHERE i.activo = TRUE AND ia.area_id = ?
                                     AND (
                                                i.usuario_id IS NULL
                                                OR (
                                                        u.id IS NOT NULL
                                                        AND LOWER(COALESCE(r.nombre_rol, '')) <> 'doctor'
                                                        AND FIND_IN_SET('doctor', REPLACE(LOWER(COALESCE(u.roles_adicionales, '')), ' ', '')) = 0
                                                )
                                     )
                 GROUP BY i.instructor_id
                 ORDER BY i.apellido_paterno, i.nombre`;
            params.push(area_id);
        } else {
            query = `SELECT i.*,
                   COALESCE(NULLIF(TRIM(u.email), ''), NULLIF(TRIM(i.email), '')) AS usuario_email,
                   u.foto_drive_id,
                        GROUP_CONCAT(DISTINCT a.nombre_area ORDER BY a.nombre_area SEPARATOR ', ') as areas,
                        GROUP_CONCAT(DISTINCT ia.area_id) as area_ids
                 FROM instructor i
               LEFT JOIN usuario u ON u.id = i.usuario_id AND u.activo = 1
                                LEFT JOIN roles r ON u.rol_id = r.rol_id
                 LEFT JOIN instructor_areas ia ON i.instructor_id = ia.instructor_id
                 LEFT JOIN area_tematica a ON ia.area_id = a.area_id
                 WHERE i.activo = TRUE
                                     AND (
                                                i.usuario_id IS NULL
                                                OR (
                                                        u.id IS NOT NULL
                                                        AND LOWER(COALESCE(r.nombre_rol, '')) <> 'doctor'
                                                        AND FIND_IN_SET('doctor', REPLACE(LOWER(COALESCE(u.roles_adicionales, '')), ' ', '')) = 0
                                                )
                                     )
                 GROUP BY i.instructor_id
                 ORDER BY i.apellido_paterno, i.nombre`;
        }

        const [rows] = await pool.query(query, params);

        // Convertir area_ids a array de números
        const instructoresConAreas = rows.map(inst => ({
            ...inst,
            area_ids_array: inst.area_ids ? inst.area_ids.split(',').map(id => parseInt(id)) : []
        }));

        res.json({ success: true, instructores: instructoresConAreas });
    } catch (error) {
        handleError(res, error);
    }
});

// Crear instructor
app.post('/api/instructores', async (req, res) => {
    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();

        const { nombre, apellido_paterno, apellido_materno, curp, rfc, cedula_profesional,
            especialidad, certificaciones, email, telefono, direccion, tarifa_hora, areas } = req.body;

        if (!nombre || !apellido_paterno) {
            return res.json({ success: false, message: 'Nombre y apellido paterno son requeridos' });
        }

        const [result] = await conn.query(
            `INSERT INTO instructor (nombre, apellido_paterno, apellido_materno, curp, rfc, 
                                     cedula_profesional, especialidad, certificaciones, email, 
                                     telefono, direccion, tarifa_hora)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)`,
            [nombre, apellido_paterno, apellido_materno, curp?.toUpperCase(), rfc?.toUpperCase(),
                cedula_profesional, especialidad, certificaciones, email, telefono, direccion, tarifa_hora]
        );

        // Asociar áreas si se proporcionan
        if (areas && areas.length > 0) {
            const areaValues = areas.map(areaId => [result.insertId, areaId]);
            await conn.query(
                'INSERT INTO instructor_areas (instructor_id, area_id) VALUES ?',
                [areaValues]
            );
        }

        await conn.commit();
        res.json({ success: true, message: 'Instructor creado', instructor_id: result.insertId });
    } catch (error) {
        await conn.rollback();
        if (error.code === 'ER_DUP_ENTRY') {
            res.json({ success: false, message: 'El CURP ya está registrado' });
        } else {
            handleError(res, error);
        }
    } finally {
        conn.release();
    }
});

