// Obtener historial de cursos
app.get('/api/historial-cursos', async (req, res) => {
    try {
        const { empresa_id, curso_id } = req.query;
        let query = `
            SELECT h.*, c.nombre_curso, e.nombre_empresa,
                   CONCAT(i.nombre, ' ', i.apellido_paterno) as instructor_nombre
            FROM historial_cursos h
            JOIN curso c ON h.curso_id = c.curso_id
            JOIN empresa e ON h.empresa_id = e.empresa_id
            LEFT JOIN instructor i ON h.instructor_id = i.instructor_id
            WHERE 1=1
        `;
        const params = [];

        if (empresa_id) {
            query += ' AND h.empresa_id = ?';
            params.push(empresa_id);
        }
        if (curso_id) {
            query += ' AND h.curso_id = ?';
            params.push(curso_id);
        }

        query += ' ORDER BY h.fecha_inicio DESC';

        const [rows] = await pool.query(query, params);
        res.json({ success: true, historial: rows });
    } catch (error) {
        handleError(res, error);
    }
});

