let _cursoHistorialConsultaSchemaReady = false;
let _cursoHistorialConsultaSchemaPromise = null;

/** Tabla/columnas de historial consultado por administrador (debe existir antes de atender peticiones). */
async function ensureCursoHistorialConsultaSchema() {
    if (_cursoHistorialConsultaSchemaReady) {
        return;
    }
    if (_cursoHistorialConsultaSchemaPromise) {
        return _cursoHistorialConsultaSchemaPromise;
    }

    _cursoHistorialConsultaSchemaPromise = (async () => {
        await exigirPoolPrincipal();

        for (const alterHistQ of [
            `ALTER TABLE curso_programado ADD COLUMN historial_consultado TINYINT(1) NOT NULL DEFAULT 1`,
            `ALTER TABLE curso_programado ADD COLUMN historial_finalizado_at DATETIME NULL`
        ]) {
            try {
                await pool.query(alterHistQ);
            } catch (e) { /* columna ya existe */ }
        }

        try {
            await pool.query(
                `CREATE INDEX idx_cp_historial_pendiente
                 ON curso_programado (historial_consultado, estatus)`
            );
        } catch (e) { /* índice ya existe */ }

        await pool.query(`
            CREATE TABLE IF NOT EXISTS curso_historial_consulta_usuario (
                id INT AUTO_INCREMENT PRIMARY KEY,
                usuario_id INT NOT NULL,
                programado_id INT NOT NULL,
                consultado_en TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
                UNIQUE KEY uk_chcu_usuario_programado (usuario_id, programado_id),
                INDEX idx_chcu_usuario (usuario_id),
                INDEX idx_chcu_programado (programado_id)
            ) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci
        `);

        // Cursos ya finalizados antes de la migración: asignar fecha para alertas por usuario
        await pool.query(`
            UPDATE curso_programado
            SET historial_finalizado_at = COALESCE(updated_at, NOW())
            WHERE historial_finalizado_at IS NULL
              AND LOWER(COALESCE(estatus, '')) IN ('completado', 'finalizado', 'cerrado', 'terminado')
        `);

        _cursoHistorialConsultaSchemaReady = true;
    })().catch((err) => {
        _cursoHistorialConsultaSchemaPromise = null;
        throw err;
    });

    return _cursoHistorialConsultaSchemaPromise;
}

/**
 * Cursos finalizados aún no consultados por el administrador actual.
 */
async function listarHistorialPendientesConsulta(usuarioId, limit = 50) {
    await ensureCursoHistorialConsultaSchema();
    const uid = Number(usuarioId);
    if (!Number.isFinite(uid) || uid <= 0) {
        return [];
    }
    const lim = Math.min(Math.max(Number(limit) || 50, 1), 100);
    const [rows] = await pool.query(
        `SELECT cp.programado_id,
                cp.curso_id,
                cp.empresa_id,
                cp.historial_finalizado_at,
                cp.updated_at,
                c.nombre_curso,
                e.nombre_empresa
         FROM curso_programado cp
         INNER JOIN curso c ON c.curso_id = cp.curso_id
         INNER JOIN empresa e ON e.empresa_id = cp.empresa_id
         WHERE LOWER(COALESCE(cp.estatus, '')) IN ('completado', 'finalizado', 'cerrado', 'terminado')
           AND NOT EXISTS (
                SELECT 1
                FROM curso_historial_consulta_usuario chcu
                WHERE chcu.usuario_id = ?
                  AND chcu.programado_id = cp.programado_id
           )
           AND cp.historial_finalizado_at IS NOT NULL
         ORDER BY COALESCE(cp.historial_finalizado_at, cp.updated_at) DESC
         LIMIT ?`,
        [uid, lim]
    );
    return rows || [];
}

async function notificarUsuariosCursoFinalizado(programadoId) {
    try {
        const [infoRows] = await pool.query(
            `SELECT cp.programado_id, cp.curso_id, cp.empresa_id,
                    c.nombre_curso, e.nombre_empresa
             FROM curso_programado cp
             INNER JOIN curso c ON c.curso_id = cp.curso_id
             INNER JOIN empresa e ON e.empresa_id = cp.empresa_id
             WHERE cp.programado_id = ?
             LIMIT 1`,
            [programadoId]
        );
        if (!infoRows.length) return;
        const info = infoRows[0];

        const rolesSql = ROLES_HISTORIAL_CAPACITACION.map(() => '?').join(', ');
        const rolesAdicionalesSql = ROLES_HISTORIAL_CAPACITACION
            .map(() => `LOWER(COALESCE(u.roles_adicionales, '')) LIKE ?`)
            .join(' OR ');
        const rolesAdicionalesParams = ROLES_HISTORIAL_CAPACITACION.map((rol) => `%${rol}%`);

        const [usuarios] = await pool.query(
            `SELECT DISTINCT u.id
             FROM usuario u
             LEFT JOIN roles r ON u.rol_id = r.rol_id
             WHERE u.activo = 1
               AND (
                    LOWER(COALESCE(r.nombre_rol, '')) IN (${rolesSql})
                    OR ${rolesAdicionalesSql}
               )`,
            [...ROLES_HISTORIAL_CAPACITACION, ...rolesAdicionalesParams]
        );
        if (!usuarios.length) return;

        const titulo = 'Capacitación finalizada';
        const mensaje = `"${info.nombre_curso}" · ${info.nombre_empresa}`;
        const ruta = `/historial-cursos?empresa_id=${info.empresa_id}&programado_id=${info.programado_id}`;

        for (const usr of usuarios) {
            await pool.query(
                `INSERT INTO notificacion_usuario (usuario_id, tipo, icono, titulo, mensaje, ruta)
                 VALUES (?, 'success', 'fa-flag-checkered', ?, ?, ?)`,
                [usr.id, titulo, mensaje, ruta]
            );
        }
    } catch (e) {
        console.error('[NOTIF] Error notif curso finalizado:', e.message);
    }
}

