// Marcar un curso finalizado como consultado en historial (por usuario)
app.patch('/api/cursos-programados/:programadoId/historial-consultado', authMiddleware, requireHistorialCapacitacion, async (req, res) => {
    try {
        await ensureCursoHistorialConsultaSchema();
        const programadoId = Number(req.params.programadoId);
        const usuarioId = Number(req.user?.id);
        if (!Number.isFinite(programadoId) || programadoId <= 0) {
            return res.status(400).json({ success: false, message: 'programadoId inválido' });
        }
        if (!Number.isFinite(usuarioId) || usuarioId <= 0) {
            return res.status(400).json({ success: false, message: 'Usuario no válido' });
        }

        const [cursoRows] = await pool.query(
            `SELECT programado_id
             FROM curso_programado
             WHERE programado_id = ?
               AND LOWER(COALESCE(estatus, '')) IN ('completado', 'finalizado', 'cerrado', 'terminado')
             LIMIT 1`,
            [programadoId]
        );
        if (!cursoRows.length) {
            return res.status(404).json({ success: false, message: 'Curso finalizado no encontrado' });
        }

        await pool.query(
            `INSERT INTO curso_historial_consulta_usuario (usuario_id, programado_id)
             VALUES (?, ?)
             ON DUPLICATE KEY UPDATE consultado_en = NOW()`,
            [usuarioId, programadoId]
        );

        res.json({ success: true, programadoId, usuario_id: usuarioId, consultado: true });
    } catch (error) {
        console.error('[ERROR] historial-consultado:', error);
        handleError(res, error);
    }
});

