// Crear curso programado
app.post('/api/cursos-programados', async (req, res) => {
    try {
        const { curso_id, empresa_id, instructor_id, fecha_inicio, fecha_fin,
            hora_inicio, hora_fin, modalidad, ubicacion, lugar_capacitacion, codigo_postal, estado, ciudad, localidad, cupo, notas, created_by } = req.body;

        const horasInformeRaw = req.body?.horas_informe ?? req.body?.horas;
        const horasInformeNum = Number(horasInformeRaw);
        const horasInforme = Number.isFinite(horasInformeNum) && horasInformeNum > 0
            ? Math.trunc(horasInformeNum)
            : null;

        const ubicacionFinal = String(lugar_capacitacion ?? ubicacion ?? '').trim() || null;

        if (!curso_id || !empresa_id || !fecha_inicio) {
            return res.json({ success: false, message: 'Curso, empresa y fecha de inicio son requeridos' });
        }

        if (!instructor_id) {
            return res.json({ success: false, message: 'El instructor es obligatorio. No se puede programar un curso sin instructor asignado.' });
        }

        // Obtener información del curso y la empresa para crear la carpeta en Google Drive
        const [cursoInfo] = await pool.query(
            'SELECT nombre_curso FROM curso WHERE curso_id = ?',
            [curso_id]
        );

        const [empresaInfo] = await pool.query(
            'SELECT nombre_empresa FROM empresa WHERE empresa_id = ?',
            [empresa_id]
        );

        if (cursoInfo.length === 0 || empresaInfo.length === 0) {
            return res.json({ success: false, message: 'Curso o empresa no encontrados' });
        }

        const nombreCurso = cursoInfo[0].nombre_curso;
        const nombreEmpresa = empresaInfo[0].nombre_empresa;

        // Insertar curso programado en la base de datos
        const [result] = await pool.query(
            `INSERT INTO curso_programado (curso_id, empresa_id, instructor_id, fecha_inicio, fecha_fin,
                                           hora_inicio, hora_fin, modalidad, ubicacion, codigo_postal, estado, ciudad, localidad, cupo, horas_informe, estatus, notas, created_by, created_at)
             VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?, 'programado', ?, ?, NOW())`,
            [curso_id, empresa_id, instructor_id || null, fecha_inicio, fecha_fin || null,
                hora_inicio || null, hora_fin || null, modalidad || 'presencial', ubicacionFinal,
                codigo_postal || null, estado || null, ciudad || null, localidad || null, cupo || 25, horasInforme, notas || null, created_by || null]
        );

        const programadoId = result.insertId;

        // Crear carpeta en Google Drive usando fecha_inicio (no fecha de creación)
        // para que quede organizada en el año/mes correcto del curso
        const carpetaResult = await crearCarpetaCapacitacion(nombreEmpresa, nombreCurso, fecha_inicio);

        if (carpetaResult.success && carpetaResult.folderId) {
            // Guardar el ID de la carpeta para que todos los uploads futuros usen la misma
            await pool.query(
                'UPDATE curso_programado SET drive_folder_id = ? WHERE programado_id = ?',
                [carpetaResult.folderId, programadoId]
            );
        }

        res.json({
            success: true,
            message: 'Curso programado creado exitosamente',
            programado_id: programadoId,
            drive_folder: carpetaResult.success ? carpetaResult.path : null,
            carpeta_nombre: carpetaResult.success ? carpetaResult.nombreCarpeta : null
        });

        // Notificación in-app para el usuario de la empresa (fire-and-forget)
        pool.query('SELECT id FROM usuario WHERE empresa_id = ? LIMIT 1', [empresa_id])
            .then(([usrRows]) => {
                if (!usrRows.length) return;
                const empUserId = usrRows[0].id;
                const msg = `Se te ha asignado el curso "${nombreCurso}" con inicio el ${fecha_inicio}.`;
                return pool.query(
                    `INSERT INTO notificacion_usuario (usuario_id, tipo, icono, titulo, mensaje, ruta)
                     VALUES (?, 'info', 'fa-graduation-cap', 'Nuevo curso asignado', ?, '/cursosbiz')`,
                    [empUserId, msg]
                );
            })
            .catch(e => console.error('[NOTIF] Error notif empresa curso asignado:', e.message));

    } catch (error) {
        handleError(res, error);
    }
});

// ── Crear evento en Google Calendar corporativo (cuenta fija Biznaga) ──
app.post('/api/google-calendar/eventos/curso', async (req, res) => {
    try {
        const {
            summary,
            description,
            location,
            startDateTime,
            endDateTime,
            attendees,
            cursoId,
            sendInvitations
        } = req.body;

        if (!summary || !startDateTime || !endDateTime) {
            return res.status(400).json({
                success: false,
                message: 'summary, startDateTime y endDateTime son obligatorios'
            });
        }

        const inicio = new Date(startDateTime);
        const fin = new Date(endDateTime);
        if (Number.isNaN(inicio.getTime()) || Number.isNaN(fin.getTime())) {
            return res.status(400).json({
                success: false,
                message: 'Fechas inválidas para Google Calendar'
            });
        }

        const GOOGLE_CLIENT_ID = process.env.GOOGLE_CLIENT_ID;
        const GOOGLE_CLIENT_SECRET = process.env.GOOGLE_CLIENT_SECRET;
        const GOOGLE_REFRESH_TOKEN = process.env.GOOGLE_REFRESH_TOKEN;
        const GOOGLE_CALENDAR_CORPORATIVO = 'risktechbiznaga@gmail.com';

        if (!GOOGLE_CLIENT_ID || !GOOGLE_CLIENT_SECRET || !GOOGLE_REFRESH_TOKEN) {
            return res.status(500).json({
                success: false,
                message: 'Google Calendar corporativo no está configurado en el backend'
            });
        }

        const { google } = require('googleapis');
        const oauth2Client = new google.auth.OAuth2(GOOGLE_CLIENT_ID, GOOGLE_CLIENT_SECRET);
        oauth2Client.setCredentials({ refresh_token: GOOGLE_REFRESH_TOKEN });

        const calendar = google.calendar({ version: 'v3', auth: oauth2Client });

        const correosValidos = Array.isArray(attendees)
            ? [...new Set(attendees
                .map((email) => String(email || '').trim().toLowerCase())
                .filter((email) => /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)))]
            : [];

        const evento = {
            summary: String(summary || '').trim(),
            description: String(description || '').trim(),
            location: String(location || '').trim(),
            start: {
                dateTime: inicio.toISOString(),
                timeZone: 'America/Mexico_City'
            },
            end: {
                dateTime: fin.toISOString(),
                timeZone: 'America/Mexico_City'
            }
        };

        if (correosValidos.length > 0) {
            evento.attendees = correosValidos.map((email) => ({ email }));
        }

        if (cursoId) {
            evento.extendedProperties = {
                private: {
                    cursoId: String(cursoId)
                }
            };
        }

        const enviarInvitaciones = !!sendInvitations && correosValidos.length > 0;

        let respuesta;
        if (enviarInvitaciones) {
            try {
                respuesta = await calendar.events.insert({
                    calendarId: GOOGLE_CALENDAR_CORPORATIVO,
                    requestBody: evento,
                    sendUpdates: 'all'
                });
            } catch (errorEnvio) {
                respuesta = await calendar.events.insert({
                    calendarId: GOOGLE_CALENDAR_CORPORATIVO,
                    requestBody: evento,
                    sendUpdates: 'none'
                });
            }
        } else {
            respuesta = await calendar.events.insert({
                calendarId: GOOGLE_CALENDAR_CORPORATIVO,
                requestBody: evento,
                sendUpdates: 'none'
            });
        }

        return res.json({
            success: true,
            message: 'Evento creado en Google Calendar corporativo',
            calendar_id: GOOGLE_CALENDAR_CORPORATIVO,
            event_id: respuesta?.data?.id || null
        });
    } catch (error) {
        const detalleGoogle = error?.response?.data?.error;
        const detalleMensaje = detalleGoogle?.message || error?.message || 'Error desconocido';
        const detalleStatus = detalleGoogle?.status || '';

        console.error('[GOOGLE-CALENDAR] Error creando evento corporativo:', error?.response?.data || error.message || error);

        const esScopeInsuficiente =
            Number(detalleGoogle?.code || error?.code || 0) === 403 &&
            (
                String(detalleMensaje).toLowerCase().includes('insufficient authentication scopes') ||
                String(detalleStatus).toUpperCase().includes('PERMISSION_DENIED')
            );

        if (esScopeInsuficiente) {
            return res.status(403).json({
                success: false,
                message: 'Faltan permisos OAuth de Google Calendar en GOOGLE_REFRESH_TOKEN. Ejecuta "node backend/setup-google-oauth.js" para regenerarlo con scope calendar.events y reinicia el backend.',
                reason: 'insufficient_scopes',
                google_error: detalleMensaje
            });
        }

        return res.status(500).json({
            success: false,
            message: 'No se pudo crear el evento en Google Calendar corporativo',
            google_error: detalleMensaje
        });
    }
});

// Actualizar curso programado
const CURSO_PROGRAMADO_CAMPOS_PERMITIDOS = [
    'curso_id', 'instructor_id', 'empresa_id', 'fecha_inicio',
    'fecha_fin', 'hora_inicio', 'hora_fin', 'cupo',
    'estatus', 'notas', 'ubicacion', 'codigo_postal', 'estado', 'ciudad', 'localidad', 'modalidad',
    'usar_puesto_real_dc3', 'usa_empresas_colaboradoras'
];

app.put('/api/cursos-programados/:id', requireAdminOrControlDocumental, async (req, res) => {
    try {
        const fields = { ...req.body };
        // Compatibilidad: algunos clientes envían "lugar"; en BD la columna es "ubicacion".
        if (fields.lugar !== undefined && fields.ubicacion === undefined) {
            fields.ubicacion = fields.lugar;
        }
        delete fields.lugar;

        const updatePayload = {};

        Object.keys(fields).forEach(key => {
            if (CURSO_PROGRAMADO_CAMPOS_PERMITIDOS.includes(key) && fields[key] !== undefined) {
                updatePayload[key] = fields[key];
            }
        });

        if (Object.keys(updatePayload).length === 0) {
            return res.json({ success: false, message: 'No hay campos para actualizar' });
        }

        // Nunca permitir quitar el instructor de un curso programado
        if ('instructor_id' in updatePayload && !updatePayload.instructor_id) {
            return res.json({ success: false, message: 'El instructor es obligatorio. No se puede dejar un curso sin instructor asignado.' });
        }

        try {
            await pool.query('UPDATE curso_programado SET ? WHERE programado_id = ?', [updatePayload, req.params.id]);
        } catch (error) {
            if (esErrorColumnaUsarPuestoRealDc3(error) && Object.prototype.hasOwnProperty.call(updatePayload, 'usar_puesto_real_dc3')) {
                delete updatePayload.usar_puesto_real_dc3;

                if (Object.keys(updatePayload).length === 0) {
                    return res.json({
                        success: false,
                        message: 'La preferencia aún no se puede guardar porque falta la columna usar_puesto_real_dc3 en BD.'
                    });
                }

                await pool.query('UPDATE curso_programado SET ? WHERE programado_id = ?', [updatePayload, req.params.id]);
            } else {
                throw error;
            }
        }

        res.json({ success: true, message: 'Curso programado actualizado' });
    } catch (error) {
        handleError(res, error);
    }
});

// ── Eliminar curso programado con progreso SSE en tiempo real ──
// EventSource no soporta headers, por lo que el JWT se pasa como query param ?token=
app.get('/api/cursos-programados/:id/eliminar-stream', async (req, res) => {
    // Autenticación manual
    const token = req.query.token;
    if (!token) {
        return res.status(401).json({ success: false, message: 'Token requerido' });
    }
    let userDecoded;
    try {
        userDecoded = verifyJwtToken(token);
    } catch (err) {
        return res.status(401).json({ success: false, message: 'Token inválido o expirado' });
    }

    // Soporta `rol` (string) o `roles` (array). Permitir root y administrador.
    if (!usuarioPuedeEliminarCursoProgramado(userDecoded)) {
        return res.status(403).json({ success: false, message: 'Sin permisos: se requiere rol administrador o superior' });
    }

    const programadoId = req.params.id;

    // Cabeceras SSE
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    res.flushHeaders();

    const emit = (progress, step, message) => {
        res.write(`data: ${JSON.stringify({ progress, step, message })}\n\n`);
    };

    try {
        emit(5, 'verificando', 'Verificando curso...');

        const [curso] = await pool.query(
            `SELECT cp.programado_id, cp.curso_id, cp.empresa_id, cp.estatus,
                    cp.fecha_inicio, cp.fecha_fin, cp.created_at,
                    c.nombre_curso, e.nombre_empresa
             FROM curso_programado cp
             LEFT JOIN curso c ON c.curso_id = cp.curso_id
             LEFT JOIN empresa e ON e.empresa_id = cp.empresa_id
             WHERE cp.programado_id = ?`,
            [programadoId]
        );

        if (curso.length === 0) {
            res.write(`data: ${JSON.stringify({ error: true, message: 'Curso programado no encontrado' })}\n\n`);
            return res.end();
        }

        emit(15, 'carpeta', 'Buscando carpeta en Google Drive...');

        let carpetaCapacitacionEliminada = 0;
        const fechasIntentoCarpeta = [curso[0].created_at, curso[0].fecha_inicio, curso[0].fecha_fin].filter(Boolean);
        if (curso[0].nombre_empresa && curso[0].nombre_curso) {
            try {
                const eliminarCarpetaRes = await driveService.eliminarCarpetaCapacitacion(
                    curso[0].nombre_empresa,
                    curso[0].nombre_curso,
                    fechasIntentoCarpeta
                );
                if (eliminarCarpetaRes.success) {
                    carpetaCapacitacionEliminada = eliminarCarpetaRes.eliminadas || 0;
                }
            } catch (errorCarpeta) {
                // silenced
            }
        }

        emit(35, 'inscripciones', 'Eliminando inscripciones...');
        const [inscripcionesResult] = await pool.query(
            'DELETE FROM inscripcion_curso WHERE programado_id = ?',
            [programadoId]
        );

        emit(55, 'documentos', 'Eliminando documentos de Drive...');
        try {
            const [docsProgramado] = await pool.query(
                'SELECT drive_file_id FROM documento_curso_programado WHERE programado_id = ? AND drive_file_id IS NOT NULL AND drive_file_id != ""',
                [programadoId]
            );
            for (const doc of docsProgramado) {
                if (esDriveIdValido(doc.drive_file_id)) {
                    try { await driveService.eliminarArchivo(doc.drive_file_id); }
                    catch (e) { /* silenced */ }
                }
            }
            await pool.query('DELETE FROM documento_curso_programado WHERE programado_id = ?', [programadoId]);
        } catch (e) { /* tabla puede no existir */ }

        emit(75, 'encuestas', 'Eliminando encuestas...');
        try {
            await pool.query('DELETE FROM encuesta_satisfaccion WHERE programado_id = ?', [programadoId]);
        } catch (e) { /* tabla puede no existir */ }

        emit(90, 'curso', 'Eliminando registro del curso...');
        await pool.query('DELETE FROM curso_programado WHERE programado_id = ?', [programadoId]);


        // Emitir progreso final y resultado
        res.write(`data: ${JSON.stringify({
            progress: 100,
            step: 'done',
            message: 'Eliminación completada',
            done: true,
            success: true,
            inscripcionesEliminadas: inscripcionesResult.affectedRows,
            carpetasCapacitacionEliminadas: carpetaCapacitacionEliminada
        })}\n\n`);
        res.end();

    } catch (error) {
        console.error('[ERROR-SSE] Eliminar curso programado:', error);
        res.write(`data: ${JSON.stringify({ error: true, message: error.message || 'Error al eliminar el curso' })}\n\n`);
        res.end();
    }
});

// Eliminar un curso programado (administrador o superior, requiere verificación de contraseña en frontend)
app.delete('/api/cursos-programados/:id', requireAdminOrControlDocumental, async (req, res) => {
    try {
        const programadoId = req.params.id;

        // Verificar que el curso exista
        const [curso] = await pool.query(
            `SELECT cp.programado_id, cp.curso_id, cp.empresa_id, cp.estatus, cp.fecha_inicio, cp.fecha_fin, cp.created_at,
                    c.nombre_curso, e.nombre_empresa
             FROM curso_programado cp
             LEFT JOIN curso c ON c.curso_id = cp.curso_id
             LEFT JOIN empresa e ON e.empresa_id = cp.empresa_id
             WHERE cp.programado_id = ?`,
            [programadoId]
        );

        if (curso.length === 0) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
        }

        let carpetaCapacitacionEliminada = 0;
        const fechasIntentoCarpeta = [curso[0].created_at, curso[0].fecha_inicio, curso[0].fecha_fin].filter(Boolean);
        if (curso[0].nombre_empresa && curso[0].nombre_curso) {
            try {
                const eliminarCarpetaRes = await driveService.eliminarCarpetaCapacitacion(
                    curso[0].nombre_empresa,
                    curso[0].nombre_curso,
                    fechasIntentoCarpeta
                );

                if (eliminarCarpetaRes.success) {
                    carpetaCapacitacionEliminada = eliminarCarpetaRes.eliminadas || 0;
                }
            } catch (errorCarpeta) {
                // silenced
            }
        }

        // Eliminar en orden para respetar foreign keys:
        // 1. Inscripciones del curso
        const [inscripcionesResult] = await pool.query(
            'DELETE FROM inscripcion_curso WHERE programado_id = ?',
            [programadoId]
        );

        // 2. Documentos del curso programado (si existen)
        try {
            const [docsProgramado] = await pool.query(
                'SELECT drive_file_id FROM documento_curso_programado WHERE programado_id = ? AND drive_file_id IS NOT NULL AND drive_file_id != ""',
                [programadoId]
            );

            for (const doc of docsProgramado) {
                if (esDriveIdValido(doc.drive_file_id)) {
                    try {
                        await driveService.eliminarArchivo(doc.drive_file_id);
                    } catch (e) {
                        // silenced
                    }
                }
            }

            await pool.query(
                'DELETE FROM documento_curso_programado WHERE programado_id = ?',
                [programadoId]
            );
        } catch (e) {
            // Tabla puede no existir, continuar
        }

        // 3. Encuestas del curso programado (si existen)
        try {
            await pool.query(
                'DELETE FROM encuesta_satisfaccion WHERE programado_id = ?',
                [programadoId]
            );
        } catch (e) {
            // Tabla puede no existir, continuar
        }

        // 4. El curso programado en sí
        await pool.query(
            'DELETE FROM curso_programado WHERE programado_id = ?',
            [programadoId]
        );


        res.json({
            success: true,
            message: 'Curso programado eliminado correctamente',
            inscripcionesEliminadas: inscripcionesResult.affectedRows,
            carpetasCapacitacionEliminadas: carpetaCapacitacionEliminada
        });
    } catch (error) {
        console.error('Error al eliminar curso programado:', error);
        handleError(res, error);
    }
});

// ── Enviar invitación de curso por correo electrónico ──
app.post('/api/enviar-invitacion-curso', async (req, res) => {
    try {
        const {
            curso_id, empresa_id, instructor_id,
            fecha_inicio, fecha_fin,
            hora_inicio, hora_fin,
            modalidad, ubicacion, lugar_capacitacion, estado, ciudad,
            cupo, notas, correos_adicionales
        } = req.body;

        const ubicacionFinal = String(lugar_capacitacion ?? ubicacion ?? '').trim() || null;

        const parsearFechaSoloDia = (fechaRaw) => {
            const fechaTexto = String(fechaRaw || '').trim();
            if (!fechaTexto) return null;

            const soloFecha = fechaTexto.match(/^(\d{4})-(\d{2})-(\d{2})$/);
            if (soloFecha) {
                const anio = Number(soloFecha[1]);
                const mes = Number(soloFecha[2]);
                const dia = Number(soloFecha[3]);
                return new Date(anio, mes - 1, dia);
            }

            const parsed = new Date(fechaTexto);
            if (Number.isNaN(parsed.getTime())) return null;

            return new Date(parsed.getFullYear(), parsed.getMonth(), parsed.getDate());
        };

        const fechaInicioCurso = parsearFechaSoloDia(fecha_inicio);
        if (fechaInicioCurso) {
            const hoy = new Date();
            hoy.setHours(0, 0, 0, 0);

            if (fechaInicioCurso.getTime() < hoy.getTime()) {
                return res.json({
                    success: true,
                    skipped: true,
                    reason: 'fecha_anterior_hoy',
                    message: 'Invitación omitida: fecha del curso anterior al día actual',
                    exitosos: 0,
                    fallidos: 0,
                    total: 0,
                    resultados: []
                });
            }
        }

        if (!emailService.isEnabled()) {
            return res.json({ success: false, message: 'Servicio de email no configurado' });
        }

        // Obtener nombre del curso
        const [cursoRows] = await pool.query(
            'SELECT nombre_curso FROM curso WHERE curso_id = ? LIMIT 1', [curso_id]
        );
        const nombreCurso = cursoRows[0]?.nombre_curso || 'Curso';

        // Obtener datos de la empresa
        const [empresaRows] = await pool.query(
            `SELECT e.nombre_empresa,
                    COALESCE(
                        (
                            SELECT u.email
                            FROM usuario u
                            LEFT JOIN roles r ON u.rol_id = r.rol_id
                            WHERE u.empresa_id = e.empresa_id
                                AND u.activo = 1
                                AND u.email IS NOT NULL
                                AND TRIM(u.email) <> ''
                            ORDER BY CASE WHEN r.nombre_rol = 'empresa' THEN 0 ELSE 1 END, u.id ASC
                            LIMIT 1
                        ),
                        NULLIF(TRIM(e.email), ''),
                        NULLIF(TRIM(e.contacto_email), '')
                    ) AS usuario_email
             FROM empresa e
                         WHERE e.empresa_id = ?
                         LIMIT 1`, [empresa_id]
        );
        const empresaNombre = empresaRows[0]?.nombre_empresa || 'Empresa';
        const empresaEmail = empresaRows[0]?.usuario_email || null;

        // Obtener datos del instructor
        let instructorNombre = 'Sin asignar';
        let instructorEmail = null;
        if (instructor_id) {
            const [instrRows] = await pool.query(
                `SELECT i.nombre,
                        i.apellido_paterno,
                        i.apellido_materno,
                        COALESCE(NULLIF(TRIM(u.email), ''), NULLIF(TRIM(i.email), '')) AS usuario_email
                 FROM instructor i
                 LEFT JOIN usuario u ON u.id = i.usuario_id AND u.activo = 1
                 WHERE i.instructor_id = ?
                 LIMIT 1`,
                [instructor_id]
            );
            if (instrRows[0]) {
                instructorNombre = `${instrRows[0].nombre || ''} ${instrRows[0].apellido_paterno || ''} ${instrRows[0].apellido_materno || ''}`.trim();
                instructorEmail = instrRows[0].usuario_email || null;
            }
        }

        const normalizarCorreo = (correo = '') => String(correo || '').trim().toLowerCase();
        const deduplicarCorreos = (lista = []) => {
            const vistos = new Set();
            return lista.filter((correo) => {
                const normalizado = normalizarCorreo(correo);
                if (!normalizado || vistos.has(normalizado)) return false;
                vistos.add(normalizado);
                return true;
            });
        };

        const correosExtras = (correos_adicionales && correos_adicionales.trim())
            ? correos_adicionales
                .split(',')
                .map((e) => e.trim())
                .filter((e) => e && /^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(e))
            : [];

        // Empresa recibe adjuntos; instructor y correos extra solo la invitación sin Excel.
        const destinatariosEmpresa = deduplicarCorreos(empresaEmail ? [empresaEmail] : []);
        const correosEmpresaNormalizados = new Set(destinatariosEmpresa.map((correo) => normalizarCorreo(correo)));
        const destinatariosSinAdjuntos = deduplicarCorreos([
            ...(instructorEmail ? [instructorEmail] : []),
            ...correosExtras
        ]).filter((correo) => !correosEmpresaNormalizados.has(normalizarCorreo(correo)));

        if (destinatariosEmpresa.length === 0 && destinatariosSinAdjuntos.length === 0) {
            return res.json({ success: false, message: 'No hay destinatarios con correo válido' });
        }

        const payloadInvitacionBase = {
            nombreCurso,
            empresaNombre,
            instructorNombre,
            fechaInicio: fecha_inicio,
            fechaFin: fecha_fin,
            horaInicio: hora_inicio,
            horaFin: hora_fin,
            modalidad,
            ubicacion: ubicacionFinal,
            estado,
            ciudad,
            cupo,
            notas
        };

        const resultados = [];

        if (destinatariosEmpresa.length > 0) {
            const adjuntosInvitacion = await obtenerAdjuntosInvitacionCursoConTimeout(45000);
            const resultadoEmpresa = await emailService.enviarInvitacionCurso({
                ...payloadInvitacionBase,
                destinatarios: destinatariosEmpresa,
                adjuntos: adjuntosInvitacion
            });

            if (Array.isArray(resultadoEmpresa?.resultados)) {
                resultados.push(...resultadoEmpresa.resultados);
            }
        }

        if (destinatariosSinAdjuntos.length > 0) {
            const resultadoSinAdjuntos = await emailService.enviarInvitacionCurso({
                ...payloadInvitacionBase,
                destinatarios: destinatariosSinAdjuntos,
                adjuntos: []
            });

            if (Array.isArray(resultadoSinAdjuntos?.resultados)) {
                resultados.push(...resultadoSinAdjuntos.resultados);
            }
        }

        const exitosos = resultados.filter(r => r.success).length;
        const fallidos = resultados.filter(r => !r.success).length;

        res.json({
            success: exitosos > 0,
            exitosos,
            fallidos,
            total: resultados.length,
            resultados
        });
    } catch (error) {
        console.error('[ERROR] Error al enviar invitación de curso:', error.message);
        handleError(res, error, 'Error al enviar invitación de curso');
    }
});

// Obtener cursos programados filtrados por empresa (para usuarios de empresa)
// Obtener cursos programados filtrados por empresa (con conteo de inscritos)
app.get('/api/cursos-programados/empresa/:empresaId', async (req, res) => {
    try {
        const empresaId = Number(req.params.empresaId);
        if (!Number.isInteger(empresaId) || empresaId <= 0) {
            return res.status(400).json({ success: false, message: 'empresaId inválido' });
        }

        const empresaIds = await obtenerIdsEmpresasConColaboradoras(pool, empresaId);
        if (empresaIds.length === 0) {
            return res.json({ success: true, cursosProgramados: [] });
        }

        const placeholders = empresaIds.map(() => '?').join(', ');
        const [rows] = await pool.query(`
            SELECT v.*,
                   cp.pasos_completados,
                   COALESCE(dcp_spf03.tiene_entrega_documentos, 0) AS tiene_entrega_documentos,
                   COALESCE((SELECT COUNT(*) FROM inscripcion_curso ic WHERE ic.programado_id = v.programado_id), 0) as inscritos
            FROM v_cursos_programados v
            INNER JOIN curso_programado cp ON cp.programado_id = v.programado_id
            LEFT JOIN (
                SELECT programado_id, 1 AS tiene_entrega_documentos
                FROM documento_curso_programado
                WHERE descripcion = 'entrega_documentos_spf03_firmado'
                   OR descripcion LIKE 'entrega_documentos_spf03%'
                   OR tipo_documento = 'entrega_documentos'
                   OR LOWER(nombre_archivo) LIKE '%sp-f-03%'
                   OR LOWER(nombre_archivo) LIKE '%sp_f_03%'
                   OR LOWER(nombre_archivo) LIKE '%sp f 03%'
                   OR LOWER(nombre_archivo) LIKE '%spf03%'
                   OR LOWER(descripcion) LIKE '%sp-f-03%'
                   OR LOWER(descripcion) LIKE '%sp_f_03%'
                   OR LOWER(descripcion) LIKE '%sp f 03%'
                   OR LOWER(descripcion) LIKE '%spf03%'
                   OR LOWER(descripcion) LIKE '%entrega_documentos%'
                GROUP BY programado_id
            ) dcp_spf03 ON dcp_spf03.programado_id = v.programado_id
            WHERE v.empresa_id IN (${placeholders})
            ORDER BY v.fecha_inicio DESC
        `, empresaIds);
        res.json({ success: true, cursosProgramados: rows });
    } catch (error) {
        handleError(res, error);
    }
});

