/** Calcula edad a partir del CURP (posiciones 5-10 = YYMMDD) respecto a una fecha de referencia */
function calcularEdadDesdeCURP(curp, fechaReferencia = new Date()) {
    if (!curp || String(curp).length < 10) return null;
    const curpUpper = String(curp).toUpperCase().trim();
    const yy = parseInt(curpUpper.substring(4, 6), 10);
    const mm = parseInt(curpUpper.substring(6, 8), 10);
    const dd = parseInt(curpUpper.substring(8, 10), 10);
    if ([yy, mm, dd].some(Number.isNaN)) return null;
    if (mm < 1 || mm > 12 || dd < 1 || dd > 31) return null;

    const anioActual = fechaReferencia.getFullYear();
    const yyActual = anioActual % 100;
    const anioNacimiento = yy <= yyActual ? 2000 + yy : 1900 + yy;

    const fechaNac = new Date(anioNacimiento, mm - 1, dd);
    if (fechaNac.getFullYear() !== anioNacimiento || fechaNac.getMonth() !== mm - 1 || fechaNac.getDate() !== dd) {
        return null;
    }

    let edad = anioActual - anioNacimiento;
    const mesDiff = fechaReferencia.getMonth() - fechaNac.getMonth();
    if (mesDiff < 0 || (mesDiff === 0 && fechaReferencia.getDate() < fechaNac.getDate())) {
        edad--;
    }
    return edad >= 0 && edad <= 120 ? edad : null;
}

/** Parsea cursos_tomados desde JSON/string/array de BD */
function parseCursosTomados(raw) {
    if (raw == null || raw === '') return [];
    if (Array.isArray(raw)) {
        return raw.map(Number).filter((n) => Number.isInteger(n) && n > 0);
    }
    if (typeof raw === 'object') {
        return Object.values(raw).map(Number).filter((n) => Number.isInteger(n) && n > 0);
    }
    try {
        const parsed = JSON.parse(String(raw));
        return Array.isArray(parsed)
            ? parsed.map(Number).filter((n) => Number.isInteger(n) && n > 0)
            : [];
    } catch {
        return String(raw)
            .split(/[,;\s]+/)
            .map(Number)
            .filter((n) => Number.isInteger(n) && n > 0);
    }
}

/** Agrega curso_id a la lista sin duplicados */
function agregarCursoTomado(cursosExistentes, cursoId) {
    const id = Number(cursoId);
    if (!Number.isInteger(id) || id <= 0) return parseCursosTomados(cursosExistentes);
    const lista = parseCursosTomados(cursosExistentes);
    if (!lista.includes(id)) lista.push(id);
    return lista;
}

const EDUCACIONES_VALIDAS = ['Educación Básica', 'Media Superior', 'Educación Superior'];
const ANTIGUEDADES_VALIDAS = ['Menor a 6 meses', '6 meses - 1 año', 'Mayor a un año'];

/** Actualiza cursos_tomados al finalizar capacitación (participantes activos en pase de lista) */
async function actualizarCursosTomadosAlFinalizar(programadoId) {
    const [cursoProg] = await pool.query(
        'SELECT curso_id FROM curso_programado WHERE programado_id = ? LIMIT 1',
        [programadoId]
    );
    if (!cursoProg.length) {
        return { actualizados: 0, total: 0, cursoId: null };
    }

    const cursoId = Number(cursoProg[0].curso_id);
    if (!Number.isInteger(cursoId) || cursoId <= 0) {
        return { actualizados: 0, total: 0, cursoId: null };
    }

    const [participantes] = await pool.query(`
        SELECT ic.empleado_id, e.cursos_tomados
        FROM inscripcion_curso ic
        INNER JOIN empleado e ON e.empleado_id = ic.empleado_id
        WHERE ic.programado_id = ? AND ic.activo = 1
    `, [programadoId]);

    let actualizados = 0;
    for (const participante of participantes) {
        const previos = parseCursosTomados(participante.cursos_tomados);
        if (previos.includes(cursoId)) continue;

        const actualizadosLista = agregarCursoTomado(previos, cursoId);
        await pool.query(
            'UPDATE empleado SET cursos_tomados = ?, updated_at = NOW() WHERE empleado_id = ?',
            [JSON.stringify(actualizadosLista), participante.empleado_id]
        );
        actualizados++;
    }

    return { actualizados, total: participantes.length, cursoId };
}

function traducirErrorRegistroEmpleado(mensajeTecnico = '', nombreEmpleado = '') {
    const texto = String(mensajeTecnico || '').trim();
    const nombre = String(nombreEmpleado || '').trim();

    const reglas = [
        { patron: /duplicate entry|er_dup_entry|unique constraint|already exists/i,
            mensaje: 'Este empleado ya está registrado o ya participa en este curso.' },
        { patron: /cannot be null|er_bad_null_error|not null/i,
            mensaje: 'Faltan datos obligatorios. Verifica nombre y CURP.' },
        { patron: /data too long|value too long/i,
            mensaje: 'Algún dato es demasiado largo. Revisa nombre, CURP o puesto.' },
        { patron: /incorrect .* value|invalid|inválid/i,
            mensaje: 'El formato de algún dato no es válido. Revisa especialmente el CURP.' },
        { patron: /foreign key|constraint fails/i,
            mensaje: 'No se pudo vincular el empleado con la empresa o el curso.' }
    ];

    let mensaje = texto;
    for (const regla of reglas) {
        if (regla.patron.test(texto)) {
            mensaje = regla.mensaje;
            break;
        }
    }

    if (mensaje === texto && /exception|sql|query|stack/i.test(texto)) {
        mensaje = 'No se pudo completar el registro. Revisa los datos e intenta de nuevo.';
    }

    return nombre ? `${nombre}: ${mensaje}` : mensaje;
}

// Registrar empleados para un curso programado (usado por empresas)
app.post('/api/cursos-programados/:programadoId/registrar-empleados', async (req, res) => {
    try {
        const { programadoId } = req.params;
        const { empleados } = req.body;

        if (!empleados || !Array.isArray(empleados) || empleados.length === 0) {
            return res.json({ success: false, message: 'Se requiere al menos un empleado' });
        }

        // Obtener empresa_id del curso programado (no confiar en el body)
        const [cursoProg] = await pool.query(
            'SELECT empresa_id FROM curso_programado WHERE programado_id = ?',
            [programadoId]
        );
        if (cursoProg.length === 0) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
        }
        const empresa_id = cursoProg[0].empresa_id;

        // ========== VALIDACIÓN DE CURPs DUPLICADOS EN LA SOLICITUD ==========
        const curpsEnSolicitud = empleados
            .filter(emp => emp.curp && emp.curp.trim().length > 0)
            .map(emp => emp.curp.toUpperCase().trim());

        const curpsDuplicados = curpsEnSolicitud.filter((curp, index) =>
            curpsEnSolicitud.indexOf(curp) !== index
        );

        if (curpsDuplicados.length > 0) {
            const curpsUnicos = [...new Set(curpsDuplicados)];
            return res.json({
                success: false,
                message: `Se detectaron CURPs duplicados en la lista: ${curpsUnicos.join(', ')}. Cada empleado debe tener un CURP único.`
            });
        }

        const empleadosRegistrados = [];
        const empleadosYaInscritos = [];
        const errores = [];
        const advertencias = [];

        for (const emp of empleados) {
            try {

                // Advertir CURP con formato no estándar pero permitir el registro
                const curpNormalizado = emp.curp ? String(emp.curp).toUpperCase().trim() : '';
                const curpFormatoValido = !curpNormalizado || /^[A-Z]{4}[0-9]{6}[HMX][A-Z]{5}[0-9A-Z][0-9]$/i.test(curpNormalizado)
                    || /^[A-Z]{4}[0-9]{6}[HMX][A-Z]{5}[0-9A-Z]$/i.test(curpNormalizado);
                if (curpNormalizado && !curpFormatoValido) {
                    advertencias.push(`CURP con formato no estándar para ${emp.nombre}: ${curpNormalizado}`);
                }

                let educacion = EDUCACIONES_VALIDAS.includes(emp.educacion) ? emp.educacion : null;
                let antiguedad = ANTIGUEDADES_VALIDAS.includes(emp.antiguedad) ? emp.antiguedad : null;
                const curpFinal = curpNormalizado || null;

                // Verificar si el empleado ya existe por CURP en esta empresa
                let empleadoId = null;
                let empleadoExistente = false;

                if (curpFinal) {
                    const [existente] = await pool.query(
                        'SELECT empleado_id, nombre, educacion, antiguedad FROM empleado WHERE curp = ? AND empresa_id = ?',
                        [curpFinal, empresa_id]
                    );
                    if (existente.length > 0) {
                        empleadoId = existente[0].empleado_id;
                        empleadoExistente = true;
                        if (!educacion && EDUCACIONES_VALIDAS.includes(existente[0].educacion)) {
                            educacion = existente[0].educacion;
                        }
                        if (!antiguedad && ANTIGUEDADES_VALIDAS.includes(existente[0].antiguedad)) {
                            antiguedad = existente[0].antiguedad;
                        }
                    }
                }

                const edad = calcularEdadDesdeCURP(curpFinal);

                if (empleadoId) {
                    const [yaInscrito] = await pool.query(
                        'SELECT inscripcion_id FROM inscripcion_curso WHERE programado_id = ? AND empleado_id = ?',
                        [programadoId, empleadoId]
                    );
                    if (yaInscrito.length > 0) {
                        empleadosYaInscritos.push({
                            empleado_id: empleadoId,
                            nombre: emp.nombre,
                            curp: emp.curp
                        });
                        continue;
                    }
                }

                if (!empleadoId) {
                    const [result] = await pool.query(
                        `INSERT INTO empleado (empresa_id, nombre, apellido_paterno, apellido_materno, curp, puesto, departamento,
                                               educacion, antiguedad, edad, activo)
                         VALUES (?, ?, '', '', ?, ?, ?, ?, ?, ?, 1)`,
                        [
                            empresa_id,
                            emp.nombre || '',
                            curpFinal,
                            emp.puesto || null,
                            null,
                            educacion,
                            antiguedad,
                            edad
                        ]
                    );
                    empleadoId = result.insertId;
                } else {
                    await pool.query(
                        `UPDATE empleado
                         SET educacion = COALESCE(?, educacion), antiguedad = COALESCE(?, antiguedad), edad = ?,
                             puesto = COALESCE(?, puesto), updated_at = NOW()
                         WHERE empleado_id = ?`,
                        [educacion, antiguedad, edad, emp.puesto || null, empleadoId]
                    );
                }

                // Inscribir al empleado en el curso con asistio=0 por defecto (no asistido)
                await pool.query(
                    'INSERT INTO inscripcion_curso (programado_id, empleado_id, fecha_inscripcion, asistio, activo) VALUES (?, ?, NOW(), 0, 1)',
                    [programadoId, empleadoId]
                );

                empleadosRegistrados.push({
                    empleado_id: empleadoId,
                    nombre: emp.nombre,
                    curp: emp.curp,
                    existente: empleadoExistente,
                    mensaje: empleadoExistente
                        ? 'Empleado existente inscrito en nuevo curso'
                        : 'Nuevo empleado registrado e inscrito'
                });
            } catch (empError) {
                console.error(`[ERROR] Error con ${emp.nombre}:`, empError.message);
                errores.push(traducirErrorRegistroEmpleado(empError.message, emp.nombre));
            }
        }

        // Actualizar estatus del curso a 'en_curso' solo si se registraron empleados nuevos
        if (empleadosRegistrados.length > 0) {
            await pool.query(
                'UPDATE curso_programado SET estatus = ? WHERE programado_id = ?',
                ['en_curso', programadoId]
            );
        }

        // Construir mensaje de respuesta
        let mensaje = '';
        if (empleadosRegistrados.length > 0) {
            mensaje += `${empleadosRegistrados.length} empleado(s) inscrito(s) exitosamente. `;
        }
        if (empleadosYaInscritos.length > 0) {
            mensaje += `${empleadosYaInscritos.length} empleado(s) ya estaban inscritos en este curso.`;
        }

        // Obtener el total de inscritos activos del curso
        const [inscritosResult] = await pool.query(
            'SELECT COUNT(*) as total FROM inscripcion_curso WHERE programado_id = ? AND activo = 1',
            [programadoId]
        );
        const totalInscritos = inscritosResult[0].total;

        res.json({
            success: true,
            message: mensaje.trim() || 'Proceso completado',
            empleadosRegistrados,
            empleadosYaInscritos: empleadosYaInscritos.length > 0 ? empleadosYaInscritos : undefined,
            totalInscritos,
            errores: errores.length > 0 ? errores : undefined,
            advertencias: advertencias.length > 0 ? advertencias : undefined
        });

        // SGC-F-33 se genera desde el frontend vía POST /generar-sgcf33-drive

        // Notificaciones por correo si se inscribieron nuevos empleados
        if (emailService.isEnabled() && empleadosRegistrados.length > 0) {
            pool.query(
                `SELECT c.nombre_curso,
                        e.nombre_empresa, e.email AS empresa_email,
                        CONCAT(u.nombre, ' ', COALESCE(u.apellido, '')) AS instructor_nombre,
                        u.email AS instructor_email,
                        u.id AS instructor_usuario_id,
                        (SELECT ue.id FROM usuario ue WHERE ue.empresa_id = e.empresa_id LIMIT 1) AS empresa_usuario_id
                 FROM curso_programado cp
                 JOIN curso c ON cp.curso_id = c.curso_id
                 JOIN empresa e ON cp.empresa_id = e.empresa_id
                 LEFT JOIN instructor i ON cp.instructor_id = i.instructor_id
                 LEFT JOIN usuario u ON i.usuario_id = u.id
                 WHERE cp.programado_id = ?`,
                [programadoId]
            ).then(([rows]) => {
                if (!rows[0]) return;
                const { nombre_curso, nombre_empresa, empresa_email, instructor_nombre, instructor_email, instructor_usuario_id, empresa_usuario_id } = rows[0];
                const cantidadRegistrados = empleadosRegistrados.length;
                const cantidadYaInscritos = empleadosYaInscritos.length;

                if (empresa_email) {
                    emailService.notificarEmpresaRegistroParticipantes({
                        empresaEmail: empresa_email, empresaNombre: nombre_empresa,
                        nombreCurso: nombre_curso, instructorNombre: instructor_nombre?.trim() || null,
                        cantidadRegistrados, cantidadYaInscritos, totalInscritos,
                        empleadosRegistrados
                    }).catch(e => console.error('[EMAIL] Error notificando empresa registro participantes:', e.message));
                }
                if (instructor_email) {
                    emailService.notificarInstructorRegistroParticipantes({
                        instructorEmail: instructor_email, instructorNombre: instructor_nombre?.trim() || '',
                        nombreCurso: nombre_curso, nombreEmpresa: nombre_empresa,
                        cantidadRegistrados, cantidadYaInscritos, totalInscritos,
                        empleadosRegistrados
                    }).catch(e => console.error('[EMAIL] Error notificando instructor registro participantes:', e.message));
                }

                // Notificaciones in-app de "Participantes registrados" deshabilitadas:
                // el instructor recibe avisos operativos (próximos / pendientes / sin gestionar).
            }).catch(e => console.error('[EMAIL] Error obteniendo datos para notificación de registro:', e.message));
        }
    } catch (error) {
        console.error('[ERROR] Error general en registro de empleados:', error);
        handleError(res, error);
    }
});

// ════════════════════════════════════════════════════════════════════════════════
// GENERAR SGC-F-33 LISTA DE ASISTENCIA (ExcelJS, diseño idéntico al original)
// ════════════════════════════════════════════════════════════════════════════════

/**
 * Genera el documento SGC-F-33 "Lista de Asistencia".
 *
 * Estrategia: descarga la plantilla .xlsx desde Google Drive (conserva 100 %
 * tipografías, estilos, bordes, colores y merges del original), rellena
 * únicamente las celdas de datos y devuelve el buffer listo para subir.
 *
 * Plantilla en Drive: «Plantilla Lista de Asistencia (NO BORRAR).xlsx»
 * ID = 18mDesmPx9gxmAECnTmCXC-dw7skZZuqe
 *
 * Celdas que rellena:
 *   C5  → nombre_curso               F5  → ubicacion (lugar)
 *   F6  → instructor_nombre          C7  → fecha (dd-Mon-yyyy)
 *   C8  → horario (HH:mm a HH:mm horas)   F8  → duración calculada ("X horas")
 *   B12:D12 … B31:D31  → nombre participante (mayúsculas)
 *   E12:F12 … E31:F31  → puesto / área
 */
const LISTA_ASISTENCIA_TEMPLATE_DRIVE_ID = String(process.env.LISTA_ASISTENCIA_TEMPLATE_DRIVE_ID || '18mDesmPx9gxmAECnTmCXC-dw7skZZuqe').trim();
const SGCF33_TEMPLATE_DRIVE_ID = LISTA_ASISTENCIA_TEMPLATE_DRIVE_ID;
const SGCF33_FILAS_POR_HOJA = 20;
const SGCF33_DATA_START_ROW = 12;
const SGCF33_DATA_END_ROW = SGCF33_DATA_START_ROW + SGCF33_FILAS_POR_HOJA - 1;

async function generarSGCF33ListaAsistencia(programadoId) {
    const ExcelJS = require('exceljs');

    // ── 1. Datos de BD ───────────────────────────────────────────────────────
    const [cursoData] = await pool.query(
        'SELECT * FROM v_cursos_programados WHERE programado_id = ?',
        [programadoId]
    );
    if (cursoData.length === 0) {
        const err = new Error('Curso programado no encontrado'); err.statusCode = 404; throw err;
    }
    const cursoInfo = cursoData[0];

    const [participantesData] = await pool.query(`
        SELECT e.nombre, e.apellido_paterno, e.apellido_materno,
               e.curp, e.puesto
        FROM inscripcion_curso ic
        JOIN empleado e ON ic.empleado_id = e.empleado_id
        WHERE ic.programado_id = ? AND ic.activo = 1
        ORDER BY e.apellido_paterno, e.apellido_materno, e.nombre
    `, [programadoId]);
    if (participantesData.length === 0) {
        const err = new Error('No hay participantes inscritos en este curso'); err.statusCode = 400; throw err;
    }

    // ── 2. Formatear datos ───────────────────────────────────────────────────
    const mesesAbrev = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
    const fechaInicio = new Date(cursoInfo.fecha_inicio);
    fechaInicio.setMinutes(fechaInicio.getMinutes() + fechaInicio.getTimezoneOffset());
    const dd = String(fechaInicio.getDate()).padStart(2, '0');
    const mesAbrev = mesesAbrev[fechaInicio.getMonth()];
    const yyyy = fechaInicio.getFullYear();
    const fechaFormateada = `${dd}-${mesAbrev}-${yyyy}`;

    let horarioTexto = '', duracionTexto = '', horaInicioCorta = '', horaFinCorta = '';
    if (cursoInfo.hora_inicio && cursoInfo.hora_fin) {
        horaInicioCorta = String(cursoInfo.hora_inicio).substring(0, 5);
        horaFinCorta    = String(cursoInfo.hora_fin).substring(0, 5);
        horarioTexto = `${horaInicioCorta} a ${horaFinCorta} horas`;
        const [hiH, hiM] = horaInicioCorta.split(':').map(Number);
        const [hfH, hfM] = horaFinCorta.split(':').map(Number);
        let diffMin = (hfH * 60 + hfM) - (hiH * 60 + hiM);
        if (diffMin <= 0) diffMin += 24 * 60; // manejar cruce de medianoche
        const h = Math.round(diffMin / 60) || Math.floor(diffMin / 60) || 1;
        duracionTexto = `${h} horas`;
    } else if (cursoInfo.curso_horas) {
        duracionTexto = `${cursoInfo.curso_horas} horas`;
    }

    const lugarTexto = cursoInfo.ubicacion || '';

    // ── 3. Descargar plantilla desde Drive y cargar con ExcelJS ──────────────
    const templateBuffer = await driveService.descargarArchivo(SGCF33_TEMPLATE_DRIVE_ID);
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.load(templateBuffer);
    const hojasDisponibles = wb.worksheets.length;
    const hojasNecesarias = Math.max(1, Math.ceil(participantesData.length / SGCF33_FILAS_POR_HOJA));

    if (hojasNecesarias > hojasDisponibles) {
        const err = new Error(`La plantilla SGC-F-33 solo soporta ${hojasDisponibles * SGCF33_FILAS_POR_HOJA} participantes (hojas disponibles: ${hojasDisponibles}).`);
        err.statusCode = 400;
        throw err;
    }

    // Quitar hojas no usadas para evitar pestañas vacías.
    for (let i = hojasDisponibles; i > hojasNecesarias; i--) {
        const hoja = wb.getWorksheet(i);
        if (hoja) wb.removeWorksheet(hoja.id);
    }

    // ── 4. Rellenar encabezados y participantes por hoja ─────────────────────
    // Merges por fila: B:D (nombre), E:F (área), J:K (firma)
    // Se omiten columnas de Entrada (G:H) y Salida (I)
    for (let hojaIdx = 0; hojaIdx < hojasNecesarias; hojaIdx++) {
        const ws = wb.getWorksheet(hojaIdx + 1);
        if (!ws) continue;

        // Asegurar configuración de impresión horizontal para exportación PDF.
        ws.pageSetup = {
            ...ws.pageSetup,
            orientation: 'landscape',
            paperSize: 1,
            fitToPage: true,
            fitToWidth: 1,
            fitToHeight: 0
        };

        // Encabezado de curso en cada hoja utilizada.
        ws.getCell('C5').value = cursoInfo.nombre_curso || '';
        ws.getCell('F5').value = lugarTexto;
        ws.getCell('F6').value = cursoInfo.instructor_nombre || '';
        ws.getCell('C7').value = fechaFormateada;
        ws.getCell('C8').value = horarioTexto;
        ws.getCell('F8').value = duracionTexto;

        const inicio = hojaIdx * SGCF33_FILAS_POR_HOJA;
        const fin = inicio + SGCF33_FILAS_POR_HOJA;
        const participantesHoja = participantesData.slice(inicio, fin);

        for (let row = SGCF33_DATA_START_ROW; row <= SGCF33_DATA_END_ROW; row++) {
            const idx = row - SGCF33_DATA_START_ROW;
            const p = participantesHoja[idx] || null;

            if (p) {
                ws.getCell(`B${row}`).value = [p.apellido_paterno, p.apellido_materno, p.nombre]
                    .filter(Boolean).join(' ').toUpperCase();
                ws.getCell(`E${row}`).value = p.puesto || '';
            }
        }
    }

    // ── 6. Generar buffer ────────────────────────────────────────────────────
    const buffer = await wb.xlsx.writeBuffer();

    const nombreArchivo = construirNombreDocProgramado({
        nombreEmpresa: cursoInfo.nombre_empresa,
        nombreCurso:   cursoInfo.nombre_curso,
        fechaInicio:   cursoInfo.fecha_inicio,
        tipoBase:      'SGC_F33_lista_asistencia',
        extension:     'xlsx'
    });

    return { buffer, nombreArchivo, participantes: participantesData.length, cursoInfo };
}

// Generar SGC-F-33 y guardar en Drive (se llama al registrar empleados)
app.post('/api/cursos-programados/:programadoId/generar-sgcf33-drive', async (req, res) => {
    try {
        const { programadoId } = req.params;
        const generado = await generarSGCF33ListaAsistencia(programadoId);

        const carpetaResult = await resolverCarpetaCursoProgramado(programadoId);

        if (!carpetaResult.success) {
            return res.status(500).json({ success: false, message: 'Error creando carpeta en Drive' });
        }

        const listasFolderId = await driveService.obtenerOCrearCarpeta('Listas_Asistencia', carpetaResult.folderId);

        // Eliminar versión anterior si existe
        await eliminarDocsProgramadoPorFiltro(programadoId, 'descripcion = ?', ['sgcf33_lista_asistencia']);

        const driveFile = await driveService.subirExcelComoGoogleSheet(
            Buffer.from(generado.buffer),
            generado.nombreArchivo,
            listasFolderId,
            { keepSingleSheet: false, maxColumns: 11 }
        );

        await pool.query(
            `INSERT INTO documento_curso_programado
             (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
             VALUES (?, 'lista_asistencia', ?, ?, ?, 'sgcf33_lista_asistencia')`,
            [programadoId, generado.nombreArchivo, driveFile.webViewLink || '', driveFile.id || null]
        );

        res.json({
            success: true,
            message: `Lista SGC-F-33 guardada en Drive con ${generado.participantes} participante(s)`,
            participantes: generado.participantes,
            archivo: {
                nombre:         generado.nombreArchivo,
                drive_file_id:  driveFile.id,
                url:            driveFile.webViewLink,
                carpeta:        `${carpetaResult.path}/Listas_Asistencia`
            }
        });
    } catch (error) {
        const status = error.statusCode || 500;
        return res.status(status).json({
            success: false,
            message: error.message || 'Error al generar/guardar lista SGC-F-33 en Drive'
        });
    }
});

// Generar SGC-F-33 vacía (sin nombres, solo datos del curso) y descargar directamente
async function generarSGCF33Vacia(programadoId) {
    const ExcelJS = require('exceljs');

    const [cursoData] = await pool.query(
        'SELECT * FROM v_cursos_programados WHERE programado_id = ?',
        [programadoId]
    );
    if (cursoData.length === 0) {
        const err = new Error('Curso programado no encontrado'); err.statusCode = 404; throw err;
    }
    const cursoInfo = cursoData[0];

    // Determinar cuántas hojas vacías se deben conservar según inscritos (20 por hoja)
    const [participantesRows] = await pool.query(
        `SELECT COUNT(*) AS total
         FROM inscripcion_curso
         WHERE programado_id = ? AND activo = 1`,
        [programadoId]
    );
    const totalParticipantes = Number(participantesRows?.[0]?.total || 0);

    const mesesAbrev = ['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];
    const fechaInicio = new Date(cursoInfo.fecha_inicio);
    fechaInicio.setMinutes(fechaInicio.getMinutes() + fechaInicio.getTimezoneOffset());
    const dd = String(fechaInicio.getDate()).padStart(2, '0');
    const mesAbrev = mesesAbrev[fechaInicio.getMonth()];
    const yyyy = fechaInicio.getFullYear();
    const fechaFormateada = `${dd}-${mesAbrev}-${yyyy}`;

    let horarioTexto = '', duracionTexto = '';
    if (cursoInfo.hora_inicio && cursoInfo.hora_fin) {
        const horaInicioCorta = String(cursoInfo.hora_inicio).substring(0, 5);
        const horaFinCorta    = String(cursoInfo.hora_fin).substring(0, 5);
        horarioTexto = `${horaInicioCorta} a ${horaFinCorta} horas`;
        const [hiH, hiM] = horaInicioCorta.split(':').map(Number);
        const [hfH, hfM] = horaFinCorta.split(':').map(Number);
        let diffMin = (hfH * 60 + hfM) - (hiH * 60 + hiM);
        if (diffMin <= 0) diffMin += 24 * 60;
        const h = Math.round(diffMin / 60) || Math.floor(diffMin / 60) || 1;
        duracionTexto = `${h} horas`;
    } else if (cursoInfo.curso_horas) {
        duracionTexto = `${cursoInfo.curso_horas} horas`;
    }

    const templateBuffer = await driveService.descargarArchivo(SGCF33_TEMPLATE_DRIVE_ID);
    const wb = new ExcelJS.Workbook();
    await wb.xlsx.load(templateBuffer);
    const hojasDisponibles = wb.worksheets.length;
    const hojasNecesarias = Math.max(1, Math.ceil(totalParticipantes / SGCF33_FILAS_POR_HOJA));

    if (hojasNecesarias > hojasDisponibles) {
        const err = new Error(`La plantilla SGC-F-33 solo soporta ${hojasDisponibles * SGCF33_FILAS_POR_HOJA} participantes (hojas disponibles: ${hojasDisponibles}).`);
        err.statusCode = 400;
        throw err;
    }

    // Quitar solo hojas no usadas para evitar pestañas vacías extra.
    for (let i = hojasDisponibles; i > hojasNecesarias; i--) {
        const hoja = wb.getWorksheet(i);
        if (hoja) wb.removeWorksheet(hoja.id);
    }

    // Encabezado en cada hoja utilizada (sin rellenar filas de participantes)
    for (let hojaIdx = 0; hojaIdx < hojasNecesarias; hojaIdx++) {
        const ws = wb.getWorksheet(hojaIdx + 1);
        if (!ws) continue;

        ws.pageSetup = {
            ...ws.pageSetup,
            orientation: 'landscape',
            paperSize: 1,
            fitToPage: true,
            fitToWidth: 1,
            fitToHeight: 0
        };

        ws.getCell('C5').value  = cursoInfo.nombre_curso || '';
        ws.getCell('F5').value  = cursoInfo.ubicacion || '';
        ws.getCell('F6').value  = cursoInfo.instructor_nombre || '';
        ws.getCell('C7').value  = fechaFormateada;
        ws.getCell('C8').value  = horarioTexto;
        ws.getCell('F8').value  = duracionTexto;
    }
    // No se rellenan filas de participantes (lista vacía)

    const buffer = await wb.xlsx.writeBuffer();
    const nombreArchivo = construirNombreDocProgramado({
        nombreEmpresa: cursoInfo.nombre_empresa,
        nombreCurso:   cursoInfo.nombre_curso,
        fechaInicio:   cursoInfo.fecha_inicio,
        tipoBase:      'SGC_F33_lista_asistencia_vacia',
        extension:     'xlsx'
    });

    return { buffer, nombreArchivo };
}

app.get('/api/cursos-programados/:programadoId/generar-sgcf33-vacia', requireAdminEmpresaInstructor, async (req, res) => {
    try {
        const { programadoId } = req.params;
        const generado = await generarSGCF33Vacia(programadoId);
        res.setHeader('Content-Type', 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet');
        res.setHeader('Content-Disposition', `attachment; filename="${generado.nombreArchivo}"`);
        res.send(Buffer.from(generado.buffer));
    } catch (error) {
        const status = error.statusCode || 500;
        return res.status(status).json({ success: false, message: error.message || 'Error generando lista vacía' });
    }
});

// Guardar SGC-F-33 vacía en Drive (misma carpeta que la lista con participantes)
app.post('/api/cursos-programados/:programadoId/generar-sgcf33-vacia-drive', requireAdminEmpresaInstructor, async (req, res) => {
    try {
        const { programadoId } = req.params;
        const generado = await generarSGCF33Vacia(programadoId);

        const [cursoInfoRows] = await pool.query(
            'SELECT * FROM v_cursos_programados WHERE programado_id = ?', [programadoId]
        );
        if (cursoInfoRows.length === 0) {
            return res.status(404).json({ success: false, message: 'Curso no encontrado' });
        }
        const ci = cursoInfoRows[0];

        const carpetaResult = await resolverCarpetaCursoProgramado(programadoId);
        if (!carpetaResult.success) {
            return res.status(500).json({ success: false, message: 'Error creando carpeta en Drive' });
        }

        const listasFolderId = await driveService.obtenerOCrearCarpeta('Listas_Asistencia', carpetaResult.folderId);

        // Eliminar versión anterior si existe
        await eliminarDocsProgramadoPorFiltro(programadoId, 'descripcion = ?', ['sgcf33_lista_asistencia_vacia']);

        const driveFile = await driveService.subirExcelComoGoogleSheet(
            Buffer.from(generado.buffer),
            generado.nombreArchivo,
            listasFolderId,
            { keepSingleSheet: false, maxColumns: 11 }
        );

        await pool.query(
            `INSERT INTO documento_curso_programado
             (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
             VALUES (?, 'lista_asistencia', ?, ?, ?, 'sgcf33_lista_asistencia_vacia')`,
            [programadoId, generado.nombreArchivo, driveFile.webViewLink || '', driveFile.id || null]
        );

        res.json({
            success: true,
            message: 'Lista SGC-F-33 vacía guardada en Drive',
            archivo: {
                nombre: generado.nombreArchivo,
                drive_file_id: driveFile.id,
                url: driveFile.webViewLink,
                carpeta: `${carpetaResult.path}/Listas_Asistencia`
            }
        });
    } catch (error) {
        const status = error.statusCode || 500;
        return res.status(status).json({ success: false, message: error.message || 'Error guardando lista vacía en Drive' });
    }
});

