// Obtener inscripciones
app.get('/api/inscripciones', async (req, res) => {
    try {
        const { curso_programado_id } = req.query;

        if (!curso_programado_id) {
            return res.status(400).json({
                success: false,
                message: 'El parámetro curso_programado_id es requerido'
            });
        }

        const [rows] = await pool.query(`
            SELECT ic.*,
                   CONCAT(e.nombre, ' ', e.apellido_paterno) as nombre_empleado,
                   e.curp, e.email
            FROM inscripcion_curso ic
            JOIN empleado e ON ic.empleado_id = e.empleado_id
            WHERE ic.programado_id = ?
            ORDER BY ic.fecha_inscripcion DESC`,
            [curso_programado_id]
        );
        res.json({ success: true, inscripciones: rows });
    } catch (error) {
        handleError(res, error);
    }
});

// Obtener participantes de un curso programado (solo activos)
app.get('/api/cursos-programados/:programadoId/participantes', async (req, res) => {
    try {
        const { programadoId } = req.params;

        const [participantes] = await pool.query(`
            SELECT
                ic.inscripcion_id,
                ic.empleado_id,
                e.nombre,
                e.apellido_paterno,
                e.apellido_materno,
                TRIM(CONCAT_WS(' ',
                    NULLIF(TRIM(e.apellido_paterno), ''),
                    NULLIF(TRIM(e.apellido_materno), ''),
                    NULLIF(TRIM(e.nombre), '')
                )) AS nombre_completo,
                e.curp,
                e.puesto,
                e.departamento,
                e.educacion,
                e.antiguedad,
                e.edad,
                e.cursos_tomados,
                COALESCE(ic.asistio, 0) as asistio,
                ic.calificacion_teorica,
                ic.calificacion_practica,
                ic.calificacion_diagnostica,
                CASE
                    WHEN ic.calificacion_teorica IS NULL AND ic.calificacion_practica IS NULL THEN NULL
                    ELSE ROUND(
                        (IFNULL(ic.calificacion_teorica, 0) + IFNULL(ic.calificacion_practica, 0))
                        /
                        ((ic.calificacion_teorica IS NOT NULL) + (ic.calificacion_practica IS NOT NULL)),
                        2
                    )
                END AS calificacion,
                ic.aprobado,
                ic.certificado_generado,
                ic.certificado_url,
                ic.folio_constancia,
                ic.fecha_certificado,
                ic.activo,
                ic.notas,
                ic.fecha_inscripcion,
                ic.empresa_documento_id,
                ic.curso_documento_id
            FROM inscripcion_curso ic
            JOIN empleado e ON ic.empleado_id = e.empleado_id
            WHERE ic.programado_id = ? AND ic.activo = 1
            ORDER BY e.apellido_paterno, e.apellido_materno, e.nombre
        `, [programadoId]);

        res.json({ success: true, participantes });
    } catch (error) {
        console.error('[ERROR] Error obteniendo participantes:', error);
        handleError(res, error);
    }
});

// Configuración de empresas colaboradoras para constancias/DC-3 (paso 8)
app.get('/api/cursos-programados/:programadoId/colaboradoras-documentos', async (req, res) => {
    try {
        const programadoId = Number(req.params.programadoId);
        if (!Number.isInteger(programadoId) || programadoId <= 0) {
            return res.status(400).json({ success: false, message: 'programadoId inválido' });
        }

        await asegurarColumnasDocumentosColaboradoras(pool);

        const [cursoRows] = await pool.query(
            'SELECT programado_id, empresa_id, usa_empresas_colaboradoras FROM curso_programado WHERE programado_id = ? LIMIT 1',
            [programadoId]
        );
        if (!Array.isArray(cursoRows) || cursoRows.length === 0) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
        }

        const cursoRow = cursoRows[0];
        const empresaId = Number(cursoRow.empresa_id);
        const grupo = await obtenerGrupoEmpresasColaboradoras(pool, empresaId);

        const [asignacionesRows] = await pool.query(
            `SELECT inscripcion_id, empresa_documento_id, curso_documento_id, cursos_documento_ids
             FROM inscripcion_curso
             WHERE programado_id = ? AND activo = 1`,
            [programadoId]
        );

        res.json({
            success: true,
            usa_empresas_colaboradoras: Number(cursoRow.usa_empresas_colaboradoras) === 1,
            tiene_grupo_colaboradoras: grupo.tieneColaboradoras,
            empresa_principal_id: grupo.empresaPrincipalId,
            empresas: grupo.empresas,
            asignaciones: (Array.isArray(asignacionesRows) ? asignacionesRows : []).map((row) => {
                const cursosIds = parseCursosDocumentoIds(row.cursos_documento_ids);
                const cursoDocId = row.curso_documento_id != null ? Number(row.curso_documento_id) : null;
                const cursosDocumentoIds = cursosIds.length > 0
                    ? cursosIds
                    : (cursoDocId ? [cursoDocId] : []);
                return {
                    inscripcion_id: Number(row.inscripcion_id),
                    empresa_documento_id: row.empresa_documento_id != null ? Number(row.empresa_documento_id) : null,
                    curso_documento_id: cursosDocumentoIds[0] ?? cursoDocId,
                    cursos_documento_ids: cursosDocumentoIds
                };
            })
        });
    } catch (error) {
        handleError(res, error, 'Error al obtener configuración de empresas colaboradoras');
    }
});

app.put('/api/cursos-programados/:programadoId/colaboradoras-documentos', async (req, res) => {
    const conn = await pool.getConnection();
    try {
        const programadoId = Number(req.params.programadoId);
        if (!Number.isInteger(programadoId) || programadoId <= 0) {
            return res.status(400).json({ success: false, message: 'programadoId inválido' });
        }

        const usaEmpresasColaboradoras = req.body?.usa_empresas_colaboradoras === true || req.body?.usa_empresas_colaboradoras === 1 || req.body?.usa_empresas_colaboradoras === '1';
        const asignaciones = Array.isArray(req.body?.asignaciones) ? req.body.asignaciones : [];

        await asegurarColumnasDocumentosColaboradoras(conn);

        const [cursoRows] = await conn.query(
            'SELECT programado_id, empresa_id FROM curso_programado WHERE programado_id = ? LIMIT 1',
            [programadoId]
        );
        if (!Array.isArray(cursoRows) || cursoRows.length === 0) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
        }

        const empresaId = Number(cursoRows[0].empresa_id);
        const grupo = await obtenerGrupoEmpresasColaboradoras(conn, empresaId);
        const idsEmpresasValidas = new Set(grupo.empresas.map((e) => e.empresa_id));

        await conn.beginTransaction();
        await conn.query(
            'UPDATE curso_programado SET usa_empresas_colaboradoras = ? WHERE programado_id = ?',
            [usaEmpresasColaboradoras ? 1 : 0, programadoId]
        );

        if (usaEmpresasColaboradoras && asignaciones.length > 0) {
            for (const item of asignaciones) {
                const inscripcionId = Number(item?.inscripcion_id);
                if (!Number.isInteger(inscripcionId) || inscripcionId <= 0) continue;

                const empresaDocId = item?.empresa_documento_id != null && item?.empresa_documento_id !== ''
                    ? Number(item.empresa_documento_id)
                    : null;
                const cursosDocIds = parseCursosDocumentoIds(item?.cursos_documento_ids);
                const cursoDocIdFallback = item?.curso_documento_id != null && item?.curso_documento_id !== ''
                    ? Number(item.curso_documento_id)
                    : null;
                const cursosDocumentoIds = cursosDocIds.length > 0
                    ? cursosDocIds
                    : (cursoDocIdFallback ? [cursoDocIdFallback] : []);
                const cursoDocId = cursosDocumentoIds[0] ?? null;

                if (empresaDocId != null && !idsEmpresasValidas.has(empresaDocId)) {
                    await conn.rollback();
                    return res.status(400).json({
                        success: false,
                        message: `La empresa asignada (ID ${empresaDocId}) no pertenece al grupo colaborador del curso`
                    });
                }

                await conn.query(
                    `UPDATE inscripcion_curso
                     SET empresa_documento_id = ?, curso_documento_id = ?, cursos_documento_ids = ?, updated_at = NOW()
                     WHERE inscripcion_id = ? AND programado_id = ?`,
                    [
                        empresaDocId,
                        cursoDocId,
                        cursosDocumentoIds.length > 0 ? JSON.stringify(cursosDocumentoIds) : null,
                        inscripcionId,
                        programadoId
                    ]
                );
            }
        } else if (!usaEmpresasColaboradoras) {
            await conn.query(
                `UPDATE inscripcion_curso
                 SET empresa_documento_id = NULL, curso_documento_id = NULL, cursos_documento_ids = NULL, updated_at = NOW()
                 WHERE programado_id = ?`,
                [programadoId]
            );
        }

        await conn.commit();
        res.json({ success: true, message: 'Configuración de empresas colaboradoras guardada' });
    } catch (error) {
        try { await conn.rollback(); } catch (_) { /* ignore */ }
        handleError(res, error, 'Error al guardar configuración de empresas colaboradoras');
    } finally {
        conn.release();
    }
});

