// ══════════════════════════════════════════════════════════════
// Generar constancias/DC-3 - Google Slides API directo
// Usa Server-Sent Events (SSE) para progreso en tiempo real
// ══════════════════════════════════════════════════════════════
app.post('/api/cursos-programados/:programadoId/generar-constancias-v2', async (req, res) => {
    // Configurar SSE
    res.setHeader('Content-Type', 'text/event-stream');
    res.setHeader('Cache-Control', 'no-cache');
    res.setHeader('Connection', 'keep-alive');
    res.setHeader('X-Accel-Buffering', 'no');
    res.flushHeaders();

    const sendEvent = (event, data) => {
        res.write(`event: ${event}\ndata: ${JSON.stringify(data)}\n\n`);
    };

    // Worker pool para concurrencia limitada (DC-3)
    async function runConcurrent(tasks, concurrency) {
        const results = new Array(tasks.length);
        let nextIdx = 0;
        async function worker() {
            while (nextIdx < tasks.length) {
                const i = nextIdx++;
                results[i] = await tasks[i]();
            }
        }
        await Promise.all(Array.from({ length: Math.min(concurrency, tasks.length) }, () => worker()));
        return results;
    }

    try {
        const { programadoId } = req.params;
        const {
            participantes,
            firmas,
            tipoDocumento,
            aplicarFiltroDC3Promedio8,
            usarFirmaDigital,
            mostrarPuestosDc3,
            cursoDestinoId,
            actualizarInscripciones,
            usarSubcarpetaCurso,
            usaEmpresasColaboradoras,
            usarHorasBase
        } = req.body;
        const horasOverrideRaw = req.body?.horas;
        const usarHorasBaseFlag = usarHorasBase !== false && usarHorasBase !== 0 && usarHorasBase !== '0' && usarHorasBase !== 'false';
        const omitirFirmas = usarFirmaDigital === false;
        const usarOcupacionGenericaDc3 = !(mostrarPuestosDc3 === true);
        const cursoDestinoIdNum = Number(cursoDestinoId);
        const permitirActualizarInscripciones = actualizarInscripciones !== false;
        const usarSubcarpetaCursoFlag = usarSubcarpetaCurso === true;
        const usaEmpresasColaboradorasFlag = usaEmpresasColaboradoras === true || usaEmpresasColaboradoras === 1 || usaEmpresasColaboradoras === '1';

        const extraerDriveFileId = (valor = '') => {
            const raw = String(valor || '').trim();
            if (!raw) return null;
            if (/^[a-zA-Z0-9_-]{10,}$/.test(raw)) return raw;

            const byIdParam = raw.match(/[?&]id=([a-zA-Z0-9_-]+)/);
            const byPath = raw.match(/\/d\/([a-zA-Z0-9_-]+)/);
            const byGoogleusercontent = raw.match(/googleusercontent\.com\/d\/([a-zA-Z0-9_-]+)/);

            return byIdParam?.[1] || byPath?.[1] || byGoogleusercontent?.[1] || null;
        };

        if (!participantes || participantes.length === 0) {
            sendEvent('error', { message: 'Debe seleccionar al menos un participante' });
            return res.end();
        }

        // ── Resolver firma y nombre del responsable de calidad (es_responsable_calidad = 1) ──
        let nombreResponsable = '';
        let firmaCalidadUrl = null;
        let firmaCalidadDriveId = null;
        let instructorIdResponsableCalidad = null;
        try {
            const [adminRows] = await pool.query(
                'SELECT nombre, apellido, firma_url, firma_drive_id, instructor_id FROM usuario WHERE es_responsable_calidad = 1 AND activo = 1 LIMIT 1'
            );
            if (adminRows.length > 0) {
                const admin = adminRows[0];
                nombreResponsable = [admin.nombre, admin.apellido].filter(Boolean).join(' ').trim();
                const instructorIdNum = Number(admin.instructor_id);
                instructorIdResponsableCalidad = Number.isFinite(instructorIdNum) ? instructorIdNum : null;
                const driveIdFirma = admin.firma_drive_id;
                if (omitirFirmas) {
                    firmaCalidadUrl = null;
                    firmaCalidadDriveId = null;
                } else if (driveIdFirma) {
                    firmaCalidadDriveId = String(driveIdFirma).trim();
                    firmaCalidadUrl = `https://lh3.googleusercontent.com/d/${firmaCalidadDriveId}`;
                } else if (admin.firma_url) {
                    const match = admin.firma_url.match(/[?&]id=([^&]+)/);
                    firmaCalidadUrl = match ? `https://lh3.googleusercontent.com/d/${match[1]}` : admin.firma_url;
                    firmaCalidadDriveId = extraerDriveFileId(admin.firma_url);
                }
            }
        } catch (adminErr) {
            logV2('WARN', `No se pudo cargar responsable de calidad: ${adminErr.message}`);
        }

        const generarConstancias = tipoDocumento === 'constancia' || tipoDocumento === 'ambos';
        const generarDC3 = tipoDocumento === 'dc3' || tipoDocumento === 'ambos';
        const tipoLabel = tipoDocumento === 'ambos' ? 'constancias + DC-3' : (tipoDocumento === 'dc3' ? 'DC-3' : 'constancias');

        let participantesConstancias = Array.isArray(participantes) ? [...participantes] : [];
        let participantesDC3 = Array.isArray(participantes) ? [...participantes] : [];

        const parseCalificacionDc3Num = (raw) => {
            if (raw === null || raw === undefined || raw === '') return null;
            const num = Number(raw);
            return Number.isFinite(num) ? num : null;
        };

        const calcularPromedioDc3 = (teoricaRaw, practicaRaw) => {
            const teorica = parseCalificacionDc3Num(teoricaRaw);
            const practica = parseCalificacionDc3Num(practicaRaw);
            const valores = [teorica, practica].filter((v) => v !== null);
            if (valores.length === 0) return null;
            return valores.reduce((acc, v) => acc + v, 0) / valores.length;
        };

        const calificacionesBody = Array.isArray(req.body?.calificaciones) ? req.body.calificaciones : [];
        const mapaCalifBody = new Map(
            calificacionesBody
                .map((c) => [Number(c?.inscripcion_id), c])
                .filter(([id]) => Number.isFinite(id))
        );

        if (generarDC3 && aplicarFiltroDC3Promedio8 !== false) {
            const inscripciones = participantesDC3
                .map((p) => Number(p?.inscripcion_id))
                .filter((id) => Number.isFinite(id));

            if (inscripciones.length > 0) {
                const [califRows] = await pool.query(
                    `SELECT inscripcion_id, calificacion_teorica, calificacion_practica
                     FROM inscripcion_curso
                     WHERE inscripcion_id IN (?)`,
                    [inscripciones]
                );

                const mapaCalif = new Map(
                    (Array.isArray(califRows) ? califRows : []).map((r) => [Number(r.inscripcion_id), r])
                );

                participantesDC3 = participantesDC3.filter((p) => {
                    const inscripcionId = Number(p?.inscripcion_id);
                    const row = mapaCalif.get(inscripcionId);
                    const bodyCal = mapaCalifBody.get(inscripcionId);

                    const teoricaRaw = bodyCal?.calificacionTeorica ?? bodyCal?.calificacion_teorica ?? row?.calificacion_teorica;
                    const practicaRaw = bodyCal?.calificacionPractica ?? bodyCal?.calificacion_practica ?? row?.calificacion_practica;

                    const promedio = calcularPromedioDc3(teoricaRaw, practicaRaw);
                    return promedio !== null && promedio >= 8;
                });

                logV2('INFO', `Filtro DC-3 (>=8) aplicado: elegibles ${participantesDC3.length} de ${participantes.length}`);
            }
        }

        // Asegura empleado_id por inscripción para construir folios individuales.
        const inscripcionesSolicitadas = Array.from(new Set(
            [...participantesConstancias, ...participantesDC3]
                .map((p) => Number(p?.inscripcion_id))
                .filter((id) => Number.isFinite(id))
        ));

        const empleadoPorInscripcion = new Map();
        const puestoPorInscripcion = new Map();
        const nombrePorInscripcion = new Map();
        if (inscripcionesSolicitadas.length > 0) {
            const [inscripcionRows] = await pool.query(
                `SELECT ic.inscripcion_id, ic.empleado_id, e.puesto,
                        e.nombre, e.apellido_paterno, e.apellido_materno
                 FROM inscripcion_curso ic
                 LEFT JOIN empleado e ON ic.empleado_id = e.empleado_id
                 WHERE ic.programado_id = ? AND ic.inscripcion_id IN (?)`,
                [programadoId, inscripcionesSolicitadas]
            );

            (Array.isArray(inscripcionRows) ? inscripcionRows : []).forEach((row) => {
                const inscripcionId = Number(row.inscripcion_id);
                const empleadoId = Number(row.empleado_id);
                const puesto = String(row.puesto || '').trim();

                if (Number.isFinite(inscripcionId)) {
                    if (Number.isFinite(empleadoId)) {
                        empleadoPorInscripcion.set(inscripcionId, empleadoId);
                    }
                    puestoPorInscripcion.set(inscripcionId, puesto);
                    nombrePorInscripcion.set(inscripcionId, {
                        nombre: String(row.nombre || '').trim(),
                        apellido_paterno: String(row.apellido_paterno || '').trim(),
                        apellido_materno: String(row.apellido_materno || '').trim()
                    });
                }
            });
        }

        const agregarEmpleadoId = (lista) => (
            (Array.isArray(lista) ? lista : []).map((p) => {
                const inscripcionId = Number(p?.inscripcion_id);
                const empleadoBody = Number(p?.empleado_id);
                const puestoBody = String(p?.puesto || '').trim();
                const empleadoId = Number.isFinite(empleadoBody)
                    ? empleadoBody
                    : empleadoPorInscripcion.get(inscripcionId);
                const puestoDB = String(puestoPorInscripcion.get(inscripcionId) || '').trim();
                const nombreDB = nombrePorInscripcion.get(inscripcionId) || {};
                const nombre = String(nombreDB.nombre || p?.nombre || '').trim();
                const apellidoPaterno = String(nombreDB.apellido_paterno || p?.apellido_paterno || '').trim();
                const apellidoMaterno = String(nombreDB.apellido_materno || p?.apellido_materno || '').trim();
                const nombreCompleto = String(p?.nombre_completo || '').trim()
                    || [apellidoPaterno, apellidoMaterno, nombre].filter(Boolean).join(' ');

                return {
                    ...p,
                    empleado_id: Number.isFinite(empleadoId) ? empleadoId : null,
                    puesto: puestoDB || puestoBody || '',
                    nombre,
                    apellido_paterno: apellidoPaterno,
                    apellido_materno: apellidoMaterno,
                    nombre_completo: nombreCompleto
                };
            })
        );

        participantesConstancias = agregarEmpleadoId(participantesConstancias);
        participantesDC3 = agregarEmpleadoId(participantesDC3);

        participantesConstancias = await enriquecerParticipantesDocumentosColaboradoras(
            pool, programadoId, participantesConstancias, usaEmpresasColaboradorasFlag
        );
        participantesDC3 = await enriquecerParticipantesDocumentosColaboradoras(
            pool, programadoId, participantesDC3, usaEmpresasColaboradorasFlag
        );

        logV2('INFO', `═══ NUEVA GENERACIÓN V2 ═══ programado_id=${programadoId} | tipo=${tipoDocumento} | participantes=${participantes.length} | colaboradoras=${usaEmpresasColaboradorasFlag} | ocupacion_dc3=${usarOcupacionGenericaDc3 ? 'generica_11' : 'puesto_empleado'} | nombres: ${participantes.map(p => p.nombre_completo).join(', ')}`);

        sendEvent('progress', { fase: 'preparando', mensaje: `Preparando generación de ${tipoLabel}...`, completados: 0, total: participantes.length, pct: 0 });

        const TEMPLATE_SLIDES_ID_DEFAULT = String(process.env.GOOGLE_SLIDES_TEMPLATE_ID || '1AKyCqRJozJq1fNrnlln2lGy4xmhoY0p4URJGDWKU7Us').trim();
        const TEMPLATE_SLIDES_ID_SERGIO_CALIDAD = String(process.env.GOOGLE_SLIDES_TEMPLATE_ID_SERGIO_CALIDAD || '1_IXySQPK-mneLslyCyrsXBbGPZZYYFeGEIyUhTKGfac').trim();
        if (!TEMPLATE_SLIDES_ID_DEFAULT) {
            return res.status(500).json({ success: false, message: 'GOOGLE_SLIDES_TEMPLATE_ID no está configurado en las variables de entorno' });
        }

        // Obtener datos del curso (vista + area_id del catálogo)
        const [cursoData] = await pool.query(
            `SELECT v.*, c.area_id,
                    c.folio            AS curso_folio_base,
                    cp.horas_informe,
                    cp.instructor_id   AS instructor_programado_id,
                    emp.logo          AS empresa_logo,
                    i.rfc              AS instructor_rfc,
                    i.firma_url        AS instructor_firma_url,
                    i.firma_drive_id   AS instructor_firma_drive_id
             FROM v_cursos_programados v
             JOIN curso c ON v.curso_id = c.curso_id
             JOIN curso_programado cp ON v.programado_id = cp.programado_id
               LEFT JOIN empresa emp ON v.empresa_id = emp.empresa_id
             LEFT JOIN instructor i ON v.instructor_id = i.instructor_id
             WHERE v.programado_id = ?`, [programadoId]
        );
        if (cursoData.length === 0) {
            sendEvent('error', { message: 'Curso programado no encontrado' });
            return res.end();
        }
        const cursoInfoBase = cursoData[0];
        const cursoIdBase = Number(cursoInfoBase.curso_id);
        let cursoInfo = cursoInfoBase;
        let cursoDestinoInfo = null;

        if (Number.isFinite(cursoDestinoIdNum)) {
            const [cursoDestinoRows] = await pool.query(
                'SELECT curso_id, nombre_curso, area_id, folio, horas FROM curso WHERE curso_id = ? LIMIT 1',
                [cursoDestinoIdNum]
            );
            if (Array.isArray(cursoDestinoRows) && cursoDestinoRows.length > 0) {
                cursoDestinoInfo = cursoDestinoRows[0];
            }
        }

        if (cursoDestinoInfo) {
            const horasDestinoNum = Number(cursoDestinoInfo.horas);
            cursoInfo = {
                ...cursoInfoBase,
                nombre_curso: cursoDestinoInfo.nombre_curso || cursoInfoBase.nombre_curso,
                area_id: cursoDestinoInfo.area_id ?? cursoInfoBase.area_id,
                curso_folio_base: cursoDestinoInfo.folio || cursoInfoBase.curso_folio_base,
                // Horas oficiales del curso destino (catálogo), no las del programado base.
                curso_horas: Number.isFinite(horasDestinoNum) && horasDestinoNum > 0
                    ? horasDestinoNum
                    : cursoInfoBase.curso_horas
            };
        }

        const horasCatalogoNum = Number(cursoInfo.curso_horas);
        const horasOverrideNum = Number(horasOverrideRaw);
        if (usarHorasBaseFlag && Number.isFinite(horasCatalogoNum) && horasCatalogoNum > 0) {
            // "Horas base": siempre las del catálogo del curso que se está generando.
            cursoInfo = { ...cursoInfo, horas_informe: horasCatalogoNum, curso_horas: horasCatalogoNum };
            logV2('INFO', `Horas base (catálogo) aplicadas: ${horasCatalogoNum}h para "${cursoInfo.nombre_curso}"`);
        } else if (Number.isFinite(horasOverrideNum) && horasOverrideNum > 0) {
            cursoInfo = { ...cursoInfo, horas_informe: horasOverrideNum };
            logV2('INFO', `Horas informe/override aplicadas: ${horasOverrideNum}h para "${cursoInfo.nombre_curso}"`);
        } else {
            logV2('INFO', `Horas usadas: informe=${cursoInfo.horas_informe || 'n/d'} | catálogo=${cursoInfo.curso_horas || 'n/d'} para "${cursoInfo.nombre_curso}"`);
        }

        const cursoDestinoIdFinal = Number.isFinite(Number(cursoDestinoInfo?.curso_id))
            ? Number(cursoDestinoInfo.curso_id)
            : cursoIdBase;
        const usarDescripcionCurso = Number.isFinite(cursoDestinoIdFinal) && !permitirActualizarInscripciones;
        const descripcionCursoSuffix = usarDescripcionCurso ? `_curso_${cursoDestinoIdFinal}` : '';
        const usarSubcarpetaCursoFinal = usarSubcarpetaCursoFlag || usarDescripcionCurso;
        const descripcionDoc = (base) => `${base}${descripcionCursoSuffix}`;

        const normalizarTexto = (valor = '') => (
            String(valor || '')
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .toLowerCase()
                .replace(/\s+/g, ' ')
                .trim()
        );
        const instructorProgramadoId = Number(cursoInfo.instructor_programado_id ?? cursoInfo.instructor_id);
        const esInstructorResponsableCalidad = Number.isFinite(instructorProgramadoId)
            && Number.isFinite(instructorIdResponsableCalidad)
            && instructorProgramadoId === instructorIdResponsableCalidad;
        const responsableCalidadEsSergio = normalizarTexto(nombreResponsable).includes('sergio');
        const usarPlantillaSergioCalidad = esInstructorResponsableCalidad && responsableCalidadEsSergio;
        const templateSlidesId = usarPlantillaSergioCalidad && TEMPLATE_SLIDES_ID_SERGIO_CALIDAD
            ? TEMPLATE_SLIDES_ID_SERGIO_CALIDAD
            : TEMPLATE_SLIDES_ID_DEFAULT;

        if (generarConstancias) {
            logV2('INFO', `Plantilla de constancias: ${usarPlantillaSergioCalidad ? 'especial Sergio calidad' : 'general'} (${templateSlidesId})`);
        }

        // Formatear fecha
        const meses = ['enero', 'febrero', 'marzo', 'abril', 'mayo', 'junio', 'julio', 'agosto', 'septiembre', 'octubre', 'noviembre', 'diciembre'];
        const fechaInicio = new Date(cursoInfo.fecha_inicio);
        const fechaFormateada = `${fechaInicio.getDate()} de ${meses[fechaInicio.getMonth()]}`;
        const anio = fechaInicio.getFullYear();

        // Folios por formato: <curso.folio>-C-<DDMMYY> y <curso.folio>-DC3-<DDMMYY>
        const fechaFolioBase = new Date(cursoInfo.fecha_inicio);
        const dd = String(fechaFolioBase.getDate()).padStart(2, '0');
        const mm = String(fechaFolioBase.getMonth() + 1).padStart(2, '0');
        const yy = String(fechaFolioBase.getFullYear()).slice(-2);
        const fechaFolio = `${dd}${mm}${yy}`;
        const folioCursoBase = String(cursoInfo.curso_folio_base || cursoInfo.curso_id || '').trim();
        const construirFolio = (tipo, empleadoId, folioBaseOverride, cursoDocId) => {
            const base = String(folioBaseOverride || folioCursoBase || '').trim() || folioCursoBase;
            const cursoSuffix = usaEmpresasColaboradorasFlag && Number.isFinite(Number(cursoDocId)) && Number(cursoDocId) > 0
                ? `-C${Number(cursoDocId)}`
                : '';
            return `${base}-${tipo}-${fechaFolio}-${empleadoId}${cursoSuffix}`;
        };
        const folioConstanciaPorClave = new Map();
        const folioDC3PorClave = new Map();

        // ═══ FOLIOS CONSTANCIA (nuevo formato) ═══
        if (generarConstancias) {
            sendEvent('progress', { fase: 'folios', mensaje: 'Asignando folio de constancias...', completados: 0, total: participantes.length, pct: 2 });
            const asignacionesConstancias = participantesConstancias
                .map((p) => {
                    const inscripcionId = Number(p?.inscripcion_id);
                    const empleadoId = Number(p?.empleado_id);
                    if (!Number.isFinite(inscripcionId) || !Number.isFinite(empleadoId)) return null;
                    const folioBaseParticipante = usaEmpresasColaboradorasFlag ? (p.folio_curso_doc || folioCursoBase) : folioCursoBase;
                    return {
                        clave: claveDocumentoParticipante(p),
                        inscripcionId,
                        folio: construirFolio('C', empleadoId, folioBaseParticipante, p.curso_documento_id)
                    };
                })
                .filter(Boolean);

            for (const asignacion of asignacionesConstancias) {
                folioConstanciaPorClave.set(asignacion.clave, asignacion.folio);
                if (permitirActualizarInscripciones) {
                    await pool.query(
                        `UPDATE inscripcion_curso SET folio_constancia = ? WHERE inscripcion_id = ?`,
                        [asignacion.folio, asignacion.inscripcionId]
                    );
                }
            }
        }

        sendEvent('progress', { fase: 'carpeta', mensaje: 'Creando carpetas en Drive...', completados: 0, total: participantes.length, pct: 4 });

        // ═══ CARPETAS EN DRIVE ═══
        const carpetaResult = await resolverCarpetaCursoProgramado(programadoId);
        const carpetaCursoId = carpetaResult.success ? carpetaResult.folderId : driveService.ROOT_FOLDER_ID;

        // Crear subcarpetas en paralelo
        let carpetaConstanciasId = null;
        let carpetaDC3Id = null;
        const [constFolderBase, dc3FolderBase] = await Promise.all([
            generarConstancias ? driveService.obtenerOCrearCarpeta('Constancias', carpetaCursoId) : null,
            generarDC3 ? driveService.obtenerOCrearCarpeta('DC-3', carpetaCursoId) : null
        ]);

        const subcarpetaCursoNombre = usarSubcarpetaCursoFinal
            ? sanitizarSegmentoNombre(cursoInfo.nombre_curso, 'curso')
            : '';

        if (constFolderBase && subcarpetaCursoNombre) {
            carpetaConstanciasId = await driveService.obtenerOCrearCarpeta(subcarpetaCursoNombre, constFolderBase);
        } else {
            carpetaConstanciasId = constFolderBase;
        }

        if (dc3FolderBase && subcarpetaCursoNombre) {
            carpetaDC3Id = await driveService.obtenerOCrearCarpeta(subcarpetaCursoNombre, dc3FolderBase);
        } else {
            carpetaDC3Id = dc3FolderBase;
        }

        const inicio = Date.now();
        let constanciaExitosos = 0, constanciaFallidos = 0;
        let dc3Exitosos = 0, dc3Fallidos = 0;
        let dc3ErrorDetalle = null;
        const idsExitosos = [];
        const constanciasGeneradas = [];
        const dc3Generados = [];
        let constanciasLoteGenerado = null;
        let dc3LoteExcelGenerado = null;
        let dc3LotePdfGenerado = null;

        // ═══ Distribución del progreso ═══
        // 'constancia': 5-95% constancias
        // 'dc3':        5-95% DC-3
        // 'ambos':      5-50% constancias, 50-95% DC-3
        const pctConstIni = 5;
        const pctConstFin = tipoDocumento === 'ambos' ? 50 : 95;
        const pctDC3Ini = tipoDocumento === 'ambos' ? 50 : 5;
        const pctDC3Fin = 95;

        // ═══ FASE 1: CONSTANCIAS (Google Slides) ═══
        if (generarConstancias) {
            const participantesLote = participantesConstancias.map((p) => {
                const folio = folioConstanciaPorClave.get(claveDocumentoParticipante(p)) || '';
                const nombreCursoParticipante = usaEmpresasColaboradorasFlag
                    ? (p.nombre_curso_doc || cursoInfo.nombre_curso || '')
                    : (cursoInfo.nombre_curso || '');
                return {
                    inscripcion_id: p.inscripcion_id,
                    folio,
                    nombre: p.nombre_completo || 'participante',
                    variables: {
                        nombre_alumno: p.nombre_completo || '',
                        nombre_taller: nombreCursoParticipante,
                        fecha: fechaFormateada,
                        anio: String(anio),
                        modalidad: cursoInfo.modalidad ? cursoInfo.modalidad.charAt(0).toUpperCase() + cursoInfo.modalidad.slice(1) : 'Presencial',
                        horas: String(cursoInfo.horas_informe || cursoInfo.curso_horas || ''),
                        ciudad: cursoInfo.ciudad || cursoInfo.localidad || '',
                        Estado: cursoInfo.estado || cursoInfo.localidad || '',
                        Instructor: `${cursoInfo.instructor_nombre || ''}`.trim(),
                        n_control: folio,
                        nombre_responsable: nombreResponsable,
                        cargo_instructor: firmas?.firma2?.cargo || 'Instructor',
                        // {{firma_instructor}} y {{firma_calidad}} se insertan como imágenes
                        // via replaceAllShapesWithImage (no como texto)
                    },
                    nombrePdf: `${(p.nombre_completo || 'participante').replace(/[^a-zA-Z0-9áéíóúñÁÉÍÓÚÑ ]/g, '_')}_${folio}.pdf`
                };
            });

            // Firmas: pasar drive_id para que generarConstanciasLote las descargue vía Drive API
            // y publique una copia temporal pública (lh3 sobre archivos privados → forbidden).
            let firmaInstructorUrl = null;
            let firmaInstructorDriveId = null;
            if (omitirFirmas) {
                firmaInstructorUrl = null;
                firmaInstructorDriveId = null;
            } else if (cursoInfo.instructor_firma_drive_id) {
                firmaInstructorDriveId = String(cursoInfo.instructor_firma_drive_id).trim();
                firmaInstructorUrl = `https://lh3.googleusercontent.com/d/${firmaInstructorDriveId}`;
            } else if (cursoInfo.instructor_firma_url) {
                firmaInstructorDriveId = extraerDriveFileId(cursoInfo.instructor_firma_url);
                const match = cursoInfo.instructor_firma_url.match(/[?&]id=([^&]+)/);
                firmaInstructorUrl = match ? `https://lh3.googleusercontent.com/d/${match[1]}` : cursoInfo.instructor_firma_url;
            }
            if (!firmaInstructorDriveId && !firmaInstructorUrl) {
                logV2('WARN', `Instructor sin firma registrada (instructor_id=${cursoInfo.instructor_id}). Se generarán constancias sin imagen de firma.`);
            } else {
                logV2('INFO', `Firma del instructor drive_id=${firmaInstructorDriveId || 'n/a'} url=${firmaInstructorUrl || 'n/a'}`);
            }
            if (!omitirFirmas && firmaCalidadDriveId) {
                logV2('INFO', `Firma de calidad drive_id=${firmaCalidadDriveId}`);
            }

            logV2('INFO', `Generando ${participantesLote.length} constancias (concurrencia 10)...`);
            sendEvent('progress', { fase: 'constancias', mensaje: 'Generando constancias...', completados: 0, total: participantesConstancias.length, pct: pctConstIni });

            const resultado = await driveService.generarConstanciasLote(
                templateSlidesId,
                participantesLote,
                carpetaConstanciasId,
                (completados, total, p) => {
                    const pct = Math.round(pctConstIni + (completados / total) * (pctConstFin - pctConstIni));
                    sendEvent('progress', {
                        fase: 'constancias',
                        mensaje: `Constancias: ${completados}/${total}`,
                        completados,
                        total,
                        pct,
                        ultimo: p.nombrePdf
                    });
                },
                10,                      // concurrencia
                firmaInstructorUrl,      // fallback URL (se republica vía Drive API)
                firmaCalidadUrl,         // fallback URL calidad
                firmaInstructorDriveId,  // {{firma_instructor}} → copia pública temporal
                omitirFirmas ? null : firmaCalidadDriveId  // {{firma_calidad}}
            );

            constanciaExitosos = resultado.exitosos;
            constanciaFallidos = resultado.fallidos;

            // Log constancias fallidas con detalle
            resultado.resultados
                .filter(r => !r.success)
                .forEach(r => logV2('ERROR', `Constancia FALLIDA: "${participantesLote[r.index].nombre}" (inscripcion_id=${participantesLote[r.index].inscripcion_id}) - ${r.error}`));

            logV2('INFO', `Constancias: ${constanciaExitosos} exitosas, ${constanciaFallidos} fallidas`);

            // Recopilar IDs exitosos para marcar en BD
            resultado.resultados
                .filter(r => r.success)
                .forEach(r => {
                    const participante = participantesConstancias[r.index];
                    idsExitosos.push(participante.inscripcion_id);
                    constanciasGeneradas.push({
                        inscripcion_id: participante.inscripcion_id,
                        curso_documento_id: participante.curso_documento_id ?? null,
                        nombre_archivo: r.nombrePdf,
                        archivo_url: r.webViewLink || '',
                        drive_file_id: r.fileId || null
                    });
                });

            const resultadosConstanciasConArchivo = resultado.resultados
                .filter((r) => r.success && r.fileId)
                .sort((a, b) => a.index - b.index);

            if (resultadosConstanciasConArchivo.length > 0) {
                sendEvent('progress', {
                    fase: 'constancias',
                    mensaje: 'Uniendo constancias en un solo PDF...',
                    completados: resultadosConstanciasConArchivo.length,
                    total: participantesConstancias.length,
                    pct: pctConstFin
                });

                try {
                    const buffersConstancias = [];
                    for (const item of resultadosConstanciasConArchivo) {
                        const pdfBuffer = await driveService.descargarArchivo(item.fileId);
                        if (pdfBuffer?.length) {
                            buffersConstancias.push(pdfBuffer);
                        }
                    }

                    if (buffersConstancias.length > 0) {
                        const bufferLote = await combinarPdfs(buffersConstancias);
                        const nombreLote = construirNombreDocProgramado({
                            nombreEmpresa: cursoInfo.nombre_empresa || 'empresa',
                            nombreCurso: cursoInfo.nombre_curso || 'curso',
                            fechaInicio: cursoInfo.fecha_inicio || new Date(),
                            tipoBase: 'constancias_consolidado',
                            extension: 'pdf'
                        });

                        const driveConstanciasLote = await driveService.uploadFileFast(
                            bufferLote,
                            nombreLote,
                            'application/pdf',
                            carpetaConstanciasId
                        );

                        constanciasLoteGenerado = {
                            nombre_archivo: nombreLote,
                            archivo_url: driveConstanciasLote?.webViewLink || '',
                            drive_file_id: driveConstanciasLote?.id || null
                        };

                        logV2('INFO', `Constancias consolidadas en 1 PDF: ${nombreLote}`);
                    }
                } catch (mergeError) {
                    logV2('WARN', `No se pudo generar PDF consolidado de constancias: ${mergeError.message}`);
                }
            }
        }

        // ═══ FASE 2: DC-3 (Excel con ExcelJS) ═══
        if (generarDC3) {
            if (participantesDC3.length === 0) {
                logV2('INFO', 'No hay participantes elegibles para DC-3 (>8).');
                sendEvent('progress', { fase: 'dc3', mensaje: 'Sin participantes elegibles para DC-3 (>8).', completados: 0, total: 0, pct: pctDC3Fin });
            } else {
                logV2('INFO', `Generando ${participantesDC3.length} DC-3 (concurrencia 8)...`);
                sendEvent('progress', { fase: 'dc3', mensaje: 'Generando DC-3...', completados: 0, total: participantesDC3.length, pct: pctDC3Ini });

                // ═══ FOLIOS DC-3 (nuevo formato) ═══
                const asignacionesDC3 = participantesDC3
                    .map((p) => {
                        const inscripcionId = Number(p?.inscripcion_id);
                        const empleadoId = Number(p?.empleado_id);
                        if (!Number.isFinite(inscripcionId) || !Number.isFinite(empleadoId)) return null;
                        const folioBaseParticipante = usaEmpresasColaboradorasFlag ? (p.folio_curso_doc || folioCursoBase) : folioCursoBase;
                        return {
                            clave: claveDocumentoParticipante(p),
                            inscripcionId,
                            folio: construirFolio('DC3', empleadoId, folioBaseParticipante, p.curso_documento_id)
                        };
                    })
                    .filter(Boolean);

                for (const asignacion of asignacionesDC3) {
                    folioDC3PorClave.set(asignacion.clave, asignacion.folio);
                    if (permitirActualizarInscripciones) {
                        await pool.query(
                            `UPDATE inscripcion_curso SET folio_dc3 = ? WHERE inscripcion_id = ?`,
                            [asignacion.folio, asignacion.inscripcionId]
                        );
                    }
                }

                // Descargar el buffer de la firma del instructor una sola vez para todo el lote.
                // La firma es la misma para todos los participantes, así evitamos N descargas.
                let instructorFirmaBuffer = null;
                let instructorFirmaExt = null;
                const instructorFirmaDriveId = extraerDriveFileId(cursoInfo.instructor_firma_drive_id || cursoInfo.instructor_firma_url);
                const calidadFirmaDriveId = extraerDriveFileId(firmaCalidadDriveId || firmaCalidadUrl);
                const firmaDc3DriveId = instructorFirmaDriveId || calidadFirmaDriveId;

                if (!omitirFirmas && firmaDc3DriveId) {
                    const firmaDc3Fuente = instructorFirmaDriveId ? 'instructor' : 'calidad';
                    try {
                        const buf = await driveService.descargarArchivo(firmaDc3DriveId);
                        if (buf && buf.length > 3) {
                            // Normalizar firma para PDF de DC-3: tinta oscura sobre fondo blanco.
                            try {
                                instructorFirmaBuffer = await normalizarFirmaParaDc3(buf);
                                instructorFirmaExt = 'png';
                            } catch (firmaPngErr) {
                                // Fallback: usar formato original si la normalización falla.
                                if (buf[0] === 0xff && buf[1] === 0xd8) {
                                    instructorFirmaBuffer = buf;
                                    instructorFirmaExt = 'jpeg';
                                } else if (buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) {
                                    instructorFirmaBuffer = buf;
                                    instructorFirmaExt = 'png';
                                } else {
                                    logV2('WARN', 'Firma del instructor en formato no compatible con ExcelJS (WebP?). Se omitirá en DC-3.');
                                }
                            }
                        }
                        logV2('INFO', `Firma para DC-3 cargada desde ${firmaDc3Fuente} (drive_id=${firmaDc3DriveId}).`);
                    } catch (firmaErr) {
                        logV2('WARN', `No se pudo descargar la firma (${firmaDc3Fuente}) para DC-3: ${firmaErr.message}`);
                    }
                } else if (!omitirFirmas) {
                    logV2('WARN', 'Sin firma del instructor ni firma de calidad. DC-3 se generarán sin imagen de firma.');
                } else {
                    logV2('INFO', 'Se omitieron firmas por configuración (usarFirmaDigital=false).');
                }

                // Descargar el logo de la empresa una sola vez para todo el lote de DC-3.
                let empresaLogoBuffer = null;
                let empresaLogoExt = null;
                const logoEmpresaRaw = (cursoInfo.empresa_logo || '').trim();
                const empresaCursoEsBiznaga = dc3Service.esEmpresaBiznaga({
                    rfc_empresa: cursoInfo.empresa_rfc,
                    nombre_empresa: cursoInfo.nombre_empresa || cursoInfo.razon_social
                });

                if (logoEmpresaRaw && !empresaCursoEsBiznaga) {
                    const logoDriveId = extraerDriveFileId(logoEmpresaRaw);
                    if (logoDriveId) {
                        try {
                            const logoBuf = await driveService.descargarArchivo(logoDriveId);
                            if (logoBuf && logoBuf.length > 11) {
                                if (logoBuf[0] === 0xff && logoBuf[1] === 0xd8) {
                                    empresaLogoBuffer = logoBuf;
                                    empresaLogoExt = 'jpeg';
                                } else if (logoBuf[0] === 0x89 && logoBuf[1] === 0x50 && logoBuf[2] === 0x4e && logoBuf[3] === 0x47) {
                                    empresaLogoBuffer = logoBuf;
                                    empresaLogoExt = 'png';
                                } else if (
                                    logoBuf[0] === 0x52 && logoBuf[1] === 0x49 && logoBuf[2] === 0x46 && logoBuf[3] === 0x46 &&
                                    logoBuf[8] === 0x57 && logoBuf[9] === 0x45 && logoBuf[10] === 0x42 && logoBuf[11] === 0x50
                                ) {
                                    logV2('WARN', 'Logo de empresa en formato WebP. ExcelJS no soporta WebP; se omitirá en DC-3.');
                                } else {
                                    logV2('WARN', 'Logo de empresa en formato no compatible con ExcelJS. Se omitirá en DC-3.');
                                }
                            }
                        } catch (logoErr) {
                            logV2('WARN', `No se pudo descargar logo de empresa para DC-3: ${logoErr.message}`);
                        }
                    } else {
                        logV2('WARN', 'No se pudo extraer el ID de Drive del logo de empresa. Se omitirá en DC-3.');
                    }
                } else if (empresaCursoEsBiznaga) {
                    logV2('INFO', 'Empresa BIZNAGA: se omite el logo derecho en DC-3 para no duplicar el de la plantilla.');
                } else {
                    logV2('INFO', 'La empresa no tiene logo configurado; DC-3 se generarán sin logo de empresa.');
                }

                const XLSX_MIME = 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet';
                try {
                    const parseLogoBuffer = (logoBuf) => {
                        if (!logoBuf || logoBuf.length <= 11) return null;
                        if (logoBuf[0] === 0xff && logoBuf[1] === 0xd8) {
                            return { buffer: logoBuf, ext: 'jpeg' };
                        }
                        if (logoBuf[0] === 0x89 && logoBuf[1] === 0x50 && logoBuf[2] === 0x4e && logoBuf[3] === 0x47) {
                            return { buffer: logoBuf, ext: 'png' };
                        }
                        return null;
                    };

                    const logosEmpresaCache = new Map();
                    if (usaEmpresasColaboradorasFlag) {
                        const logosUnicos = new Set(
                            participantesDC3
                                .map((p) => String(p?.empresa_logo_doc || '').trim())
                                .filter(Boolean)
                        );
                        for (const logoRaw of logosUnicos) {
                            const logoDriveId = extraerDriveFileId(logoRaw);
                            if (!logoDriveId) continue;
                            try {
                                const logoBuf = await driveService.descargarArchivo(logoDriveId);
                                const parsed = parseLogoBuffer(logoBuf);
                                if (parsed) {
                                    logosEmpresaCache.set(logoRaw, parsed);
                                }
                            } catch (logoErr) {
                                logV2('WARN', `No se pudo descargar logo colaboradora para DC-3: ${logoErr.message}`);
                            }
                        }
                    }

                    const participantesConFolio = participantesDC3.map((p) => {
                        const base = {
                            ...p,
                            folio_dc3: folioDC3PorClave.get(claveDocumentoParticipante(p)) || ''
                        };
                        if (!usaEmpresasColaboradorasFlag) {
                            return base;
                        }
                        const logoRaw = String(p?.empresa_logo_doc || '').trim();
                        const logoEntry = logoRaw ? logosEmpresaCache.get(logoRaw) : null;
                        const nombreEmpresaDoc = p.nombre_empresa_doc || cursoInfo.nombre_empresa;
                        const rfcEmpresaDoc = p.rfc_empresa_doc || cursoInfo.empresa_rfc;
                        const omitirLogoBiznaga = dc3Service.esEmpresaBiznaga({
                            rfc_empresa: rfcEmpresaDoc,
                            nombre_empresa: nombreEmpresaDoc
                        });
                        return {
                            ...base,
                            nombre_empresa: nombreEmpresaDoc,
                            rfc_empresa: rfcEmpresaDoc,
                            nombre_curso: p.nombre_curso_doc || cursoInfo.nombre_curso,
                            area_id: p.area_id_doc ?? cursoInfo.area_id,
                            empresa_logo_buffer: omitirLogoBiznaga ? null : (logoEntry?.buffer || empresaLogoBuffer),
                            empresa_logo_ext: omitirLogoBiznaga ? null : (logoEntry?.ext || empresaLogoExt)
                        };
                    });

                    sendEvent('progress', {
                        fase: 'dc3',
                        mensaje: 'Generando consolidado de DC-3...',
                        completados: 0,
                        total: participantesConFolio.length,
                        pct: Math.min(pctDC3Ini + 2, pctDC3Fin - 25)
                    });

                    const bufferConsolidado = await dc3Service.generarDC3Consolidado(
                        cursoInfo,
                        cursoInfo.area_id,
                        participantesConFolio,
                        {
                            agente_capacitador: COMPANY_LEGAL_NAME,
                            instructor_firma_buffer: instructorFirmaBuffer,
                            instructor_firma_ext: instructorFirmaExt,
                            empresa_logo_buffer: empresaLogoBuffer,
                            empresa_logo_ext: empresaLogoExt,
                            usar_ocupacion_generica: usarOcupacionGenericaDc3
                        }
                    );

                    const nombreArchivoConsolidado = construirNombreDocProgramado({
                        nombreEmpresa: usaEmpresasColaboradorasFlag
                            ? `${cursoInfo.nombre_empresa || 'empresa'}_COLABORADORAS`
                            : (cursoInfo.nombre_empresa || 'empresa'),
                        nombreCurso: `${cursoInfo.nombre_curso || 'curso'}_DC3_CONSOLIDADO`,
                        fechaInicio: cursoInfo.fecha_inicio || new Date(),
                        tipoBase: 'dc3_consolidado',
                        extension: 'xlsx'
                    });

                    // Subir como XLSX y convertir a Google Sheet nativo (editor integrado completo).
                    const driveXlsxTemp = await driveService.uploadFileFast(
                        bufferConsolidado,
                        nombreArchivoConsolidado,
                        XLSX_MIME,
                        carpetaDC3Id
                    );
                    if (!driveXlsxTemp?.id) {
                        throw new Error('No se obtuvo ID de Drive para el XLSX consolidado de DC-3');
                    }

                    const driveFile = await driveService.convertirOfficeExcelAGoogleSheet(driveXlsxTemp.id, {
                        nombre: String(nombreArchivoConsolidado).replace(/\.xlsx$/i, ''),
                        carpetaId: carpetaDC3Id,
                        eliminarOriginal: true
                    });

                    if (!driveFile?.id) {
                        throw new Error('No se obtuvo ID de Drive para el Google Sheet consolidado de DC-3');
                    }

                    dc3LoteExcelGenerado = {
                        nombre_archivo: driveFile.name || String(nombreArchivoConsolidado).replace(/\.xlsx$/i, ''),
                        archivo_url: driveFile.webViewLink
                            || `https://docs.google.com/spreadsheets/d/${driveFile.id}/edit`,
                        drive_file_id: driveFile.id
                    };

                    const totalIndividuales = participantesConFolio.length;
                    sendEvent('progress', {
                        fase: 'dc3',
                        mensaje: 'Exportando DC-3 consolidado a PDF...',
                        completados: totalIndividuales,
                        total: totalIndividuales,
                        pct: Math.min(pctDC3Ini + 8, pctDC3Fin - 18)
                    });

                    let pdfBufferDc3Consolidado = null;
                    let buffersIndividuales = [];

                    // Estrategia 1: una sola exportación a PDF (1 llamada a Google; evita rate limit 429).
                    try {
                        pdfBufferDc3Consolidado = await driveService.exportarArchivoPDF(driveFile.id, { landscape: false });
                        if (pdfBufferDc3Consolidado?.length) {
                            const { PDFDocument } = require('pdf-lib');
                            const pdfConsolidado = await PDFDocument.load(pdfBufferDc3Consolidado, { ignoreEncryption: true });
                            const paginasDisponibles = pdfConsolidado.getPageCount();

                            if (paginasDisponibles >= totalIndividuales) {
                                for (let idx = 0; idx < totalIndividuales; idx++) {
                                    const pdfIndividual = await PDFDocument.create();
                                    const [pagina] = await pdfIndividual.copyPages(pdfConsolidado, [idx]);
                                    pdfIndividual.addPage(pagina);
                                    buffersIndividuales.push(Buffer.from(await pdfIndividual.save()));
                                }
                                logV2('INFO', `DC-3 PDF: exportación única (${paginasDisponibles} páginas) + división local.`);
                            } else {
                                throw new Error(`PDF consolidado incompleto: ${paginasDisponibles} páginas para ${totalIndividuales} participantes`);
                            }
                        }
                    } catch (exportUnicoErr) {
                        logV2('WARN', `Exportación única DC-3 falló (${exportUnicoErr.message}), intentando por hoja con throttling...`);
                        buffersIndividuales = [];
                        pdfBufferDc3Consolidado = null;

                        const pdfExport = await driveService.exportarArchivoPDFPorHojas(driveFile.id, { landscape: false });
                        pdfBufferDc3Consolidado = pdfExport?.consolidado;
                        buffersIndividuales = Array.isArray(pdfExport?.porHoja) ? pdfExport.porHoja : [];
                    }

                    if (!pdfBufferDc3Consolidado?.length) {
                        throw new Error('No se pudo exportar DC-3 consolidado a PDF');
                    }

                    if (buffersIndividuales.length < totalIndividuales) {
                        throw new Error(`PDF incompleto: ${buffersIndividuales.length} documento(s) para ${totalIndividuales} participante(s)`);
                    }

                    sendEvent('progress', {
                        fase: 'dc3',
                        mensaje: 'Generando DC-3 individuales (PDF)...',
                        completados: 0,
                        total: totalIndividuales,
                        pct: Math.min(pctDC3Ini + 10, pctDC3Fin - 16)
                    });

                    let completadosIndividuales = 0;
                    const tareasIndividuales = participantesConFolio.map((p, idx) => async () => {
                        const inscripcionId = Number(p?.inscripcion_id);
                        if (!Number.isFinite(inscripcionId)) {
                            throw new Error('inscripcion_id inválido para generar DC-3 individual');
                        }

                        const nombrePersona = sanitizarSegmentoNombre(
                            p.nombre_completo || `${p.apellido_paterno || ''} ${p.apellido_materno || ''} ${p.nombre || ''}`,
                            `participante_${inscripcionId}`
                        );
                        const folioSeguro = sanitizarSegmentoNombre(p.folio_dc3 || `inscripcion_${inscripcionId}`, `inscripcion_${inscripcionId}`);
                        const baseArchivo = `${nombrePersona}_${folioSeguro}_dc3`;
                        const nombrePdf = `${baseArchivo}.pdf`;

                        const pdfBufferIndividual = buffersIndividuales[idx];
                        if (!pdfBufferIndividual?.length) {
                            throw new Error(`No se pudo construir el PDF individual del participante índice ${idx}`);
                        }

                        const drivePdf = await driveService.uploadFileFast(
                            Buffer.from(pdfBufferIndividual),
                            nombrePdf,
                            'application/pdf',
                            carpetaDC3Id
                        );

                        if (!drivePdf?.id) {
                            throw new Error('No se obtuvo ID de Drive para el PDF individual');
                        }

                        return {
                            success: true,
                            index: idx,
                            inscripcion_id: inscripcionId,
                            nombre_archivo: nombrePdf,
                            archivo_url: drivePdf.webViewLink || '',
                            drive_file_id: drivePdf.id
                        };
                    });

                    const resultadosIndividuales = await runConcurrent(
                        tareasIndividuales.map((tarea) => async () => {
                            try {
                                const r = await tarea();
                                completadosIndividuales += 1;
                                const pct = Math.round(
                                    Math.min(
                                        pctDC3Fin - 20,
                                        pctDC3Ini + ((completadosIndividuales / Math.max(1, totalIndividuales)) * ((pctDC3Fin - 20) - pctDC3Ini))
                                    )
                                );
                                sendEvent('progress', {
                                    fase: 'dc3',
                                    mensaje: `DC-3 individuales PDF: ${completadosIndividuales}/${totalIndividuales}`,
                                    completados: completadosIndividuales,
                                    total: totalIndividuales,
                                    pct,
                                    ultimo: r?.nombre_archivo || ''
                                });
                                return r;
                            } catch (taskErr) {
                                completadosIndividuales += 1;
                                const pct = Math.round(
                                    Math.min(
                                        pctDC3Fin - 20,
                                        pctDC3Ini + ((completadosIndividuales / Math.max(1, totalIndividuales)) * ((pctDC3Fin - 20) - pctDC3Ini))
                                    )
                                );
                                sendEvent('progress', {
                                    fase: 'dc3',
                                    mensaje: `DC-3 individuales PDF: ${completadosIndividuales}/${totalIndividuales}`,
                                    completados: completadosIndividuales,
                                    total: totalIndividuales,
                                    pct
                                });
                                return {
                                    success: false,
                                    error: taskErr.message || String(taskErr)
                                };
                            }
                        }),
                        4
                    );

                    resultadosIndividuales
                        .filter((r) => r?.success)
                        .forEach((r) => {
                            dc3Generados.push({
                                inscripcion_id: r.inscripcion_id,
                                curso_documento_id: participantesConFolio[r.index]?.curso_documento_id ?? null,
                                nombre_archivo: r.nombre_archivo,
                                archivo_url: r.archivo_url,
                                drive_file_id: r.drive_file_id
                            });
                        });

                    const dc3IndividualesFallidos = resultadosIndividuales.filter((r) => !r?.success);
                    dc3IndividualesFallidos.forEach((r, idxFallido) => {
                        logV2('ERROR', `DC-3 individual FALLIDO #${idxFallido + 1}: ${r?.error || 'error desconocido'}`);
                    });

                    // Exportar el consolidado de DC-3 a PDF y guardarlo en la misma carpeta DC-3.
                    try {
                        sendEvent('progress', {
                            fase: 'dc3',
                            mensaje: 'Exportando DC-3 consolidado a PDF...',
                            completados: participantesDC3.length,
                            total: participantesDC3.length,
                            pct: Math.min(pctDC3Fin, 94)
                        });

                        if (pdfBufferDc3Consolidado?.length) {
                            const nombreArchivoConsolidadoPdf = construirNombreDocProgramado({
                                nombreEmpresa: cursoInfo.nombre_empresa || 'empresa',
                                nombreCurso: `${cursoInfo.nombre_curso || 'curso'}_DC3_CONSOLIDADO`,
                                fechaInicio: cursoInfo.fecha_inicio || new Date(),
                                tipoBase: 'dc3_consolidado',
                                extension: 'pdf'
                            });

                            const drivePdf = await driveService.uploadFileFast(
                                Buffer.from(pdfBufferDc3Consolidado),
                                nombreArchivoConsolidadoPdf,
                                'application/pdf',
                                carpetaDC3Id
                            );

                            if (drivePdf?.id) {
                                dc3LotePdfGenerado = {
                                    nombre_archivo: nombreArchivoConsolidadoPdf,
                                    archivo_url: drivePdf.webViewLink || '',
                                    drive_file_id: drivePdf.id
                                };
                                logV2('INFO', `DC-3 consolidado exportado a PDF: ${nombreArchivoConsolidadoPdf}`);
                            }
                        }
                    } catch (pdfErr) {
                        logV2('WARN', `No se pudo exportar DC-3 consolidado a PDF: ${pdfErr.message}`);
                    }

                    dc3Exitosos = dc3Generados.length;
                    dc3Fallidos = Math.max(0, participantesDC3.length - dc3Exitosos);

                    sendEvent('progress', {
                        fase: 'dc3',
                        mensaje: `DC-3 individuales PDF: ${dc3Exitosos}/${participantesDC3.length}`,
                        completados: dc3Exitosos,
                        total: participantesDC3.length,
                        pct: pctDC3Fin,
                        ultimo: nombreArchivoConsolidado
                    });

                    logV2('INFO', `DC-3 individuales PDF: ${dc3Exitosos} exitosos, ${dc3Fallidos} fallidos`);
                } catch (error) {
                    dc3Exitosos = 0;
                    dc3Fallidos = participantesDC3.length;
                    dc3ErrorDetalle = error.message || String(error);
                    logV2('ERROR', `DC-3 FALLIDO: ${dc3ErrorDetalle}`);
                }
            }
        }

        // ═══ GUARDAR EN BD ═══
        sendEvent('progress', { fase: 'guardando', mensaje: 'Guardando en base de datos...', completados: participantes.length, total: participantes.length, pct: 96 });

        if (idsExitosos.length > 0) {
            await pool.query(`
                UPDATE inscripcion_curso
                SET certificado_generado = 1, fecha_certificado = CURDATE()
                WHERE inscripcion_id IN (?)
            `, [idsExitosos]);

            for (const item of constanciasGeneradas) {
                await pool.query(
                    `UPDATE inscripcion_curso
                     SET certificado_url = ?, certificado_generado = 1, fecha_certificado = CURDATE()
                     WHERE inscripcion_id = ?`,
                    [item.archivo_url || '', item.inscripcion_id]
                );

                const descripcion = descripcionDocumentoInscripcion(
                    'constancia',
                    item.inscripcion_id,
                    item.curso_documento_id,
                    usaEmpresasColaboradorasFlag,
                    usarDescripcionCurso ? cursoDestinoIdFinal : null
                );
                await eliminarDocsProgramadoPorFiltro(programadoId, 'descripcion = ?', [descripcion]);
                await pool.query(
                    `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
                     VALUES (?, 'otro', ?, ?, ?, ?)`,
                    [programadoId, item.nombre_archivo, item.archivo_url || '', item.drive_file_id || null, descripcion]
                );
            }
        }

        for (const item of dc3Generados) {
            const descripcion = descripcionDocumentoInscripcion(
                'dc3',
                item.inscripcion_id,
                item.curso_documento_id,
                usaEmpresasColaboradorasFlag,
                usarDescripcionCurso ? cursoDestinoIdFinal : null
            );
            await eliminarDocsProgramadoPorFiltro(programadoId, 'descripcion = ?', [descripcion]);
            await pool.query(
                `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
                 VALUES (?, 'otro', ?, ?, ?, ?)`,
                [programadoId, item.nombre_archivo, item.archivo_url || '', item.drive_file_id || null, descripcion]
            );
        }

        if (constanciasLoteGenerado?.drive_file_id) {
            const descripcionConstancias = descripcionDoc('constancias_lote_programado');
            await eliminarDocsProgramadoPorFiltro(programadoId, 'descripcion = ?', [descripcionConstancias]);
            await pool.query(
                `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
                 VALUES (?, 'otro', ?, ?, ?, ?)`,
                [
                    programadoId,
                    constanciasLoteGenerado.nombre_archivo,
                    constanciasLoteGenerado.archivo_url || '',
                    constanciasLoteGenerado.drive_file_id,
                    descripcionConstancias
                ]
            );
        }

        if (dc3LotePdfGenerado?.drive_file_id) {
            const descripcionDc3Pdf = descripcionDoc('dc3_lote_pdf_programado');
            await eliminarDocsProgramadoPorFiltro(programadoId, 'descripcion = ?', [descripcionDc3Pdf]);
            await pool.query(
                `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
                 VALUES (?, 'otro', ?, ?, ?, ?)`,
                [
                    programadoId,
                    dc3LotePdfGenerado.nombre_archivo,
                    dc3LotePdfGenerado.archivo_url || '',
                    dc3LotePdfGenerado.drive_file_id,
                    descripcionDc3Pdf
                ]
            );
        }

        if (dc3LoteExcelGenerado?.drive_file_id) {
            const descripcionDc3Excel = descripcionDoc('dc3_lote_excel_programado');
            await eliminarDocsProgramadoPorFiltro(programadoId, 'descripcion = ?', [descripcionDc3Excel]);
            await pool.query(
                `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
                 VALUES (?, 'otro', ?, ?, ?, ?)`,
                [
                    programadoId,
                    dc3LoteExcelGenerado.nombre_archivo,
                    dc3LoteExcelGenerado.archivo_url || '',
                    dc3LoteExcelGenerado.drive_file_id,
                    descripcionDc3Excel
                ]
            );
        }

        // ═══ RESUMEN FINAL ═══
        const duracion = ((Date.now() - inicio) / 1000).toFixed(1);
        const totalExitosos = constanciaExitosos + dc3Exitosos;
        const totalFallidos = constanciaFallidos + dc3Fallidos;

        // Construir mensaje detallado
        let mensaje = '';
        if (generarConstancias && generarDC3) {
            mensaje = `${constanciaExitosos} constancias + ${dc3Exitosos} DC-3 en ${duracion}s`;
        } else if (generarConstancias) {
            mensaje = `${constanciaExitosos} constancias en ${duracion}s`;
        } else {
            mensaje = `${dc3Exitosos} DC-3 en ${duracion}s`;
        }
        if (totalFallidos > 0) mensaje += ` (${totalFallidos} fallaron)`;

        logV2('INFO', `COMPLETADO en ${duracion}s. ${mensaje}`);

        // Carpetas de salida (evitar "undefined/..." cuando solo hay folderId en BD)
        const carpetas = [];
        const basePath = (carpetaResult && carpetaResult.success && carpetaResult.path)
            ? String(carpetaResult.path)
            : '';
        if (generarConstancias) carpetas.push(basePath ? `${basePath}/Constancias` : 'Constancias');
        if (generarDC3) carpetas.push(basePath ? `${basePath}/DC-3` : 'DC-3');

        sendEvent('done', {
            success: totalExitosos > 0,
            message: mensaje,
            exitosos: totalExitosos,
            fallidos: totalFallidos,
            total: participantesConstancias.length,
            constancias: generarConstancias ? { exitosos: constanciaExitosos, fallidos: constanciaFallidos } : null,
            dc3: generarDC3 ? { exitosos: dc3Exitosos, fallidos: dc3Fallidos, error: dc3ErrorDetalle } : null,
            elegibles_dc3: participantesDC3.length,
            duracion,
            carpeta: carpetas.length > 0 ? carpetas.join(' | ') : null,
            constancias_consolidado: constanciasLoteGenerado ? {
                nombre_archivo: constanciasLoteGenerado.nombre_archivo,
                archivo_url: constanciasLoteGenerado.archivo_url
            } : null,
            dc3_consolidado_excel: dc3LoteExcelGenerado ? {
                nombre_archivo: dc3LoteExcelGenerado.nombre_archivo,
                archivo_url: dc3LoteExcelGenerado.archivo_url
            } : null,
            dc3_consolidado_pdf: dc3LotePdfGenerado ? {
                nombre_archivo: dc3LotePdfGenerado.nombre_archivo,
                archivo_url: dc3LotePdfGenerado.archivo_url
            } : null
        });
        res.end();
    } catch (error) {
        logV2('ERROR', `Error fatal generando documentos V2: ${error.message}\n${error.stack}`);
        sendEvent('error', { message: error.message || 'Error interno del servidor' });
        res.end();
    }
});

app.get('/api/cursos-programados/:programadoId/documentos-generados-zip', async (req, res) => {
    try {
        const { programadoId } = req.params;
                const cursoIdParam = Number(req.query.curso_id);
                const descripcionSuffix = Number.isFinite(cursoIdParam) ? `_curso_${cursoIdParam}` : '';
                const descripcionConstancias = `constancias_lote_programado${descripcionSuffix}`;
                const descripcionDc3Excel = `dc3_lote_excel_programado${descripcionSuffix}`;
                const descripcionDc3Pdf = `dc3_lote_pdf_programado${descripcionSuffix}`;

        const [rowsLote] = await pool.query(
            `SELECT descripcion, nombre_archivo, drive_file_id, fecha_subida
             FROM documento_curso_programado
             WHERE programado_id = ?
               AND drive_file_id IS NOT NULL
               AND drive_file_id != ''
                             AND descripcion IN (?, ?, ?)
             ORDER BY fecha_subida DESC`,
                        [programadoId, descripcionConstancias, descripcionDc3Excel, descripcionDc3Pdf]
        );

        const byDescripcion = new Map();
        for (const doc of (Array.isArray(rowsLote) ? rowsLote : [])) {
            if (!byDescripcion.has(doc.descripcion)) {
                byDescripcion.set(doc.descripcion, doc);
            }
        }

        // Compatibilidad: si no existe registro explícito de Excel consolidado,
        // usar el último dc3_inscripcion_* (todos apuntan al mismo archivo consolidado).
        if (!byDescripcion.has(descripcionDc3Excel)) {
            const likeDc3 = descripcionSuffix
                ? `dc3_inscripcion_%${descripcionSuffix}`
                : 'dc3_inscripcion_%';
            const [rowsDc3Fallback] = await pool.query(
                `SELECT descripcion, nombre_archivo, drive_file_id, fecha_subida
                 FROM documento_curso_programado
                 WHERE programado_id = ?
                   AND drive_file_id IS NOT NULL
                   AND drive_file_id != ''
                   AND descripcion LIKE ?
                 ORDER BY fecha_subida DESC
                 LIMIT 1`,
                [programadoId, likeDc3]
            );
            if (Array.isArray(rowsDc3Fallback) && rowsDc3Fallback.length > 0) {
                byDescripcion.set(descripcionDc3Excel, {
                    ...rowsDc3Fallback[0],
                    descripcion: descripcionDc3Excel
                });
            }
        }

        const docsObjetivo = [
            byDescripcion.get(descripcionConstancias),
            byDescripcion.get(descripcionDc3Excel),
            byDescripcion.get(descripcionDc3Pdf)
        ].filter(Boolean);

        if (docsObjetivo.length === 0) {
            return res.status(404).json({
                success: false,
                message: 'No hay archivos consolidados para descargar. Genere documentos nuevamente para crear el ZIP consolidado.'
            });
        }

        const zip = new AdmZip();

        const nombresUsados = new Set();
        const nombreSeguro = (original, fallback) => {
            const base = String(original || fallback || 'documento')
                .replace(/[\\/:*?"<>|]/g, '_')
                .trim();

            if (!nombresUsados.has(base)) {
                nombresUsados.add(base);
                return base;
            }

            const punto = base.lastIndexOf('.');
            const stem = punto > 0 ? base.slice(0, punto) : base;
            const ext = punto > 0 ? base.slice(punto) : '';
            let idx = 2;
            let candidato = `${stem}_${idx}${ext}`;
            while (nombresUsados.has(candidato)) {
                idx += 1;
                candidato = `${stem}_${idx}${ext}`;
            }
            nombresUsados.add(candidato);
            return candidato;
        };

        for (const doc of docsObjetivo) {
            try {
                const buffer = await driveService.descargarArchivo(doc.drive_file_id);
                const folder = String(doc.descripcion || '').startsWith('dc3_') ? 'DC-3' : 'Constancias';
                const fileName = nombreSeguro(doc.nombre_archivo, `${folder}.bin`);
                zip.addFile(`${folder}/${fileName}`, Buffer.from(buffer));
            } catch (e) {
                // silenced
            }
        }

        if (zip.getEntries().length === 0) {
            return res.status(500).json({ success: false, message: 'No se pudieron empaquetar archivos para descarga.' });
        }

        const fecha = new Date().toISOString().slice(0, 10);
        const nombreZip = `Documentos_Consolidados_Curso_${programadoId}_${fecha}.zip`;
        const zipBuffer = zip.toBuffer();

        res.setHeader('Content-Type', 'application/zip');
        res.setHeader('Content-Disposition', `attachment; filename="${nombreZip}"`);
        return res.send(zipBuffer);
    } catch (error) {
        console.error('[ERROR] documentos-generados-zip:', error);
        return res.status(500).json({ success: false, message: error.message || 'No se pudo generar el ZIP.' });
    }
});

/**
 * ZIP de documentos individuales de constancias / DC-3.
 * tipo=constancias → todos los PDF/archivos individuales de constancias (plano)
 * tipo=dc3         → todos los individuales de DC-3 (plano)
 * tipo=ambos       → una carpeta por empleado con su constancia y DC-3
 */
app.get('/api/cursos-programados/:programadoId/documentos-individuales-zip', async (req, res) => {
    try {
        const programadoId = Number(req.params.programadoId);
        const tipoRaw = String(req.query.tipo || '').trim().toLowerCase();
        const cursoIdParam = Number(req.query.curso_id);
        const tipo = ['constancias', 'dc3', 'ambos'].includes(tipoRaw) ? tipoRaw : null;

        if (!Number.isInteger(programadoId) || programadoId <= 0) {
            return res.status(400).json({ success: false, message: 'programadoId inválido' });
        }
        if (!tipo) {
            return res.status(400).json({
                success: false,
                message: 'Parámetro tipo inválido. Use constancias, dc3 o ambos.'
            });
        }

        const descripcionSuffix = Number.isFinite(cursoIdParam) && cursoIdParam > 0
            ? `_curso_${cursoIdParam}`
            : '';

        const likeConstancia = descripcionSuffix
            ? `constancia_inscripcion_%${descripcionSuffix}`
            : 'constancia_inscripcion_%';
        const likeDc3 = descripcionSuffix
            ? `dc3_inscripcion_%${descripcionSuffix}`
            : 'dc3_inscripcion_%';

        const incluirConstancias = tipo === 'constancias' || tipo === 'ambos';
        const incluirDc3 = tipo === 'dc3' || tipo === 'ambos';

        const likes = [];
        if (incluirConstancias) likes.push(likeConstancia);
        if (incluirDc3) likes.push(likeDc3);

        const likeClause = likes.map(() => 'd.descripcion LIKE ?').join(' OR ');
        const [rowsDocs] = await pool.query(
            `SELECT
                d.descripcion,
                d.nombre_archivo,
                d.drive_file_id,
                d.fecha_subida
             FROM documento_curso_programado d
             WHERE d.programado_id = ?
               AND COALESCE(d.activo, 1) = 1
               AND d.drive_file_id IS NOT NULL
               AND d.drive_file_id != ''
               AND (${likeClause})
             ORDER BY d.fecha_subida DESC`,
            [programadoId, ...likes]
        );

        const docs = Array.isArray(rowsDocs) ? rowsDocs : [];
        if (docs.length === 0) {
            return res.status(404).json({
                success: false,
                message: 'No hay documentos individuales para descargar.'
            });
        }

        const parseMeta = (descripcion) => {
            const m = String(descripcion || '').match(/^(constancia|dc3)_inscripcion_(\d+)(?:_curso_(\d+))?$/i);
            if (!m) return null;
            return {
                tipoDoc: m[1].toLowerCase() === 'dc3' ? 'dc3' : 'constancia',
                inscripcionId: Number(m[2]),
                cursoDocId: m[3] ? Number(m[3]) : null
            };
        };

        const inscripcionIds = new Set();
        for (const row of docs) {
            const meta = parseMeta(row.descripcion);
            if (!meta) continue;
            if (descripcionSuffix && meta.cursoDocId !== cursoIdParam) continue;
            inscripcionIds.add(meta.inscripcionId);
        }

        /** @type {Map<number, string>} */
        const nombresPorInscripcion = new Map();
        if (inscripcionIds.size > 0) {
            const ids = Array.from(inscripcionIds);
            const [rowsEmp] = await pool.query(
                `SELECT
                    ic.inscripcion_id,
                    CONCAT_WS(' ',
                        NULLIF(TRIM(e.apellido_paterno), ''),
                        NULLIF(TRIM(e.apellido_materno), ''),
                        NULLIF(TRIM(e.nombre), '')
                    ) AS empleado_nombre
                 FROM inscripcion_curso ic
                 JOIN empleado e ON e.empleado_id = ic.empleado_id
                 WHERE ic.programado_id = ?
                   AND ic.inscripcion_id IN (?)`,
                [programadoId, ids]
            );
            for (const r of (Array.isArray(rowsEmp) ? rowsEmp : [])) {
                const nombre = String(r.empleado_nombre || '').trim();
                if (nombre) {
                    nombresPorInscripcion.set(Number(r.inscripcion_id), nombre);
                }
            }
        }

        const nombreZipSeguro = (original, fallback, usados) => {
            const base = String(original || fallback || 'documento')
                .replace(/[\\/:*?"<>|]/g, '_')
                .trim() || fallback || 'documento';
            if (!usados.has(base)) {
                usados.add(base);
                return base;
            }
            const punto = base.lastIndexOf('.');
            const stem = punto > 0 ? base.slice(0, punto) : base;
            const ext = punto > 0 ? base.slice(punto) : '';
            let idx = 2;
            let candidato = `${stem}_${idx}${ext}`;
            while (usados.has(candidato)) {
                idx += 1;
                candidato = `${stem}_${idx}${ext}`;
            }
            usados.add(candidato);
            return candidato;
        };

        const esPdf = (nombre) => /\.pdf$/i.test(String(nombre || ''));
        const preferirDoc = (actual, candidato) => {
            if (!actual) return candidato;
            const actualPdf = esPdf(actual.nombre_archivo);
            const candidatoPdf = esPdf(candidato.nombre_archivo);
            if (candidatoPdf && !actualPdf) return candidato;
            return actual;
        };

        /** @type {Map<number, { inscripcionId: number, empleadoNombre: string, constancia: any, dc3: any }>} */
        const porInscripcion = new Map();

        for (const row of docs) {
            const meta = parseMeta(row.descripcion);
            if (!meta) continue;

            if (descripcionSuffix && meta.cursoDocId !== cursoIdParam) continue;

            const key = meta.inscripcionId;
            if (!porInscripcion.has(key)) {
                porInscripcion.set(key, {
                    inscripcionId: key,
                    empleadoNombre: nombresPorInscripcion.get(key) || `inscripcion_${key}`,
                    constancia: null,
                    dc3: null
                });
            }
            const entry = porInscripcion.get(key);

            if (meta.tipoDoc === 'constancia' && incluirConstancias) {
                entry.constancia = preferirDoc(entry.constancia, row);
            }
            if (meta.tipoDoc === 'dc3' && incluirDc3) {
                entry.dc3 = preferirDoc(entry.dc3, row);
            }
        }

        const entradas = Array.from(porInscripcion.values()).filter((e) => {
            if (tipo === 'constancias') return !!e.constancia?.drive_file_id;
            if (tipo === 'dc3') return !!e.dc3?.drive_file_id;
            return !!(e.constancia?.drive_file_id || e.dc3?.drive_file_id);
        });

        if (entradas.length === 0) {
            return res.status(404).json({
                success: false,
                message: 'No hay documentos individuales para descargar.'
            });
        }

        const zip = new AdmZip();
        const nombresUsados = new Set();
        const carpetasUsadas = new Set();

        const descargarYAgregar = async (driveFileId, rutaZip) => {
            const buffer = await driveService.descargarArchivo(driveFileId);
            zip.addFile(rutaZip, Buffer.from(buffer));
        };

        const tareas = [];
        for (const entry of entradas) {
            if (tipo === 'ambos') {
                let carpetaBase = sanitizarSegmentoNombre(entry.empleadoNombre, `inscripcion_${entry.inscripcionId}`);
                let carpeta = carpetaBase;
                let idxCarpeta = 2;
                while (carpetasUsadas.has(carpeta.toLowerCase())) {
                    carpeta = `${carpetaBase}_${idxCarpeta}`;
                    idxCarpeta += 1;
                }
                carpetasUsadas.add(carpeta.toLowerCase());

                const nombresEnCarpeta = new Set();
                if (entry.constancia?.drive_file_id) {
                    const fileName = nombreZipSeguro(
                        entry.constancia.nombre_archivo,
                        `Constancia_${entry.inscripcionId}.pdf`,
                        nombresEnCarpeta
                    );
                    tareas.push(() => descargarYAgregar(entry.constancia.drive_file_id, `${carpeta}/${fileName}`));
                }
                if (entry.dc3?.drive_file_id) {
                    const fileName = nombreZipSeguro(
                        entry.dc3.nombre_archivo,
                        `DC-3_${entry.inscripcionId}.pdf`,
                        nombresEnCarpeta
                    );
                    tareas.push(() => descargarYAgregar(entry.dc3.drive_file_id, `${carpeta}/${fileName}`));
                }
            } else if (tipo === 'constancias' && entry.constancia?.drive_file_id) {
                const fileName = nombreZipSeguro(
                    entry.constancia.nombre_archivo,
                    `Constancia_${entry.inscripcionId}.pdf`,
                    nombresUsados
                );
                tareas.push(() => descargarYAgregar(entry.constancia.drive_file_id, fileName));
            } else if (tipo === 'dc3' && entry.dc3?.drive_file_id) {
                const fileName = nombreZipSeguro(
                    entry.dc3.nombre_archivo,
                    `DC-3_${entry.inscripcionId}.pdf`,
                    nombresUsados
                );
                tareas.push(() => descargarYAgregar(entry.dc3.drive_file_id, fileName));
            }
        }

        const concurrency = 4;
        for (let i = 0; i < tareas.length; i += concurrency) {
            const lote = tareas.slice(i, i + concurrency);
            await Promise.all(lote.map(async (fn) => {
                try {
                    await fn();
                } catch (e) {
                    // Continuar con el resto si un archivo falla
                }
            }));
        }

        if (zip.getEntries().length === 0) {
            return res.status(500).json({
                success: false,
                message: 'No se pudieron empaquetar archivos para descarga.'
            });
        }

        const fecha = new Date().toISOString().slice(0, 10);
        const nombrePorTipo = {
            constancias: `Constancias_Individuales_Curso_${programadoId}_${fecha}.zip`,
            dc3: `DC3_Individuales_Curso_${programadoId}_${fecha}.zip`,
            ambos: `DC3_y_Constancias_Por_Empleado_Curso_${programadoId}_${fecha}.zip`
        };
        const nombreZip = nombrePorTipo[tipo];
        const zipBuffer = zip.toBuffer();

        res.setHeader('Content-Type', 'application/zip');
        res.setHeader('Content-Disposition', `attachment; filename="${nombreZip}"`);
        return res.send(zipBuffer);
    } catch (error) {
        console.error('[ERROR] documentos-individuales-zip:', error);
        return res.status(500).json({
            success: false,
            message: error.message || 'No se pudo generar el ZIP.'
        });
    }
});

app.get('/api/cursos-programados/:programadoId/constancias-combinadas-pdf', async (req, res) => {
    try {
        const { programadoId } = req.params;
        const cursoIdParam = Number(req.query.curso_id);
        const descripcionSuffix = Number.isFinite(cursoIdParam) ? `_curso_${cursoIdParam}` : '';
        const descripcionLote = descripcionSuffix
            ? `constancias_lote_programado${descripcionSuffix}`
            : 'constancias_lote_programado';
        const descripcionLike = descripcionSuffix
            ? `constancia_inscripcion_%${descripcionSuffix}`
            : 'constancia_inscripcion_%';
        const [rows] = await pool.query(
            `SELECT nombre_archivo, drive_file_id
             FROM documento_curso_programado
                         WHERE programado_id = ?
                             AND descripcion = ?
               AND drive_file_id IS NOT NULL
               AND drive_file_id != ''
             ORDER BY fecha_subida DESC
             LIMIT 1`,
                        [programadoId, descripcionLote]
        );

        const doc = Array.isArray(rows) && rows.length > 0 ? rows[0] : null;

        // Caso 1: ya existe el PDF consolidado en Drive
        if (doc?.drive_file_id) {
            const fileBuffer = await driveService.descargarArchivo(doc.drive_file_id);
            const nombreArchivo = (doc.nombre_archivo || `Constancias_Curso_${programadoId}.pdf`).replace(/[\r\n"]/g, '_');

            res.setHeader('Content-Type', 'application/pdf');
            res.setHeader('Content-Disposition', `attachment; filename="${nombreArchivo}"`);
            return res.send(fileBuffer);
        }

        // Caso 2 (fallback): no existe consolidado guardado, combinar constancias individuales
        const [rowsConstancias] = await pool.query(
            `SELECT descripcion, nombre_archivo, drive_file_id, fecha_subida
             FROM documento_curso_programado
                         WHERE programado_id = ?
                             AND descripcion LIKE ?
               AND COALESCE(activo, 1) = 1
               AND drive_file_id IS NOT NULL
               AND drive_file_id != ''
             ORDER BY fecha_subida DESC`,
                        [programadoId, descripcionLike]
        );

        const docs = Array.isArray(rowsConstancias) ? rowsConstancias : [];
        if (docs.length === 0) {
            return res.status(404).json({
                success: false,
                message: 'No se encontraron constancias para generar el PDF consolidado.'
            });
        }

        // Deduplicar por descripción (quedarse con la más reciente)
        const dedupPorDescripcion = new Map();
        for (const item of docs) {
            if (!dedupPorDescripcion.has(item.descripcion)) {
                dedupPorDescripcion.set(item.descripcion, item);
            }
        }
        const unicos = Array.from(dedupPorDescripcion.values())
            .sort((a, b) => String(a.descripcion || '').localeCompare(String(b.descripcion || '')));

        const buffers = [];
        for (const item of unicos) {
            try {
                const pdfBuffer = await driveService.descargarArchivo(item.drive_file_id);
                if (pdfBuffer?.length) {
                    buffers.push(pdfBuffer);
                }
            } catch (e) {
                // Silenciar una constancia fallida y continuar con el resto
            }
        }

        if (buffers.length === 0) {
            return res.status(500).json({
                success: false,
                message: 'No se pudieron descargar constancias para combinar.'
            });
        }

        const bufferLote = await combinarPdfs(buffers);

        // Intentar guardar el consolidado para usos posteriores
        let nombreArchivo = `Constancias_Curso_${programadoId}.pdf`;
        try {
            const [cursoRows] = await pool.query(
                `SELECT nombre_empresa, nombre_curso, fecha_inicio
                 FROM v_cursos_programados
                 WHERE programado_id = ?
                 LIMIT 1`,
                [programadoId]
            );

            const cursoInfo = Array.isArray(cursoRows) && cursoRows.length > 0 ? cursoRows[0] : null;
            if (cursoInfo) {
                nombreArchivo = construirNombreDocProgramado({
                    nombreEmpresa: cursoInfo.nombre_empresa || 'empresa',
                    nombreCurso: cursoInfo.nombre_curso || 'curso',
                    fechaInicio: cursoInfo.fecha_inicio || new Date(),
                    tipoBase: 'constancias_consolidado',
                    extension: 'pdf'
                });
            }

            const carpetaResult = await resolverCarpetaCursoProgramado(programadoId);
            const carpetaCursoId = carpetaResult.success ? carpetaResult.folderId : driveService.ROOT_FOLDER_ID;
            const carpetaConstanciasId = await driveService.obtenerOCrearCarpeta('Constancias', carpetaCursoId);

            const fileSubido = await driveService.uploadFileFast(
                bufferLote,
                nombreArchivo,
                'application/pdf',
                carpetaConstanciasId
            );

            if (fileSubido?.id) {
                await eliminarDocsProgramadoPorFiltro(programadoId, 'descripcion = ?', [descripcionLote]);
                await pool.query(
                    `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
                     VALUES (?, 'otro', ?, ?, ?, ?)`,
                    [
                        programadoId,
                        nombreArchivo,
                        fileSubido?.webViewLink || '',
                        fileSubido.id,
                        descripcionLote
                    ]
                );
            }
        } catch (persistErr) {
            // No bloquear la descarga si falla persistencia
            console.warn('[WARN] constancias-combinadas-pdf: no se pudo persistir consolidado:', persistErr.message);
        }

        nombreArchivo = String(nombreArchivo || `Constancias_Curso_${programadoId}.pdf`).replace(/[\r\n"]/g, '_');
        res.setHeader('Content-Type', 'application/pdf');
        res.setHeader('Content-Disposition', `attachment; filename="${nombreArchivo}"`);
        return res.send(bufferLote);
    } catch (error) {
        console.error('[ERROR] constancias-combinadas-pdf:', error);
        return res.status(500).json({
            success: false,
            message: error.message || 'No se pudo descargar el PDF consolidado de constancias.'
        });
    }
});

app.post('/api/cursos-programados/:programadoId/registrar-descarga-constancias-dc3', async (req, res) => {
    try {
        const programadoId = Number(req.params.programadoId || 0);
        if (!programadoId) {
            return res.status(400).json({ success: false, message: 'programado_id inválido' });
        }

        await asegurarColumnasHistorialDescargasCursoProgramado(pool);

        const nombreUsuario = obtenerNombreUsuarioAccion(req);
        const fechaMexico = obtenerFechaHoraMexicoMySQL(new Date());

        const [result] = await pool.query(
            `UPDATE curso_programado
             SET ultima_descarga_constancias_por = ?,
                 ultima_descarga_constancias_fecha = ?
             WHERE programado_id = ?`,
            [nombreUsuario, fechaMexico, programadoId]
        );

        if (!result?.affectedRows) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
        }

        return res.json({
            success: true,
            message: 'Historial de descarga registrado correctamente',
            data: {
                programado_id: programadoId,
                ultima_descarga_constancias_por: nombreUsuario,
                ultima_descarga_constancias_fecha: fechaMexico
            }
        });
    } catch (error) {
        console.error('[ERROR] registrar-descarga-constancias-dc3:', error);
        return res.status(500).json({
            success: false,
            message: error.message || 'No se pudo registrar la descarga de constancias/DC-3.'
        });
    }
});

app.get('/api/cursos-programados/:programadoId/dc3-combinados-pdf', async (req, res) => {
    try {
        const { programadoId } = req.params;
                const cursoIdParam = Number(req.query.curso_id);
                const descripcionSuffix = Number.isFinite(cursoIdParam) ? `_curso_${cursoIdParam}` : '';
                const descripcionPdf = `dc3_lote_pdf_programado${descripcionSuffix}`;
                const descripcionExcel = `dc3_lote_excel_programado${descripcionSuffix}`;
                const descripcionLike = descripcionSuffix ? `dc3_inscripcion_%${descripcionSuffix}` : 'dc3_inscripcion_%';

        const [rowsPdf] = await pool.query(
            `SELECT nombre_archivo, drive_file_id
             FROM documento_curso_programado
             WHERE programado_id = ?
                             AND descripcion = ?
               AND drive_file_id IS NOT NULL
               AND drive_file_id != ''
             ORDER BY fecha_subida DESC
             LIMIT 1`,
                        [programadoId, descripcionPdf]
        );

        const pdfExistente = Array.isArray(rowsPdf) && rowsPdf.length > 0 ? rowsPdf[0] : null;
        if (pdfExistente?.drive_file_id) {
            const fileBuffer = await driveService.descargarArchivo(pdfExistente.drive_file_id);
            const nombreArchivo = (pdfExistente.nombre_archivo || `DC3_Consolidado_Curso_${programadoId}.pdf`).replace(/[\r\n"]/g, '_');

            res.setHeader('Content-Type', 'application/pdf');
            res.setHeader('Content-Disposition', `attachment; filename="${nombreArchivo}"`);
            return res.send(fileBuffer);
        }

        const [rowsExcel] = await pool.query(
            `SELECT nombre_archivo, drive_file_id
             FROM documento_curso_programado
             WHERE programado_id = ?
               AND descripcion IN ('dc3_lote_excel_programado')
               AND drive_file_id IS NOT NULL
               AND drive_file_id != ''
             ORDER BY fecha_subida DESC
             LIMIT 1`,
            [programadoId]
        );

        let excelConsolidado = Array.isArray(rowsExcel) && rowsExcel.length > 0 ? rowsExcel[0] : null;

        if (!excelConsolidado?.drive_file_id) {
            const [rowsDc3Fallback] = await pool.query(
                `SELECT nombre_archivo, drive_file_id
                 FROM documento_curso_programado
                 WHERE programado_id = ?
                   AND descripcion LIKE 'dc3_inscripcion_%'
                   AND drive_file_id IS NOT NULL
                   AND drive_file_id != ''
                 ORDER BY fecha_subida DESC
                 LIMIT 1`,
                [programadoId]
            );
            excelConsolidado = Array.isArray(rowsDc3Fallback) && rowsDc3Fallback.length > 0 ? rowsDc3Fallback[0] : null;
        }

        if (!excelConsolidado?.drive_file_id) {
            return res.status(404).json({
                success: false,
                message: 'No se encontró el DC-3 consolidado. Genere documentos nuevamente para obtener el PDF unificado.'
            });
        }

        const pdfBuffer = await driveService.exportarArchivoPDF(excelConsolidado.drive_file_id, { landscape: false });
        if (!pdfBuffer?.length) {
            return res.status(500).json({
                success: false,
                message: 'No se pudo exportar el DC-3 consolidado a PDF.'
            });
        }

        let nombreArchivo = `DC3_Consolidado_Curso_${programadoId}.pdf`;
        try {
            const [cursoRows] = await pool.query(
                `SELECT nombre_empresa, nombre_curso, fecha_inicio
                 FROM v_cursos_programados
                 WHERE programado_id = ?
                 LIMIT 1`,
                [programadoId]
            );

            const cursoInfo = Array.isArray(cursoRows) && cursoRows.length > 0 ? cursoRows[0] : null;
            if (cursoInfo) {
                nombreArchivo = construirNombreDocProgramado({
                    nombreEmpresa: cursoInfo.nombre_empresa || 'empresa',
                    nombreCurso: `${cursoInfo.nombre_curso || 'curso'}_DC3_CONSOLIDADO`,
                    fechaInicio: cursoInfo.fecha_inicio || new Date(),
                    tipoBase: 'dc3_consolidado',
                    extension: 'pdf'
                });
            }

            const carpetaResult = await resolverCarpetaCursoProgramado(programadoId);
            const carpetaCursoId = carpetaResult.success ? carpetaResult.folderId : driveService.ROOT_FOLDER_ID;
            const carpetaDC3Id = await driveService.obtenerOCrearCarpeta('DC-3', carpetaCursoId);

            const fileSubido = await driveService.uploadFileFast(
                Buffer.from(pdfBuffer),
                nombreArchivo,
                'application/pdf',
                carpetaDC3Id
            );

            if (fileSubido?.id) {
                await eliminarDocsProgramadoPorFiltro(programadoId, 'descripcion = ?', ['dc3_lote_pdf_programado']);
                await pool.query(
                    `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
                     VALUES (?, 'otro', ?, ?, ?, 'dc3_lote_pdf_programado')`,
                    [
                        programadoId,
                        nombreArchivo,
                        fileSubido?.webViewLink || '',
                        fileSubido.id
                    ]
                );
            }
        } catch (persistErr) {
            console.warn('[WARN] dc3-combinados-pdf: no se pudo persistir consolidado:', persistErr.message);
        }

        nombreArchivo = String(nombreArchivo || `DC3_Consolidado_Curso_${programadoId}.pdf`).replace(/[\r\n"]/g, '_');
        res.setHeader('Content-Type', 'application/pdf');
        res.setHeader('Content-Disposition', `attachment; filename="${nombreArchivo}"`);
        return res.send(Buffer.from(pdfBuffer));
    } catch (error) {
        console.error('[ERROR] dc3-combinados-pdf:', error);
        return res.status(500).json({
            success: false,
            message: error.message || 'No se pudo descargar el PDF consolidado de DC-3.'
        });
    }
});

