// Limpiar constancias/DC-3 de un curso del programado (BD + Drive)
app.delete('/api/cursos-programados/:programadoId/constancias-dc3', requireAdmin, async (req, res) => {
    try {
        const programadoId = Number(req.params.programadoId);
        const cursoCatalogoId = Number(req.body?.curso_catalogo_id ?? req.query?.curso_catalogo_id);
        const modoRaw = String(req.body?.modo || req.query?.modo || 'curso').trim().toLowerCase();
        const modo = modoRaw === 'huerfanos' ? 'huerfanos' : 'curso';

        if (!Number.isInteger(programadoId) || programadoId <= 0) {
            return res.status(400).json({ success: false, message: 'programadoId inválido' });
        }
        if (!Number.isInteger(cursoCatalogoId) || cursoCatalogoId <= 0) {
            return res.status(400).json({ success: false, message: 'curso_catalogo_id inválido' });
        }

        const resultado = await limpiarConstanciasDc3Programado(programadoId, cursoCatalogoId, modo);
        return res.json({
            success: true,
            message: modo === 'huerfanos'
                ? 'Registros huérfanos eliminados correctamente'
                : 'Constancias y DC-3 eliminados correctamente',
            resultado
        });
    } catch (error) {
        console.error('[ERROR] limpiar constancias-dc3:', error);
        const status = Number(error.statusCode) || 500;
        return res.status(status).json({
            success: false,
            message: error.message || 'No se pudo limpiar constancias y DC-3 del curso seleccionado.'
        });
    }
});

