// =====================================================
// GENERAR INFORME FOTOGRÁFICO (Google Slides → PDF)
// =====================================================
app.post('/api/cursos-programados/:programadoId/generar-informe-fotografico', async (req, res) => {
    try {
        const { programadoId } = req.params;
        const templateId = String(process.env.GOOGLE_SLIDES_INFORME_FOTO_TEMPLATE_ID || '1kdYycWWSORz9KubyZF1atrO1-rpxcFEA').trim();
        if (!templateId) {
            return res.status(500).json({ success: false, message: 'No se ha configurado GOOGLE_SLIDES_INFORME_FOTO_TEMPLATE_ID en el servidor.' });
        }

        // 1. Obtener datos del curso
        const [cursoRows] = await pool.query(
            `SELECT cp.programado_id, cp.fecha_inicio, cp.fecha_fin, c.nombre_curso, e.nombre_empresa, e.logo AS empresa_logo
             FROM curso_programado cp
             JOIN curso c ON cp.curso_id = c.curso_id
             JOIN empresa e ON cp.empresa_id = e.empresa_id
             WHERE cp.programado_id = ?
             LIMIT 1`,
            [programadoId]
        );

        if (!cursoRows.length) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado.' });
        }

        const cursoInfo = cursoRows[0];

        // 2. Obtener fotos de evidencia
        const [fotos] = await pool.query(
            `SELECT drive_file_id FROM documento_curso_programado
             WHERE programado_id = ? AND descripcion = 'foto_evidencia' AND drive_file_id IS NOT NULL
             ORDER BY fecha_subida ASC`,
            [programadoId]
        );

        if (!fotos.length) {
            return res.status(400).json({ success: false, message: 'No hay fotos de evidencia subidas para este curso. Sube fotos en el paso de Evidencias primero.' });
        }

        // Convertir drive_file_ids a URLs accesibles por Google Slides API
        const fotoUrls = fotos.map(f => `https://lh3.googleusercontent.com/d/${f.drive_file_id}`);

        // 3. Obtener logo de empresa
        let logoUrl = null;
        const logoRaw = (cursoInfo.empresa_logo || '').trim();
        if (logoRaw) {
            const raw = String(logoRaw).trim();
            let logoDriveId = null;
            if (/^[a-zA-Z0-9_-]{10,}$/.test(raw)) logoDriveId = raw;
            else {
                const m = raw.match(/[?&]id=([a-zA-Z0-9_-]+)/) || raw.match(/\/d\/([a-zA-Z0-9_-]+)/) || raw.match(/googleusercontent\.com\/d\/([a-zA-Z0-9_-]+)/);
                if (m) logoDriveId = m[1];
            }
            if (logoDriveId) {
                logoUrl = `https://lh3.googleusercontent.com/d/${logoDriveId}`;
            }
        }

        // 4. Construir texto de información
        const mesesEs = ['Enero', 'Febrero', 'Marzo', 'Abril', 'Mayo', 'Junio', 'Julio', 'Agosto', 'Septiembre', 'Octubre', 'Noviembre', 'Diciembre'];
        const fechaInicio = new Date(cursoInfo.fecha_inicio);
        const fechaStr = !isNaN(fechaInicio.getTime())
            ? `${fechaInicio.getDate()} ${mesesEs[fechaInicio.getMonth()]} ${fechaInicio.getFullYear()}`
            : '';
        const infoText = `${cursoInfo.nombre_curso.toUpperCase()}\n${fechaStr}`;

        // 5. Resolver carpeta de Drive
        const carpetaResult = await resolverCarpetaCursoProgramado(programadoId);
        if (!carpetaResult.success) {
            return res.status(500).json({ success: false, message: 'No se pudo resolver carpeta en Drive.' });
        }

        const informeFolderId = await driveService.obtenerOCrearCarpeta('Informe_Final', carpetaResult.folderId);

        // 6. Generar nombre de archivo
        const nombreArchivo = construirNombreDocProgramado({
            nombreEmpresa: cursoInfo.nombre_empresa,
            nombreCurso: cursoInfo.nombre_curso,
            fechaInicio: cursoInfo.fecha_inicio,
            tipoBase: 'informe_fotografico',
            extension: '' // Sin extensión, es presentación de Google Slides
        }).replace(/\.$/, ''); // Quitar punto final si quedó

        // 7. Generar el informe fotográfico
        console.log(`[INFO] Generando Informe Fotográfico: ${fotoUrls.length} fotos, logo: ${logoUrl ? 'sí' : 'no'}`);
        const resultado = await driveService.generarInformeFotograficoSlides(
            templateId, fotoUrls, logoUrl, infoText, nombreArchivo, informeFolderId
        );

        if (!resultado.success) {
            return res.status(500).json({ success: false, message: resultado.error || 'Error al generar el informe fotográfico.' });
        }

        // 8. Registrar en BD (eliminar previo si existe)
        await eliminarDocsProgramadoPorFiltro(programadoId, 'descripcion = ?', ['informe_fotografico']);
        await pool.query(
            `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
             VALUES (?, 'informe_fotografico', ?, ?, ?, 'informe_fotografico')`,
            [programadoId, nombreArchivo, resultado.webViewLink || '', resultado.fileId || null]
        );

        let archivoPdf = null;
        try {
            archivoPdf = await asegurarInformeFotograficoPdfOficial(programadoId, {
                force: true,
                slidesDriveFileId: resultado.fileId
            });
        } catch (pdfErr) {
            console.warn('[WARN] Informe fotográfico generado, pero no se pudo crear PDF oficial:', pdfErr.message);
        }

        return res.json({
            success: true,
            message: 'Informe fotográfico generado exitosamente.',
            archivo: {
                nombre: nombreArchivo,
                drive_file_id: resultado.fileId,
                url: resultado.webViewLink,
                carpeta: `${carpetaResult.path || ''}/Informe_Final`
            },
            archivo_pdf: archivoPdf
        });
    } catch (error) {
        console.error('[ERROR] generar-informe-fotografico:', error);
        return res.status(500).json({ success: false, message: error.message || 'No se pudo generar el informe fotográfico.' });
    }
});

