// Limpiar calificaciones de todos los participantes al eliminar un documento de examen
app.post('/api/cursos-programados/:programadoId/limpiar-calificaciones', async (req, res) => {
    try {
        const { programadoId } = req.params;
        const { tipo } = req.body; // 'diagnostico' | 'evaluacion'

        if (!['diagnostico', 'evaluacion'].includes(tipo)) {
            return res.status(400).json({ success: false, message: 'tipo debe ser diagnostico o evaluacion' });
        }

        const [exists] = await pool.query(
            'SELECT programado_id FROM curso_programado WHERE programado_id = ?',
            [programadoId]
        );
        if (exists.length === 0) {
            return res.status(404).json({ success: false, message: 'Curso no encontrado' });
        }

        let updateQuery;
        if (tipo === 'diagnostico') {
            updateQuery = 'UPDATE inscripcion_curso SET calificacion_diagnostica = NULL, updated_at = NOW() WHERE programado_id = ? AND activo = 1';
        } else {
            updateQuery = 'UPDATE inscripcion_curso SET calificacion_teorica = NULL, calificacion_practica = NULL, updated_at = NOW() WHERE programado_id = ? AND activo = 1';
        }

        const [result] = await pool.query(updateQuery, [programadoId]);
        res.json({ success: true, message: 'Calificaciones limpiadas', afectados: result.affectedRows });
    } catch (error) {
        console.error('[ERROR] Error limpiando calificaciones:', error);
        handleError(res, error);
    }
});

// Actualizar estatus de un curso programado (ej. 'completado')
app.patch('/api/cursos-programados/:programadoId/estatus', async (req, res) => {
    try {
        const { programadoId } = req.params;
        const { estatus } = req.body;

        const estatusPermitidos = ['programado', 'en_curso', 'completado', 'cancelado', 'pospuesto'];
        if (!estatus || !estatusPermitidos.includes(estatus)) {
            return res.json({ success: false, message: `Estatus inválido. Valores permitidos: ${estatusPermitidos.join(', ')}` });
        }

        const [prevRows] = await pool.query(
            'SELECT estatus FROM curso_programado WHERE programado_id = ? LIMIT 1',
            [programadoId]
        );
        if (!prevRows.length) {
            return res.json({ success: false, message: 'Curso programado no encontrado' });
        }
        const estatusAnterior = String(prevRows[0].estatus || '').toLowerCase();
        const pasaACompletado = estatus === 'completado' && estatusAnterior !== 'completado';

        let result;
        if (estatus === 'completado') {
            [result] = await pool.query(
                `UPDATE curso_programado
                 SET estatus = ?,
                     historial_finalizado_at = NOW(),
                     updated_at = NOW()
                 WHERE programado_id = ?`,
                [estatus, programadoId]
            );
        } else {
            [result] = await pool.query(
                'UPDATE curso_programado SET estatus = ?, updated_at = NOW() WHERE programado_id = ?',
                [estatus, programadoId]
            );
        }

        if (result.affectedRows === 0) {
            return res.json({ success: false, message: 'Curso programado no encontrado' });
        }

        let cursosTomadosResumen = null;
        let informeFinalPdfActualizado = null;
        if (estatus === 'completado') {
            try {
                cursosTomadosResumen = await actualizarCursosTomadosAlFinalizar(programadoId);
            } catch (cursosError) {
                console.error('[ERROR] Error actualizando cursos_tomados al finalizar:', cursosError.message);
            }

            try {
                informeFinalPdfActualizado = await regenerarInformeFinalPdfOficialDesdeSheet(programadoId, {});
            } catch (informePdfErr) {
                console.warn('[WARN] No se pudo actualizar automáticamente el PDF oficial del Informe Final al completar curso:', informePdfErr?.message || informePdfErr);
            }

            if (pasaACompletado) {
                // Fire-and-forget: avisa a administradores
                notificarUsuariosCursoFinalizado(programadoId).catch(() => {});
            }
        }

        res.json({
            success: true,
            message: `Estatus actualizado a '${estatus}'`,
            programadoId,
            estatus,
            cursosTomados: cursosTomadosResumen,
            informeFinalPdfActualizado
        });
    } catch (error) {
        console.error('[ERROR] Error actualizando estatus:', error);
        handleError(res, error);
    }
});

