// Subir examen resuelto (PDF global) a la carpeta de capacitación en Drive
app.post('/api/cursos-programados/:programadoId/subir-examen-resuelto', (req, res) => {
    uploadExamenResuelto.single('archivo')(req, res, async (uploadErr) => {
        const inicio = Date.now();
        let tempPath = null;

        try {
            if (uploadErr) {
                console.error('[ERROR] Upload examen (multer):', uploadErr.message);
                const maxMb = Math.round(MAX_EXAMEN_RESUELTO_BYTES / (1024 * 1024));
                const message = uploadErr.code === 'LIMIT_FILE_SIZE'
                    ? `El archivo supera el tamaño máximo permitido (${maxMb} MB). Comprima el PDF o reduzca la resolución del escaneo.`
                    : (uploadErr.message || 'Error al cargar archivo');
                return res.status(400).json({ success: false, message });
            }

            const { programadoId } = req.params;
            const tipoExamen = req.body.tipo_examen === 'final' ? 'final' : 'diagnostico';

            if (!req.file) {
                return res.status(400).json({ success: false, message: 'No se proporcionó archivo PDF' });
            }

            tempPath = req.file.path;

            // Obtener datos del curso programado
            const [cursoRows] = await pool.query(`
                SELECT cp.programado_id, cp.fecha_inicio, c.nombre_curso, e.nombre_empresa
                FROM curso_programado cp
                JOIN curso c ON cp.curso_id = c.curso_id
                JOIN empresa e ON cp.empresa_id = e.empresa_id
                WHERE cp.programado_id = ?
            `, [programadoId]);

            if (cursoRows.length === 0) {
                return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
            }

            const curso = cursoRows[0];
            const prefijo = tipoExamen === 'final' ? 'evaluacion_resuelta' : 'examen_resuelto';
            const extension = (req.file.originalname?.split('.').pop() || 'pdf').toLowerCase();
            const nombreArchivo = construirNombreDocProgramado({
                nombreEmpresa: curso.nombre_empresa,
                nombreCurso: curso.nombre_curso,
                fechaInicio: curso.fecha_inicio,
                tipoBase: prefijo,
                extension
            });

            // Obtener/crear carpeta de capacitación en Drive
            const carpetaResult = await resolverCarpetaCursoProgramado(programadoId);

            if (!carpetaResult.success) {
                return res.status(500).json({ success: false, message: 'Error creando carpeta en Drive' });
            }

            // Subir archivo a subcarpeta por tipo (stream desde disco temporal)
            const subcarpetaTipo = tipoExamen === 'final' ? 'Evaluaciones_Finales' : 'Examenes_Diagnostico';
            const examenesFolderId = await driveService.obtenerOCrearCarpeta(subcarpetaTipo, carpetaResult.folderId);
            const fileStream = fs.createReadStream(tempPath);
            const driveFile = await driveService.subirArchivo(
                fileStream,
                nombreArchivo,
                req.file.mimetype || 'application/pdf',
                examenesFolderId
            );


            // Persistir en documento_curso_programado para que el estado se mantenga al recargar
            const tipoDoc = tipoExamen === 'final' ? 'evaluacion_resuelta' : 'examen_resuelto';
            let documentoProgId = null;
            try {
                await eliminarDocsProgramadoPorFiltro(
                    programadoId,
                    'descripcion = ?',
                    [tipoDoc]
                );
                const [insertResult] = await pool.query(
                    `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
                     VALUES (?, 'otro', ?, ?, ?, ?)`,
                    [programadoId, nombreArchivo, driveFile.webViewLink || '', driveFile.id || null, tipoDoc]
                );
                documentoProgId = insertResult?.insertId || null;
            } catch (dbErr) {
                // silenced
            }

            return res.json({
                success: true,
                message: `${prefijo} subido exitosamente`,
                archivo: {
                    id: documentoProgId,
                    documento_prog_id: documentoProgId,
                    nombre: nombreArchivo,
                    drive_file_id: driveFile.id,
                    url: driveFile.webViewLink,
                    carpeta: `${carpetaResult.path}/${subcarpetaTipo}`
                }
            });
        } catch (error) {
            console.error('[ERROR] Error subiendo examen resuelto:', error);
            return handleError(res, error);
        } finally {
            if (tempPath) {
                fs.promises.unlink(tempPath).catch(() => { });
            }
        }
    });
});

// Subir fotos de evidencia (múltiples imágenes) a la carpeta de capacitación en Drive
app.post('/api/cursos-programados/:programadoId/subir-fotos-evidencia', uploadFotosEvidencia.array('fotos', 20), async (req, res) => {
    try {
        const { programadoId } = req.params;
        const maxFotosEvidencia = 20;

        if (!req.files || req.files.length === 0) {
            return res.status(400).json({ success: false, message: 'No se proporcionaron fotos' });
        }

        // Obtener datos del curso programado
        const [cursoRows] = await pool.query(`
            SELECT cp.programado_id, cp.fecha_inicio, c.nombre_curso, e.nombre_empresa
            FROM curso_programado cp
            JOIN curso c ON cp.curso_id = c.curso_id
            JOIN empresa e ON cp.empresa_id = e.empresa_id
            WHERE cp.programado_id = ?
        `, [programadoId]);

        if (cursoRows.length === 0) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
        }

        const curso = cursoRows[0];

        // Obtener/crear carpeta de capacitación en Drive
        const carpetaResult = await resolverCarpetaCursoProgramado(programadoId);

        if (!carpetaResult.success) {
            return res.status(500).json({ success: false, message: 'Error creando carpeta en Drive' });
        }

        // Crear subcarpeta "Evidencias" dentro de la carpeta de capacitación
        let evidenciasFolderId = carpetaResult.folderId;
        try {
            // crearCarpeta devuelve directamente el ID como string
            const subFolderId = await driveService.crearCarpeta('Evidencias', carpetaResult.folderId);
            if (subFolderId) {
                evidenciasFolderId = subFolderId;
            }
        } catch (e) {
            // silenced
        }

        const [existentesRows] = await pool.query(
            `SELECT COUNT(*) AS total
             FROM documento_curso_programado
             WHERE programado_id = ? AND descripcion = 'foto_evidencia'`,
            [programadoId]
        );

        const totalExistentes = Number(existentesRows?.[0]?.total || 0);
        if (totalExistentes >= maxFotosEvidencia) {
            return res.status(400).json({
                success: false,
                message: `Límite alcanzado: ya existen ${maxFotosEvidencia} fotos de evidencia para este curso.`
            });
        }

        const cupoDisponible = maxFotosEvidencia - totalExistentes;
        const archivosEntrada = req.files.slice(0, cupoDisponible);
        const resultados = [];
        let indiceGlobal = totalExistentes;
        for (let i = 0; i < archivosEntrada.length; i++) {
            const file = archivosEntrada[i];
            const ext = (file.originalname.split('.').pop() || 'jpg').toLowerCase();
            indiceGlobal++;
            const nombreArchivo = construirNombreDocProgramado({
                nombreEmpresa: curso.nombre_empresa,
                nombreCurso: curso.nombre_curso,
                fechaInicio: curso.fecha_inicio,
                tipoBase: 'foto_evidencia',
                extension: ext,
                indice: indiceGlobal
            });

            try {
                const driveFile = await driveService.subirArchivo(
                    file.buffer, nombreArchivo, file.mimetype, evidenciasFolderId
                );

                // Persistir en BD con drive_file_id
                try {
                    await pool.query(
                        `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
                         VALUES (?, 'foto_evidencia', ?, ?, ?, 'foto_evidencia')`,
                        [programadoId, nombreArchivo, driveFile.webViewLink || '', driveFile.id || null]
                    );
                } catch (dbErr) {
                    // silenced
                }

                resultados.push({
                    nombre: nombreArchivo,
                    drive_file_id: driveFile.id,
                    url: driveFile.webViewLink,
                    thumbnailLink: driveFile.thumbnailLink || null
                });

            } catch (uploadErr) {
                console.error(`[ERROR] Error subiendo foto ${nombreArchivo}:`, uploadErr.message);
                resultados.push({ nombre: nombreArchivo, error: uploadErr.message });
            }
        }

        res.json({
            success: true,
            message: `${resultados.filter(r => !r.error).length} de ${archivosEntrada.length} fotos subidas exitosamente`,
            fotos: resultados,
            total_recibidas: req.files.length,
            total_procesadas: archivosEntrada.length,
            total_existentes: totalExistentes + resultados.filter(r => !r.error).length,
            carpeta: carpetaResult.path + '/Evidencias'
        });
    } catch (error) {
        console.error('[ERROR] Error subiendo fotos de evidencia:', error);
        handleError(res, error);
    }
});

