// Vincular Entrega de Documentos (SP-F-03) a otros cursos sin re-subir el archivo
app.post('/api/cursos-programados/:programadoId/entrega-documentos/vincular', requireAdminEmpresaInstructor, async (req, res) => {
    try {
        const { programadoId } = req.params;
        const payload = req.body || {};

        const rawIds = Array.isArray(payload.programadoIds) ? payload.programadoIds : [];
        const programadoIds = [...new Set(rawIds.map((id) => Number(id)).filter((id) => Number.isFinite(id) && id > 0))]
            .filter((id) => id !== Number(programadoId));

        if (!programadoIds.length) {
            return res.json({ success: true, vinculados: 0, omitidos: 0, vinculadosIds: [] });
        }

        const driveFileId = String(payload.driveFileId || '').trim();
        let archivoUrl = String(payload.archivoUrl || '').trim();
        const nombreArchivo = String(payload.nombreArchivo || '').trim() || 'entrega_documentos_spf03_firmado';
        const descripcion = String(payload.descripcion || 'entrega_documentos_spf03_firmado').trim();
        const tipoDocumento = String(payload.tipoDocumento || 'otro').trim() || 'otro';

        if (!driveFileId && !archivoUrl) {
            return res.status(400).json({ success: false, message: 'Se requiere driveFileId o archivoUrl para vincular.' });
        }

        if (!archivoUrl && driveFileId) {
            archivoUrl = `https://drive.google.com/file/d/${driveFileId}/view`;
        }

        const [origenRows] = await pool.query(
            'SELECT empresa_id FROM curso_programado WHERE programado_id = ? LIMIT 1',
            [programadoId]
        );

        if (!origenRows.length) {
            return res.status(404).json({ success: false, message: 'Curso programado no encontrado' });
        }

        const empresaId = origenRows[0].empresa_id;
        const [targetRows] = await pool.query(
            'SELECT programado_id, empresa_id, fecha_inicio FROM curso_programado WHERE programado_id IN (?)',
            [programadoIds]
        );

        const mismosEmpresa = targetRows.filter((row) => Number(row.empresa_id) === Number(empresaId));
        const idsMismosEmpresa = mismosEmpresa.map((row) => Number(row.programado_id));
        const omitidosPorEmpresa = programadoIds.filter((id) => !idsMismosEmpresa.includes(id));

        if (!idsMismosEmpresa.length) {
            return res.json({
                success: true,
                vinculados: 0,
                omitidos: 0,
                omitidosPorEmpresa: omitidosPorEmpresa.length,
                vinculadosIds: []
            });
        }

        const [existentesRows] = await pool.query(
            'SELECT programado_id FROM documento_curso_programado WHERE programado_id IN (?) AND descripcion = ?',
            [idsMismosEmpresa, descripcion]
        );
        const existentes = new Set(existentesRows.map((row) => Number(row.programado_id)));
        const idsInsertar = idsMismosEmpresa.filter((id) => !existentes.has(id));

        for (const id of idsInsertar) {
            await pool.query(
                `INSERT INTO documento_curso_programado (programado_id, tipo_documento, nombre_archivo, archivo_url, drive_file_id, descripcion)
                 VALUES (?, ?, ?, ?, ?, ?)`,
                [id, tipoDocumento, nombreArchivo, archivoUrl, driveFileId || null, descripcion]
            );
        }

        const years = new Set();
        mismosEmpresa.forEach((row) => {
            if (idsInsertar.includes(Number(row.programado_id))) {
                const dt = new Date(row.fecha_inicio);
                if (!Number.isNaN(dt.getTime())) {
                    years.add(dt.getFullYear());
                }
            }
        });

        for (const year of years) {
            try {
                await guardarControlCapacitacionExcelEnDrive(year);
            } catch (controlErr) {
                console.warn('[WARN] No se pudo actualizar el control de capacitacion:', controlErr.message || controlErr);
            }
        }

        return res.json({
            success: true,
            vinculados: idsInsertar.length,
            omitidos: idsMismosEmpresa.length - idsInsertar.length,
            omitidosPorEmpresa: omitidosPorEmpresa.length,
            vinculadosIds: idsInsertar
        });
    } catch (error) {
        console.error('[ERROR] vincular-entrega-documentos:', error);
        handleError(res, error);
    }
});

// Eliminar documento de Drive y BD (sincronizado)
app.delete('/api/documentos-curso-programado/:documentoProgId', async (req, res) => {
    try {
        const { documentoProgId } = req.params;

        // Obtener el registro con verificación de que el curso programado existe
        const [doc] = await pool.query(
            `SELECT dcp.*, cp.empresa_id, cp.instructor_id
             FROM documento_curso_programado dcp
             INNER JOIN curso_programado cp ON dcp.programado_id = cp.programado_id
             WHERE dcp.documento_prog_id = ?`,
            [documentoProgId]
        );

        if (doc.length === 0) {
            return res.status(404).json({ success: false, message: 'Documento no encontrado' });
        }

        // Eliminar de Google Drive si tiene drive_file_id
        if (doc[0].drive_file_id) {
            try {
                await driveService.eliminarArchivo(doc[0].drive_file_id);
            } catch (driveErr) {
                // silenced
            }
        }

        // Eliminar de BD
        await pool.query(
            'DELETE FROM documento_curso_programado WHERE documento_prog_id = ?',
            [documentoProgId]
        );


        res.json({ success: true, message: 'Documento eliminado de Drive y BD correctamente' });
    } catch (error) {
        console.error('[ERROR] Error eliminando documento:', error);
        handleError(res, error);
    }
});

// Crear inscripción
app.post('/api/inscripciones', async (req, res) => {
    try {
        const { programado_id, empleado_id } = req.body;

        if (!programado_id || !empleado_id) {
            return res.json({ success: false, message: 'Curso programado y empleado son requeridos' });
        }

        const [result] = await pool.query(
            `INSERT INTO inscripcion_curso (programado_id, empleado_id, asistio, activo, fecha_inscripcion)
             VALUES (?, ?, 0, 1, NOW())`,
            [programado_id, empleado_id]
        );

        res.json({ success: true, message: 'Inscripción creada', inscripcion_id: result.insertId });
    } catch (error) {
        if (error.code === 'ER_DUP_ENTRY') {
            res.json({ success: false, message: 'El empleado ya está inscrito en este curso' });
        } else {
            handleError(res, error);
        }
    }
});

