// Obtener instructor por ID
app.get('/api/instructores/:id', async (req, res) => {
    try {
        const [rows] = await pool.query(
            `SELECT i.*,
                    GROUP_CONCAT(a.nombre_area) as areas
             FROM instructor i
             LEFT JOIN instructor_areas ia ON i.instructor_id = ia.instructor_id
             LEFT JOIN area_tematica a ON ia.area_id = a.area_id
             WHERE i.instructor_id = ?
             GROUP BY i.instructor_id`,
            [req.params.id]
        );
        if (rows.length > 0) {
            res.json({ success: true, instructor: rows[0] });
        } else {
            res.status(404).json({ success: false, message: 'Instructor no encontrado' });
        }
    } catch (error) {
        handleError(res, error);
    }
});

// Actualizar instructor
app.put('/api/instructores/:id', async (req, res) => {
    const conn = await pool.getConnection();
    try {
        await conn.beginTransaction();

        const { areas, ...fields } = req.body;
        const updatePayload = {};

        Object.keys(fields).forEach(key => {
            if (fields[key] !== undefined && key !== 'instructor_id') {
                updatePayload[key] = fields[key];
            }
        });

        if (Object.keys(updatePayload).length > 0) {
            await conn.query('UPDATE instructor SET ? WHERE instructor_id = ?', [updatePayload, req.params.id]);
        }

        // Actualizar áreas si se proporcionan
        if (areas && Array.isArray(areas)) {
            await conn.query('DELETE FROM instructor_areas WHERE instructor_id = ?', [req.params.id]);
            if (areas.length > 0) {
                const areaValues = areas.map(areaId => [req.params.id, areaId]);
                await conn.query('INSERT INTO instructor_areas (instructor_id, area_id) VALUES ?', [areaValues]);
            }
        }

        await conn.commit();
        res.json({ success: true, message: 'Instructor actualizado' });
    } catch (error) {
        await conn.rollback();
        handleError(res, error);
    } finally {
        conn.release();
    }
});

// Eliminar instructor (soft delete)
app.delete('/api/instructores/:id', async (req, res) => {
    try {
        await pool.query('UPDATE instructor SET activo = FALSE WHERE instructor_id = ?', [req.params.id]);
        res.json({ success: true, message: 'Instructor eliminado' });
    } catch (error) {
        handleError(res, error);
    }
});

// =====================================================
// FEEDBACK DE INSTRUCTOR (Encuestas de satisfacción)
// =====================================================

/**
 * GET /api/instructores/:instructorId/feedback
 * Obtiene la retroalimentación agregada de un instructor a partir de las
 * encuestas de satisfacción de todos sus cursos programados.
 * Extrae preguntas 4 (desempeño), 5 (dominio) y 7 (comentarios).
 */
app.get('/api/instructores/:instructorId/feedback', async (req, res) => {
    try {
        const { instructorId } = req.params;

        // Obtener todos los cursos programados del instructor que tengan resultados de encuesta archivados
        const [cursos] = await pool.query(
            `SELECT cp.programado_id, cp.fecha_inicio, cp.google_form_id,
                    c.nombre_curso, e.nombre_empresa,
                    dcp.drive_file_id
             FROM curso_programado cp
             INNER JOIN curso c ON c.curso_id = cp.curso_id
             INNER JOIN empresa e ON e.empresa_id = cp.empresa_id
             LEFT JOIN documento_curso_programado dcp
                 ON dcp.programado_id = cp.programado_id
                 AND dcp.descripcion = 'encuesta_resultados_cierre'
                 AND dcp.drive_file_id IS NOT NULL
             WHERE cp.instructor_id = ?
             ORDER BY cp.fecha_inicio DESC`,
            [instructorId]
        );

        if (!cursos.length) {
            return res.json({
                success: true,
                instructor_id: Number(instructorId),
                total_cursos: 0,
                total_respuestas: 0,
                desempeno: { excelente: 0, bueno: 0, regular: 0, malo: 0, total: 0 },
                dominio: { excelente: 0, bueno: 0, regular: 0, malo: 0, total: 0 },
                comentarios: [],
                cursos_detalle: []
            });
        }

        // Contadores agregados
        const desempeno = { excelente: 0, bueno: 0, regular: 0, malo: 0, total: 0 };
        const dominio = { excelente: 0, bueno: 0, regular: 0, malo: 0, total: 0 };
        const comentarios = [];
        let totalRespuestas = 0;
        const cursosDetalle = [];

        for (const curso of cursos) {
            let stats = null;

            // Intentar obtener datos archivados de Drive
            if (curso.drive_file_id) {
                try {
                    const buffer = await driveService.descargarArchivo(curso.drive_file_id);
                    stats = JSON.parse(buffer.toString('utf8'));
                } catch (e) {
                    // No se pudo descargar, intentar en vivo
                }
            }

            // Si no hay archivo archivado, intentar obtener en vivo
            if (!stats && curso.google_form_id) {
                try {
                    stats = await googleFormsService.obtenerEstadisticasFormulario(curso.google_form_id);
                } catch (e) {
                    // No se pudieron obtener stats en vivo
                }
            }

            if (!stats || !stats.preguntas || stats.preguntas.length === 0) continue;

            totalRespuestas += stats.total_respuestas || 0;
            const preguntas = stats.preguntas;

            // Pregunta 4: desempeño del instructor (índice 3)
            const p4 = preguntas[3];
            if (p4 && p4.type === 'choice') {
                for (const opt of p4.options) {
                    const label = opt.label.toLowerCase();
                    if (label.includes('excelente')) desempeno.excelente += opt.count;
                    else if (label.includes('buen')) desempeno.bueno += opt.count;
                    else if (label.includes('regular')) desempeno.regular += opt.count;
                    else if (label.includes('mal') || label.includes('deficiente')) desempeno.malo += opt.count;
                }
                desempeno.total += p4.total_respuestas || 0;
            }

            // Pregunta 5: dominio de temas del instructor (índice 4)
            const p5 = preguntas[4];
            if (p5 && p5.type === 'choice') {
                for (const opt of p5.options) {
                    const label = opt.label.toLowerCase();
                    if (label.includes('excelente')) dominio.excelente += opt.count;
                    else if (label.includes('buen')) dominio.bueno += opt.count;
                    else if (label.includes('regular')) dominio.regular += opt.count;
                    else if (label.includes('mal') || label.includes('deficiente')) dominio.malo += opt.count;
                }
                dominio.total += p5.total_respuestas || 0;
            }

            // Pregunta 7: comentarios (índice 6)
            const p7 = preguntas[6];
            if (p7 && p7.type === 'text' && p7.muestras_texto) {
                for (const texto of p7.muestras_texto) {
                    if (texto.trim()) {
                        comentarios.push({
                            texto: texto.trim(),
                            curso: curso.nombre_curso,
                            empresa: curso.nombre_empresa,
                            fecha: curso.fecha_inicio
                        });
                    }
                }
            }

            cursosDetalle.push({
                programado_id: curso.programado_id,
                nombre_curso: curso.nombre_curso,
                nombre_empresa: curso.nombre_empresa,
                fecha_inicio: curso.fecha_inicio,
                total_respuestas: stats.total_respuestas || 0
            });
        }

        // Calcular porcentajes
        const calcPorcentaje = (obj) => {
            const t = obj.total || 1;
            return {
                ...obj,
                excelente_pct: Math.round((obj.excelente / t) * 100),
                bueno_pct: Math.round((obj.bueno / t) * 100),
                regular_pct: Math.round((obj.regular / t) * 100),
                malo_pct: Math.round((obj.malo / t) * 100)
            };
        };

        res.json({
            success: true,
            instructor_id: Number(instructorId),
            total_cursos: cursosDetalle.length,
            total_respuestas: totalRespuestas,
            desempeno: calcPorcentaje(desempeno),
            dominio: calcPorcentaje(dominio),
            comentarios: comentarios.slice(0, 20),
            cursos_detalle: cursosDetalle
        });
    } catch (error) {
        handleError(res, error, 'Error al obtener feedback del instructor');
    }
});

/**
 * GET /api/admin/instructores-rendimiento
 * Panel de administrador: rendimiento agregado de todos los instructores activos.
 */
app.get('/api/admin/instructores-rendimiento', requireAdmin, async (req, res) => {
    try {
        const normalizar = (texto = '') => String(texto)
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .toLowerCase()
            .trim();

        const calcPorcentajeEscalaCuatro = (obj) => {
            const t = obj.total || 1;
            return {
                ...obj,
                excelente_pct: Math.round((obj.excelente / t) * 100),
                bueno_pct: Math.round((obj.bueno / t) * 100),
                regular_pct: Math.round((obj.regular / t) * 100),
                malo_pct: Math.round((obj.malo / t) * 100)
            };
        };

        const calcPorcentajeSiNo = (obj) => {
            const t = obj.total || 1;
            return {
                ...obj,
                si_pct: Math.round((obj.si / t) * 100),
                no_pct: Math.round((obj.no / t) * 100)
            };
        };

        const acumularEscalaCuatro = (pregunta, target) => {
            if (!pregunta || pregunta.type !== 'choice') return;
            for (const opt of pregunta.options || []) {
                const label = normalizar(opt.label);
                if (label.includes('excelente')) target.excelente += opt.count || 0;
                else if (label.includes('buen')) target.bueno += opt.count || 0;
                else if (label.includes('regular')) target.regular += opt.count || 0;
                else if (label.includes('mal') || label.includes('deficiente')) target.malo += opt.count || 0;
            }
            target.total += pregunta.total_respuestas || 0;
        };

        const acumularSiNo = (pregunta, target) => {
            if (!pregunta || pregunta.type !== 'choice') return;
            for (const opt of pregunta.options || []) {
                const label = normalizar(opt.label);
                if (label.includes('si')) target.si += opt.count || 0;
                else if (label.includes('no')) target.no += opt.count || 0;
            }
            target.total += pregunta.total_respuestas || 0;
        };

        const [instructores] = await pool.query(
            `SELECT i.instructor_id, i.nombre, i.apellido_paterno, i.apellido_materno,
                    i.especialidad, i.foto_url, i.usuario_id,
                    u.foto_drive_id
             FROM instructor i
             INNER JOIN usuario u ON i.usuario_id = u.id
             INNER JOIN roles r ON u.rol_id = r.rol_id
             WHERE i.activo = 1
               AND r.nombre_rol = 'instructor'
             ORDER BY i.nombre`
        );

        const resultado = [];
        const rendimientoGeneral = {
            evaluacion_curso: { excelente: 0, bueno: 0, regular: 0, malo: 0, total: 0 },
            pertinencia_temas: { excelente: 0, bueno: 0, regular: 0, malo: 0, total: 0 },
            recomendacion_biznaga: { si: 0, no: 0, total: 0 }
        };
        let totalRespuestasGenerales = 0;

        for (const inst of instructores) {
            // Contar cursos y obtener feedback agregado
            const [cursosInfo] = await pool.query(
                `SELECT COUNT(*) as total_cursos,
                        SUM(CASE WHEN cp.estatus = 'completado' THEN 1 ELSE 0 END) as cursos_completados
                 FROM curso_programado cp
                 WHERE cp.instructor_id = ?`,
                [inst.instructor_id]
            );

            // Obtener archivos de encuesta cerrados
            const [archivos] = await pool.query(
                `SELECT dcp.drive_file_id, cp.fecha_inicio, c.nombre_curso
                 FROM documento_curso_programado dcp
                 INNER JOIN curso_programado cp ON cp.programado_id = dcp.programado_id
                 INNER JOIN curso c ON c.curso_id = cp.curso_id
                 WHERE cp.instructor_id = ?
                   AND dcp.descripcion = 'encuesta_resultados_cierre'
                   AND dcp.drive_file_id IS NOT NULL
                 ORDER BY cp.fecha_inicio DESC
                 LIMIT 10`,
                [inst.instructor_id]
            );

            const desempeno = { excelente: 0, bueno: 0, regular: 0, malo: 0, total: 0 };
            const dominio = { excelente: 0, bueno: 0, regular: 0, malo: 0, total: 0 };
            let totalRespuestas = 0;

            for (const archivo of archivos) {
                try {
                    const buffer = await driveService.descargarArchivo(archivo.drive_file_id);
                    const stats = JSON.parse(buffer.toString('utf8'));
                    if (!stats.preguntas || stats.preguntas.length < 5) continue;

                    totalRespuestas += stats.total_respuestas || 0;
                    totalRespuestasGenerales += stats.total_respuestas || 0;

                    const p4 = stats.preguntas[3];
                    acumularEscalaCuatro(p4, desempeno);

                    const p5 = stats.preguntas[4];
                    acumularEscalaCuatro(p5, dominio);

                    const p2 = stats.preguntas[1];
                    acumularEscalaCuatro(p2, rendimientoGeneral.evaluacion_curso);

                    const p3 = stats.preguntas[2];
                    acumularEscalaCuatro(p3, rendimientoGeneral.pertinencia_temas);

                    const p6 = stats.preguntas[5];
                    acumularSiNo(p6, rendimientoGeneral.recomendacion_biznaga);
                } catch (e) {
                    // No se pudo leer archivo archivado
                }
            }

            // Calcular puntaje general (0-100) ponderado
            const totalDesempeno = desempeno.total || 0;
            const totalDominio = dominio.total || 0;
            let puntaje = 0;
            if (totalDesempeno + totalDominio > 0) {
                const scoreDesempeno = totalDesempeno > 0
                    ? ((desempeno.excelente * 100 + desempeno.bueno * 75 + desempeno.regular * 50 + desempeno.malo * 25) / totalDesempeno)
                    : 0;
                const scoreDominio = totalDominio > 0
                    ? ((dominio.excelente * 100 + dominio.bueno * 75 + dominio.regular * 50 + dominio.malo * 25) / totalDominio)
                    : 0;
                puntaje = Math.round((scoreDesempeno + scoreDominio) / 2);
            }

            resultado.push({
                instructor_id: inst.instructor_id,
                nombre: [inst.nombre, inst.apellido_paterno, inst.apellido_materno].filter(Boolean).join(' '),
                especialidad: inst.especialidad,
                foto_drive_id: inst.foto_drive_id,
                total_cursos: cursosInfo[0]?.total_cursos || 0,
                cursos_completados: cursosInfo[0]?.cursos_completados || 0,
                total_respuestas: totalRespuestas,
                puntaje,
                desempeno: calcPorcentajeEscalaCuatro(desempeno),
                dominio: calcPorcentajeEscalaCuatro(dominio)
            });
        }

        // Ordenar por puntaje descendente
        resultado.sort((a, b) => b.puntaje - a.puntaje);

        res.json({
            success: true,
            instructores: resultado,
            rendimiento_general: {
                total_respuestas: totalRespuestasGenerales,
                evaluacion_curso: calcPorcentajeEscalaCuatro(rendimientoGeneral.evaluacion_curso),
                pertinencia_temas: calcPorcentajeEscalaCuatro(rendimientoGeneral.pertinencia_temas),
                recomendacion_biznaga: calcPorcentajeSiNo(rendimientoGeneral.recomendacion_biznaga)
            }
        });
    } catch (error) {
        handleError(res, error, 'Error al obtener rendimiento de instructores');
    }
});

/**
 * GET /api/doctor/perfil
 * Devuelve el perfil medico del usuario autenticado, incluso si doctor es rol adicional.
 */
app.get('/api/doctor/perfil', async (req, res) => {
    try {
        let userRoles = Array.isArray(req.user?.roles)
            ? req.user.roles.map(r => String(r).toLowerCase())
            : (req.user?.rol ? [String(req.user.rol).toLowerCase()] : []);

        const userId = Number(req.user?.id || 0);

        // Fallback para tokens/sesiones antiguas sin roles adicionales.
        if (!userRoles.includes('doctor') && userId) {
            const [userRows] = await pool.query(
                `SELECT LOWER(r.nombre_rol) AS rol_principal,
                        LOWER(COALESCE(u.roles_adicionales, '')) AS roles_adicionales
                 FROM usuario u
                 JOIN roles r ON u.rol_id = r.rol_id
                 WHERE u.id = ?
                 LIMIT 1`,
                [userId]
            );

            if (userRows.length > 0) {
                const rolesDB = [userRows[0].rol_principal];
                if (userRows[0].roles_adicionales) {
                    const adicionales = userRows[0].roles_adicionales
                        .split(',')
                        .map(r => String(r).trim().toLowerCase())
                        .filter(Boolean);
                    rolesDB.push(...adicionales);
                }
                userRoles = Array.from(new Set([...userRoles, ...rolesDB]));
            }
        }

        if (!userRoles.includes('doctor')) {
            return res.status(403).json({
                success: false,
                message: 'Este recurso solo esta disponible para perfiles con rol doctor'
            });
        }

        let instructorId = Number(req.user?.instructor_id || 0) || null;
        let instructor = null;

        if (instructorId) {
            const [rowsById] = await pool.query(
                'SELECT * FROM instructor WHERE instructor_id = ? AND activo = 1 LIMIT 1',
                [instructorId]
            );
            instructor = rowsById[0] || null;
        }

        if (!instructor && userId) {
            const [rowsByUser] = await pool.query(
                `SELECT * FROM instructor
                 WHERE usuario_id = ? AND activo = 1
                 ORDER BY instructor_id DESC
                 LIMIT 1`,
                [userId]
            );

            instructor = rowsByUser[0] || null;

            // Sincronizar instructor_id en usuario para futuras sesiones/token.
            if (instructor?.instructor_id) {
                instructorId = Number(instructor.instructor_id);
                await pool.query(
                    `UPDATE usuario
                     SET instructor_id = ?
                     WHERE id = ? AND (instructor_id IS NULL OR instructor_id <> ?)`,
                    [instructorId, userId, instructorId]
                );
            }
        }

        if (!instructor) {
            return res.status(404).json({
                success: false,
                message: 'No se encontro un perfil de doctor vinculado al usuario'
            });
        }

        return res.json({
            success: true,
            instructor
        });
    } catch (error) {
        handleError(res, error, 'Error al obtener perfil del doctor');
    }
});

/**
 * GET /api/doctor/resumen
 * Resumen para el perfil de un doctor: estadísticas de historias clínicas realizadas.
 */
app.get('/api/doctor/resumen', async (req, res) => {
    try {
        await poolMedicosReady;
        const nombreDoctor = req.user ? [req.user.nombre, req.user.apellido].filter(Boolean).join(' ') : null;

        // Total de historias clínicas creadas por este doctor
        let totalHistorias = 0;
        let historiasEsteMes = 0;
        let empresasAtendidas = 0;
        let ultimaHistoria = null;

        if (nombreDoctor) {
            const [[countRow]] = await poolMedicos.query(
                `SELECT COUNT(*) as total FROM historia_clinica WHERE activo = 1 AND personal_elaboro = ?`,
                [nombreDoctor]
            );
            totalHistorias = countRow?.total || 0;

            const [[mesRow]] = await poolMedicos.query(
                `SELECT COUNT(*) as total FROM historia_clinica
                 WHERE activo = 1 AND personal_elaboro = ?
                   AND MONTH(created_at) = MONTH(NOW()) AND YEAR(created_at) = YEAR(NOW())`,
                [nombreDoctor]
            );
            historiasEsteMes = mesRow?.total || 0;

            const [[empresasRow]] = await poolMedicos.query(
                `SELECT COUNT(DISTINCT empresa_id) as total FROM historia_clinica
                 WHERE activo = 1 AND personal_elaboro = ? AND empresa_id IS NOT NULL`,
                [nombreDoctor]
            );
            empresasAtendidas = empresasRow?.total || 0;

            const [ultimaRow] = await poolMedicos.query(
                `SELECT created_at, nombre FROM historia_clinica
                 WHERE activo = 1 AND personal_elaboro = ?
                 ORDER BY created_at DESC LIMIT 1`,
                [nombreDoctor]
            );
            ultimaHistoria = ultimaRow.length > 0 ? ultimaRow[0] : null;
        }

        // Estadísticas globales rápidas
        const [[globalRow]] = await poolMedicos.query(
            `SELECT COUNT(*) as total FROM historia_clinica WHERE activo = 1`
        );

        res.json({
            success: true,
            doctor: nombreDoctor,
            mis_historias: totalHistorias,
            historias_este_mes: historiasEsteMes,
            empresas_atendidas: empresasAtendidas,
            ultima_historia: ultimaHistoria,
            total_historias_sistema: globalRow?.total || 0
        });
    } catch (error) {
        handleError(res, error, 'Error al obtener resumen del doctor');
    }
});

