/**
 * GET /api/notificaciones
 * Retorna las notificaciones no descartadas del usuario autenticado
 */
app.get('/api/notificaciones', authMiddleware, async (req, res) => {
    try {
        const pcResolutivosService = require('./pcResolutivosService');
        const ambientalService = require('./ambientalService');
        await Promise.all([
            poolBiznagaSgcReady.catch(() => null),
            poolProteccionCivilReady.catch(() => null)
        ]);

        const operativas = await notificacionesOperativasService.generarNotificacionesOperativas({
            pool,
            poolSgc: poolBiznagaSgc,
            poolPC: poolProteccionCivil,
            user: req.user,
            pcResolutivosService,
            ambientalService
        });

        // Legacy: solo conservar notificaciones que no sean ruido eliminado
        // (Participantes registrados, empresas sin actividad, etc.)
        const TITULOS_BLOQUEADOS = [
            'participante',
            'participantes registrados',
            'sin actividad',
            'empresas sin actividad'
        ];
        const [legacyRows] = await pool.query(
            `SELECT notif_id, tipo, icono, titulo, mensaje, ruta, created_at
             FROM notificacion_usuario
             WHERE usuario_id = ? AND descartada = 0
             ORDER BY created_at DESC
             LIMIT 50`,
            [req.user.id]
        );
        const legacyFiltradas = (legacyRows || [])
            .filter((n) => {
                const t = String(n.titulo || '').toLowerCase();
                return !TITULOS_BLOQUEADOS.some((b) => t.includes(b));
            })
            .map((n) => ({ ...n, auto: false }));

        // Roles con notificaciones operativas: no mezclar legacy (evita ruido)
        const roles = notificacionesOperativasService.rolesDeUsuario(req.user);
        const usaOperativas = notificacionesOperativasService.tieneRol(
            roles,
            'instructor', 'control_documental', 'proteccion_civil', 'ambiental'
        );
        const notificaciones = usaOperativas
            ? operativas
            : [...operativas, ...legacyFiltradas].slice(0, 50);

        res.json({ success: true, notificaciones });
    } catch (error) {
        handleError(res, error);
    }
});

/**
 * PATCH /api/notificaciones/:id/descartar
 * Descarta (oculta) una notificación del usuario autenticado
 */
app.patch('/api/notificaciones/:id/descartar', authMiddleware, async (req, res) => {
    try {
        const { id } = req.params;
        const userId = req.user.id;
        const [result] = await pool.query(
            `UPDATE notificacion_usuario SET descartada = 1 WHERE notif_id = ? AND usuario_id = ?`,
            [id, userId]
        );
        if (result.affectedRows === 0) {
            return res.status(404).json({ success: false, message: 'Notificación no encontrada' });
        }
        res.json({ success: true });
    } catch (error) {
        handleError(res, error);
    }
});

