/**
 * GET /api/notas-version
 * Sistema siempre activo. Historial de versiones + áreas para aportaciones.
 */
function usuarioPuedeEditarNotasVersion(req) {
    if (process.env.NODE_ENV === 'production') return false;
    const userRoles = Array.isArray(req.user?.roles)
        ? req.user.roles.map((r) => String(r).toLowerCase())
        : (req.user?.rol ? [String(req.user.rol).toLowerCase()] : []);
    return userRoles.includes('root') || userRoles.includes('administrador');
}

app.get('/api/notas-version', authMiddleware, (req, res) => {
    try {
        // Fuerza activo permanente: las aportaciones/notificaciones siempre están disponibles.
        if (!notasVersionService.readData().activo) {
            notasVersionService.setActivo(true);
        }
        const puedeEditar = usuarioPuedeEditarNotasVersion(req);
        const payload = notasVersionService.listar({
            incluirBorrador: puedeEditar,
            puedeActivar: false
        });
        res.json({
            success: true,
            ...payload,
            activo: true,
            puedeActivar: false,
            puedeEditar,
            areasTicket: ticketsService.AREAS,
            iconos: notasVersionService.ICONOS_PERMITIDOS
        });
    } catch (error) {
        handleError(res, error, 'Error al obtener notas de versión');
    }
});

