/**
 * GET /api/tickets/:id/evidencias/:evidenciaId
 * Imagen de evidencia: el autor del ticket o un usuario root.
 */
app.get('/api/tickets/:id/evidencias/:evidenciaId', authMiddleware, async (req, res) => {
    try {
        const ticket = await ticketsService.obtenerPorId(pool, req.params.id);
        if (!ticket) {
            return res.status(404).json({ success: false, message: 'Ticket no encontrado' });
        }
        const userRoles = Array.isArray(req.user?.roles)
            ? req.user.roles.map((r) => String(r).toLowerCase())
            : (req.user?.rol ? [String(req.user.rol).toLowerCase()] : []);
        const esRoot = userRoles.includes('root');
        const esAutor = Number(ticket.usuario_id) === Number(req.user?.id);
        if (!esRoot && !esAutor) {
            return res.status(403).json({ success: false, message: 'No tiene acceso a esta evidencia' });
        }
        const archivo = await ticketsService.obtenerArchivoEvidencia(
            pool,
            req.params.id,
            req.params.evidenciaId
        );
        res.setHeader('Content-Type', archivo.mime);
        res.setHeader('Cache-Control', 'private, max-age=86400');
        if (archivo.filename) {
            res.setHeader(
                'Content-Disposition',
                `inline; filename="${String(archivo.filename).replace(/"/g, '')}"`
            );
        }
        if (Buffer.isBuffer(archivo.buffer)) {
            return res.send(archivo.buffer);
        }
        return res.sendFile(path.resolve(archivo.path));
    } catch (error) {
        const status = error.status || 500;
        if (status >= 400 && status < 500) {
            return res.status(status).json({ success: false, message: error.message });
        }
        handleError(res, error, 'Error al obtener evidencia');
    }
});

