/**
 * POST /api/sgc/solicitud-documentos/:id/reemplazar-formato
 * Reemplaza archivo asociado (descarga o formato interactivo) y avanza a lista maestra.
 */
app.post(
    '/api/sgc/solicitud-documentos/:id/reemplazar-formato',
    authMiddleware,
    requireRootOCalidadSgc,
    uploadSgcFormatoDescarga.single('archivo'),
    async (req, res) => {
        try {
            await poolBiznagaSgcReady;
            const sgcSgcF01Service = require('./sgcSgcF01Service');
            const sgcFormatosDescargaService = require('./sgcFormatosDescargaService');
            const contexto = await sgcSolicitudDocumentosService.resolverContextoGestion({
                pool,
                poolSgc: poolBiznagaSgc,
                solicitudId: req.params.id,
                sgcF01Service: sgcSgcF01Service,
                formatosDescargaService: sgcFormatosDescargaService
            });
            const solicitud = contexto.solicitud;
            if (solicitud.paso_flujo === 'revision') {
                return res.status(400).json({
                    success: false,
                    message: 'Primero autoriza la solicitud'
                });
            }
            if (!req.file?.buffer) {
                return res.status(400).json({ success: false, message: 'Debe adjuntar el archivo nuevo' });
            }

            const fmt = contexto.formatoDescarga;
            const codigo = String(req.body?.codigo || solicitud.codigo || fmt?.codigo || '').trim();
            const titulo = String(
                req.body?.titulo || solicitud.nombre_documento || fmt?.titulo || ''
            ).trim();
            const driveFileIdActual = String(
                req.body?.drive_file_id || fmt?.drive_file_id_actual || solicitud.drive_file_id || ''
            ).trim();
            const nombreArchivo = String(
                req.body?.nombre_archivo || fmt?.nombre_archivo || req.file.originalname || ''
            ).trim();
            const origen = String(fmt?.origen || '');
            const esDescarga = origen === 'formato_descarga'
                || (fmt?.catalog_key && !String(fmt.catalog_key).startsWith('sgc:'));

            if (!driveFileIdActual) {
                return res.status(400).json({
                    success: false,
                    message: 'No se encontró el archivo de Drive asociado a este documento.'
                });
            }

            let resultado;
            if (esDescarga && fmt?.catalog_key && !String(fmt.catalog_key).startsWith('sgc:')) {
                resultado = await sgcFormatosDescargaService.reemplazarFormatoDescarga({
                    poolSgc: poolBiznagaSgc,
                    catalogKey: fmt.catalog_key,
                    codigo,
                    titulo,
                    driveFileIdActual,
                    nombreArchivo,
                    fileBuffer: req.file.buffer,
                    mimeType: req.file.mimetype,
                    originalName: req.file.originalname,
                    usuario: req.user
                });
            } else {
                // Formato interactivo (ej. DG-F-04): archivar nombre y subir nuevo en la misma carpeta
                const meta = await driveService.obtenerMetadatosArchivo(driveFileIdActual);
                const parentId = meta?.parents?.[0] || null;
                if (!parentId) {
                    return res.status(500).json({
                        success: false,
                        message: 'No se pudo determinar la carpeta del archivo en Drive'
                    });
                }
                const baseName = String(nombreArchivo || codigo || 'formato').replace(/\.[^.]+$/, '');
                const ext = (req.file.originalname.match(/\.[^.]+$/) || [''])[0];
                const stamp = new Date().toISOString().slice(0, 10);
                await driveService.renombrarArchivoPorId(
                    driveFileIdActual,
                    `${baseName}_prev_${stamp}${ext || ''}`
                );
                const nuevo = await driveService.subirArchivoNuevo(
                    req.file.buffer,
                    `${baseName}${ext || ''}`,
                    req.file.mimetype || 'application/octet-stream',
                    parentId
                );
                try {
                    await poolBiznagaSgc.query(
                        `UPDATE sgc_formato_cabecera
                         SET drive_file_id = ?, updated_at = NOW()
                         WHERE UPPER(TRIM(codigo_formato)) = ?`,
                        [nuevo.id, codigo.toUpperCase()]
                    );
                } catch (err) {
                    console.warn('[sgc-sol-doc] No se pudo actualizar cabecera Drive:', err.message);
                }
                resultado = {
                    catalog_key: fmt?.catalog_key || `sgc:${codigo}`,
                    codigo,
                    drive_file_id_actual: nuevo.id,
                    archivado: { nombre_archivo: `${baseName}_prev_${stamp}` }
                };
            }

            const actualizada = await sgcSolicitudDocumentosService.marcarFormatoListo(
                pool,
                solicitud.solicitud_id,
                {
                    catalogKey: resultado.catalog_key || fmt?.catalog_key || `sgc:${codigo}`,
                    driveFileId: resultado.drive_file_id_actual,
                    versionNueva: contexto.propuesta?.versionNueva,
                    fechaRevisionNueva: contexto.propuesta?.fechaRevisionNueva
                }
            );

            res.json({
                success: true,
                message: `Formato actualizado. Versión anterior archivada como ${resultado.archivado?.nombre_archivo || 'histórico'}`,
                solicitud: actualizada,
                reemplazo: resultado
            });
        } catch (error) {
            const status = error.status || 500;
            if (status >= 400 && status < 500) {
                return res.status(status).json({ success: false, message: error.message });
            }
            handleError(res, error, 'Error al reemplazar formato desde solicitud');
        }
    }
);

