/**
 * POST /api/sgc/solicitud-documentos/:id/lista-maestra
 * Actualiza SGC-F-01 (+1 versión, fecha México) y avanza a notificar.
 */
app.post('/api/sgc/solicitud-documentos/:id/lista-maestra', authMiddleware, requireRootOCalidadSgc, async (req, res) => {
    try {
        await poolBiznagaSgcReady;
        const sgcSgcF01Service = require('./sgcSgcF01Service');
        const sgcFormatosDescargaService = require('./sgcFormatosDescargaService');
        const contexto = await sgcSolicitudDocumentosService.resolverContextoGestion({
            pool,
            poolSgc: poolBiznagaSgc,
            solicitudId: req.params.id,
            sgcF01Service: sgcSgcF01Service,
            formatosDescargaService: sgcFormatosDescargaService
        });

        const base = contexto.documentoMaestro || {};
        const versionNueva = String(
            req.body?.versionVigente
            || contexto.propuesta?.versionNueva
            || sgcSolicitudDocumentosService.incrementarVersion(base.versionVigente || contexto.solicitud.version_actual)
        ).trim();
        const fechaRevision = String(
            req.body?.fechaRevision
            || contexto.propuesta?.fechaRevisionNueva
            || sgcSolicitudDocumentosService.fechaHoyIso()
        ).trim();

        const documento = {
            codigo: String(req.body?.codigo || base.codigo || contexto.solicitud.codigo || '').trim(),
            nombreDocumento: String(
                req.body?.nombreDocumento || base.nombreDocumento || contexto.solicitud.nombre_documento || ''
            ).trim(),
            nombreOriginal: base.nombreDocumento || contexto.solicitud.nombre_documento || '',
            area: String(req.body?.area || base.area || '').trim(),
            tipo: String(req.body?.tipo || base.tipo || 'Interno').trim(),
            especie: String(
                req.body?.especie || base.especie || contexto.solicitud.tipo_documento || ''
            ).trim(),
            versionVigente: versionNueva,
            fechaRevision,
            responsable: String(
                req.body?.responsable || base.responsable || 'Coordinador del SGC'
            ).trim(),
            vigente: req.body?.vigente !== false
        };

        if (!documento.codigo && !documento.nombreDocumento) {
            return res.status(400).json({
                success: false,
                message: 'No hay datos suficientes para actualizar la lista maestra'
            });
        }

        const payloadF01 = await sgcSgcF01Service.actualizarDocumento(poolBiznagaSgc, { documento });
        const solicitud = await sgcSolicitudDocumentosService.marcarListaMaestraListo(
            pool,
            req.params.id,
            { versionNueva, fechaRevisionNueva: fechaRevision }
        );

        res.json({
            success: true,
            message: `Lista maestra actualizada a versión ${versionNueva}`,
            solicitud,
            listaMaestra: payloadF01
        });
    } catch (error) {
        const status = error.status || error.statusCode || 500;
        if (status >= 400 && status < 500) {
            return res.status(status).json({ success: false, message: error.message });
        }
        handleError(res, error, 'Error al actualizar lista maestra desde solicitud');
    }
});

/**
 * POST /api/sgc/solicitud-documentos/:id/cerrar
 * Body: { notificar: boolean, descripcion?: string }
 * Si notificar=true crea ticket SGC Urgente tipo Actualización.
 */
app.post('/api/sgc/solicitud-documentos/:id/cerrar', authMiddleware, requireRootOCalidadSgc, async (req, res) => {
    try {
        const notificar = req.body?.notificar === true || req.body?.notificar === 1 || req.body?.notificar === '1';
        const descripcion = String(req.body?.descripcion || '').trim();
        let ticketId = null;
        let ticket = null;

        if (notificar) {
            if (!descripcion) {
                return res.status(400).json({
                    success: false,
                    message: 'Describe el cambio o mejora para notificar a Sistemas'
                });
            }
            const solicitud = await sgcSolicitudDocumentosService.obtenerPorId(pool, req.params.id);
            const prefijo = solicitud
                ? `[SGC · Solicitud #${solicitud.solicitud_id}] ${solicitud.codigo || solicitud.nombre_documento}: `
                : '[SGC · Solicitud de documentos] ';
            ticket = await ticketsService.crear(pool, {
                area: 'SGC',
                descripcion: `${prefijo}${descripcion}`,
                prioridad: 'urgente',
                tipo: 'actualizacion',
                usuarioId: req.user?.id,
                evidencias: [],
                evidenciaDescripciones: []
            });
            ticketId = ticket?.ticket_id || null;
        }

        const solicitud = await sgcSolicitudDocumentosService.cerrarConNotificacion(pool, req.params.id, {
            notificar,
            ticketId,
            notasCambio: descripcion
        });

        res.json({
            success: true,
            solicitud,
            ticket,
            message: notificar
                ? 'Solicitud cerrada y ticket enviado a Sistemas'
                : 'Solicitud cerrada sin notificar a Sistemas'
        });
    } catch (error) {
        const status = error.status || 500;
        if (status >= 400 && status < 500) {
            return res.status(status).json({ success: false, message: error.message });
        }
        handleError(res, error, 'Error al cerrar solicitud de documento');
    }
});

