/**
 * POST /api/opiniones
 * Perfil empresa envía el mensaje. El nombre de empresa se toma de su cuenta.
 * No se escribe en SGC ni en SGC-F-05.
 */
app.post('/api/opiniones', authMiddleware, requireRole('empresa'), async (req, res) => {
    try {
        let cliente = '';
        let empresaId = req.user?.empresa_id || null;
        if (empresaId) {
            const [empresaRows] = await pool.query(
                'SELECT nombre_empresa FROM empresa WHERE empresa_id = ? LIMIT 1',
                [empresaId]
            );
            if (empresaRows.length > 0) {
                cliente = empresaRows[0].nombre_empresa;
            }
        }
        if (!cliente) {
            return res.status(400).json({
                success: false,
                message: 'No se pudo identificar la empresa del usuario'
            });
        }
        const opinion = await opinionesService.crear(pool, {
            tipo: req.body?.tipo,
            descripcion: req.body?.descripcion,
            cliente,
            empresaId,
            usuarioId: req.user?.id
        });
        try { require('./sgcDashboardService').invalidarCacheDashboard(); } catch (_e) { /* dashboard aún no cargado */ }
        res.status(201).json({ success: true, opinion });
    } catch (error) {
        const status = error.status || 500;
        if (status >= 400 && status < 500) {
            return res.status(status).json({ success: false, message: error.message });
        }
        handleError(res, error, 'Error al registrar la opinión');
    }
});

