const CONTROL_CAPACITACION_TEMPLATE_SHEET_ID = String(process.env.CONTROL_CAPACITACION_TEMPLATE_SHEET_ID || '19iQ0A_RMLjXdy60NUeAdEBJiG0ksYXKtLSBBM589S7A').trim();
const CONTROL_CAPACITACION_DATA_START_ROW = 5;
const CONTROL_CAPACITACION_TOTAL_COLS = 19;
const CONTROL_CAPACITACION_DRIVE_FOLDER_ID = process.env.CONTROL_CAPACITACION_DRIVE_FOLDER_ID || '1Bse1AqnZXVfWuBOHiwtAYi9JOrIYufMZ';
const CONTROL_CAPACITACION_COLUMNS = {
    no: 1,
    empresa: 2,
    curso: 3,
    dia: 5,
    fecha: 6,
    horario: 7,
    horas: 8,
    modalidad: 9,
    instructor: 10,
    lugar: 11,
    participantes: 12,
    acreditaciones: 13,
    estatusAcreditaciones: 14,
    rfc: 15,
    email: 16,
    observaciones: 17
};

const DIAS_SEMANA_CORTO = ['Domingo', 'Lunes', 'Martes', 'Miercoles', 'Jueves', 'Viernes', 'Sabado'];

function formatFechaControl(fecha) {
    if (!fecha) return '';
    const dt = new Date(fecha);
    if (Number.isNaN(dt.getTime())) return '';
    dt.setMinutes(dt.getMinutes() + dt.getTimezoneOffset());
    const d = String(dt.getDate()).padStart(2, '0');
    const m = String(dt.getMonth() + 1).padStart(2, '0');
    const y = dt.getFullYear();
    return `${d}/${m}/${y}`;
}

function formatDiaSemanaControl(fecha) {
    if (!fecha) return '';
    const dt = new Date(fecha);
    if (Number.isNaN(dt.getTime())) return '';
    dt.setMinutes(dt.getMinutes() + dt.getTimezoneOffset());
    return DIAS_SEMANA_CORTO[dt.getDay()] || '';
}

function formatHorarioControl(horaInicio, horaFin) {
    if (!horaInicio || !horaFin) return '';
    const to12h = (raw) => {
        const val = String(raw || '').substring(0, 5);
        const [hTxt, mTxt] = val.split(':');
        const h24 = Number(hTxt);
        const m = Number(mTxt);
        if (Number.isNaN(h24) || Number.isNaN(m)) return val;
        const period = h24 >= 12 ? 'pm' : 'am';
        const h12 = (h24 % 12) || 12;
        return `${h12} ${period}`;
    };

    return `${to12h(horaInicio)} - ${to12h(horaFin)}`;
}

function formatModalidadControl(modalidad) {
    const val = String(modalidad || '').toLowerCase();
    if (val === 'presencial') return 'Presencial';
    if (val === 'virtual') return 'Virtual';
    if (val === 'hibrido') return 'Híbrido';
    return modalidad || 'Presencial';
}

function buildNombreControlCapacitacion(extension = 'pdf') {
    const fecha = new Date();
    const yyyy = fecha.getFullYear();
    const mm = String(fecha.getMonth() + 1).padStart(2, '0');
    const dd = String(fecha.getDate()).padStart(2, '0');
    return `control_capacitacion_empresarial_${yyyy}${mm}${dd}.${extension}`;
}

function buildNombreHojaControlCapacitacion(year) {
    return `Capacitación empresarial ${year}`;
}

function formatFechaCompactaControl(fecha = new Date()) {
    const yyyy = fecha.getFullYear();
    const mm = String(fecha.getMonth() + 1).padStart(2, '0');
    const dd = String(fecha.getDate()).padStart(2, '0');
    return `${yyyy}${mm}${dd}`;
}

function buildNombreArchivoControlCapacitacionDrive(year) {
    return `${year} Control de capacitación empresarial.xlsx`;
}

function normalizarTextoControl(valor = '') {
    return String(valor)
        .normalize('NFD')
        .replace(/[\u0300-\u036f]/g, '')
        .toLowerCase();
}

function deepClone(value) {
    if (value === undefined || value === null) return value;
    return JSON.parse(JSON.stringify(value));
}

function copiarEstructuraHojaTemplate(origen, destino, maxRows = 80, maxCols = CONTROL_CAPACITACION_TOTAL_COLS) {
    for (let c = 1; c <= maxCols; c++) {
        const colOrigen = origen.getColumn(c);
        const colDestino = destino.getColumn(c);
        colDestino.width = colOrigen.width;
        colDestino.hidden = colOrigen.hidden;
        colDestino.style = deepClone(colOrigen.style) || {};
    }

    for (let r = 1; r <= maxRows; r++) {
        const rowOrigen = origen.getRow(r);
        const rowDestino = destino.getRow(r);
        rowDestino.height = rowOrigen.height;
        rowDestino.hidden = rowOrigen.hidden;

        for (let c = 1; c <= maxCols; c++) {
            const celdaOrigen = rowOrigen.getCell(c);
            const celdaDestino = rowDestino.getCell(c);
            celdaDestino.value = deepClone(celdaOrigen.value);
            celdaDestino.style = deepClone(celdaOrigen.style) || {};
        }
    }

    const merges = (origen.model && Array.isArray(origen.model.merges)) ? origen.model.merges : [];
    merges.forEach((mergeRange) => {
        try {
            destino.mergeCells(mergeRange);
        } catch (e) {
            // ignore merge conflict
        }
    });

    destino.pageSetup = deepClone(origen.pageSetup) || {};
    destino.headerFooter = deepClone(origen.headerFooter) || {};
    destino.views = deepClone(origen.views) || [];
}

function estatusAcreditacionesControl(participantes, acreditaciones, tieneEntregaDocumentos) {
    // SP-F-03 firmado implica entrega documental: prevalece sobre estatus históricos incompletos en BD.
    if (tieneEntregaDocumentos) return 'Entregadas';
    const completos = participantes > 0 && acreditaciones >= participantes;
    if (!completos) return 'No realizadas';
    return 'Generadas';
}

/** Dashboard: considerar finalizado por estatus; para estatus legacy usar fallback por fecha pasada. */
function esCursoFinalizadoDashboard(row) {
    const estatusNoFinalizados = new Set(['programado', 'en_curso', 'pospuesto', 'cancelado']);
    const estatusFinalizados = new Set(['completado', 'finalizado', 'cerrado', 'terminado']);
    const estatus = String(row?.estatus || '').trim().toLowerCase();

    if (estatusNoFinalizados.has(estatus)) {
        return false;
    }

    if (estatusFinalizados.has(estatus)) {
        return true;
    }

    const fechaRef = row?.fecha_fin || row?.fecha_inicio;
    if (!fechaRef) {
        return false;
    }

    const fin = new Date(fechaRef);
    if (Number.isNaN(fin.getTime())) {
        return false;
    }

    fin.setHours(23, 59, 59, 999);
    const hoy = new Date();
    hoy.setHours(23, 59, 59, 999);
    const fechaPasada = fin.getTime() <= hoy.getTime();

    return fechaPasada;
}

/** Misma lógica que Historial de Cursos (cursoTieneAnexoSubido) para KPIs y gráficos del dashboard. */
function cursoTieneAnexoSubidoDashboard(row) {
    if (Boolean(Number(row?.tiene_entrega_documentos || 0))) {
        return true;
    }

    const participantes = Number(row?.total_participantes || 0);
    const acreditacionesBd = Number(row?.total_acreditaciones || 0);
    const tieneDocumentosAcreditacion = Boolean(Number(row?.tiene_documentos_acreditacion || 0));
    const acreditaciones = (acreditacionesBd >= participantes && participantes > 0)
        ? acreditacionesBd
        : (tieneDocumentosAcreditacion && participantes > 0 ? participantes : acreditacionesBd);
    const tieneEntregaDocumentos = Boolean(Number(row?.tiene_entrega_documentos || 0));

    if (estatusAcreditacionesControl(participantes, acreditaciones, tieneEntregaDocumentos) === 'Entregadas') {
        return true;
    }

    const estatusAcreditaciones = String(row?.estatus_acreditaciones || '').trim().toLowerCase();
    if (estatusAcreditaciones === 'entregadas') {
        return true;
    }

    const estatusAnexo = String(row?.estatus_anexo || row?.estatus_entrega_documentos || '').trim().toLowerCase();
    return ['subido', 'entregado', 'cargado', 'firmado', 'completado'].includes(estatusAnexo);
}

const SQL_SUBQUERY_ANEXO_SPF03 = `
    SELECT programado_id, 1 AS tiene_entrega_documentos
    FROM documento_curso_programado
    WHERE descripcion = 'entrega_documentos_spf03_firmado'
       OR descripcion LIKE 'entrega_documentos_spf03%'
       OR tipo_documento = 'entrega_documentos'
       OR LOWER(nombre_archivo) LIKE '%sp-f-03%'
       OR LOWER(nombre_archivo) LIKE '%sp_f_03%'
       OR LOWER(nombre_archivo) LIKE '%sp f 03%'
       OR LOWER(nombre_archivo) LIKE '%spf03%'
       OR LOWER(descripcion) LIKE '%sp-f-03%'
       OR LOWER(descripcion) LIKE '%sp_f_03%'
       OR LOWER(descripcion) LIKE '%sp f 03%'
       OR LOWER(descripcion) LIKE '%spf03%'
       OR LOWER(descripcion) LIKE '%entrega_documentos%'
    GROUP BY programado_id
`;

function aplicarEstiloBaseFila(worksheet, sourceRowIdx, targetRowIdx) {
    const sourceRow = worksheet.getRow(sourceRowIdx);
    const targetRow = worksheet.getRow(targetRowIdx);
    targetRow.height = sourceRow.height;
    for (let c = 1; c <= CONTROL_CAPACITACION_TOTAL_COLS; c++) {
        targetRow.getCell(c).style = deepClone(sourceRow.getCell(c).style) || {};
        targetRow.getCell(c).value = null;
    }
}

function aplicarTipografiaTitulosControl(worksheet) {
    for (let rowIdx = 1; rowIdx <= 4; rowIdx++) {
        const row = worksheet.getRow(rowIdx);
        for (let col = 1; col <= CONTROL_CAPACITACION_TOTAL_COLS; col++) {
            const cell = row.getCell(col);
            cell.font = {
                ...(cell.font || {}),
                name: 'Calibri',
                size: 10
            };
        }
    }

    for (let rowIdx = 1; rowIdx <= 4; rowIdx++) {
        const row = worksheet.getRow(rowIdx);
        for (let col = 1; col <= CONTROL_CAPACITACION_TOTAL_COLS; col++) {
            const cell = row.getCell(col);
            const raw = cell.value;
            const txt = typeof raw === 'string' ? raw : (raw && raw.richText ? raw.richText.map((r) => r.text || '').join('') : '');
            const normalizado = String(txt || '')
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .toUpperCase();
            if (normalizado.includes('CONTROL DE CAPACITACION EMPRESARIAL')) {
                cell.font = {
                    ...(cell.font || {}),
                    name: 'Calibri',
                    size: 17,
                    bold: true
                };
            }
        }
    }
}

function asegurarMergeFilaControl(worksheet, rowIndex) {
    const mergeRanges = [`C${rowIndex}:D${rowIndex}`, `Q${rowIndex}:S${rowIndex}`];
    for (const range of mergeRanges) {
        try {
            worksheet.mergeCells(range);
        } catch (_error) {
            // Si ya estaba combinado, no hacemos nada.
        }
    }
}

function aplicarBordeDerechoObservaciones(worksheet, startRow, endRow) {
    for (let rowIdx = startRow; rowIdx <= endRow; rowIdx++) {
        const cell = worksheet.getRow(rowIdx).getCell(CONTROL_CAPACITACION_COLUMNS.observaciones);
        const baseBorder = cell.border || {};
        cell.border = {
            ...baseBorder,
            right: { style: 'medium', color: { argb: 'FF000000' } }
        };
    }
}

function poblarHojaControl(worksheet, year, registros, overrides = new Map()) {
    aplicarTipografiaTitulosControl(worksheet);

    const generatedTextCell = worksheet.getCell('A2');
    if (generatedTextCell && typeof generatedTextCell.value === 'string' && generatedTextCell.value.toUpperCase().includes('AÑO')) {
        generatedTextCell.value = `Año ${year} - Generado ${formatFechaControl(new Date())}`;
    }

    const baseDataStyleRow = CONTROL_CAPACITACION_DATA_START_ROW;

    for (let i = 0; i < registros.length; i++) {
        const excelRow = CONTROL_CAPACITACION_DATA_START_ROW + i;
        if (excelRow > baseDataStyleRow) {
            aplicarEstiloBaseFila(worksheet, baseDataStyleRow, excelRow);
        }

        const item = registros[i];
        const row = worksheet.getRow(excelRow);
        asegurarMergeFilaControl(worksheet, excelRow);
        const participantes = Number(item.total_participantes || 0);
        const acreditacionesBd = Number(item.total_acreditaciones || 0);
        const tieneDocumentosAcreditacion = Boolean(Number(item.tiene_documentos_acreditacion || 0));
        const acreditaciones = (acreditacionesBd >= participantes && participantes > 0)
            ? acreditacionesBd
            : (tieneDocumentosAcreditacion && participantes > 0 ? participantes : acreditacionesBd);
        const tieneEntregaDocumentos = Boolean(Number(item.tiene_entrega_documentos || 0));
        const estatus = estatusAcreditacionesControl(participantes, acreditaciones, tieneEntregaDocumentos);

        // Valores calculados automáticamente
        const calcHorario = formatHorarioControl(item.hora_inicio, item.hora_fin);
        const calcHoras = Number(item.curso_horas || 0) || '';
        const calcModalidad = formatModalidadControl(item.modalidad);
        const calcInstructor = item.instructor_nombre || '';
        const calcLugar = item.ubicacion || '';
        const calcAcreditaciones = (acreditaciones > 0 || tieneEntregaDocumentos || tieneDocumentosAcreditacion)
            ? 'DC-3 y diplomas'
            : 'Sin acreditaciones';
        const calcRfc = item.rfc || '';
        const calcEmail = item.email_representante || '';

        // Buscar override del admin en el archivo Drive previo
        const empresaKey = String(item.nombre_empresa || '').trim();
        const cursoKey = String(item.nombre_curso || `Curso ID ${item.curso_id || ''}`).trim();
        const fechaKey = formatFechaControl(item.fecha_inicio);
        const overrideKey = `${empresaKey}|${cursoKey}|${fechaKey}`;
        const override = overrides.get(overrideKey);
        const driveRow = override?._driveRow || {};

        row.getCell(CONTROL_CAPACITACION_COLUMNS.no).value = i + 1;
        row.getCell(CONTROL_CAPACITACION_COLUMNS.empresa).value = empresaKey;
        row.getCell(CONTROL_CAPACITACION_COLUMNS.curso).value = cursoKey;
        row.getCell(CONTROL_CAPACITACION_COLUMNS.dia).value = formatDiaSemanaControl(item.fecha_inicio);
        row.getCell(CONTROL_CAPACITACION_COLUMNS.fecha).value = fechaKey;
        row.getCell(CONTROL_CAPACITACION_COLUMNS.horario).value = resolverValorConOverride(calcHorario, driveRow.horario);
        row.getCell(CONTROL_CAPACITACION_COLUMNS.horas).value = resolverValorConOverride(calcHoras, driveRow.horas);
        row.getCell(CONTROL_CAPACITACION_COLUMNS.modalidad).value = resolverValorConOverride(calcModalidad, driveRow.modalidad);
        row.getCell(CONTROL_CAPACITACION_COLUMNS.instructor).value = resolverValorConOverride(calcInstructor, driveRow.instructor);
        row.getCell(CONTROL_CAPACITACION_COLUMNS.lugar).value = resolverValorConOverride(calcLugar, driveRow.lugar);
        row.getCell(CONTROL_CAPACITACION_COLUMNS.participantes).value = resolverValorConOverride(participantes, driveRow.participantes);
        row.getCell(CONTROL_CAPACITACION_COLUMNS.acreditaciones).value = resolverValorConOverride(calcAcreditaciones, driveRow.acreditaciones);
        row.getCell(CONTROL_CAPACITACION_COLUMNS.estatusAcreditaciones).value = estatus;
        row.getCell(CONTROL_CAPACITACION_COLUMNS.rfc).value = resolverValorConOverride(calcRfc, driveRow.rfc);
        row.getCell(CONTROL_CAPACITACION_COLUMNS.email).value = resolverValorConOverride(calcEmail, driveRow.email);
        // Observaciones: siempre preservar el valor del Drive (nunca sobreescribir)
        const obsPreservada = override ? (override.observaciones ?? null) : null;
        row.getCell(CONTROL_CAPACITACION_COLUMNS.observaciones).value = obsPreservada !== null ? obsPreservada : (item.observaciones || '');

        for (let col = 1; col <= CONTROL_CAPACITACION_TOTAL_COLS; col++) {
            const cell = row.getCell(col);
            cell.font = {
                ...(cell.font || {}),
                name: 'Calibri',
                size: 10,
                bold: false
            };
        }

        const empresaCell = row.getCell(CONTROL_CAPACITACION_COLUMNS.empresa);
        empresaCell.font = {
            ...(empresaCell.font || {}),
            name: 'Calibri',
            size: 10,
            bold: true
        };

        const noCell = row.getCell(CONTROL_CAPACITACION_COLUMNS.no);
        noCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FF00B050' } };
        noCell.font = {
            ...(noCell.font || {}),
            name: 'Calibri',
            size: 10,
            color: { argb: 'FF000000' },
            bold: false
        };

        const estatusCell = row.getCell(CONTROL_CAPACITACION_COLUMNS.estatusAcreditaciones);
        if (estatus === 'Entregadas') {
            estatusCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFB7E1CD' } };
            estatusCell.font = {
                ...(estatusCell.font || {}),
                name: 'Calibri',
                size: 10,
                color: { argb: 'FF0B7A34' },
                bold: false
            };
        } else if (estatus === 'Generadas') {
            estatusCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFFCE5CD' } };
            estatusCell.font = {
                ...(estatusCell.font || {}),
                name: 'Calibri',
                size: 10,
                color: { argb: 'FF9C6500' },
                bold: false
            };
        } else {
            estatusCell.fill = { type: 'pattern', pattern: 'solid', fgColor: { argb: 'FFF4CCCC' } };
            estatusCell.font = {
                ...(estatusCell.font || {}),
                name: 'Calibri',
                size: 10,
                color: { argb: 'FFC00000' },
                bold: false
            };
        }

        // Ajuste dinámico de altura para evitar texto cortado en celdas con wrap.
        const textosFila = [
            row.getCell(CONTROL_CAPACITACION_COLUMNS.curso).value,
            row.getCell(CONTROL_CAPACITACION_COLUMNS.instructor).value,
            row.getCell(CONTROL_CAPACITACION_COLUMNS.acreditaciones).value,
            row.getCell(CONTROL_CAPACITACION_COLUMNS.email).value,
            row.getCell(CONTROL_CAPACITACION_COLUMNS.observaciones).value
        ].map((v) => String(v || ''));
        const lineasEstimadas = Math.max(1, ...textosFila.map((t) => Math.ceil(t.length / 24)));
        const alturaBase = Number(row.height || 24);
        row.height = Math.max(alturaBase, Math.min(84, 18 * lineasEstimadas));
    }

    const cleanupStart = CONTROL_CAPACITACION_DATA_START_ROW + registros.length;
    const cleanupEnd = Math.max(cleanupStart, CONTROL_CAPACITACION_DATA_START_ROW + 120);
    for (let row = cleanupStart; row <= cleanupEnd; row++) {
        const rowObj = worksheet.getRow(row);
        for (let col = 1; col <= CONTROL_CAPACITACION_TOTAL_COLS; col++) {
            rowObj.getCell(col).value = null;
        }
    }

    const lastDataRow = Math.max(CONTROL_CAPACITACION_DATA_START_ROW, CONTROL_CAPACITACION_DATA_START_ROW + registros.length - 1);

    // Refuerza solo el borde derecho exterior de Observaciones, sin alterar bordes inferiores.
    aplicarBordeDerechoObservaciones(worksheet, 1, lastDataRow);

    worksheet.pageSetup = {
        ...(worksheet.pageSetup || {}),
        fitToPage: true,
        fitToWidth: 1,
        fitToHeight: 0,
        printArea: `A1:S${lastDataRow}`
    };
}

function mapearRegistroControlCapacitacion(item, numero = 1) {
    const participantes = Number(item.total_participantes || 0);
    const acreditacionesBd = Number(item.total_acreditaciones || 0);
    const tieneDocumentosAcreditacion = Boolean(Number(item.tiene_documentos_acreditacion || 0));
    const acreditaciones = (acreditacionesBd >= participantes && participantes > 0)
        ? acreditacionesBd
        : (tieneDocumentosAcreditacion && participantes > 0 ? participantes : acreditacionesBd);
    const tieneEntregaDocumentos = Boolean(Number(item.tiene_entrega_documentos || 0));
    const estatus = estatusAcreditacionesControl(participantes, acreditaciones, tieneEntregaDocumentos);

    return {
        no: numero,
        programado_id: item.programado_id,
        empresa_id: item.empresa_id,
        empresa: String(item.nombre_empresa || '').trim(),
        nombre_curso: String(item.nombre_curso || `Curso ID ${item.curso_id || ''}`).trim(),
        dia: formatDiaSemanaControl(item.fecha_inicio),
        fecha: formatFechaControl(item.fecha_inicio),
        fecha_inicio: item.fecha_inicio,
        horario: formatHorarioControl(item.hora_inicio, item.hora_fin),
        horas: Number(item.curso_horas || 0) || null,
        modalidad: formatModalidadControl(item.modalidad),
        instructor: item.instructor_nombre || '',
        lugar: item.ubicacion || '',
        numero_participantes: participantes,
        acreditaciones: (acreditaciones > 0 || tieneEntregaDocumentos || tieneDocumentosAcreditacion)
            ? 'DC-3 y diplomas'
            : 'Sin acreditaciones',
        estatus_acreditaciones: estatus,
        rfc: item.rfc || '',
        email_representante: item.email_representante || '',
        observaciones: item.observaciones || '',
        ultima_descarga_constancias_por: item.ultima_descarga_constancias_por || null,
        ultima_descarga_constancias_fecha: serializarFechaHoraMexicoMySQL(item.ultima_descarga_constancias_fecha)
    };
}

async function obtenerDatosControlCapacitacion() {
    await asegurarColumnasHistorialDescargasCursoProgramado(pool);

    const [rows] = await pool.query(`
        SELECT
            cp.programado_id,
            cp.curso_id,
            cp.empresa_id,
            cp.fecha_inicio,
            cp.hora_inicio,
            cp.hora_fin,
            cp.modalidad,
            cp.ubicacion,
            cp.notas AS observaciones,
            cp.ultima_descarga_constancias_por,
            DATE_FORMAT(cp.ultima_descarga_constancias_fecha, '%Y-%m-%d %H:%i:%s') AS ultima_descarga_constancias_fecha,
            COALESCE(NULLIF(TRIM(c.nombre_curso), ''), CONCAT('Curso ID ', cp.curso_id)) AS nombre_curso,
            c.horas AS curso_horas,
            e.nombre_empresa,
            e.rfc,
            COALESCE(NULLIF(e.contacto_email, ''), NULLIF(e.email, ''), '') AS email_representante,
            CONCAT_WS(' ', i.nombre, i.apellido_paterno, i.apellido_materno) AS instructor_nombre,
            COALESCE(SUM(CASE WHEN ic.activo = 1 THEN 1 ELSE 0 END), 0) AS total_participantes,
            COALESCE(SUM(CASE WHEN ic.activo = 1 AND ic.certificado_generado = 1 THEN 1 ELSE 0 END), 0) AS total_acreditaciones,
            COALESCE(MAX(dcp_spf03.tiene_entrega_documentos), 0) AS tiene_entrega_documentos,
            COALESCE(MAX(dcp_acc.tiene_documentos_acreditacion), 0) AS tiene_documentos_acreditacion
        FROM curso_programado cp
        LEFT JOIN curso c ON c.curso_id = cp.curso_id
        JOIN empresa e ON e.empresa_id = cp.empresa_id
        LEFT JOIN instructor i ON i.instructor_id = cp.instructor_id
        LEFT JOIN inscripcion_curso ic ON ic.programado_id = cp.programado_id
        LEFT JOIN (
            SELECT programado_id, 1 AS tiene_entrega_documentos
            FROM documento_curso_programado
            WHERE descripcion = 'entrega_documentos_spf03_firmado'
               OR descripcion LIKE 'entrega_documentos_spf03%'
               OR tipo_documento = 'entrega_documentos'
               OR LOWER(nombre_archivo) LIKE '%sp-f-03%'
               OR LOWER(nombre_archivo) LIKE '%sp_f_03%'
               OR LOWER(nombre_archivo) LIKE '%sp f 03%'
               OR LOWER(nombre_archivo) LIKE '%spf03%'
               OR LOWER(descripcion) LIKE '%sp-f-03%'
               OR LOWER(descripcion) LIKE '%sp_f_03%'
               OR LOWER(descripcion) LIKE '%sp f 03%'
               OR LOWER(descripcion) LIKE '%spf03%'
               OR LOWER(descripcion) LIKE '%entrega_documentos%'
            GROUP BY programado_id
        ) dcp_spf03 ON dcp_spf03.programado_id = cp.programado_id
        LEFT JOIN (
            SELECT programado_id,
                MAX(CASE
                    WHEN descripcion LIKE 'constancia_inscripcion_%'
                      OR descripcion LIKE 'dc3_inscripcion_%'
                      OR descripcion LIKE 'constancias_lote%'
                      OR descripcion LIKE 'dc3_lote%'
                    THEN 1 ELSE 0
                END) AS tiene_documentos_acreditacion
            FROM documento_curso_programado
            GROUP BY programado_id
        ) dcp_acc ON dcp_acc.programado_id = cp.programado_id
        WHERE cp.estatus != 'cancelado'
        GROUP BY
            cp.programado_id,
            cp.curso_id,
            cp.empresa_id,
            cp.fecha_inicio,
            cp.hora_inicio,
            cp.hora_fin,
            cp.modalidad,
            cp.ubicacion,
            cp.notas,
            cp.ultima_descarga_constancias_por,
            cp.ultima_descarga_constancias_fecha,
            c.nombre_curso,
            c.horas,
            e.nombre_empresa,
            e.rfc,
            e.contacto_email,
            e.email,
            i.nombre,
            i.apellido_paterno,
            i.apellido_materno
        ORDER BY cp.fecha_inicio ASC, cp.programado_id ASC
    `);
    return rows;
}

function agruparControlPorAnio(rows) {
    const byYear = new Map();
    rows.forEach((row) => {
        const dt = new Date(row.fecha_inicio);
        const year = Number.isNaN(dt.getTime()) ? new Date().getFullYear() : dt.getFullYear();
        if (!byYear.has(year)) byYear.set(year, []);
        byYear.get(year).push(row);
    });
    return byYear;
}

async function generarControlCapacitacionEmpresarialExcel(options = {}) {
    const ExcelJS = require('exceljs');
    const soloAnio = Number(options.soloAnio || 0) || null;
    const overrides = options.overrides instanceof Map ? options.overrides : new Map();
    const rows = await obtenerDatosControlCapacitacion();

    if (!rows.length) {
        const err = new Error('No hay cursos programados para generar el control de capacitación empresarial.');
        err.statusCode = 404;
        throw err;
    }

    const byYear = agruparControlPorAnio(rows);
    const anios = Array.from(byYear.keys()).sort((a, b) => a - b);

    const templateBuffer = await driveService.exportarArchivoXLSX(CONTROL_CAPACITACION_TEMPLATE_SHEET_ID);
    const templateWorkbook = new ExcelJS.Workbook();
    await templateWorkbook.xlsx.load(templateBuffer);

    if (!templateWorkbook.worksheets.length) {
        const err = new Error('La plantilla de Control de Capacitacion no contiene hojas.');
        err.statusCode = 500;
        throw err;
    }

    const workbook = templateWorkbook;
    workbook.creator = 'Biznaga R&T';
    workbook.created = new Date();
    const templateSheet = workbook.worksheets[0];

    // Si la plantilla trae hojas de ejemplo adicionales, se eliminan para evitar
    // conflictos de nombre al renombrar/generar por año.
    if (workbook.worksheets.length > 1) {
        for (let i = workbook.worksheets.length - 1; i >= 1; i--) {
            workbook.removeWorksheet(workbook.worksheets[i].id);
        }
    }

    const aniosObjetivo = soloAnio ? anios.filter((y) => y === soloAnio) : anios;
    if (!aniosObjetivo.length) {
        const err = new Error('No hay cursos del año solicitado para generar el control.');
        err.statusCode = 404;
        throw err;
    }

    const hojasPorAnio = new Map();
    const primerAnio = aniosObjetivo[0];
    templateSheet.name = buildNombreHojaControlCapacitacion(primerAnio);
    hojasPorAnio.set(primerAnio, templateSheet);

    for (let i = 1; i < aniosObjetivo.length; i++) {
        const year = aniosObjetivo[i];
        const worksheet = workbook.addWorksheet(buildNombreHojaControlCapacitacion(year));
        const registrosAnio = byYear.get(year) || [];
        const minFilas = 14;
        const maxRows = Math.max(minFilas, CONTROL_CAPACITACION_DATA_START_ROW + registrosAnio.length + 3);
        copiarEstructuraHojaTemplate(templateSheet, worksheet, maxRows, CONTROL_CAPACITACION_TOTAL_COLS);
        hojasPorAnio.set(year, worksheet);
    }

    aniosObjetivo.forEach((year) => {
        const worksheet = hojasPorAnio.get(year);
        const registrosAnio = byYear.get(year) || [];
        poblarHojaControl(worksheet, year, registrosAnio, overrides);
    });

    const buffer = await workbook.xlsx.writeBuffer();
    return {
        buffer: Buffer.from(buffer),
        nombreArchivo: buildNombreControlCapacitacion('xlsx'),
        anios: aniosObjetivo
    };
}

async function generarControlCapacitacionEmpresarialPdf() {
    const anioActual = new Date().getFullYear();
    const excel = await generarControlCapacitacionEmpresarialExcel({ soloAnio: anioActual });
    const tempFolderId = await driveService.obtenerOCrearCarpeta('Reportes_Temporales');

    let tempDriveFileId = null;
    try {
        const upload = await driveService.subirExcelComoGoogleSheet(
            excel.buffer,
            `tmp_${Date.now()}_${excel.nombreArchivo}`,
            tempFolderId,
            {
                keepSingleSheet: true,
                sheetTitle: buildNombreHojaControlCapacitacion(anioActual),
                maxColumns: CONTROL_CAPACITACION_TOTAL_COLS
            }
        );
        tempDriveFileId = upload.id;

        const pdfBuffer = await driveService.exportarArchivoPDF(tempDriveFileId, { landscape: true });
        return {
            buffer: pdfBuffer,
            nombreArchivo: buildNombreControlCapacitacion('pdf'),
            anios: excel.anios
        };
    } finally {
        if (tempDriveFileId) {
            try {
                await driveService.eliminarArchivo(tempDriveFileId);
            } catch (cleanupError) {
                console.warn('[WARN] No se pudo eliminar el archivo temporal del control de capacitación:', cleanupError.message);
            }
        }
    }
}

async function resolverCarpetaControlCapacitacionDrive(fechaRef = new Date()) {
    const fecha = new Date(fechaRef);
    const anio = fecha.getFullYear();

    return {
        folderId: CONTROL_CAPACITACION_DRIVE_FOLDER_ID,
        anio,
        path: 'ControlCapacitacion'
    };
}

async function obtenerEstadoControlCapacitacionExcelDrive(anio = new Date().getFullYear()) {
    const carpeta = await resolverCarpetaControlCapacitacionDrive(new Date());
    const archivos = await driveService.listarArchivosCarpeta(carpeta.folderId);
    const nombreObjetivo = normalizarTextoControl(`${anio} Control de capacitación empresarial`);

    const candidatos = (archivos || [])
        .filter((f) => {
            const name = String(f.name || '');
            const nameNorm = normalizarTextoControl(name);
            return nameNorm.startsWith(nombreObjetivo) && nameNorm.endsWith('.xlsx');
        })
        .sort((a, b) => new Date(b.modifiedTime || 0).getTime() - new Date(a.modifiedTime || 0).getTime());

    const ultimo = candidatos[0] || null;
    return {
        existe: !!ultimo,
        archivo: ultimo,
        candidatos,
        carpeta
    };
}

/**
 * Lee el Excel existente en Drive y extrae los valores que el administrador
 * pudo haber modificado manualmente. Devuelve un Map donde la clave es
 * "<empresa>|<curso>|<fecha>" y el valor es un objeto con los campos
 * que deben preservarse al actualizar.
 *
 * Siempre se preserva la columna "Observaciones".
 * Para las demás columnas auto-generadas, si el valor en Drive difiere del
 * valor que el sistema habría calculado automáticamente, se considera una
 * edición manual y también se preserva.
 */
async function leerOverridesControlDrive(archivoId, anio) {
    const ExcelJS = require('exceljs');
    try {
        const buffer = await driveService.descargarArchivo(archivoId);
        const wb = new ExcelJS.Workbook();
        await wb.xlsx.load(buffer);

        const nombreHoja = buildNombreHojaControlCapacitacion(anio);
        const ws = wb.getWorksheet(nombreHoja) || wb.worksheets[0];
        if (!ws) return new Map();

        const overrides = new Map();
        const dataStart = CONTROL_CAPACITACION_DATA_START_ROW;

        ws.eachRow((row, rowNumber) => {
            if (rowNumber < dataStart) return;
            const noVal = row.getCell(CONTROL_CAPACITACION_COLUMNS.no).value;
            if (!noVal && noVal !== 0) return;

            const empresa = String(row.getCell(CONTROL_CAPACITACION_COLUMNS.empresa).value || '').trim();
            const curso = String(row.getCell(CONTROL_CAPACITACION_COLUMNS.curso).value || '').trim();
            const fecha = String(row.getCell(CONTROL_CAPACITACION_COLUMNS.fecha).value || '').trim();
            if (!empresa && !curso) return;

            const key = `${empresa}|${curso}|${fecha}`;
            overrides.set(key, {
                // Siempre preservar Observaciones
                observaciones: row.getCell(CONTROL_CAPACITACION_COLUMNS.observaciones).value,
                // Campos que el admin puede haber editado manualmente (estatus se recalcula)
                _driveRow: {
                    horario: row.getCell(CONTROL_CAPACITACION_COLUMNS.horario).value,
                    horas: row.getCell(CONTROL_CAPACITACION_COLUMNS.horas).value,
                    modalidad: row.getCell(CONTROL_CAPACITACION_COLUMNS.modalidad).value,
                    instructor: row.getCell(CONTROL_CAPACITACION_COLUMNS.instructor).value,
                    lugar: row.getCell(CONTROL_CAPACITACION_COLUMNS.lugar).value,
                    participantes: row.getCell(CONTROL_CAPACITACION_COLUMNS.participantes).value,
                    acreditaciones: row.getCell(CONTROL_CAPACITACION_COLUMNS.acreditaciones).value,
                    rfc: row.getCell(CONTROL_CAPACITACION_COLUMNS.rfc).value,
                    email: row.getCell(CONTROL_CAPACITACION_COLUMNS.email).value,
                }
            });
        });

        return overrides;
    } catch (e) {
        console.warn('[WARN] No se pudo leer el Excel existente para preservar overrides:', e.message);
        return new Map();
    }
}

/**
 * Compara el valor calculado automáticamente con el valor en Drive.
 * Si difieren, retorna el valor de Drive (edición manual del admin).
 * Si son iguales, retorna el valor calculado.
 */
function resolverValorConOverride(valorCalculado, valorDrive) {
    if (valorDrive === null || valorDrive === undefined) return valorCalculado;
    const calcStr = String(valorCalculado ?? '').trim();
    const driveStr = String(valorDrive ?? '').trim();
    if (driveStr === '' && calcStr !== '') return valorCalculado;
    if (calcStr !== driveStr) return valorDrive;
    return valorCalculado;
}

async function guardarControlCapacitacionExcelEnDrive(anio = new Date().getFullYear()) {
    const estadoPrevio = await obtenerEstadoControlCapacitacionExcelDrive(anio);

    // Leer overrides del archivo existente antes de eliminarlo
    let overrides = new Map();
    if (estadoPrevio.existe && estadoPrevio.archivo?.id) {
        overrides = await leerOverridesControlDrive(estadoPrevio.archivo.id, anio);
    }

    const excel = await generarControlCapacitacionEmpresarialExcel({ soloAnio: anio, overrides });
    const nombreArchivo = buildNombreArchivoControlCapacitacionDrive(anio);

    if (estadoPrevio.candidatos.length) {
        for (const archivoPrevio of estadoPrevio.candidatos) {
            try {
                await driveService.eliminarArchivo(archivoPrevio.id);
            } catch (e) {
                console.warn('[WARN] No se pudo eliminar una versión previa del control de capacitación:', e.message);
            }
        }
    }

    const archivoSubido = await driveService.subirArchivo(
        excel.buffer,
        nombreArchivo,
        'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
        estadoPrevio.carpeta.folderId
    );

    return {
        accion: estadoPrevio.existe ? 'actualizado' : 'generado',
        archivo: archivoSubido,
        carpeta: estadoPrevio.carpeta
    };
}

// Helper para queries cross-database seguras
const safeQuery = async (poolRef, query, fallback = null) => {
    try {
        if (!poolRef) return fallback;
        const [rows] = await poolRef.query(query);
        return rows;
    } catch (err) {
        console.error('[Dashboard] Cross-DB query failed:', err.message);
        return fallback;
    }
};

async function obtenerMetricasOperativasDashboard(options = {}) {
    const anio = Number(options.anio) || new Date().getFullYear();
    const empresaId = Number(options.empresaId || 0) || 0;
    const cursoId = Number(options.cursoId || 0) || 0;
    const hasEmpresaFilter = empresaId > 0;
    const hasCursoFilter = cursoId > 0;

    await asegurarColumnasHistorialDescargasCursoProgramado(pool);

    const filterClauses = ['cp.estatus != ?', 'YEAR(COALESCE(cp.fecha_inicio, cp.fecha_fin, cp.created_at)) = ?'];
    const filterParams = ['cancelado', anio];
    if (hasEmpresaFilter) {
        filterClauses.push('cp.empresa_id = ?');
        filterParams.push(empresaId);
    }
    if (hasCursoFilter) {
        filterClauses.push('cp.curso_id = ?');
        filterParams.push(cursoId);
    }
    const whereClause = filterClauses.join(' AND ');

    const [rows] = await pool.query(`
        SELECT
            cp.programado_id,
            cp.estatus,
            cp.fecha_inicio,
            cp.fecha_fin,
            cp.created_at,
            MONTH(COALESCE(cp.fecha_inicio, cp.fecha_fin, cp.created_at)) AS mes_num,
            cp.ultima_descarga_constancias_fecha,
            COALESCE(participantes.total_participantes, 0) AS total_participantes,
            COALESCE(acreditaciones.total_acreditaciones, 0) AS total_acreditaciones,
            COALESCE(dcp_spf03.tiene_entrega_documentos, 0) AS tiene_entrega_documentos,
            COALESCE(dcp_acc.tiene_documentos_acreditacion, 0) AS tiene_documentos_acreditacion
        FROM curso_programado cp
        LEFT JOIN (
            SELECT programado_id, COUNT(*) AS total_participantes
            FROM inscripcion_curso
            WHERE activo = 1
            GROUP BY programado_id
        ) participantes ON participantes.programado_id = cp.programado_id
        LEFT JOIN (
            SELECT programado_id,
                SUM(CASE WHEN activo = 1 AND certificado_generado = 1 THEN 1 ELSE 0 END) AS total_acreditaciones
            FROM inscripcion_curso
            GROUP BY programado_id
        ) acreditaciones ON acreditaciones.programado_id = cp.programado_id
        LEFT JOIN (
            ${SQL_SUBQUERY_ANEXO_SPF03}
        ) dcp_spf03 ON dcp_spf03.programado_id = cp.programado_id
        LEFT JOIN (
            SELECT programado_id,
                MAX(CASE
                    WHEN descripcion LIKE 'constancia_inscripcion_%'
                      OR descripcion LIKE 'dc3_inscripcion_%'
                      OR descripcion LIKE 'constancias_lote%'
                      OR descripcion LIKE 'dc3_lote%'
                    THEN 1 ELSE 0
                END) AS tiene_documentos_acreditacion
            FROM documento_curso_programado
            GROUP BY programado_id
        ) dcp_acc ON dcp_acc.programado_id = cp.programado_id
        WHERE ${whereClause}
    `, filterParams);

    const resumen = {
        totalCursos: 0,
        totalProgramados: 0,
        totalHistorialFinalizados: 0,
        totalConParticipantes: 0,
        constanciasEntregadas: 0,
        constanciasNoRealizadas: 0,
        constanciasDescargadas: 0,
        constanciasGeneradas: 0,
        sinParticipantes: 0
    };

    const mensualMap = new Map();
    for (let m = 1; m <= 12; m++) {
        mensualMap.set(m, {
            mes_num: m,
            programados: 0,
            finalizados: 0,
            conParticipantes: 0,
            constanciasEntregadas: 0,
            constanciasNoRealizadas: 0,
            constanciasDescargadas: 0
        });
    }

    rows.forEach((row) => {
        const estatus = String(row.estatus || '').trim().toLowerCase();
        const mes = Number(row.mes_num) || 0;
        const mesValido = mes >= 1 && mes <= 12;
        const entry = mesValido ? mensualMap.get(mes) : null;
        const finalizado = esCursoFinalizadoDashboard(row);

        resumen.totalCursos++;

        const participantes = Number(row.total_participantes || 0);
        const acreditacionesBd = Number(row.total_acreditaciones || 0);
        const tieneDocumentosAcreditacion = Boolean(Number(row.tiene_documentos_acreditacion || 0));
        const acreditaciones = (acreditacionesBd >= participantes && participantes > 0)
            ? acreditacionesBd
            : (tieneDocumentosAcreditacion && participantes > 0 ? participantes : acreditacionesBd);
        const tieneEntregaDocumentos = Boolean(Number(row.tiene_entrega_documentos || 0));
        const estatusConstancia = estatusAcreditacionesControl(participantes, acreditaciones, tieneEntregaDocumentos);
        const descargada = Boolean(row.ultima_descarga_constancias_fecha);

        if (estatus === 'programado') {
            resumen.totalProgramados++;
            if (participantes === 0) resumen.sinParticipantes++;
            if (entry) entry.programados++;
        } else if (estatus === 'en_curso') {
            resumen.totalConParticipantes++;
            if (entry) entry.conParticipantes++;
        } else if (participantes === 0 && estatus !== 'completado') {
            resumen.sinParticipantes++;
        }

        if (finalizado) {
            resumen.totalHistorialFinalizados++;
            const tieneAnexo = cursoTieneAnexoSubidoDashboard(row);
            if (tieneAnexo) {
                resumen.constanciasEntregadas++;
                if (entry) entry.constanciasEntregadas++;
            } else {
                resumen.constanciasNoRealizadas++;
                if (entry) entry.constanciasNoRealizadas++;
                if (estatusConstancia === 'Generadas') {
                    resumen.constanciasGeneradas++;
                }
            }
            if (descargada) {
                resumen.constanciasDescargadas++;
                if (entry) entry.constanciasDescargadas++;
            }
            if (entry) entry.finalizados++;
        }
    });

    const anioActual = new Date().getFullYear();
    const mesLimite = anio === anioActual ? new Date().getMonth() + 1 : 12;
    const tendenciaMensual = Array.from(mensualMap.values()).filter((item) => item.mes_num <= mesLimite);

    return { resumen, tendenciaMensual };
}

app.get('/api/v2/dashboard', async (req, res) => {
    try {
        const anioActual = new Date().getFullYear();
        const anio = Number(req.query?.anio || anioActual) || anioActual;
        const empresaId = Number(req.query?.empresaId || 0) || 0;
        const cursoId = Number(req.query?.cursoId || 0) || 0;
        const hasEmpresaFilter = empresaId > 0;
        const hasCursoFilter = cursoId > 0;

        const buildProgramadoFilter = (alias = 'cp', includeYear = true) => {
            const clauses = [];
            const params = [];

            if (includeYear) {
                clauses.push(`YEAR(${alias}.fecha_inicio) = ?`);
                params.push(anio);
            }
            if (hasEmpresaFilter) {
                clauses.push(`${alias}.empresa_id = ?`);
                params.push(empresaId);
            }
            if (hasCursoFilter) {
                clauses.push(`${alias}.curso_id = ?`);
                params.push(cursoId);
            }

            return {
                clause: clauses.length ? clauses.join(' AND ') : '1 = 1',
                params
            };
        };

        const statusFilters = buildProgramadoFilter('cp', true);
        const rangoMensual = 'CASE WHEN ? = YEAR(CURDATE()) THEN MONTH(CURDATE()) ELSE 12 END';

        // --- KPIs (todas las queries en paralelo) ---
        const [
            [cursos], [cursosNuevos], [empleados], [empNuevos],
            [empresas], [instructores], [statusCursos],
            [aprobacion], [documentos]
        ] = await Promise.all([
            pool.query('SELECT COUNT(*) as total FROM curso WHERE activo = 1'),
            pool.query(`SELECT COUNT(*) as total FROM curso WHERE activo = 1 AND created_at >= DATE_FORMAT(CURDATE(), '%Y-%m-01')`),
            pool.query('SELECT COUNT(*) as total FROM empleado WHERE activo = 1'),
            pool.query(`SELECT COUNT(*) as total FROM empleado WHERE activo = 1 AND created_at >= DATE_FORMAT(CURDATE(), '%Y-%m-01')`),
            pool.query('SELECT COUNT(*) as total FROM empresa WHERE activo = 1'),
            pool.query('SELECT COUNT(*) as total FROM instructor WHERE activo = 1'),
            pool.query(`SELECT
                SUM(CASE WHEN estatus = 'programado' THEN 1 ELSE 0 END) as programados,
                SUM(CASE WHEN estatus = 'en_curso' THEN 1 ELSE 0 END) as en_curso,
                SUM(CASE WHEN estatus = 'completado' THEN 1 ELSE 0 END) as completados,
                COUNT(*) as total
            FROM curso_programado cp
            WHERE ${statusFilters.clause}`,
            statusFilters.params),
            pool.query(`SELECT
                COUNT(*) as total_inscripciones,
                SUM(CASE WHEN ic.aprobado = 1 THEN 1 ELSE 0 END) as aprobados
            FROM inscripcion_curso ic
            JOIN curso_programado cp ON cp.programado_id = ic.programado_id
            WHERE ic.activo = 1
            AND YEAR(ic.fecha_inscripcion) = ?
            ${hasEmpresaFilter ? 'AND cp.empresa_id = ?' : ''}
            ${hasCursoFilter ? 'AND cp.curso_id = ?' : ''}`,
            [
                anio,
                ...(hasEmpresaFilter ? [empresaId] : []),
                ...(hasCursoFilter ? [cursoId] : [])
            ]),
            pool.query(`SELECT COUNT(*) as total FROM documento_curso_programado
                WHERE fecha_subida >= DATE_FORMAT(CURDATE(), '%Y-%m-01')`)
        ]);

        // Cross-DB queries seguras
        const pcPendientes = await safeQuery(poolProteccionCivil,
            `SELECT COUNT(*) as total FROM documento_proteccion_civil WHERE estatus IN ('pendiente', 'revision')`,
            [{ total: 0 }]);
        const expedientesMes = await safeQuery(poolMedicos,
            `SELECT COUNT(*) as total FROM historia_clinica WHERE activo = 1 AND created_at >= DATE_FORMAT(CURDATE(), '%Y-%m-01')`,
            [{ total: 0 }]);

        const totalInsc = aprobacion[0].total_inscripciones || 0;
        const aprobados = aprobacion[0].aprobados || 0;

        const kpis = {
            totalCursos: cursos[0].total,
            cursosNuevosMes: cursosNuevos[0].total,
            totalEmpleados: empleados[0].total,
            empleadosNuevosMes: empNuevos[0].total,
            totalEmpresas: empresas[0].total,
            totalInstructores: instructores[0].total,
            programados: statusCursos[0].programados || 0,
            enCurso: statusCursos[0].en_curso || 0,
            completados: statusCursos[0].completados || 0,
            tasaAprobacion: totalInsc > 0 ? Math.round((aprobados / totalInsc) * 100) : 0,
            documentosEsteMes: documentos[0].total,
            docsPcPendientes: pcPendientes[0].total,
            expedientesMes: expedientesMes[0].total
        };

        // --- Alertas ---
        const alertas = [];

        // Alertas del dashboard: solo operativas de capacitación (sin "empresas sin actividad")
        const [
            [sinInstructorItems],
            [sinCerrarItems],
            [inminentesItems]
        ] = await Promise.all([
            pool.query(`
                SELECT cp.programado_id as id, c.nombre_curso as nombre,
                    e.nombre_empresa as empresa,
                    DATE_FORMAT(cp.fecha_inicio, '%Y-%m-%d') as fecha,
                    DATEDIFF(cp.fecha_inicio, CURDATE()) as dias_para_inicio
                FROM curso_programado cp
                JOIN curso c ON cp.curso_id = c.curso_id
                JOIN empresa e ON cp.empresa_id = e.empresa_id
                WHERE cp.instructor_id IS NULL
                AND cp.fecha_inicio BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 7 DAY)
                AND cp.estatus NOT IN ('cancelado', 'completado')
                ORDER BY cp.fecha_inicio ASC`),
            pool.query(`
                SELECT cp.programado_id as id, c.nombre_curso as nombre,
                    e.nombre_empresa as empresa,
                    DATE_FORMAT(cp.fecha_fin, '%Y-%m-%d') as fecha,
                    DATEDIFF(CURDATE(), cp.fecha_fin) as dias_vencido
                FROM curso_programado cp
                JOIN curso c ON cp.curso_id = c.curso_id
                JOIN empresa e ON cp.empresa_id = e.empresa_id
                WHERE cp.fecha_fin < CURDATE() AND cp.estatus = 'en_curso'
                ORDER BY cp.fecha_fin ASC`),
            pool.query(`
                SELECT cp.programado_id as id, c.nombre_curso as nombre,
                    e.nombre_empresa as empresa,
                    DATE_FORMAT(cp.fecha_inicio, '%Y-%m-%d') as fecha,
                    DATEDIFF(cp.fecha_inicio, CURDATE()) as dias_para_inicio
                FROM curso_programado cp
                JOIN curso c ON cp.curso_id = c.curso_id
                JOIN empresa e ON cp.empresa_id = e.empresa_id
                WHERE cp.fecha_inicio BETWEEN CURDATE() AND DATE_ADD(CURDATE(), INTERVAL 3 DAY)
                AND cp.estatus = 'programado'
                ORDER BY cp.fecha_inicio ASC`)
        ]);

        const fmtFecha = (d) => {
            if (!d) return '';
            const dt = new Date(d);
            return dt.toLocaleDateString('es-MX', { day: '2-digit', month: 'short', year: 'numeric' });
        };

        if (sinInstructorItems.length > 0) {
            alertas.push({
                tipo: 'danger', icono: 'fa-exclamation-triangle',
                titulo: `${sinInstructorItems.length} curso${sinInstructorItems.length > 1 ? 's' : ''} sin instructor asignado`,
                resumen: 'Próximos 7 días — requiere atención urgente',
                accion: 'Ir a gestionar cursos',
                ruta: '/gestionar-curso',
                prioridad: 1,
                items: sinInstructorItems.map(i => ({
                    id: i.id,
                    label: i.nombre,
                    meta: `${i.empresa} · ${i.dias_para_inicio === 0 ? 'Inicia hoy' : `Inicia en ${i.dias_para_inicio} día${i.dias_para_inicio > 1 ? 's' : ''}`} — ${fmtFecha(i.fecha)}`,
                    ruta: `/informacion-general/${i.id}`
                }))
            });
        }
        if (sinCerrarItems.length > 0) {
            alertas.push({
                tipo: 'warning', icono: 'fa-clock',
                titulo: `${sinCerrarItems.length} curso${sinCerrarItems.length > 1 ? 's' : ''} sin cerrar`,
                resumen: 'Pasaron su fecha de término y siguen activos',
                accion: 'Ir a gestionar cursos',
                ruta: '/gestionar-curso',
                prioridad: 2,
                items: sinCerrarItems.map(i => ({
                    id: i.id,
                    label: i.nombre,
                    meta: `${i.empresa} · Venció ${i.dias_vencido === 1 ? 'ayer' : `hace ${i.dias_vencido} días`} — ${fmtFecha(i.fecha)}`,
                    ruta: `/informacion-general/${i.id}`
                }))
            });
        }

        const pcItems = await safeQuery(poolProteccionCivil,
            `SELECT d.documento_id as id,
                COALESCE(d.nombre_documento, CONCAT('Documento #', d.documento_id)) as nombre,
                d.empresa_id,
                DATE_FORMAT(d.fecha_actualizacion, '%Y-%m-%d') as fecha
             FROM documento_proteccion_civil d
             WHERE d.estatus = 'revision'
             ORDER BY d.fecha_actualizacion ASC LIMIT 10`, []);
        if (pcItems.length > 0) {
            alertas.push({
                tipo: 'warning', icono: 'fa-shield-alt',
                titulo: `${pcItems.length} documento${pcItems.length > 1 ? 's' : ''} de Protección Civil en revisión`,
                resumen: 'Pendientes de aprobación',
                accion: 'Ir a Protección Civil',
                ruta: '/proteccion-civil',
                prioridad: 2,
                items: pcItems.map(i => ({
                    id: i.id,
                    label: i.nombre,
                    meta: i.fecha ? `Actualizado: ${fmtFecha(i.fecha)}` : 'Sin fecha',
                    ruta: i.empresa_id
                        ? `/proteccion-civil/empresas/${i.empresa_id}/revisar-documentos`
                        : '/proteccion-civil'
                }))
            });
        }

        if (inminentesItems.length > 0) {
            alertas.push({
                tipo: 'info', icono: 'fa-calendar-day',
                titulo: `${inminentesItems.length} curso${inminentesItems.length > 1 ? 's' : ''} inician en los próximos 3 días`,
                resumen: 'Verificar preparación, logística e instructor',
                accion: 'Ver calendario',
                ruta: '/calendario',
                prioridad: 3,
                items: inminentesItems.map(i => ({
                    id: i.id,
                    label: i.nombre,
                    meta: `${i.empresa} · ${i.dias_para_inicio === 0 ? 'Hoy' : i.dias_para_inicio === 1 ? 'Mañana' : `En ${i.dias_para_inicio} días`} — ${fmtFecha(i.fecha)}`,
                    ruta: `/informacion-general/${i.id}`
                }))
            });
        }
        alertas.sort((a, b) => a.prioridad - b.prioridad);

        // --- Tendencias mensuales: volumen y alcance ---
        const [tendenciasRows] = await pool.query(`
            SELECT
                m.mes as mes_num,
                ? as anio,
                COALESCE(c.total_cursos, 0) as total_cursos,
                COALESCE(p.personas_capacitadas, 0) as personas_capacitadas,
                COALESCE(p.total_inscripciones, 0) as total_inscripciones
            FROM (SELECT 1 as mes UNION SELECT 2 UNION SELECT 3 UNION SELECT 4
                  UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8
                  UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12) m
            LEFT JOIN (
                SELECT MONTH(cp2.fecha_inicio) as mes,
                    COUNT(DISTINCT cp2.programado_id) as total_cursos,
                    COALESCE(SUM(cp2.cupo), 0) as cupo_total
                FROM curso_programado cp2
                WHERE cp2.estatus != 'cancelado'
                AND YEAR(cp2.fecha_inicio) = ?
                ${hasEmpresaFilter ? 'AND cp2.empresa_id = ?' : ''}
                ${hasCursoFilter ? 'AND cp2.curso_id = ?' : ''}
                GROUP BY MONTH(cp2.fecha_inicio)
            ) c ON c.mes = m.mes
            LEFT JOIN (
                SELECT MONTH(ic2.fecha_inscripcion) as mes,
                    COUNT(ic2.inscripcion_id) as total_inscripciones,
                    COUNT(DISTINCT ic2.empleado_id) as personas_capacitadas
                FROM inscripcion_curso ic2
                JOIN curso_programado cp2f ON cp2f.programado_id = ic2.programado_id
                WHERE ic2.activo = 1
                AND YEAR(ic2.fecha_inscripcion) = ?
                ${hasEmpresaFilter ? 'AND cp2f.empresa_id = ?' : ''}
                ${hasCursoFilter ? 'AND cp2f.curso_id = ?' : ''}
                GROUP BY MONTH(ic2.fecha_inscripcion)
            ) p ON p.mes = m.mes
            WHERE m.mes <= ${rangoMensual}
            ORDER BY m.mes ASC
        `, [
            anio,
            anio,
            ...(hasEmpresaFilter ? [empresaId] : []),
            ...(hasCursoFilter ? [cursoId] : []),
            anio,
            ...(hasEmpresaFilter ? [empresaId] : []),
            ...(hasCursoFilter ? [cursoId] : []),
            anio
        ]);

        const [cursosPorMesEstatus] = await pool.query(`
            SELECT
                MONTH(cp.fecha_inicio) as mes_num,
                cp.estatus as estatus,
                COUNT(DISTINCT cp.programado_id) as total_cursos
            FROM curso_programado cp
            WHERE cp.estatus != 'cancelado'
            AND YEAR(cp.fecha_inicio) = ?
            ${hasEmpresaFilter ? 'AND cp.empresa_id = ?' : ''}
            ${hasCursoFilter ? 'AND cp.curso_id = ?' : ''}
            AND MONTH(cp.fecha_inicio) <= ${rangoMensual}
            GROUP BY MONTH(cp.fecha_inicio), cp.estatus
            ORDER BY MONTH(cp.fecha_inicio) ASC
        `, [
            anio,
            ...(hasEmpresaFilter ? [empresaId] : []),
            ...(hasCursoFilter ? [cursoId] : []),
            anio
        ]);

        // --- Aprobación mensual basada en calificaciones reales ---
        const [aprobacionMensual] = await pool.query(`
            SELECT
                m.mes as mes_num,
                ? as anio,
                COALESCE(g.total_evaluados, 0) as total_evaluados,
                COALESCE(g.aprobados, 0) as aprobados,
                COALESCE(g.reprobados, 0) as reprobados,
                COALESCE(g.sin_evaluar, 0) as sin_evaluar,
                COALESCE(g.promedio_general, 0) as promedio_general,
                CASE WHEN COALESCE(g.total_evaluados, 0) > 0
                     THEN ROUND(g.aprobados * 100.0 / g.total_evaluados, 1)
                     ELSE 0 END as tasa_aprobacion
            FROM (SELECT 1 as mes UNION SELECT 2 UNION SELECT 3 UNION SELECT 4
                  UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8
                  UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12) m
            LEFT JOIN (
                SELECT MONTH(ic3.fecha_inscripcion) as mes,
                    SUM(CASE WHEN ic3.calificacion_teorica IS NOT NULL
                              OR ic3.calificacion_practica IS NOT NULL
                         THEN 1 ELSE 0 END) as total_evaluados,
                    SUM(CASE WHEN (
                        CASE
                            WHEN ic3.calificacion_teorica IS NOT NULL AND ic3.calificacion_practica IS NOT NULL
                                THEN (ic3.calificacion_teorica + ic3.calificacion_practica) / 2
                            WHEN ic3.calificacion_teorica IS NOT NULL
                                THEN ic3.calificacion_teorica
                            WHEN ic3.calificacion_practica IS NOT NULL
                                THEN ic3.calificacion_practica
                            ELSE NULL
                        END) >= 8 THEN 1 ELSE 0 END) as aprobados,
                    SUM(CASE WHEN (
                        CASE
                            WHEN ic3.calificacion_teorica IS NOT NULL AND ic3.calificacion_practica IS NOT NULL
                                THEN (ic3.calificacion_teorica + ic3.calificacion_practica) / 2
                            WHEN ic3.calificacion_teorica IS NOT NULL
                                THEN ic3.calificacion_teorica
                            WHEN ic3.calificacion_practica IS NOT NULL
                                THEN ic3.calificacion_practica
                            ELSE NULL
                        END) < 8 AND (ic3.calificacion_teorica IS NOT NULL OR ic3.calificacion_practica IS NOT NULL)
                         THEN 1 ELSE 0 END) as reprobados,
                    SUM(CASE WHEN ic3.calificacion_teorica IS NULL
                              AND ic3.calificacion_practica IS NULL
                         THEN 1 ELSE 0 END) as sin_evaluar,
                    ROUND(AVG(
                        CASE
                            WHEN ic3.calificacion_teorica IS NOT NULL AND ic3.calificacion_practica IS NOT NULL
                                THEN (ic3.calificacion_teorica + ic3.calificacion_practica) / 2
                            WHEN ic3.calificacion_teorica IS NOT NULL
                                THEN ic3.calificacion_teorica
                            WHEN ic3.calificacion_practica IS NOT NULL
                                THEN ic3.calificacion_practica
                            ELSE NULL
                        END
                    ), 1) as promedio_general
                FROM inscripcion_curso ic3
                JOIN curso_programado cp3f ON cp3f.programado_id = ic3.programado_id
                WHERE ic3.activo = 1
                AND YEAR(ic3.fecha_inscripcion) = ?
                ${hasEmpresaFilter ? 'AND cp3f.empresa_id = ?' : ''}
                ${hasCursoFilter ? 'AND cp3f.curso_id = ?' : ''}
                GROUP BY MONTH(ic3.fecha_inscripcion)
            ) g ON g.mes = m.mes
            WHERE m.mes <= ${rangoMensual}
            ORDER BY m.mes ASC
        `, [
            anio,
            anio,
            ...(hasEmpresaFilter ? [empresaId] : []),
            ...(hasCursoFilter ? [cursoId] : []),
            anio
        ]);

        // Personas capacitadas por mes (ano actual, 12 meses completos)
        const [personasMensual] = await pool.query(`
            SELECT m.mes,
                COALESCE(t.total_inscripciones, 0) as total_inscripciones,
                COALESCE(t.personas_unicas, 0) as personas_unicas
            FROM (SELECT 1 as mes UNION SELECT 2 UNION SELECT 3 UNION SELECT 4
                  UNION SELECT 5 UNION SELECT 6 UNION SELECT 7 UNION SELECT 8
                  UNION SELECT 9 UNION SELECT 10 UNION SELECT 11 UNION SELECT 12) m
            LEFT JOIN (
                SELECT MONTH(ic.fecha_inscripcion) as mes,
                    COUNT(ic.inscripcion_id) as total_inscripciones,
                    COUNT(DISTINCT ic.empleado_id) as personas_unicas
                FROM inscripcion_curso ic
                JOIN curso_programado cp4f ON cp4f.programado_id = ic.programado_id
                WHERE ic.activo = 1
                AND YEAR(ic.fecha_inscripcion) = ?
                ${hasEmpresaFilter ? 'AND cp4f.empresa_id = ?' : ''}
                ${hasCursoFilter ? 'AND cp4f.curso_id = ?' : ''}
                GROUP BY MONTH(ic.fecha_inscripcion)
            ) t ON t.mes = m.mes
            WHERE m.mes <= ${rangoMensual}
            ORDER BY m.mes ASC
        `, [
            anio,
            ...(hasEmpresaFilter ? [empresaId] : []),
            ...(hasCursoFilter ? [cursoId] : []),
            anio
        ]);

        // --- Distribuciones ---
        const [[porArea], [porEstatus]] = await Promise.all([
            pool.query(`SELECT a.nombre_area, a.color,
                COUNT(DISTINCT cp.programado_id) as total_cursos,
                COUNT(DISTINCT ic.empleado_id) as total_capacitados
            FROM area_tematica a
            LEFT JOIN curso c ON a.area_id = c.area_id AND c.activo = 1
            LEFT JOIN curso_programado cp ON cp.curso_id = c.curso_id
                AND cp.estatus != 'cancelado'
                AND YEAR(cp.fecha_inicio) = ?
                ${hasEmpresaFilter ? 'AND cp.empresa_id = ?' : ''}
                ${hasCursoFilter ? 'AND cp.curso_id = ?' : ''}
            LEFT JOIN inscripcion_curso ic ON ic.programado_id = cp.programado_id AND ic.activo = 1
            WHERE a.activo = 1
            GROUP BY a.area_id, a.nombre_area, a.color
            HAVING total_cursos > 0
            ORDER BY total_cursos DESC`, [
                anio,
                ...(hasEmpresaFilter ? [empresaId] : []),
                ...(hasCursoFilter ? [cursoId] : [])
            ]),
            pool.query(`SELECT cp.estatus as estatus, COUNT(*) as total
                FROM curso_programado cp
                WHERE ${statusFilters.clause}
                GROUP BY cp.estatus`, statusFilters.params)
        ]);

        // --- Agenda de cursos: hoy + próximos programados ---
        const [cursosHoyRows] = await pool.query(`
            SELECT
                cp.programado_id,
                c.nombre_curso,
                e.nombre_empresa,
                cp.fecha_inicio,
                cp.fecha_fin,
                cp.hora_inicio,
                cp.hora_fin,
                cp.estatus,
                cp.cupo,
                TRIM(CONCAT(
                    COALESCE(i.nombre, ''), ' ',
                    COALESCE(i.apellido_paterno, ''), ' ',
                    COALESCE(i.apellido_materno, '')
                )) AS instructor,
                (SELECT COUNT(*) FROM inscripcion_curso ic WHERE ic.programado_id = cp.programado_id AND ic.activo = 1) AS participantes_cargados
            FROM curso_programado cp
            JOIN curso c ON cp.curso_id = c.curso_id
            JOIN empresa e ON cp.empresa_id = e.empresa_id
            LEFT JOIN instructor i ON cp.instructor_id = i.instructor_id
            WHERE cp.estatus != 'cancelado'
              AND CURDATE() BETWEEN DATE(cp.fecha_inicio) AND DATE(COALESCE(cp.fecha_fin, cp.fecha_inicio))
              ${hasEmpresaFilter ? 'AND cp.empresa_id = ?' : ''}
              ${hasCursoFilter ? 'AND cp.curso_id = ?' : ''}
            ORDER BY
              CASE WHEN cp.hora_inicio IS NULL THEN 1 ELSE 0 END,
              cp.hora_inicio ASC,
              cp.programado_id ASC
        `, [
            ...(hasEmpresaFilter ? [empresaId] : []),
            ...(hasCursoFilter ? [cursoId] : [])
        ]);

        const filtroFechaProximos = anio === anioActual
            ? {
                clause: 'DATE(cp.fecha_inicio) > CURDATE() AND DATE(cp.fecha_inicio) <= DATE_ADD(CURDATE(), INTERVAL 30 DAY)',
                params: []
            }
            : {
                clause: 'YEAR(cp.fecha_inicio) = ? AND DATE(cp.fecha_inicio) > CURDATE()',
                params: [anio]
            };

        const [proximosCursosProgramados] = await pool.query(`
            SELECT
                cp.programado_id,
                c.nombre_curso,
                e.nombre_empresa,
                e.logo AS empresa_logo,
                cp.fecha_inicio,
                cp.fecha_fin,
                cp.hora_inicio,
                cp.hora_fin,
                cp.estatus,
                cp.cupo,
                cp.ubicacion,
                TRIM(CONCAT(
                    COALESCE(i.nombre, ''), ' ',
                    COALESCE(i.apellido_paterno, ''), ' ',
                    COALESCE(i.apellido_materno, '')
                )) AS instructor,
                DATEDIFF(cp.fecha_inicio, CURDATE()) AS dias_faltantes,
                (SELECT COUNT(*) FROM inscripcion_curso ic WHERE ic.programado_id = cp.programado_id AND ic.activo = 1) AS participantes_cargados
            FROM curso_programado cp
            JOIN curso c ON cp.curso_id = c.curso_id
            JOIN empresa e ON cp.empresa_id = e.empresa_id
            LEFT JOIN instructor i ON cp.instructor_id = i.instructor_id
            WHERE ${filtroFechaProximos.clause}
              AND cp.estatus NOT IN ('cancelado', 'completado')
              ${hasEmpresaFilter ? 'AND cp.empresa_id = ?' : ''}
              ${hasCursoFilter ? 'AND cp.curso_id = ?' : ''}
            ORDER BY cp.fecha_inicio ASC, cp.hora_inicio ASC, cp.programado_id ASC
            LIMIT 12
        `, [
            ...filtroFechaProximos.params,
            ...(hasEmpresaFilter ? [empresaId] : []),
            ...(hasCursoFilter ? [cursoId] : [])
        ]);

        // --- Top 5 empresas ---
        const [empresasTop] = await pool.query(`
            SELECT e.empresa_id, e.nombre_empresa,
                COUNT(DISTINCT cp.programado_id) as total_cursos,
                COUNT(DISTINCT ic.empleado_id) as total_empleados_capacitados,
                MAX(cp.fecha_inicio) as ultimo_curso
            FROM empresa e
            JOIN curso_programado cp ON cp.empresa_id = e.empresa_id AND cp.estatus != 'cancelado'
            LEFT JOIN inscripcion_curso ic ON ic.programado_id = cp.programado_id AND ic.activo = 1
            WHERE e.activo = TRUE
            AND YEAR(cp.fecha_inicio) = ?
            ${hasEmpresaFilter ? 'AND cp.empresa_id = ?' : ''}
            ${hasCursoFilter ? 'AND cp.curso_id = ?' : ''}
            GROUP BY e.empresa_id, e.nombre_empresa
            HAVING total_cursos > 0
            ORDER BY total_cursos DESC, total_empleados_capacitados DESC
            LIMIT 5
        `, [
            anio,
            ...(hasEmpresaFilter ? [empresaId] : []),
            ...(hasCursoFilter ? [cursoId] : [])
        ]);

        const [[empresasFiltro], [cursosFiltro], metricasOperativas] = await Promise.all([
            pool.query(`SELECT empresa_id, nombre_empresa FROM empresa WHERE activo = 1 ORDER BY nombre_empresa ASC`),
            pool.query(`SELECT curso_id, nombre_curso FROM curso WHERE activo = 1 ORDER BY nombre_curso ASC`),
            obtenerMetricasOperativasDashboard({ anio, empresaId, cursoId })
        ]);

        // --- Actividad reciente ---
        const [actividadReciente] = await pool.query(`
            (SELECT 'curso_programado' as tipo, cp.programado_id as ref_id,
                CONCAT(c.nombre_curso, ' — ', e.nombre_empresa) as descripcion,
                cp.created_at as fecha
            FROM curso_programado cp
            JOIN curso c ON cp.curso_id = c.curso_id
            JOIN empresa e ON cp.empresa_id = e.empresa_id
            ORDER BY cp.created_at DESC LIMIT 5)
            UNION ALL
            (SELECT 'documento' as tipo, dcp.documento_prog_id as ref_id,
                CONCAT(dcp.tipo_documento, ': ', COALESCE(dcp.nombre_archivo, 'archivo')) as descripcion,
                dcp.fecha_subida as fecha
            FROM documento_curso_programado dcp
            ORDER BY dcp.fecha_subida DESC LIMIT 5)
            UNION ALL
            (SELECT 'inscripcion' as tipo, ic.inscripcion_id as ref_id,
                CONCAT(emp.nombre, ' ', COALESCE(emp.apellido_paterno, '')) as descripcion,
                ic.created_at as fecha
            FROM inscripcion_curso ic
            JOIN empleado emp ON ic.empleado_id = emp.empleado_id
            WHERE ic.activo = 1
            ORDER BY ic.created_at DESC LIMIT 5)
            ORDER BY fecha DESC LIMIT 10
        `);

        res.json({
            success: true,
            timestamp: new Date().toISOString(),
            filtros: {
                anio,
                empresaId: hasEmpresaFilter ? empresaId : null,
                cursoId: hasCursoFilter ? cursoId : null,
                anios: [anioActual, anioActual - 1, anioActual - 2, anioActual - 3],
                empresas: empresasFiltro,
                cursos: cursosFiltro
            },
            kpis,
            alertas,
            tendencias: { cursosPorMes: tendenciasRows, cursosPorMesEstatus, personasMensual, aprobacionMensual },
            distribuciones: { porArea, porEstatus },
            metricasOperativas,
            cursoHoy: cursosHoyRows[0] || null,
            cursosHoy: cursosHoyRows,
            proximosCursosProgramados,
            proximosCursos: proximosCursosProgramados,
            empresasTop,
            actividadReciente
        });

    } catch (error) {
        handleError(res, error);
    }
});

app.get('/api/dashboard/control-capacitacion/registros', async (req, res) => {
    try {
        const anio = Number(req.query?.anio || 0) || null;
        const rows = await obtenerDatosControlCapacitacion();
        const filtrados = anio
            ? rows.filter((row) => {
                const dt = new Date(row.fecha_inicio);
                const year = Number.isNaN(dt.getTime()) ? null : dt.getFullYear();
                return year === anio;
            })
            : rows;
        const registros = filtrados.map((item, index) => mapearRegistroControlCapacitacion(item, index + 1));
        return res.json({
            success: true,
            anio: anio || null,
            total: registros.length,
            registros
        });
    } catch (error) {
        const status = error.statusCode || 500;
        return res.status(status).json({
            success: false,
            message: error.message || 'No se pudo obtener el control de capacitación empresarial.'
        });
    }
});

