app.get('/api/historias-clinicas', async (req, res) => {
    await poolMedicosReady;
    try {
        const [columnRows] = await poolMedicos.query('SHOW COLUMNS FROM historia_clinica');
        const availableCols = new Set((columnRows || []).map((c) => c.Field));

        const selectedCols = [
            'id',
            'tipo_historia',
            'fecha_elaboracion',
            'matricula',
            'nombre',
            'area',
            'personal_elaboro',
            'empresa_id',
            'created_at'
        ].filter((col) => availableCols.has(col));

        if (selectedCols.length === 0) {
            throw new Error('No hay columnas disponibles para listar historia_clinica');
        }

        let query = `SELECT ${selectedCols.join(', ')} FROM historia_clinica WHERE activo = 1`;
        const params = [];

        if (req.query.empresa_id && availableCols.has('empresa_id')) {
            query += ' AND empresa_id = ?';
            params.push(req.query.empresa_id);
        }
        if (req.query.instructor_id && availableCols.has('instructor_id')) {
            query += ' AND instructor_id = ?';
            params.push(req.query.instructor_id);
        }
        if (req.query.matricula) {
            query += ' AND matricula = ?';
            params.push(req.query.matricula);
        }
        if (req.query.nombre) {
            query += ' AND nombre LIKE ?';
            params.push(`%${req.query.nombre}%`);
        }
        if (req.query.tipo) {
            query += ' AND tipo_historia = ?';
            params.push(req.query.tipo);
        }

        query += ' ORDER BY created_at DESC';

        const [rows] = await poolMedicos.query(query, params);
        res.json({ success: true, historias: rows });
    } catch (error) {
        console.error('[ERROR] Listar historias clínicas:', error.message);
        res.status(500).json({ success: false, message: 'Error al obtener historias clínicas' });
    }
});

// Obtener una historia clínica completa por ID
app.get('/api/historias-clinicas/:id', async (req, res) => {
    await poolMedicosReady;
    try {
        const [rows] = await poolMedicos.query('SELECT * FROM historia_clinica WHERE id = ? AND activo = 1', [req.params.id]);
        if (rows.length === 0) {
            return res.status(404).json({ success: false, message: 'Historia clínica no encontrada' });
        }

        const historia = rows[0];

        // Cargar antecedentes laborales
        const [laborales] = await poolMedicos.query(
            'SELECT * FROM antecedente_laboral WHERE historia_clinica_id = ? ORDER BY orden', [historia.id]
        );
        historia.antecedentes_laborales = laborales;

        // Cargar diagnósticos
        const [diagnosticos] = await poolMedicos.query(
            'SELECT * FROM diagnostico WHERE historia_clinica_id = ? ORDER BY numero', [historia.id]
        );
        historia.diagnosticos = diagnosticos;

        res.json({ success: true, historia });
    } catch (error) {
        console.error('[ERROR] Obtener historia clínica:', error.message);
        res.status(500).json({ success: false, message: 'Error al obtener historia clínica' });
    }
});

// Actualizar historia clínica
app.put('/api/historias-clinicas/:id', async (req, res) => {
    await poolMedicosReady;
    const conn = await poolMedicos.getConnection();
    try {
        await conn.beginTransaction();
        const d = req.body;
        const id = req.params.id;

        const camposRaw = buildHistoriaCampos(d);
        const { filtrados: campos, omitidos } = await filtrarCamposHistoriaDisponibles(camposRaw, conn);

        if (omitidos.length > 0) {
            console.warn('[WARN] Campos omitidos al actualizar historia_clinica por no existir en BD:', omitidos.join(', '));
        }
        if (Object.keys(campos).length === 0) {
            throw new Error('No hay campos válidos para actualizar en historia_clinica');
        }

        await conn.query('UPDATE historia_clinica SET ? WHERE id = ? AND activo = 1', [campos, id]);

        // Reemplazar antecedentes laborales
        await conn.query('DELETE FROM antecedente_laboral WHERE historia_clinica_id = ?', [id]);
        if (d.antecedentes_laborales && d.antecedentes_laborales.length > 0) {
            for (let i = 0; i < d.antecedentes_laborales.length; i++) {
                const al = d.antecedentes_laborales[i];
                await conn.query(`
                    INSERT INTO antecedente_laboral 
                    (historia_clinica_id, empresa, puesto, tiempo, epp_visual, epp_auditivo, epp_respiratorio, epp_no_aplica, enfermedad_trabajo, accidente_trabajo, orden)
                    VALUES (?, ?, ?, ?, ?, ?, ?, ?, ?, ?, ?)
                `, [id, al.empresa || null, al.puesto || null, al.tiempo || null,
                    al.epp_visual ? 1 : 0, al.epp_auditivo ? 1 : 0, al.epp_respiratorio ? 1 : 0,
                    al.epp_no_aplica ? 1 : 0,
                    al.enfermedad_trabajo || null, al.accidente_trabajo || null, i]);
            }
        }

        // Reemplazar diagnósticos
        await conn.query('DELETE FROM diagnostico WHERE historia_clinica_id = ?', [id]);
        if (d.diagnosticos && d.diagnosticos.length > 0) {
            for (let i = 0; i < d.diagnosticos.length; i++) {
                const diag = d.diagnosticos[i];
                await conn.query(`
                    INSERT INTO diagnostico (historia_clinica_id, numero, diagnostico, recomendacion)
                    VALUES (?, ?, ?, ?)
                `, [id, i + 1, diag.diagnostico || null, diag.recomendacion || null]);
            }
        }

        await conn.commit();
        res.json({ success: true, message: 'Historia clínica actualizada', id: parseInt(id) });
    } catch (error) {
        await conn.rollback();
        console.error('[ERROR] Actualizar historia clínica:', error.message);
        res.status(500).json({ success: false, message: 'Error al actualizar historia clínica', error: error.message });
    } finally {
        conn.release();
    }
});

// Subir PDF de expediente médico a Google Drive (carpeta Expedientes_medicos)
app.post('/api/historias-clinicas/:id/subir-pdf', async (req, res) => {
    try {
        const { id } = req.params;
        const { pdf_base64, nombre_archivo } = req.body;
        let empresaNombre = null;

        if (!pdf_base64) {
            return res.status(400).json({ success: false, message: 'No se recibió el PDF (pdf_base64 requerido)' });
        }

        // Decodificar base64 a Buffer
        const pdfBuffer = Buffer.from(pdf_base64, 'base64');

        // Generar nombre de archivo si no se proporcionó
        const anio = new Date().getFullYear().toString().slice(-2);
        const folio = String(id).padStart(3, '0');
        const nombrePdf = nombre_archivo || `B-HC-${anio}-${folio}.pdf`;

        const { empresas: empresasSincronizadas } = await sincronizarCarpetasEmpresasExpedientesDrive();
        const empresasPorId = new Map(empresasSincronizadas.map((empresa) => [Number(empresa.empresa_id), empresa.nombre_empresa]));

        try {
            const [historiaRows] = await poolMedicos.query(
                'SELECT empresa_id FROM historia_clinica WHERE id = ? LIMIT 1',
                [id]
            );

            const empresaId = historiaRows?.[0]?.empresa_id || null;
            if (empresaId) {
                empresaNombre = empresasPorId.get(Number(empresaId)) || null;

                if (!empresaNombre) {
                    const [empresaRows] = await pool.query(
                        'SELECT nombre_empresa FROM empresa WHERE empresa_id = ? LIMIT 1',
                        [empresaId]
                    );
                    empresaNombre = empresaRows?.[0]?.nombre_empresa || null;
                }
            }
        } catch (lookupErr) {
            console.warn('[WARN] No se pudo resolver nombre de empresa para carpeta de expediente:', lookupErr.message);
        }

        // Subir a Google Drive en carpeta Expedientes_medicos/{Empresa}
        const driveResult = await driveService.subirExpedienteMedico(pdfBuffer, nombrePdf, empresaNombre);

        // Guardar el drive_file_id en la BD (columna pdf_drive_file_id)
        try {
            await poolMedicos.query(
                'UPDATE historia_clinica SET pdf_drive_file_id = ?, pdf_drive_url = ? WHERE id = ?',
                [driveResult.id, driveResult.webViewLink || null, id]
            );
        } catch (dbErr) {
            // silenced
        }

        res.json({
            success: true,
            message: `PDF "${nombrePdf}" subido a Google Drive`,
            drive_file_id: driveResult.id,
            web_view_link: driveResult.webViewLink || null,
            nombre_archivo: nombrePdf
        });
    } catch (error) {
        console.error('[ERROR] Subir PDF expediente médico:', error.message);
        res.status(500).json({ success: false, message: 'Error al subir PDF a Google Drive', error: error.message });
    }
});

