app.post(
    '/api/sgc/formatos-descarga/subir',
    authMiddleware,
    denyEmpresa,
    requireAdmin,
    uploadSgcFormatoDescarga.single('archivo'),
    async (req, res) => {
        try {
            await poolBiznagaSgcReady;
            if (!req.file?.buffer) {
                return res.status(400).json({ success: false, message: 'Debe adjuntar el archivo del formato' });
            }
            const codigo = String(req.body?.codigo || '').trim();
            const titulo = String(req.body?.titulo || '').trim();
            const categoriaId = String(req.body?.categoria_id || req.body?.categoriaId || '').trim();
            const nombreArchivo = String(req.body?.nombre_archivo || req.file.originalname || '').trim();

            const resultado = await sgcFormatosDescargaService.subirFormatoDescarga({
                poolSgc: poolBiznagaSgc,
                codigo,
                titulo,
                categoriaId,
                fileBuffer: req.file.buffer,
                mimeType: req.file.mimetype,
                originalName: req.file.originalname,
                nombreArchivo,
                usuario: req.user
            });

            res.json({
                success: true,
                message: `Formato ${resultado.codigo} subido correctamente`,
                ...resultado
            });
        } catch (error) {
            const status = error.status || 500;
            if (status !== 500) {
                return res.status(status).json({ success: false, message: error.message });
            }
            handleError(res, error, 'Error al subir formato de descarga');
        }
    }
);

