// ── Delegaciones de edición SGC (por formato / Capítulos) ──
app.get('/api/sgc/editores-delegados/mi-permiso', authMiddleware, denyEmpresa, async (req, res) => {
    try {
        const userId = Number(req.user?.id || 0);
        const username = String(req.user?.username || '').toLowerCase().trim();
        const roles = getUserRolesLower(req);
        const formatoCodigo = sgcEditoresDelegadosService.normalizarFormatoCodigo(
            req.query?.formato || req.query?.formato_codigo || req.query?.codigo || ''
        );
        const esGestor = roles.includes('root') || username === 'sergio56' || username === 'calidad';
        const esDelegadoCualquiera = userId > 0
            ? await sgcEditoresDelegadosService.esEditorDelegado(pool, userId)
            : false;
        const excepcionFormato = formatoCodigo === 'ath-f-08' && username === 'mafer295';
        const esDelegadoFormato = formatoCodigo && userId > 0
            ? await sgcEditoresDelegadosService.esEditorDelegadoFormato(pool, userId, formatoCodigo)
            : false;
        const puedeGestionarPlantillas = esGestor
            || excepcionFormato
            || (formatoCodigo ? esDelegadoFormato : esDelegadoCualquiera);
        res.json({
            success: true,
            formato_codigo: formatoCodigo || null,
            sgc_editor_delegado: esDelegadoCualquiera,
            sgc_editor_formato: !!(formatoCodigo && (esGestor || excepcionFormato || esDelegadoFormato)),
            puede_gestionar_delegaciones: esGestor,
            puede_gestionar_plantillas: !!puedeGestionarPlantillas
        });
    } catch (error) {
        handleError(res, error, 'Error al consultar permiso de edición SGC');
    }
});

app.get('/api/sgc/editores-delegados', authMiddleware, requireGestorDelegacionesSgc, async (req, res) => {
    try {
        await sgcEditoresDelegadosService.asegurarTabla(pool);
        const formatoCodigo = sgcEditoresDelegadosService.normalizarFormatoCodigo(
            req.query?.formato || req.query?.formato_codigo || req.query?.codigo || ''
        );
        if (!formatoCodigo) {
            return res.status(400).json({
                success: false,
                message: 'Indique el formato (query formato) para listar delegaciones'
            });
        }
        const [editores, candidatos] = await Promise.all([
            sgcEditoresDelegadosService.listarEditores(pool, formatoCodigo),
            sgcEditoresDelegadosService.listarCandidatos(pool)
        ]);
        res.json({
            success: true,
            formato_codigo: formatoCodigo,
            editores,
            candidatos,
            usuario_ids: editores.map((e) => Number(e.usuario_id))
        });
    } catch (error) {
        handleError(res, error, 'Error al listar editores delegados SGC');
    }
});

app.put('/api/sgc/editores-delegados', authMiddleware, requireGestorDelegacionesSgc, async (req, res) => {
    try {
        await sgcEditoresDelegadosService.asegurarTabla(pool);
        const formatoCodigo = sgcEditoresDelegadosService.normalizarFormatoCodigo(
            req.body?.formato_codigo || req.body?.formato || req.body?.codigo || req.query?.formato || ''
        );
        if (!formatoCodigo) {
            return res.status(400).json({
                success: false,
                message: 'Indique formato_codigo para guardar delegaciones'
            });
        }
        const rawIds = req.body?.usuario_ids ?? req.body?.usuarios ?? req.body?.ids ?? [];
        const otorgadoPor = Number(req.user?.id || 0) || null;
        const guardados = await sgcEditoresDelegadosService.guardarEditores(
            pool,
            formatoCodigo,
            rawIds,
            otorgadoPor
        );
        const editores = await sgcEditoresDelegadosService.listarEditores(pool, formatoCodigo);
        res.json({
            success: true,
            message: 'Delegaciones del formato actualizadas',
            formato_codigo: formatoCodigo,
            usuario_ids: guardados,
            editores
        });
    } catch (error) {
        handleError(res, error, 'Error al guardar editores delegados SGC');
    }
});

