// =====================================================
// SENSORES IoT (Blynk) — solo root / iot
// =====================================================
app.get('/api/sensores/estado', requireRootOrIot, async (req, res) => {
    try {
        const estado = await blynkService.obtenerEstadoSensor();
        const { errors, ...safe } = estado;
        return res.json({
            success: true,
            ...safe,
            ...(errors && Object.keys(errors).length ? { partialErrors: errors } : {})
        });
    } catch (error) {
        const status = Number(error.statusCode) || 500;
        const code = error.code || (status === 503 ? 'BLYNK_NOT_CONFIGURED' : 'BLYNK_ERROR');
        const payload = error.payload || null;
        if (payload) {
            const { errors, ...safe } = payload;
            return res.status(status).json({
                success: false,
                code,
                message: error.message || 'Error al consultar sensores',
                ...safe,
                ...(errors && Object.keys(errors).length ? { partialErrors: errors } : {})
            });
        }
        return res.status(status).json({
            success: false,
            code,
            message: error.message || 'Error al consultar sensores'
        });
    }
});

