app.post('/api/control-proyectos/eliminados/restaurar', requireRole('root'), async (req, res) => {
    try {
        await poolBiznagaSgcReady;
        const auditoria = {
            usuarioNombre: obtenerNombreUsuarioAccion(req),
            fechaHora: obtenerFechaHoraMexicoMySQL()
        };

        let resultado;
        if (Array.isArray(req.body?.ids) && req.body.ids.length) {
            resultado = await sgcControlProyectosService.restaurarActividades(
                poolBiznagaSgc,
                req.body.ids,
                auditoria
            );
        } else if (req.body?.proyecto && typeof req.body.proyecto === 'object') {
            resultado = await sgcControlProyectosService.restaurarProyecto(
                poolBiznagaSgc,
                req.body.proyecto,
                auditoria
            );
        } else {
            return res.status(400).json({
                success: false,
                message: 'Indica ids de actividades o un proyecto para restaurar.'
            });
        }

        sgcDashboardService.invalidarCacheDashboard();
        const eliminados = await sgcControlProyectosService.listarEliminados(poolBiznagaSgc, {
            empresaId: req.body?.empresaId
        });
        const dashboard = await sgcControlProyectosService.obtenerDashboard(poolBiznagaSgc, {
            empresaId: req.body?.empresaId
        });

        return res.json({
            success: true,
            message: resultado.restauradas
                ? `Se restauraron ${resultado.restauradas} actividad(es).`
                : 'No había actividades eliminadas que restaurar.',
            restauracion: resultado,
            eliminados,
            ...dashboard
        });
    } catch (error) {
        if (error.statusCode === 400) {
            return res.status(400).json({ success: false, message: error.message });
        }
        handleError(res, error, 'No se pudieron restaurar los registros eliminados');
    }
});

