app.get('/api/sgc/formatos/sgc-f-01', requireAdminOrSgc, async (req, res) => {
    const t0 = Date.now();
    try {
        await poolBiznagaSgcReady;
        const payload = await sgcSgcF01Service.cargarFormato(poolBiznagaSgc);
        startupLog.detail(`[SGC-F-01] GET /formatos/sgc-f-01 ${Date.now() - t0}ms`);
        return res.json({ success: true, ...payload });
    } catch (error) {
        console.error(`[SGC-F-01] GET error ${Date.now() - t0}ms:`, error?.message || error);
        // Nunca dejar al cliente colgado: responder catálogo aunque falle el pool
        try {
            const fallback = sgcSgcF01Service.cargarFormato
                ? await sgcSgcF01Service.cargarFormato(null)
                : null;
            if (fallback) {
                return res.json({ success: true, ...fallback, aviso: 'Catálogo local (BD no disponible)' });
            }
        } catch (_) { /* ignore */ }
        handleError(res, error, 'No se pudo cargar el formato SGC-F-01');
    }
});

