const uploadSgcF02DocsFisicos = multer({
    storage: storageMemory,
    limits: { fileSize: 15 * 1024 * 1024 },
    fileFilter: function (req, file, cb) {
        const mime = String(file.mimetype || '').toLowerCase();
        const ext = path.extname(String(file.originalname || '')).toLowerCase();
        const okMime = mime === 'application/pdf' || mime === 'image/jpeg' || mime === 'image/jpg';
        const okExt = ['.pdf', '.jpg', '.jpeg'].includes(ext);
        if (okMime || okExt) {
            cb(null, true);
        } else {
            cb(new Error('Solo se permiten archivos PDF, JPG o JPEG'));
        }
    }
});

app.get('/api/sgc/formatos/sgc-f-02/documentos-fisicos', requireAdminOrSgc, async (req, res) => {
    try {
        const archivos = await sgcSgcF02Service.listarDocumentosFisicos();
        return res.json({
            success: true,
            carpetaDriveId: sgcSgcF02Service.CARPETA_DOCS_FISICOS_ID,
            archivos
        });
    } catch (error) {
        handleError(res, error, 'No se pudieron listar los documentos físicos de SGC-F-02');
    }
});

app.post(
    '/api/sgc/formatos/sgc-f-02/documentos-fisicos',
    requireAdminOrSgc,
    (req, res, next) => {
        uploadSgcF02DocsFisicos.array('archivos', 12)(req, res, (err) => {
            if (err) {
                return res.status(400).json({ success: false, message: err.message || 'Archivo no válido' });
            }
            return next();
        });
    },
    async (req, res) => {
        try {
            const files = Array.isArray(req.files) ? req.files : [];
            if (!files.length) {
                return res.status(400).json({ success: false, message: 'Selecciona al menos un archivo PDF, JPG o JPEG.' });
            }
            const subidos = [];
            for (const file of files) {
                const item = await sgcSgcF02Service.subirDocumentoFisico(
                    file.buffer,
                    file.originalname,
                    file.mimetype
                );
                subidos.push(item);
            }
            const archivos = await sgcSgcF02Service.listarDocumentosFisicos();
            return res.json({
                success: true,
                message: subidos.length === 1
                    ? 'Documento físico subido correctamente.'
                    : `${subidos.length} documentos físicos subidos correctamente.`,
                subidos,
                archivos
            });
        } catch (error) {
            handleError(res, error, 'No se pudieron subir los documentos físicos de SGC-F-02');
        }
    }
);

