app.post('/api/sgc/documentacion-extra/subir-lote', requireAdminOrSgc, async (req, res) => {
    try {
        await poolBiznagaSgcReady;
        const usuario = req.user?.usuario || req.user?.email || req.user?.nombre || '';
        const archivos = req.body?.archivos || req.body?.files || [];
        const resultado = await sgcDocumentacionExtraService.subirDocumentosLote(
            poolBiznagaSgc,
            archivos,
            usuario
        );
        const parcial = resultado.fallidos > 0 && resultado.exitosos > 0;
        return res.json({
            success: resultado.fallidos === 0,
            partial: parcial,
            message: resultado.fallidos === 0
                ? `${resultado.exitosos} documento(s) subido(s) correctamente.`
                : `${resultado.exitosos} de ${resultado.total} documento(s) subido(s).`,
            ...resultado
        });
    } catch (error) {
        handleError(res, error, 'No se pudo subir el lote de documentos');
    }
});

