/** Sube una imagen a la raíz del Repositorio DI y la deja lista para asociar al inventario. */
app.post('/api/innovacion/inventario/subir-imagen', requireAdminOrInnovacion, async (req, res) => {
    try {
        await poolBiznagaSgcReady;
        const usuario = obtenerNombreUsuarioAccion(req);
        const body = {
            ...(req.body || {}),
            // Raíz del repositorio: el usuario puede moverla después a una carpeta.
            carpeta_relativa: '',
            carpetaRelativa: ''
        };
        const documento = await sgcDocumentacionExtraService.subirDocumento(
            poolBiznagaSgc,
            body,
            usuario
        );
        if (!innovacionInventarioService.esMimeImagen(documento.mimeType, documento.nombreArchivo)) {
            try {
                await sgcDocumentacionExtraService.eliminarDocumento(poolBiznagaSgc, documento.id);
            } catch (cleanupErr) {
                console.warn('[inventario] No se pudo limpiar archivo no-imagen:', cleanupErr.message);
            }
            return res.status(400).json({
                success: false,
                message: 'Solo se permiten imágenes (JPG, PNG, WEBP, GIF o SVG).'
            });
        }
        return res.json({
            success: true,
            message: 'Imagen subida al repositorio. Quedó en la raíz para que pueda moverla a una carpeta.',
            documento
        });
    } catch (error) {
        if (
            String(error.message || '').includes('archivo')
            || String(error.message || '').includes('vacío')
            || String(error.message || '').includes('inválido')
        ) {
            return res.status(400).json({ success: false, message: error.message });
        }
        handleError(res, error, 'No se pudo subir la imagen al repositorio');
    }
});

