app.get('/api/innovacion/inventario/:id/miniatura', requireAdminOrInnovacion, async (req, res) => {
    try {
        await poolBiznagaSgcReady;
        const item = await innovacionInventarioService.obtenerItem(poolBiznagaSgc, req.params.id);
        if (!item) {
            return res.status(404).json({ success: false, message: 'Registro de inventario no encontrado.' });
        }
        if (item.imagenSignId) {
            const { doc, buffer } = await innovacionSignService.leerBufferSign(
                poolBiznagaSgc,
                item.imagenSignId
            );
            const dataUrl = await sgcDocumentacionExtraService.bufferADataUrlMiniatura(buffer);
            return res.json({
                success: true,
                dataUrl,
                origen: 'catalogo',
                signId: item.imagenSignId,
                nombreArchivo: doc.nombreArchivo || doc.nombreSenal || null
            });
        }
        if (!item.imagenDocumentoId) {
            return res.status(404).json({ success: false, message: 'El registro no tiene imagen asociada.' });
        }
        const resultado = await sgcDocumentacionExtraService.obtenerMiniaturaDocumento(
            poolBiznagaSgc,
            item.imagenDocumentoId
        );
        return res.json({
            success: true,
            ...resultado,
            origen: 'repositorio',
            documentoId: item.imagenDocumentoId
        });
    } catch (error) {
        if (
            String(error.message || '').includes('no encontrado')
            || String(error.message || '').includes('ya no existe')
        ) {
            return res.status(404).json({ success: false, message: error.message });
        }
        handleError(res, error, 'No se pudo generar la miniatura del inventario');
    }
});

/** Descarga un documento-imagen del repositorio DI (para selector / miniaturas). */
app.get('/api/innovacion/inventario/documentos/:docId/archivo', requireAdminOrInnovacion, async (req, res) => {
    try {
        await poolBiznagaSgcReady;
        const docId = parseInt(req.params.docId, 10);
        const { doc, buffer } = await sgcDocumentacionExtraService.descargarBufferDocumento(
            poolBiznagaSgc,
            docId
        );
        if (!innovacionInventarioService.esMimeImagen(doc.mimeType, doc.nombreArchivo)) {
            return res.status(400).json({
                success: false,
                message: 'El documento no es una imagen.'
            });
        }
        const nombre = encodeURIComponent(doc.nombreArchivo || 'imagen');
        res.setHeader('Content-Type', doc.mimeType || 'image/jpeg');
        res.setHeader('Content-Disposition', `inline; filename="${nombre}"; filename*=UTF-8''${nombre}`);
        res.setHeader('Cache-Control', 'private, max-age=120');
        return res.send(buffer);
    } catch (error) {
        if (String(error.message || '').includes('no encontrado')) {
            return res.status(404).json({ success: false, message: error.message });
        }
        handleError(res, error, 'No se pudo descargar la imagen del repositorio');
    }
});

