// Obtener items de una plantilla PIPC (preview del xlsx para checklist de asignación)
app.get('/api/proteccion-civil/catalogo/documentos/:documentoId/plantilla-items', requireAdminOrPC, async (req, res) => {
    try {
        await poolProteccionCivilReady;
        const { documentoId } = req.params;

        const [rows] = await poolProteccionCivil.query(
            `SELECT documento_id, nombre, drive_file_id, mime_type, hoja_nombre, archivo_maestro_nombre
             FROM pc_catalogo_documento
             WHERE documento_id = ? AND activo = 1
             LIMIT 1`,
            [documentoId]
        );

        if (!rows.length) {
            return res.status(404).json({ success: false, message: 'Documento de catálogo no encontrado' });
        }

        const doc = rows[0];
        const esXlsx = esArchivoExcelCatalogo(doc.mime_type, doc.nombre || doc.archivo_maestro_nombre);

        if (!esXlsx || !doc.drive_file_id) {
            return res.status(400).json({ success: false, message: 'La plantilla no es un archivo Excel válido' });
        }

        let driveFileId = String(doc.drive_file_id || '').trim();
        if (!(await driveService.verificarArchivoExiste(driveFileId))) {
            const reparado = await repararDriveFileIdCatalogoPipc(doc);
            if (!reparado?.fileId) {
                return res.status(404).json({
                    success: false,
                    message: 'El archivo de Drive ya no existe. Sincroniza el catálogo PIPC.'
                });
            }
            driveFileId = reparado.fileId;
            await poolProteccionCivil.query(
                `UPDATE pc_catalogo_documento SET
                    drive_file_id = ?,
                    mime_type = ?,
                    drive_web_view_link = ?,
                    drive_download_link = ?,
                    fecha_actualizacion = NOW()
                 WHERE documento_id = ?`,
                [
                    reparado.fileId,
                    reparado.mimeType || doc.mime_type,
                    reparado.webViewLink || null,
                    reparado.webContentLink || null,
                    doc.documento_id
                ]
            );
        }

        const ExcelJS = require('exceljs');
        const buffer = await driveService.exportarArchivoXLSX(driveFileId);
        const workbook = new ExcelJS.Workbook();
        await workbook.xlsx.load(buffer);

        const worksheet = resolverWorksheetPipc(workbook, doc.hoja_nombre);
        if (!worksheet) {
            return res.status(400).json({ success: false, message: 'La plantilla no contiene hojas de cálculo' });
        }

        const parseado = parsearPlantillaPipcDesdeWorksheet(worksheet, {
            hojaNombre: doc.hoja_nombre || doc.nombre
        });
        const nombrePlantilla = String(doc.hoja_nombre || doc.nombre || 'Plantilla').replace(/\.xlsx?$/i, '').trim();

        res.json({
            success: true,
            documento_id: doc.documento_id,
            nombre: nombrePlantilla,
            hoja_nombre: doc.hoja_nombre || null,
            archivo_maestro_nombre: doc.archivo_maestro_nombre || null,
            total: parseado.total,
            items: parseado.items,
            grupos: parseado.grupos
        });
    } catch (error) {
        handleError(res, error, 'Error al leer items de la plantilla PIPC');
    }
});

// URL del editor integrado (Google Sheets) con pestaña correcta
app.get('/api/proteccion-civil/catalogo/documentos/:documentoId/url-editor', requireAdminOrPC, async (req, res) => {
    try {
        await poolProteccionCivilReady;
        const { documentoId } = req.params;
        const modo = String(req.query.modo || 'edit').toLowerCase() === 'preview' ? 'preview' : 'edit';

        const [rows] = await poolProteccionCivil.query(
            `SELECT documento_id, nombre, drive_file_id, mime_type, hoja_nombre, drive_sheet_gid, archivo_maestro_nombre
             FROM pc_catalogo_documento
             WHERE documento_id = ? AND activo = 1
             LIMIT 1`,
            [documentoId]
        );

        if (!rows.length || !rows[0].drive_file_id) {
            return res.status(404).json({ success: false, message: 'Documento de catálogo no encontrado' });
        }

        const doc = rows[0];
        const hojaObjetivo = String(doc.hoja_nombre || doc.nombre || '').trim();
        let driveFileId = String(doc.drive_file_id || '').trim();
        let mimeType = String(doc.mime_type || '').trim();

        if (!(await driveService.verificarArchivoExiste(driveFileId))) {
            const reparado = await repararDriveFileIdCatalogoPipc(doc);
            if (!reparado?.fileId) {
                return res.status(404).json({
                    success: false,
                    message: 'El archivo de Drive ya no existe. Sincroniza el catálogo PIPC.'
                });
            }
            driveFileId = reparado.fileId;
            mimeType = reparado.mimeType || mimeType;
            await poolProteccionCivil.query(
                `UPDATE pc_catalogo_documento SET
                    drive_file_id = ?,
                    mime_type = ?,
                    drive_web_view_link = ?,
                    drive_download_link = ?,
                    drive_sheet_gid = NULL,
                    fecha_actualizacion = NOW()
                 WHERE documento_id = ?`,
                [
                    reparado.fileId,
                    reparado.mimeType || mimeType,
                    reparado.webViewLink || null,
                    reparado.webContentLink || null,
                    doc.documento_id
                ]
            );
            console.log(`[PC-CATALOGO] Editor: drive_file_id reparado para documento ${doc.documento_id} -> ${reparado.fileId}`);
        }

        const asegurado = await driveService.asegurarSpreadsheetNativoParaCatalogo(
            driveFileId,
            String(doc.archivo_maestro_nombre || doc.nombre || '').trim()
        );
        if (asegurado.converted) {
            await actualizarDriveFileMaestroCatalogo(poolProteccionCivil, driveFileId, asegurado);
            console.log(`[PC-CATALOGO] Editor: xlsx ${asegurado.previousFileId} -> Google Sheet ${asegurado.fileId}`);
            driveFileId = asegurado.fileId;
            mimeType = asegurado.mimeType;
        }

        let gid = null;

        if (hojaObjetivo) {
            gid = await driveService.obtenerGidHojaPorNombre(driveFileId, hojaObjetivo);
            if (gid != null) {
                const gidCached = doc.drive_sheet_gid != null ? Number(doc.drive_sheet_gid) : null;
                if (gidCached !== gid) {
                    await poolProteccionCivil.query(
                        'UPDATE pc_catalogo_documento SET drive_sheet_gid = ?, fecha_actualizacion = NOW() WHERE documento_id = ?',
                        [gid, doc.documento_id]
                    );
                }
            } else if (doc.drive_sheet_gid) {
                console.warn(
                    `[PC-CATALOGO] gid no resuelto para documento ${doc.documento_id} hoja "${hojaObjetivo}", `
                    + `se omite caché ${doc.drive_sheet_gid}`
                );
            }
        }

        const esExcel = esArchivoExcelCatalogo(mimeType, doc.nombre)
            || mimeType.includes('google-apps.spreadsheet');
        let url = '';
        if (esExcel) {
            url = driveService.construirUrlEditorGoogleSheet(driveFileId, { modo, gid });
        } else if (modo === 'edit') {
            const mime = String(doc.mime_type || '').toLowerCase();
            if (mime === 'application/vnd.google-apps.document') {
                url = `https://docs.google.com/document/d/${driveFileId}/edit`;
            } else if (mime === 'application/vnd.google-apps.presentation') {
                url = `https://docs.google.com/presentation/d/${driveFileId}/edit`;
            } else {
                url = `https://drive.google.com/file/d/${driveFileId}/preview`;
            }
        } else {
            url = `https://drive.google.com/file/d/${driveFileId}/preview`;
        }

        res.json({
            success: true,
            url,
            drive_file_id: driveFileId,
            gid,
            hoja_nombre: hojaObjetivo || null,
            modo
        });
    } catch (error) {
        handleError(res, error, 'Error al resolver URL del editor de catálogo');
    }
});

// Asignar documentos del catálogo a una empresa (descarga xlsx y parsea sub-documentos)
app.post('/api/proteccion-civil/empresas/:empresaId/asignar-catalogo', requireAdminOrPC, async (req, res) => {
    try {
        const { empresaId } = req.params;
        const { documentos } = req.body;
        const asignadoPorUsuarioId = Number(req?.user?.id) || null;

        console.log(`[PC-ASIGNAR] Inicio empresa_id=${empresaId}, total_documentos=${Array.isArray(documentos) ? documentos.length : 0}, usuario_id=${asignadoPorUsuarioId || 'N/A'}`);

        if (!Array.isArray(documentos) || documentos.length === 0) {
            return res.status(400).json({ success: false, message: 'No se enviaron documentos para asignar' });
        }

        const ExcelJS = require('exceljs');
        let totalPadres = 0;
        let totalHijos = 0;
        const resumen = [];
        const tareasCarpetas = [];

        const normalizarTitulo = (valor = '') => String(valor)
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/[^a-z0-9\s]/gi, '')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();

        const esSubtituloEntrega = (valor = '') => {
            const n = normalizarTitulo(valor);
            return n === 'fisico' || n === 'usb' || n === 'presentar';
        };

        const obtenerMetaEntrada = (nombreRaw = '') => {
            const limpio = String(nombreRaw || '').trim();
            if (!limpio) return { nombre: '', tipoEntrada: 'archivo' };
            const esTexto = limpio.startsWith('*') || limpio.endsWith('*');
            if (esTexto) {
                return {
                    nombre: limpio.replace(/^\*+/, '').replace(/\*+$/, '').trim(),
                    tipoEntrada: 'texto'
                };
            }
            return { nombre: limpio, tipoEntrada: 'archivo' };
        };

        // Obtener nombre de empresa para crear carpetas en Drive
        let nombreEmpresaPC = String(empresaId);
        try {
            const [empRowsPC] = await pool.query('SELECT nombre_empresa FROM empresa WHERE empresa_id = ?', [empresaId]);
            if (empRowsPC.length > 0) nombreEmpresaPC = empRowsPC[0].nombre_empresa;
        } catch (e) { /* silenced */ }

        const registrarResolutivoTramite = async (padreId, nombreAsignacion) => {
            if (!padreId) return;
            try {
                await poolBiznagaSgcReady;
                await pcResolutivosService.crearResolutivoEnTramite({
                    poolSgc: poolBiznagaSgc,
                    poolBiznaga: pool,
                    empresaId: Number(empresaId),
                    documentoAsignacionId: padreId,
                    nombreAsignacion,
                    responsableUsuarioId: asignadoPorUsuarioId
                });
            } catch (resErr) {
                console.warn(`[PC-ASIGNAR] No se pudo crear resolutivo En trámite (${nombreAsignacion}):`, resErr.message);
            }
        };

        const buscarPadreAsignacionActiva = async (nombreLimpio) => {
            const [rows] = await poolProteccionCivil.query(
                `SELECT documento_id, especificacion
                 FROM documento_proteccion_civil
                 WHERE empresa_id = ?
                   AND (documento_padre_id IS NULL OR documento_padre_id = 0)
                   AND LOWER(TRIM(REPLACE(REPLACE(nombre_documento, '.xlsx', ''), '.XLSX', ''))) = LOWER(TRIM(?))
                 ORDER BY documento_id DESC
                 LIMIT 1`,
                [empresaId, nombreLimpio]
            );
            return rows[0] || null;
        };

        const obtenerNombresHijosExistentes = async (padreId) => {
            const [rows] = await poolProteccionCivil.query(
                'SELECT nombre_documento FROM documento_proteccion_civil WHERE documento_padre_id = ?',
                [padreId]
            );
            return new Set(rows.map((row) => normalizarTitulo(row.nombre_documento)));
        };

        const filtrarFilasNuevas = async (padreId, filasLista) => {
            if (!Array.isArray(filasLista) || filasLista.length === 0) return [];
            const existentes = await obtenerNombresHijosExistentes(padreId);
            return filasLista.filter((fila) => !existentes.has(normalizarTitulo(fila.nombre)));
        };

        const sincronizarVisibilidadHijos = async (padreId, filasLista) => {
            if (!padreId || !Array.isArray(filasLista) || !filasLista.length) return;
            const [hijos] = await poolProteccionCivil.query(
                'SELECT documento_id, nombre_documento FROM documento_proteccion_civil WHERE documento_padre_id = ?',
                [padreId]
            );
            for (const fila of filasLista) {
                const clave = normalizarClaveDocumentoPipc(fila.nombre);
                const hijo = hijos.find((row) => normalizarClaveDocumentoPipc(row.nombre_documento) === clave);
                if (!hijo) continue;
                await poolProteccionCivil.query(
                    'UPDATE documento_proteccion_civil SET visible_empresa = ?, fecha_actualizacion = NOW() WHERE documento_id = ?',
                    [fila.visible_empresa ? 1 : 0, hijo.documento_id]
                );
            }
        };

        const construirFilasCompletasDesdeDoc = async (docRef, nombrePlantilla) => {
            if (Array.isArray(docRef.items_necesarios) && docRef.items_necesarios.length && !docRef.items_checklist?.length) {
                docRef.items_checklist = docRef.items_necesarios.map((item) => ({
                    nombre: item.nombre || item.documento,
                    especificacion: item.especificacion,
                    obligatorio: item.obligatorio,
                    tipo_entrada: item.tipo_entrada,
                    visible_empresa: true,
                    necesario: true
                }));
            }
            return construirFilasPipcCompletas(driveService, docRef, nombrePlantilla);
        };

        let totalPadresNuevos = 0;
        let totalPadresActualizados = 0;
        const pdfsGenerados = [];

        for (const doc of documentos) {
            const esXlsx = esArchivoExcelCatalogo(doc.mime_type, doc.nombre || doc.archivo_maestro_nombre);

            if (esXlsx && doc.drive_file_id) {
                // ── Documento XLSX: crear padre + hijos según checklist ──
                try {
                    let hojaNombre = String(doc.hoja_nombre || '').trim();
                    if (!hojaNombre && doc.catalogo_documento_id) {
                        const [catDocRows] = await poolProteccionCivil.query(
                            'SELECT hoja_nombre, nombre FROM pc_catalogo_documento WHERE documento_id = ? AND activo = 1 LIMIT 1',
                            [doc.catalogo_documento_id]
                        );
                        if (catDocRows.length) {
                            hojaNombre = String(catDocRows[0].hoja_nombre || '').trim();
                            if (!doc.nombre && catDocRows[0].nombre) {
                                doc.nombre = catDocRows[0].nombre;
                            }
                        }
                    }
                    doc.hoja_nombre = hojaNombre || doc.hoja_nombre;

                    const nombreLimpio = (doc.nombre || doc.hoja_nombre || 'Documento').replace(/\.xlsx?$/i, '').trim();
                    const padreExistente = await buscarPadreAsignacionActiva(nombreLimpio);
                    let padreId;
                    let padreEsNuevo = false;

                    if (padreExistente) {
                        padreId = padreExistente.documento_id;
                        totalPadres++;
                        totalPadresActualizados++;
                        if (doc.catalogo_documento_id) {
                            await poolProteccionCivil.query(
                                `UPDATE documento_proteccion_civil
                                 SET catalogo_documento_id = COALESCE(catalogo_documento_id, ?),
                                     fecha_actualizacion = NOW()
                                 WHERE documento_id = ?`,
                                [doc.catalogo_documento_id, padreId]
                            );
                        }
                        await registrarResolutivoTramite(padreId, nombreLimpio);
                        console.log(`[PC-ASIGNAR] Reutilizando asignación existente "${nombreLimpio}" (padre_id=${padreId})`);
                    } else {
                        const [parentResult] = await poolProteccionCivil.query(`
                            INSERT INTO documento_proteccion_civil
                                (empresa_id, nombre_documento, especificacion, obligatorio, estatus, catalogo_documento_id, asignado_por_usuario_id, tipo_entrada, fecha_asignacion, fecha_creacion)
                            VALUES (?, ?, 'Documento asignado desde catálogo', 1, 'pendiente', ?, ?, 'archivo', NOW(), NOW())
                        `, [empresaId, nombreLimpio, doc.catalogo_documento_id || null, asignadoPorUsuarioId]);

                        padreId = parentResult.insertId;
                        padreEsNuevo = true;
                        totalPadres++;
                        totalPadresNuevos++;
                        await registrarResolutivoTramite(padreId, nombreLimpio);

                        const ahora = new Date();
                        const fechaCarpeta = `${String(ahora.getDate()).padStart(2, '0')}-${String(ahora.getMonth() + 1).padStart(2, '0')}-${ahora.getFullYear()}`;
                        const nombreCarpetaDrive = `${nombreLimpio}_${fechaCarpeta}`;
                        tareasCarpetas.push(
                            driveService.crearCarpetaDocumentoPC(nombreEmpresaPC, nombreCarpetaDrive)
                                .catch((folderErr) => {
                                    // silenced
                                })
                        );
                        await poolProteccionCivil.query(
                            'UPDATE documento_proteccion_civil SET especificacion = ? WHERE documento_id = ?',
                            [`carpeta_drive:${nombreCarpetaDrive}`, padreId]
                        );
                    }

                    let filasCompletas = [];

                    try {
                        filasCompletas = await construirFilasCompletasDesdeDoc(doc, nombreLimpio);
                    } catch (lecturaErr) {
                        console.warn(`[PC-ASIGNAR] No se pudo construir checklist completo para "${nombreLimpio}":`, lecturaErr.message);
                    }

                    if (!filasCompletas.length) {
                        resumen.push({ nombre: nombreLimpio, tipo: 'xlsx', subdocumentos: 0 });
                        continue;
                    }

                    console.log(`[PC-ASIGNAR] Checklist completo: ${filasCompletas.length} requisito(s), visibles empresa: ${filasCompletas.filter((f) => f.visible_empresa).length} para "${nombreLimpio}"`);

                    const esActualizacionPadre = !padreEsNuevo && !!padreExistente;
                    let filasParaSync = filasCompletas;
                    if (esActualizacionPadre && Array.isArray(doc.items_necesarios) && doc.items_necesarios.length) {
                        filasParaSync = doc.items_necesarios
                            .map((item) => ({
                                nombre: String(item.nombre || item.documento || '').trim(),
                                especificacion: String(item.especificacion || '').trim(),
                                obligatorio: item.obligatorio !== false,
                                tipo_entrada: item.tipo_entrada || 'archivo',
                                visible_empresa: item.visible_empresa !== false && item.visible_empresa !== 0
                            }))
                            .filter((item) => item.nombre);
                    }

                    const syncPipc = await insertarRequisitosFaltantesPadrePipc({
                        poolProteccionCivil,
                        driveService,
                        empresaId: Number(empresaId),
                        padreId,
                        padreNombre: nombreLimpio,
                        catalogoDocumentoId: doc.catalogo_documento_id || null,
                        asignadoPorUsuarioId,
                        actualizarVisibilidad: true,
                        filasVisibilidad: filasParaSync
                    });
                    const filasNuevas = syncPipc.insertados;
                    totalHijos += filasNuevas;

                    const itemsPdf = filasCompletas.filter((fila) => fila.visible_empresa);
                    if (itemsPdf.length) {
                        try {
                            const tituloPdf = /^pipc/i.test(nombreLimpio) ? nombreLimpio : `PIPC ${nombreLimpio}`;
                            const pdfBuffer = await generarListadoPipcPdf({
                                tituloUbicacion: tituloPdf,
                                items: itemsPdf.map((fila) => ({
                                    documento: fila.nombre,
                                    especificacion: fila.especificacion
                                }))
                            });
                            pdfsGenerados.push({
                                plantilla: nombreLimpio,
                                filename: `Listado_${sanitizarNombreArchivo(tituloPdf)}.pdf`,
                                mime_type: 'application/pdf',
                                base64: pdfBuffer.toString('base64')
                            });
                        } catch (pdfErr) {
                            console.warn(`[PC-ASIGNAR] No se pudo generar PDF para "${nombreLimpio}":`, pdfErr.message);
                        }
                    }

                    resumen.push({
                        nombre: nombreLimpio,
                        tipo: padreEsNuevo ? 'xlsx' : 'xlsx-actualizado',
                        subdocumentos: filasNuevas.length,
                        total_requisitos: filasCompletas.length,
                        visibles_empresa: itemsPdf.length
                    });

                } catch (parseErr) {
                    console.error(`[PC-ASIGNAR] Error procesando xlsx "${doc.nombre}":`, parseErr.message);
                    const nombreLimpio = (doc.nombre || 'Documento').replace(/\.xlsx?$/i, '').trim();
                    const padreExistente = await buscarPadreAsignacionActiva(nombreLimpio);
                    if (padreExistente) {
                        totalPadres++;
                        totalPadresActualizados++;
                        await registrarResolutivoTramite(padreExistente.documento_id, nombreLimpio);
                        resumen.push({ nombre: nombreLimpio, tipo: 'xlsx-error-actualizado', subdocumentos: 0 });
                    } else {
                        const [fallbackResult] = await poolProteccionCivil.query(`
                            INSERT INTO documento_proteccion_civil
                                (empresa_id, nombre_documento, especificacion, obligatorio, estatus, catalogo_documento_id, asignado_por_usuario_id, tipo_entrada, fecha_asignacion, fecha_creacion)
                            VALUES (?, ?, 'Error al leer xlsx - asignado como documento individual', 1, 'pendiente', ?, ?, 'archivo', NOW(), NOW())
                        `, [empresaId, nombreLimpio, doc.catalogo_documento_id || null, asignadoPorUsuarioId]);
                        totalPadres++;
                        totalPadresNuevos++;
                        await registrarResolutivoTramite(fallbackResult.insertId, nombreLimpio);
                        resumen.push({ nombre: nombreLimpio, tipo: 'xlsx-error', subdocumentos: 0 });
                    }
                }
            } else {
                // ── Documento no-xlsx: crear registro individual ──
                const nombreDoc = (doc.nombre || 'Documento').replace(/\.[^.]+$/, '').trim();
                const padreExistente = await buscarPadreAsignacionActiva(nombreDoc);
                if (padreExistente) {
                    totalPadres++;
                    totalPadresActualizados++;
                    await registrarResolutivoTramite(padreExistente.documento_id, nombreDoc);
                    resumen.push({ nombre: nombreDoc, tipo: 'individual-actualizado', subdocumentos: 0 });
                } else {
                    const [resultIndividual] = await poolProteccionCivil.query(`
                        INSERT INTO documento_proteccion_civil
                            (empresa_id, nombre_documento, especificacion, obligatorio, estatus, catalogo_documento_id, asignado_por_usuario_id, tipo_entrada, fecha_asignacion, fecha_creacion)
                        VALUES (?, ?, '', 1, 'pendiente', ?, ?, 'archivo', NOW(), NOW())
                    `, [empresaId, nombreDoc, doc.catalogo_documento_id || null, asignadoPorUsuarioId]);
                    totalPadres++;
                    totalPadresNuevos++;
                    await registrarResolutivoTramite(resultIndividual.insertId, nombreDoc);

                    const ahoraInd = new Date();
                    const fechaInd = `${String(ahoraInd.getDate()).padStart(2, '0')}-${String(ahoraInd.getMonth() + 1).padStart(2, '0')}-${ahoraInd.getFullYear()}`;
                    const nombreCarpetaInd = `${nombreDoc}_${fechaInd}`;
                    tareasCarpetas.push(
                        driveService.crearCarpetaDocumentoPC(nombreEmpresaPC, nombreCarpetaInd)
                            .catch((folderErr) => {
                                // silenced
                            })
                    );
                    await poolProteccionCivil.query(
                        'UPDATE documento_proteccion_civil SET especificacion = ? WHERE documento_id = ?',
                        [`carpeta_drive:${nombreCarpetaInd}`, resultIndividual.insertId]
                    );

                    resumen.push({ nombre: nombreDoc, tipo: 'individual', subdocumentos: 0 });
                }
            }
        }

        if (tareasCarpetas.length > 0) {
            await Promise.allSettled(tareasCarpetas);
        }

        // Notificar a usuarios de empresa por cada documento padre asignado
        if (resumen.length > 0) {
            const nombresPadre = [...new Set(resumen.map(r => (r?.nombre || '').trim()).filter(Boolean))];
            await notificarAsignacionPadresPCAEmpresa(empresaId, nombresPadre);
        }

        // Notificacion por correo a empresa (sin listar documentos)
        try {
            const [empresaRows] = await pool.query(
                'SELECT nombre_empresa FROM empresa WHERE empresa_id = ? LIMIT 1',
                [empresaId]
            );
            const nombreEmpresa = empresaRows.length > 0
                ? empresaRows[0].nombre_empresa
                : `Empresa #${empresaId}`;

            console.log(`[EMAIL][PC] Preparando correo de asignacion para empresa_id=${empresaId} (${nombreEmpresa})`);

            const correosEmpresa = await obtenerCorreosEmpresaPC(empresaId);
            console.log(`[EMAIL][PC] Destinatarios empresa_id=${empresaId}: ${correosEmpresa.length}`);
            if (correosEmpresa.length === 0) {
                console.warn(`[EMAIL][PC] Sin destinatarios para empresa_id=${empresaId}`);
            }
            for (const correo of correosEmpresa) {
                emailService.notificarEmpresaDocumentosPCAsignados({
                    empresaEmail: correo,
                    empresaNombre: nombreEmpresa,
                    fechaAsignacion: new Date()
                }).then((resultado) => {
                    if (resultado?.success) {
                        console.log(`[EMAIL][PC] Asignacion enviada a empresa: ${correo}`);
                    } else {
                        console.warn(`[EMAIL][PC] Asignacion no enviada a ${correo}: ${resultado?.error || 'sin detalle'}`);
                    }
                }).catch((err) => {
                    console.error(`[EMAIL][PC] Error notificando asignacion a empresa (${correo}):`, err.message);
                });
            }
        } catch (emailErr) {
            console.error('[EMAIL][PC] Error preparando notificacion de asignacion a empresa:', emailErr.message);
        }

        let pipcCobertura = null;
        try {
            const [docsActuales] = await poolProteccionCivil.query(
                `SELECT documento_id, documento_padre_id, catalogo_documento_id, clave_workflow
                 FROM documento_proteccion_civil WHERE empresa_id = ?`,
                [empresaId]
            );
            const syncOps = await pcCentroOperaciones.syncPasoAsignarSegunCobertura(
                poolProteccionCivil,
                empresaId,
                docsActuales
            );
            pipcCobertura = syncOps.pipc_cobertura;
        } catch (syncOpsErr) {
            console.warn('[PC-ASIGNAR] No se pudo sincronizar paso asignar:', syncOpsErr.message);
        }

        res.json({
            success: true,
            message: `Asignación completada: ${totalPadres} plantilla(s) procesada(s), ${totalHijos} requisito(s) nuevo(s)`,
            totalPadres,
            totalPadresNuevos,
            totalPadresActualizados,
            totalHijos,
            resumen,
            pdfs: pdfsGenerados,
            pipc_cobertura: pipcCobertura
        });
    } catch (error) {
        handleError(res, error, 'Error al asignar documentos desde catálogo');
    }
});

// Actualizar estatus de un documento de PC
app.put('/api/proteccion-civil/documentos/:documentoId/estatus', requireAdminOrPC, async (req, res) => {
    try {
        const { documentoId } = req.params;
        const { estatus } = req.body;

        const estatusValidos = ['pendiente', 'aprobado', 'rechazado', 'revision'];
        if (!estatusValidos.includes(estatus)) {
            return res.status(400).json({ success: false, message: 'Estatus inválido' });
        }

        await poolProteccionCivil.query(
            'UPDATE documento_proteccion_civil SET estatus = ?, fecha_actualizacion = NOW() WHERE documento_id = ?',
            [estatus, documentoId]
        );

        // Si se aprueba y tiene archivo, registrar en historial (archivo ya está en Proteccion_civil/Historial de documentos/)
        if (estatus === 'aprobado') {
            try {
                await registrarHistorialDocumentoAprobadoPC(documentoId);
            } catch (historialErr) {
                // silenced
            }
        }

        // Si deja de estar aprobado (rechazo o reapertura a pendiente/revisión), quitar del historial
        if (estatus === 'rechazado' || estatus === 'pendiente' || estatus === 'revision') {
            try {
                await poolProteccionCivil.query(
                    'DELETE FROM historial_documentos_pc WHERE documento_id = ?',
                    [documentoId]
                );
                await poolProteccionCivil.query(
                    'DELETE FROM historial_textos_pc WHERE documento_id = ?',
                    [documentoId]
                );
            } catch (histErr) {
                // silenced
            }
        }

        res.json({ success: true, message: 'Estatus actualizado correctamente' });
    } catch (error) {
        handleError(res, error, 'Error al actualizar estatus del documento');
    }
});

