// Eliminar documento de PC
app.delete('/api/proteccion-civil/documentos/:documentoId', requireAdminOrPC, async (req, res) => {
    try {
        const { documentoId } = req.params;
        const [targetRows] = await poolProteccionCivil.query(
            `SELECT d.documento_id, d.empresa_id, d.documento_padre_id, d.archivo_url, d.estatus,
                    COALESCE(p.documento_id, d.documento_id) AS padre_id,
                    COALESCE(p.especificacion, d.especificacion) AS espec_padre
             FROM documento_proteccion_civil d
             LEFT JOIN documento_proteccion_civil p ON d.documento_padre_id = p.documento_id
             WHERE d.documento_id = ?`,
            [documentoId]
        );

        if (targetRows.length === 0) {
            return res.status(404).json({ success: false, message: 'Documento no encontrado' });
        }

        const target = targetRows[0];
        const esPadre = !target.documento_padre_id;

        let allDocs = [target];
        if (esPadre) {
            const [rowsPadre] = await poolProteccionCivil.query(
                'SELECT documento_id, empresa_id, archivo_url, estatus FROM documento_proteccion_civil WHERE documento_id = ? OR documento_padre_id = ?',
                [target.documento_id, target.documento_id]
            );
            allDocs = rowsPadre;
        }

        const empresaId = target.empresa_id;
        // Eliminar archivos de Google Drive solo para documentos NO aprobados
        for (const doc of allDocs) {
            if (doc.estatus === 'aprobado') continue; // conservar archivos aprobados en Drive
            if (doc.archivo_url && doc.archivo_url.length > 10) {
                try {
                    await driveService.eliminarArchivo(doc.archivo_url);
                } catch (driveErr) {
                    // silenced
                }
            }
            try {
                const adjuntos = await listarArchivosDocumentoPC(doc.documento_id);
                for (const adj of adjuntos) {
                    if (!adj.drive_file_id || String(adj.drive_file_id).length <= 10) continue;
                    if (doc.archivo_url && String(adj.drive_file_id) === String(doc.archivo_url)) continue;
                    try {
                        await driveService.eliminarArchivo(adj.drive_file_id);
                    } catch (driveErr) {
                        // silenced
                    }
                }
            } catch (listErr) {
                // silenced
            }
        }
        // Eliminar historial vinculado solo a documentos NO aprobados
        const idsNoAprobados = allDocs.filter((d) => d.estatus !== 'aprobado').map((d) => d.documento_id);
        const idsEliminar = allDocs.map((d) => d.documento_id);
        if (idsNoAprobados.length > 0) {
            await poolProteccionCivil.query(
                'DELETE FROM historial_documentos_pc WHERE documento_id IN (?)',
                [idsNoAprobados]
            );
            await poolProteccionCivil.query(
                'DELETE FROM historial_textos_pc WHERE documento_id IN (?)',
                [idsNoAprobados]
            );
        }
        if (idsEliminar.length > 0) {
            await poolProteccionCivil.query(
                'DELETE FROM documento_proteccion_civil_archivo WHERE documento_id IN (?)',
                [idsEliminar]
            );
        }

        let padreEliminadoEnCascada = false;

        if (esPadre) {
            // Eliminar hijos primero, luego el padre
            await poolProteccionCivil.query('DELETE FROM documento_proteccion_civil WHERE documento_padre_id = ?', [target.documento_id]);
            await poolProteccionCivil.query('DELETE FROM documento_proteccion_civil WHERE documento_id = ?', [target.documento_id]);
        } else {
            await poolProteccionCivil.query('DELETE FROM documento_proteccion_civil WHERE documento_id = ?', [target.documento_id]);

            const padreId = Number(target.padre_id || 0);
            if (padreId > 0) {
                const [padreRows] = await poolProteccionCivil.query(
                    `SELECT documento_id, empresa_id, catalogo_documento_id, especificacion, archivo_url, estatus
                     FROM documento_proteccion_civil WHERE documento_id = ?`,
                    [padreId]
                );
                if (padreRows.length > 0) {
                    const padre = padreRows[0];
                    const [hijosRestantes] = await poolProteccionCivil.query(
                        'SELECT documento_id, nombre_documento, archivo_url, estatus FROM documento_proteccion_civil WHERE documento_padre_id = ?',
                        [padreId]
                    );
                    const hijosReales = hijosRestantes.filter(
                        (hijo) => !esSubtituloOperativoPcNombre(hijo.nombre_documento)
                    );
                    if (hijosReales.length === 0 && Number(padre.catalogo_documento_id || 0) > 0) {
                        for (const hijo of hijosRestantes) {
                            if (hijo.estatus === 'aprobado') continue;
                            if (hijo.archivo_url && hijo.archivo_url.length > 10) {
                                try {
                                    await driveService.eliminarArchivo(hijo.archivo_url);
                                } catch (driveErr) {
                                    // silenced
                                }
                            }
                        }
                        const idsHijosRestantes = hijosRestantes.map((hijo) => hijo.documento_id);
                        const idsHijosNoAprobados = hijosRestantes
                            .filter((hijo) => hijo.estatus !== 'aprobado')
                            .map((hijo) => hijo.documento_id);
                        if (idsHijosNoAprobados.length > 0) {
                            await poolProteccionCivil.query(
                                'DELETE FROM historial_documentos_pc WHERE documento_id IN (?)',
                                [idsHijosNoAprobados]
                            );
                            await poolProteccionCivil.query(
                                'DELETE FROM historial_textos_pc WHERE documento_id IN (?)',
                                [idsHijosNoAprobados]
                            );
                        }
                        if (idsHijosRestantes.length > 0) {
                            await poolProteccionCivil.query(
                                'DELETE FROM documento_proteccion_civil WHERE documento_id IN (?)',
                                [idsHijosRestantes]
                            );
                        }
                        await poolProteccionCivil.query(
                            'DELETE FROM documento_proteccion_civil WHERE documento_id = ?',
                            [padreId]
                        );
                        allDocs.push(padre, ...hijosRestantes);
                        padreEliminadoEnCascada = true;
                    }
                }
            }
        }

        // Limpiar carpeta Drive de la asignación padre SOLO si no hay documentos aprobados
        // (los archivos aprobados viven dentro de esa carpeta, borrarla los eliminaría de Drive)
        const tieneAprobados = allDocs.some(d => d.estatus === 'aprobado');
        const especCarpetaPadre = esPadre
            ? target.espec_padre
            : (padreEliminadoEnCascada
                ? allDocs.find((doc) => Number(doc.catalogo_documento_id || 0) > 0)?.especificacion
                : null);
        const debeLimpiarCarpeta = (esPadre || padreEliminadoEnCascada)
            && !tieneAprobados
            && especCarpetaPadre
            && String(especCarpetaPadre).startsWith('carpeta_drive:');
        if (debeLimpiarCarpeta) {
            const nombreCarpeta = String(especCarpetaPadre).replace('carpeta_drive:', '');
            try {
                const [empRows] = await pool.query('SELECT nombre_empresa FROM empresa WHERE empresa_id = ?', [empresaId]);
                const nombreEmpresa = empRows.length > 0 ? empRows[0].nombre_empresa : String(empresaId);
                await driveService.eliminarCarpetaDocumentoPC(nombreEmpresa, nombreCarpeta);
            } catch (folderErr) {
                // silenced
            }
        }

        // Si no queda ningún registro en historial para esta empresa, limpiar carpeta de empresa en Drive
        const [historialRows] = await poolProteccionCivil.query(
            `SELECT COUNT(*) AS total FROM historial_documentos_pc WHERE empresa_id = ?`,
            [empresaId]
        );

        if ((historialRows[0]?.total || 0) === 0) {
            try {
                const [empRows] = await pool.query('SELECT nombre_empresa FROM empresa WHERE empresa_id = ?', [empresaId]);
                const nombreEmpresa = empRows.length > 0 ? empRows[0].nombre_empresa : String(empresaId);
                await driveService.eliminarCarpetaHistorialEmpresaPC(nombreEmpresa);
            } catch (cleanupErr) {
                // silenced
            }
        }
        const totalEliminados = allDocs.length;

        try {
            const [docsRestantes] = await poolProteccionCivil.query(
                `SELECT documento_id, documento_padre_id, catalogo_documento_id, clave_workflow
                 FROM documento_proteccion_civil WHERE empresa_id = ?`,
                [empresaId]
            );
            await pcCentroOperaciones.syncPasoAsignarSegunCobertura(
                poolProteccionCivil,
                empresaId,
                docsRestantes
            );
        } catch (syncOpsErr) {
            console.warn('[PC] No se pudo sincronizar paso asignar tras eliminar documento:', syncOpsErr.message);
        }

        res.json({
            success: true,
            message: `Asignación cancelada correctamente (${totalEliminados} documento${totalEliminados > 1 ? 's' : ''} eliminado${totalEliminados > 1 ? 's' : ''})`,
            padre_eliminado: padreEliminadoEnCascada || esPadre
        });
    } catch (error) {
        handleError(res, error, 'Error al eliminar documento');
    }
});

// Eliminar TODOS los archivos de un documento de PC (sin eliminar la asignación)
app.delete('/api/proteccion-civil/empresas/:empresaId/documentos/:documentoId/archivo', requireAdminOrEmpresa, verificarEmpresaPropia, verificarServicioProteccionCivilEmpresa, async (req, res) => {
    try {
        const { empresaId, documentoId } = req.params;

        // Obtener archivo actual
        const [docs] = await poolProteccionCivil.query(
            'SELECT archivo_url, nombre_archivo FROM documento_proteccion_civil WHERE documento_id = ? AND empresa_id = ?',
            [documentoId, empresaId]
        );

        if (docs.length === 0) {
            return res.status(404).json({ success: false, message: 'Documento no encontrado' });
        }

        const archivos = await listarArchivosDocumentoPC(documentoId);
        const driveIds = new Set();
        for (const archivo of archivos) {
            if (archivo.drive_file_id && String(archivo.drive_file_id).length > 10) {
                driveIds.add(String(archivo.drive_file_id));
            }
        }
        if (docs[0].archivo_url && docs[0].archivo_url.length > 10) {
            driveIds.add(String(docs[0].archivo_url));
        }

        for (const driveId of driveIds) {
            try {
                await driveService.eliminarArchivo(driveId);
            } catch (driveErr) {
                // silenced
            }
        }

        await poolProteccionCivil.query(
            'DELETE FROM documento_proteccion_civil_archivo WHERE documento_id = ?',
            [documentoId]
        );

        // Limpiar campos de archivo y resetear estatus a pendiente
        await poolProteccionCivil.query(`
            UPDATE documento_proteccion_civil 
            SET archivo_url = NULL, nombre_archivo = NULL, valor_texto = NULL, fecha_subida = NULL, estatus = 'pendiente', fecha_actualizacion = NOW()
            WHERE documento_id = ? AND empresa_id = ?
        `, [documentoId, empresaId]);

        res.json({ success: true, message: 'Archivo eliminado correctamente', archivos: [] });
    } catch (error) {
        handleError(res, error, 'Error al eliminar archivo');
    }
});

// Eliminar un archivo específico de un requerimiento PC
app.delete('/api/proteccion-civil/empresas/:empresaId/documentos/:documentoId/archivos/:archivoId', requireAdminOrEmpresa, verificarEmpresaPropia, verificarServicioProteccionCivilEmpresa, async (req, res) => {
    try {
        const { empresaId, documentoId, archivoId } = req.params;

        const [docs] = await poolProteccionCivil.query(
            'SELECT documento_id, estatus FROM documento_proteccion_civil WHERE documento_id = ? AND empresa_id = ?',
            [documentoId, empresaId]
        );
        if (docs.length === 0) {
            return res.status(404).json({ success: false, message: 'Documento no encontrado' });
        }

        const [archivos] = await poolProteccionCivil.query(
            `SELECT archivo_id, drive_file_id, nombre_archivo
             FROM documento_proteccion_civil_archivo
             WHERE archivo_id = ? AND documento_id = ?
             LIMIT 1`,
            [archivoId, documentoId]
        );

        if (!archivos.length) {
            return res.status(404).json({ success: false, message: 'Archivo no encontrado' });
        }

        const archivo = archivos[0];
        if (archivo.drive_file_id && String(archivo.drive_file_id).length > 10) {
            try {
                await driveService.eliminarArchivo(archivo.drive_file_id);
            } catch (driveErr) {
                // silenced
            }
        }

        await poolProteccionCivil.query(
            'DELETE FROM documento_proteccion_civil_archivo WHERE archivo_id = ? AND documento_id = ?',
            [archivoId, documentoId]
        );

        const restantes = await listarArchivosDocumentoPC(documentoId);
        await sincronizarCamposLegacyArchivoPC(documentoId);

        if (!restantes.length) {
            await poolProteccionCivil.query(
                `UPDATE documento_proteccion_civil
                 SET estatus = 'pendiente', fecha_actualizacion = NOW()
                 WHERE documento_id = ? AND empresa_id = ?`,
                [documentoId, empresaId]
            );
        }

        const [estadoRows] = await poolProteccionCivil.query(
            'SELECT estatus, archivo_url, nombre_archivo, fecha_subida FROM documento_proteccion_civil WHERE documento_id = ? LIMIT 1',
            [documentoId]
        );

        res.json({
            success: true,
            message: 'Archivo eliminado correctamente',
            archivos: restantes,
            estatus: estadoRows[0]?.estatus || docs[0].estatus,
            archivo_url: estadoRows[0]?.archivo_url || null,
            nombre_archivo: estadoRows[0]?.nombre_archivo || null,
            fecha_subida: estadoRows[0]?.fecha_subida || null
        });
    } catch (error) {
        handleError(res, error, 'Error al eliminar archivo');
    }
});

// Subir archivo de documento de PC
app.post('/api/proteccion-civil/documentos/:documentoId/archivo', requireAdminOrEmpresa, verificarDocumentoEmpresa, verificarServicioProteccionCivilEmpresa, manejarUploadProteccionCivil, async (req, res) => {
    try {
        const { documentoId } = req.params;
        const file = req.file;

        if (!file) {
            return res.status(400).json({ success: false, message: 'No se recibió el archivo. Selecciónalo otra vez e inténtalo de nuevo.' });
        }

        // Obtener empresa_id, nombre del documento padre y carpeta Drive desde proteccion_civil DB
        const [docs] = await poolProteccionCivil.query(
            `SELECT dpc.empresa_id, dpc.documento_padre_id, dpc.nombre_documento, dpc.tipo_entrada,
                    padre.nombre_documento as nombre_padre,
                    padre.especificacion as espec_padre,
                    dpc.especificacion as espec_propia
             FROM documento_proteccion_civil dpc
             LEFT JOIN documento_proteccion_civil padre ON dpc.documento_padre_id = padre.documento_id
             WHERE dpc.documento_id = ?`,
            [documentoId]
        );

        if (docs.length === 0) {
            return res.status(404).json({ success: false, message: 'Documento no encontrado' });
        }

        const esTextoPorNombre = /\*\s*$/.test(String(docs[0].nombre_documento || ''));
        if (docs[0].tipo_entrada === 'texto' || esTextoPorNombre) {
            return res.status(400).json({
                success: false,
                message: 'Esta asignación es de texto. Usa el endpoint de texto para guardar el valor.'
            });
        }

        // Obtener nombre de carpeta en Drive (guardado como "carpeta_drive:NombreDoc+fecha")
        const especPadre = docs[0].espec_padre || docs[0].espec_propia || '';
        let nombreCarpetaDrive;
        if (especPadre.startsWith('carpeta_drive:')) {
            nombreCarpetaDrive = especPadre.replace('carpeta_drive:', '');
        } else {
            nombreCarpetaDrive = docs[0].nombre_padre || docs[0].nombre_documento;
        }

        // Obtener nombre de empresa desde biznaga DB
        const [empRows] = await pool.query('SELECT nombre_empresa FROM empresa WHERE empresa_id = ?', [docs[0].empresa_id]);
        // Usar nombre real de empresa SIN sanitización agresiva para que coincida con la carpeta creada durante la asignación
        const nombreEmpresa = empRows.length > 0 ? empRows[0].nombre_empresa : String(docs[0].empresa_id);
        const timestamp = Date.now();
        const nombreOriginalUtf8 = (() => {
            try {
                const { repararNombreUtf8 } = require('./ambientalTramiteArchivosService');
                if (typeof repararNombreUtf8 === 'function') {
                    return repararNombreUtf8(file.originalname);
                }
            } catch (_) { /* fallback abajo */ }
            const original = String(file.originalname || '').trim();
            if (/Ã.|Â./.test(original)) {
                try {
                    return Buffer.from(original, 'latin1').toString('utf8');
                } catch (_) { /* ignore */ }
            }
            return original || 'archivo';
        })();
        const nombreArchivo = `PC_${timestamp}_${nombreOriginalUtf8}`;

        // Subir a Google Drive en carpeta Proteccion_civil/Historial de documentos/{empresa}/{doc+fecha}/
        let driveFileId = null;
        try {
            const driveFile = await driveService.subirArchivoProteccionCivil(
                file.buffer, nombreEmpresa, nombreArchivo, file.mimetype || 'application/pdf', nombreCarpetaDrive
            );
            driveFileId = driveFile.id;
        } catch (driveError) {
            console.error('[ERROR] Falló subida a Drive (Protección Civil):', driveError.message);
            return res.status(500).json({
                success: false,
                message: 'No se pudo guardar el archivo en el almacenamiento. Espera un momento e inténtalo de nuevo.'
            });
        }

        if (!esDriveIdValido(driveFileId)) {
            return res.status(500).json({
                success: false,
                message: 'No se pudo confirmar que el archivo se guardó bien. Inténtalo de nuevo.'
            });
        }

        // Subida = entrega en revisión; la aprobación es manual (revisión / marcar entregado).
        // Así los faltantes no se completan solos al subir el primer archivo.
        const nuevoEstatus = 'revision';

        const existentes = await listarArchivosDocumentoPC(documentoId);
        const siguienteOrden = existentes.length > 0
            ? Math.max(...existentes.map((a) => Number(a.orden) || 0)) + 1
            : 0;

        const [insertResult] = await poolProteccionCivil.query(
            `INSERT INTO documento_proteccion_civil_archivo
                (documento_id, drive_file_id, nombre_archivo, mime_type, orden, fecha_subida)
             VALUES (?, ?, ?, ?, ?, NOW())`,
            [documentoId, driveFileId, nombreOriginalUtf8, file.mimetype || null, siguienteOrden]
        );

        await poolProteccionCivil.query(`
            UPDATE documento_proteccion_civil 
            SET archivo_url = ?, nombre_archivo = ?, valor_texto = NULL, fecha_subida = NOW(), estatus = ?
            WHERE documento_id = ?
        `, [driveFileId, nombreOriginalUtf8, nuevoEstatus, documentoId]);

        const archivos = await listarArchivosDocumentoPC(documentoId);

        res.json({
            success: true,
            message: 'Archivo subido correctamente',
            url: driveFileId,
            drive_file_id: driveFileId,
            archivo_id: insertResult?.insertId || null,
            nombre_archivo: nombreOriginalUtf8,
            estatus: nuevoEstatus,
            auto_aprobado: false,
            archivos
        });

        // Notificar revisión a admins/PC cuando sube la empresa
        if (!puedeAutoAprobarSubidaPC(req)) {
            notificarRevisionPC(docs[0].empresa_id, nombreEmpresa).catch(() => {});
        }
        // Si con esta subida se completo el documento padre, notificar al perfil asignador
        notificarAsignadorSiPadreCompletoPC(documentoId).catch(() => {});
    } catch (error) {
        handleError(res, error, 'Error al subir archivo');
    }
});

// Guardar valor de texto de una asignación marcada con *
app.put('/api/proteccion-civil/documentos/:documentoId/texto', requireAdminOrEmpresa, verificarDocumentoEmpresa, verificarServicioProteccionCivilEmpresa, async (req, res) => {
    try {
        const { documentoId } = req.params;
        const { valor_texto } = req.body;

        const [rows] = await poolProteccionCivil.query(
            'SELECT tipo_entrada, nombre_documento, valor_texto FROM documento_proteccion_civil WHERE documento_id = ? LIMIT 1',
            [documentoId]
        );

        if (rows.length === 0) {
            return res.status(404).json({ success: false, message: 'Documento no encontrado' });
        }

        const esTextoPorNombre = /\*\s*$/.test(String(rows[0].nombre_documento || ''));
        if (rows[0].tipo_entrada !== 'texto' && !esTextoPorNombre) {
            return res.status(400).json({ success: false, message: 'Esta asignación no es de tipo texto' });
        }

        const valor = String(valor_texto || '').trim();
        const valorAnterior = String(rows[0].valor_texto || '').trim();
        const nombreNormalizado = String(rows[0].nombre_documento || '')
            .normalize('NFD')
            .replace(/[\u0300-\u036f]/g, '')
            .replace(/[^a-z0-9\s]/gi, ' ')
            .replace(/\s+/g, ' ')
            .trim()
            .toLowerCase();
        const esAutollenado = (
            (nombreNormalizado.includes('nombre') && nombreNormalizado.includes('empresa')
                && !nombreNormalizado.includes('representante') && !nombreNormalizado.includes('legal'))
            || nombreNormalizado.includes('direccion')
            || nombreNormalizado.includes('domicilio')
            || nombreNormalizado.includes('telefono')
            || nombreNormalizado.startsWith('tel ')
            || nombreNormalizado === 'tel'
            || nombreNormalizado.includes('correo')
            || nombreNormalizado.includes('email')
            || (nombreNormalizado.includes('representante') && nombreNormalizado.includes('legal'))
        );
        const cambioDetectado = valor !== valorAnterior;

        const autoAprobadoPorRol = puedeAutoAprobarSubidaPC(req);
        let nuevoEstatus = 'pendiente';
        if (valor.length > 0) {
            if (autoAprobadoPorRol) {
                // Admin/root/proteccion_civil: aprobación inmediata al capturar texto.
                nuevoEstatus = 'aprobado';
            } else if (esAutollenado && !cambioDetectado) {
                // Si el autollenado no cambió, se aprueba automáticamente.
                nuevoEstatus = 'aprobado';
            } else {
                // Texto nuevo o modificado de empresa queda en revisión.
                nuevoEstatus = 'revision';
            }
        }

        // Obtener empresa_id del documento para la notificación
        const [docInfo] = await poolProteccionCivil.query(
            'SELECT empresa_id FROM documento_proteccion_civil WHERE documento_id = ? LIMIT 1',
            [documentoId]
        );

        await poolProteccionCivil.query(
            `UPDATE documento_proteccion_civil
             SET valor_texto = ?, archivo_url = NULL, nombre_archivo = NULL, fecha_subida = NOW(), estatus = ?, fecha_actualizacion = NOW()
             WHERE documento_id = ?`,
            [valor || null, nuevoEstatus, documentoId]
        );

        if (nuevoEstatus === 'aprobado') {
            try {
                await registrarHistorialDocumentoAprobadoPC(documentoId);
            } catch (historialErr) {
                // silenced
            }
        }

        res.json({
            success: true,
            message: 'Valor de texto guardado correctamente',
            estatus: nuevoEstatus,
            autollenado: esAutollenado,
            cambio_detectado: cambioDetectado,
            auto_aprobado: autoAprobadoPorRol || (esAutollenado && !cambioDetectado && nuevoEstatus === 'aprobado')
        });

        // Notificación única a admins/PC si el documento entró en revisión (fire-and-forget)
        if (nuevoEstatus === 'revision' && docInfo.length > 0) {
            const [empR] = await pool.query('SELECT nombre_empresa FROM empresa WHERE empresa_id = ?', [docInfo[0].empresa_id]);
            const nomEmp = empR.length > 0 ? empR[0].nombre_empresa : String(docInfo[0].empresa_id);
            notificarRevisionPC(docInfo[0].empresa_id, nomEmp).catch(() => {});
        }

        // Si el valor de texto completo los subdocumentos del padre, notificar al perfil asignador
        notificarAsignadorSiPadreCompletoPC(documentoId).catch(() => {});
    } catch (error) {
        handleError(res, error, 'Error al guardar valor de texto');
    }
});

// PDF listado maestro SP-F-01 con estatus de entrega (Sí = aprobado, No = resto)
app.get('/api/proteccion-civil/documentos/:documentoId/listado-estatus/pdf', requireAdminOrEmpresa, verificarDocumentoEmpresa, verificarServicioProteccionCivilEmpresa, async (req, res) => {
    try {
        const { documentoId } = req.params;
        const ocultarSoloInternos = esPerfilEmpresa(req) && !tieneAlgunRol(req, 'administrador', 'root', 'proteccion_civil');

        const [padreRows] = await poolProteccionCivil.query(
            `SELECT documento_id, nombre_documento, documento_padre_id
             FROM documento_proteccion_civil
             WHERE documento_id = ?
             LIMIT 1`,
            [documentoId]
        );

        if (padreRows.length === 0) {
            return res.status(404).json({ success: false, message: 'Documento no encontrado' });
        }

        const padreRef = padreRows[0];
        const padreId = padreRef.documento_padre_id ? padreRef.documento_padre_id : padreRef.documento_id;
        const [padreInfoRows] = await poolProteccionCivil.query(
            `SELECT documento_id, nombre_documento
             FROM documento_proteccion_civil
             WHERE documento_id = ?
             LIMIT 1`,
            [padreId]
        );
        const padreInfo = padreInfoRows[0] || padreRef;

        const [hijos] = await poolProteccionCivil.query(
            `SELECT nombre_documento, especificacion, estatus, comentarios, visible_empresa
             FROM documento_proteccion_civil
             WHERE documento_padre_id = ?
               AND (clave_workflow IS NULL OR clave_workflow = '')
             ORDER BY documento_id ASC`,
            [padreId]
        );

        const esSubtituloOperativo = (nombre = '') => {
            const n = String(nombre || '')
                .normalize('NFD')
                .replace(/[\u0300-\u036f]/g, '')
                .replace(/[^a-z0-9\s]/gi, ' ')
                .replace(/\s+/g, ' ')
                .trim()
                .toLowerCase();
            return n === 'fisico' || n === 'usb' || n === 'presentar';
        };

        let items = (hijos || []).filter((h) => !esSubtituloOperativo(h.nombre_documento));
        if (ocultarSoloInternos) {
            items = items.filter((h) => h.visible_empresa === 1 || h.visible_empresa === true);
        }

        if (!items.length) {
            return res.status(404).json({ success: false, message: 'No hay requisitos para generar el listado' });
        }

        const nombrePadre = String(padreInfo.nombre_documento || 'PIPC').trim();
        const tituloPdf = /^pipc/i.test(nombrePadre) ? nombrePadre : `PIPC ${nombrePadre}`;
        const pdfBuffer = await generarListadoPipcPdf({
            tituloUbicacion: tituloPdf,
            items: items.map((item) => ({
                documento: String(item.nombre_documento || '').replace(/\*+\s*$/, '').trim(),
                especificacion: String(item.especificacion || item.comentarios || '').trim(),
                entregado: item.estatus === 'aprobado' ? 'Sí' : 'No'
            }))
        });

        const filename = `Listado_${sanitizarNombreArchivo(tituloPdf)}.pdf`;
        res.setHeader('Content-Type', 'application/pdf');
        res.setHeader('Content-Disposition', `attachment; filename="${filename}"`);
        res.send(pdfBuffer);
    } catch (error) {
        handleError(res, error, 'Error al generar listado de estatus PDF');
    }
});

/** Detecta MIME real por firma de bytes (prioridad sobre extensión del nombre). */
function detectarMimeArchivoPC(buffer, nombreArchivo) {
    const buf = Buffer.isBuffer(buffer) ? buffer : Buffer.from(buffer || []);
    const ext = String(nombreArchivo || '').split('.').pop().toLowerCase();
    const porExtension = {
        pdf: 'application/pdf',
        png: 'image/png',
        jpg: 'image/jpeg',
        jpeg: 'image/jpeg',
        gif: 'image/gif',
        webp: 'image/webp',
        bmp: 'image/bmp',
        jfif: 'image/jpeg'
    };

    if (buf.length >= 3 && buf[0] === 0xff && buf[1] === 0xd8 && buf[2] === 0xff) {
        return 'image/jpeg';
    }
    if (buf.length >= 8 && buf[0] === 0x89 && buf[1] === 0x50 && buf[2] === 0x4e && buf[3] === 0x47) {
        return 'image/png';
    }
    if (buf.length >= 6 && buf[0] === 0x47 && buf[1] === 0x49 && buf[2] === 0x46) {
        return 'image/gif';
    }
    if (buf.length >= 12 && buf.toString('ascii', 0, 4) === 'RIFF' && buf.toString('ascii', 8, 12) === 'WEBP') {
        return 'image/webp';
    }
    if (buf.length >= 4 && buf[0] === 0x25 && buf[1] === 0x50 && buf[2] === 0x44 && buf[3] === 0x46) {
        return 'application/pdf';
    }

    return porExtension[ext] || 'application/octet-stream';
}

// Descargar archivo de documento de PC desde Google Drive (streaming como blob)
app.get('/api/proteccion-civil/documentos/:documentoId/descargar', requireAdminOrEmpresa, verificarDocumentoEmpresa, verificarServicioProteccionCivilEmpresa, async (req, res) => {
    try {
        const { documentoId } = req.params;
        const archivoId = Number(req.query.archivo_id || 0);

        let archivo_url = null;
        let nombre_archivo = null;

        if (archivoId > 0) {
            const [archivos] = await poolProteccionCivil.query(
                `SELECT drive_file_id, nombre_archivo
                 FROM documento_proteccion_civil_archivo
                 WHERE archivo_id = ? AND documento_id = ?
                 LIMIT 1`,
                [archivoId, documentoId]
            );
            if (archivos.length) {
                archivo_url = archivos[0].drive_file_id;
                nombre_archivo = archivos[0].nombre_archivo;
            }
        }

        if (!archivo_url) {
            const [docs] = await poolProteccionCivil.query(
                'SELECT archivo_url, nombre_archivo FROM documento_proteccion_civil WHERE documento_id = ?',
                [documentoId]
            );

            if (docs.length === 0 || !docs[0].archivo_url) {
                return res.status(404).json({ success: false, message: 'Archivo no encontrado' });
            }
            archivo_url = docs[0].archivo_url;
            nombre_archivo = docs[0].nombre_archivo;
        }

        const driveId = extraerDriveIdDesdeUrl(archivo_url) || String(archivo_url || '').trim();
        if (!driveId) {
            return res.status(404).json({ success: false, message: 'ID de archivo en Drive no válido' });
        }

        const ext = (nombre_archivo || '').split('.').pop().toLowerCase();
        const contentTypeMap = {
            'pdf': 'application/pdf',
            'png': 'image/png',
            'jpg': 'image/jpeg',
            'jpeg': 'image/jpeg',
            'gif': 'image/gif',
            'webp': 'image/webp',
            'bmp': 'image/bmp',
            'doc': 'application/msword',
            'docx': 'application/vnd.openxmlformats-officedocument.wordprocessingml.document',
            'xls': 'application/vnd.ms-excel',
            'xlsx': 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet',
            'ppt': 'application/vnd.ms-powerpoint',
            'pptx': 'application/vnd.openxmlformats-officedocument.presentationml.presentation'
        };
        const extensionesOffice = ['doc', 'docx', 'xls', 'xlsx', 'ppt', 'pptx'];
        const usarVistaPrevia = req.query.preview === '1' || req.query.vistaPrevia === '1';

        let fileBuffer;
        let contentType;

        if (usarVistaPrevia && extensionesOffice.includes(ext)) {
            fileBuffer = await driveService.exportarArchivoPDF(driveId);
            contentType = 'application/pdf';
        } else {
            fileBuffer = await driveService.descargarArchivo(driveId);
            contentType = detectarMimeArchivoPC(fileBuffer, nombre_archivo);
        }

        const nombreSeguro = (nombre_archivo || 'archivo').replace(/["\r\n]/g, '').replace(/[^a-zA-Z0-9._\- ]/g, '_');

        res.setHeader('Content-Type', contentType);
        res.setHeader('Content-Disposition', `inline; filename="${nombreSeguro}"`);
        res.setHeader('Cache-Control', 'public, max-age=3600');
        res.send(Buffer.from(fileBuffer));

    } catch (error) {
        console.error('[ERROR] Error al descargar archivo PC:', error.message);
        handleError(res, error, 'Error al descargar archivo');
    }
});

