app.post(
    '/api/proteccion-civil/empresas/:empresaId/documentacion-extra',
    requireAdminOrEmpresa,
    verificarEmpresaPropia,
    verificarServicioProteccionCivilEmpresa,
    manejarUploadPcDocumentacionExtra,
    async (req, res) => {
        const files = Array.isArray(req.files) ? req.files : [];
        try {
            await poolProteccionCivilReady;
            if (!files.length) {
                return res.status(400).json({
                    success: false,
                    message: 'No se recibió ningún archivo. Selecciónalos e inténtalo de nuevo.'
                });
            }

            const empresaId = Number(req.params.empresaId);
            const [empRows] = await pool.query(
                'SELECT nombre_empresa FROM empresa WHERE empresa_id = ? LIMIT 1',
                [empresaId]
            );
            if (!empRows.length) {
                return res.status(404).json({ success: false, message: 'Empresa no encontrada' });
            }
            const nombreEmpresa = empRows[0].nombre_empresa;
            const usuario = req.user?.usuario || req.user?.email || req.user?.nombre || '';

            // Rutas relativas (mismo orden que archivos). Vacío = raíz de Documentación Extra.
            let carpetasLista = [];
            try {
                const rawJson = req.body?.carpetasRelativasJson;
                if (rawJson) {
                    const parsed = typeof rawJson === 'string' ? JSON.parse(rawJson) : rawJson;
                    if (Array.isArray(parsed)) {
                        carpetasLista = parsed;
                    }
                }
            } catch (parseErr) {
                console.warn('[PC-EXTRA] carpetasRelativasJson inválido:', parseErr.message);
            }
            if (!carpetasLista.length) {
                const carpetasRaw = req.body?.carpetasRelativas;
                carpetasLista = Array.isArray(carpetasRaw)
                    ? carpetasRaw
                    : (carpetasRaw != null && carpetasRaw !== '' ? [carpetasRaw] : []);
            }

            const documentos = [];
            const errores = [];

            for (let i = 0; i < files.length; i++) {
                const file = files[i];
                const carpetaRelativa = pcDocumentacionExtraService.sanitizarCarpetaRelativa(
                    carpetasLista[i] != null ? carpetasLista[i] : ''
                );
                try {
                    const buffer = await fs.promises.readFile(file.path);
                    const documento = await pcDocumentacionExtraService.subirDocumento(
                        poolProteccionCivil,
                        empresaId,
                        nombreEmpresa,
                        {
                            buffer,
                            nombreArchivo: file.originalname,
                            mimeType: file.mimetype,
                            carpetaRelativa
                        },
                        usuario
                    );
                    documentos.push(documento);
                } catch (err) {
                    errores.push({
                        nombre: file.originalname || 'archivo',
                        carpetaRelativa: carpetaRelativa || '',
                        error: err?.message || String(err)
                    });
                }
            }

            const exitosos = documentos.length;
            const fallidos = errores.length;
            return res.json({
                success: fallidos === 0,
                partial: fallidos > 0 && exitosos > 0,
                message: fallidos === 0
                    ? `${exitosos} documento(s) subido(s) en Documentación Extra.`
                    : `${exitosos} de ${exitosos + fallidos} documento(s) subido(s).`,
                total: exitosos + fallidos,
                exitosos,
                fallidos,
                documentos,
                errores
            });
        } catch (error) {
            handleError(res, error, 'No se pudo subir la documentación extra');
        } finally {
            await limpiarArchivosTemporalesPcExtra(files);
        }
    }
);

