// Crear categoría del catálogo de PC (BD + carpeta en Drive)
app.post('/api/proteccion-civil/catalogo/categorias', requireAdminOrPC, async (req, res) => {
    try {
        await poolProteccionCivilReady;

        const nombre = String(req.body?.nombre || '').trim();
        if (!nombre) {
            return res.status(400).json({ success: false, message: 'El nombre de la categoría es obligatorio' });
        }

        const slug = mapearSlugCategoriaPC(nombre);
        if (!slug) {
            return res.status(400).json({ success: false, message: 'Nombre de categoría inválido' });
        }

        const [existentes] = await poolProteccionCivil.query(
            'SELECT categoria_id, activo FROM pc_catalogo_categoria WHERE slug = ? LIMIT 1',
            [slug]
        );

        let categoriaId = null;
        if (existentes.length) {
            categoriaId = existentes[0].categoria_id;
            await poolProteccionCivil.query(
                'UPDATE pc_catalogo_categoria SET nombre = ?, activo = 1, fecha_actualizacion = NOW() WHERE categoria_id = ?',
                [nombre, categoriaId]
            );
        } else {
            const [ordenRows] = await poolProteccionCivil.query(
                'SELECT COALESCE(MAX(orden), 0) AS maxOrden FROM pc_catalogo_categoria'
            );
            const siguienteOrden = Number(ordenRows?.[0]?.maxOrden || 0) + 1;

            const [insertResult] = await poolProteccionCivil.query(
                `INSERT INTO pc_catalogo_categoria
                    (slug, nombre, orden, activo, fecha_actualizacion)
                 VALUES (?, ?, ?, 1, NOW())`,
                [slug, nombre, siguienteOrden]
            );
            categoriaId = insertResult.insertId;
        }

        let folderId = null;
        try {
            folderId = await resolverCarpetaCategoriaPCDrive(nombre);
            if (folderId) {
                await poolProteccionCivil.query(
                    'UPDATE pc_catalogo_categoria SET drive_folder_id = ?, fecha_actualizacion = NOW() WHERE categoria_id = ?',
                    [folderId, categoriaId]
                );
            }
        } catch (driveErr) {
            console.warn('[PC-CATALOGO] No se pudo crear/resolver carpeta de categoría en Drive:', driveErr.message);
        }

        res.json({
            success: true,
            message: 'Categoría creada correctamente',
            categoria: {
                id: categoriaId,
                slug,
                nombre,
                drive_folder_id: folderId
            }
        });
    } catch (error) {
        handleError(res, error, 'Error al crear categoría del catálogo');
    }
});

// Cambiar nombre de categoría del catálogo de PC
app.put('/api/proteccion-civil/catalogo/categorias/:categoriaId', requireAdminOrPC, async (req, res) => {
    try {
        await poolProteccionCivilReady;

        const categoriaRef = String(req.params.categoriaId || '').trim();
        const nuevoNombre = String(req.body?.nombre || '').trim();

        if (!nuevoNombre) {
            return res.status(400).json({ success: false, message: 'El nuevo nombre de la categoría es obligatorio' });
        }

        const esIdNumerico = /^\d+$/.test(categoriaRef);
        const [catRows] = await poolProteccionCivil.query(
            esIdNumerico
                ? 'SELECT * FROM pc_catalogo_categoria WHERE categoria_id = ? AND activo = 1 LIMIT 1'
                : 'SELECT * FROM pc_catalogo_categoria WHERE slug = ? AND activo = 1 LIMIT 1',
            [esIdNumerico ? Number(categoriaRef) : categoriaRef]
        );

        if (!catRows.length) {
            return res.status(404).json({ success: false, message: 'Categoría no encontrada' });
        }

        const categoria = catRows[0];
        const nuevoSlug = mapearSlugCategoriaPC(nuevoNombre);

        // Actualizamos nombre y slug para que la sincronización no lo detecte como "nuevo"
        await poolProteccionCivil.query(
            'UPDATE pc_catalogo_categoria SET nombre = ?, slug = ?, fecha_actualizacion = NOW() WHERE categoria_id = ?',
            [nuevoNombre, nuevoSlug, categoria.categoria_id]
        );

        if (categoria.drive_folder_id) {
            try {
                await driveService.renombrarCarpetaPorId(categoria.drive_folder_id, nuevoNombre);
            } catch (driveErr) {
                console.warn('[PC-CATALOGO] No se pudo renombrar carpeta de Drive de categoría:', driveErr.message);
            }
        }

        // Actualizamos la marca de tiempo para evitar que una sincronización automática sobrescriba los datos inmediatos
        _lastSyncCatalogoPC = Date.now();

        res.json({
            success: true,
            message: 'Categoría actualizada correctamente',
            categoria: {
                categoria_id: categoria.categoria_id,
                slug: nuevoSlug,
                nombre: nuevoNombre,
                drive_folder_id: categoria.drive_folder_id || null
            }
        });
    } catch (error) {
        handleError(res, error, 'Error al actualizar categoría del catálogo');
    }
});

// Quitar categoría del catálogo de PC (solo si está vacía)
app.delete('/api/proteccion-civil/catalogo/categorias/:categoriaId', requireAdminOrPC, async (req, res) => {
    try {
        await poolProteccionCivilReady;
        const categoriaRef = String(req.params.categoriaId || '').trim();
        const esIdNumerico = /^\d+$/.test(categoriaRef);

        const [catRows] = await poolProteccionCivil.query(
            esIdNumerico
                ? 'SELECT categoria_id, nombre, drive_folder_id FROM pc_catalogo_categoria WHERE categoria_id = ? AND activo = 1 LIMIT 1'
                : 'SELECT categoria_id, nombre, drive_folder_id FROM pc_catalogo_categoria WHERE slug = ? AND activo = 1 LIMIT 1',
            [esIdNumerico ? Number(categoriaRef) : categoriaRef]
        );

        if (!catRows.length) {
            return res.status(404).json({ success: false, message: 'Categoría no encontrada' });
        }

        const categoria = catRows[0];
        const [docsRows] = await poolProteccionCivil.query(
            'SELECT COUNT(*) AS total FROM pc_catalogo_documento WHERE categoria_id = ? AND activo = 1',
            [categoria.categoria_id]
        );

        const totalDocs = Number(docsRows?.[0]?.total || 0);
        if (totalDocs > 0) {
            return res.status(409).json({
                success: false,
                message: `La categoría "${categoria.nombre}" tiene ${totalDocs} documento(s). Elimínalos primero para poder quitarla.`
            });
        }

        const folderId = categoria.drive_folder_id || await buscarCarpetaCategoriaPCDrive(categoria.nombre);
        if (folderId) {
            try {
                await driveService.eliminarCarpetaPorId(folderId);
            } catch (driveErr) {
                return res.status(409).json({
                    success: false,
                    message: `No se pudo eliminar la carpeta de Drive para "${categoria.nombre}". Verifica permisos o contenido compartido.`
                });
            }
        }

        await poolProteccionCivil.query(
            'UPDATE pc_catalogo_categoria SET activo = 0, drive_folder_id = NULL, fecha_actualizacion = NOW() WHERE categoria_id = ?',
            [categoria.categoria_id]
        );

        res.json({ success: true, message: 'Categoría quitada correctamente' });
    } catch (error) {
        handleError(res, error, 'Error al quitar categoría del catálogo');
    }
});

// Subir nuevo documento al catálogo de PC (Drive + BD)
app.post('/api/proteccion-civil/catalogo/documentos', requireAdminOrPC, (req, res, next) => {
    uploadDocumentoCatalogoPC.single('archivo')(req, res, (err) => {
        if (err) return res.status(400).json({ success: false, message: mensajeErrorUploadPC(err) });
        next();
    });
}, async (req, res) => {
    try {
        await poolProteccionCivilReady;

        const categoriaRef = String(req.body.categoria_id || '').trim();
        if (!categoriaRef) {
            return res.status(400).json({ success: false, message: 'La categoría es obligatoria' });
        }

        if (!req.file) {
            return res.status(400).json({ success: false, message: 'No se recibió ningún archivo' });
        }

        const extensionNuevoCatalogo = path.extname(String(req.file.originalname || '')).toLowerCase();
        const mimeNuevoCatalogo = String(req.file.mimetype || '').toLowerCase();
        const esNuevoDocumentoExcelXlsx = extensionNuevoCatalogo === '.xlsx' && (
            !mimeNuevoCatalogo
            || mimeNuevoCatalogo === 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            || mimeNuevoCatalogo === 'application/vnd.ms-excel'
            || mimeNuevoCatalogo === 'application/octet-stream'
        );

        if (!esNuevoDocumentoExcelXlsx) {
            return res.status(400).json({
                success: false,
                message: 'En el catálogo solo se pueden subir nuevos documentos en formato Excel .xlsx'
            });
        }

        const esCategoriaNumerica = /^\d+$/.test(categoriaRef);
        const [catRows] = await poolProteccionCivil.query(
            esCategoriaNumerica
                ? 'SELECT categoria_id, slug, nombre, drive_folder_id FROM pc_catalogo_categoria WHERE categoria_id = ? AND activo = 1 LIMIT 1'
                : 'SELECT categoria_id, slug, nombre, drive_folder_id FROM pc_catalogo_categoria WHERE slug = ? AND activo = 1 LIMIT 1',
            [esCategoriaNumerica ? Number(categoriaRef) : categoriaRef]
        );

        if (!catRows.length) {
            return res.status(404).json({ success: false, message: 'Categoría no encontrada' });
        }

        const categoria = catRows[0];
        let carpetaCategoriaId = categoria.drive_folder_id || null;

        if (!carpetaCategoriaId) {
            carpetaCategoriaId = await resolverCarpetaCategoriaPCDrive(categoria.nombre);
            await poolProteccionCivil.query(
                'UPDATE pc_catalogo_categoria SET drive_folder_id = ?, fecha_actualizacion = NOW() WHERE categoria_id = ?',
                [carpetaCategoriaId, categoria.categoria_id]
            );
        }

        if (!carpetaCategoriaId) {
            return res.status(409).json({
                success: false,
                message: 'No se pudo resolver la carpeta de la categoría en Google Drive. Sincroniza el catálogo e inténtalo de nuevo.'
            });
        }

        const nombreArchivoOriginal = String(req.file.originalname || 'documento').trim();
        const nombrePreferido = String(req.body.nombre || '').trim().replace(/\s+/g, ' ');
        let nombreArchivo = nombreArchivoOriginal;
        if (nombrePreferido) {
            const base = nombrePreferido.replace(/\.xlsx?$/i, '');
            nombreArchivo = /\.xlsx$/i.test(nombrePreferido) ? nombrePreferido : `${base}.xlsx`;
        }
        const subida = await driveService.subirArchivo(
            req.file.buffer,
            nombreArchivo,
            req.file.mimetype || 'application/octet-stream',
            carpetaCategoriaId
        );

        const [insertResult] = await poolProteccionCivil.query(
            `INSERT INTO pc_catalogo_documento
                (categoria_id, nombre, jurisdiccion, drive_file_id, drive_web_view_link, drive_download_link, mime_type, size_bytes, fecha_actualizacion_drive, activo, fecha_actualizacion)
             VALUES (?, ?, 'General', ?, ?, ?, ?, ?, NOW(), 1, NOW())`,
            [
                categoria.categoria_id,
                nombreArchivo,
                subida.id,
                subida.webViewLink || null,
                subida.webContentLink || null,
                subida.mimeType || req.file.mimetype || null,
                subida.size ? Number(subida.size) : req.file.size || null
            ]
        );

        res.json({
            success: true,
            message: 'Documento subido correctamente al catálogo',
            documento: {
                documento_id: insertResult.insertId,
                categoria_id: categoria.categoria_id,
                categoria_slug: categoria.slug,
                nombre: nombreArchivo,
                drive_file_id: subida.id
            }
        });
    } catch (error) {
        handleError(res, error, 'Error al subir documento al catálogo');
    }
});

// Crear formato PIPC (u otra categoría) desde plantilla Google Sheets + registro BD
app.post('/api/proteccion-civil/catalogo/documentos/desde-plantilla', requireAdminOrPC, async (req, res) => {
    try {
        await poolProteccionCivilReady;

        const categoriaRef = String(req.body.categoria_id || '').trim();
        const nombreFormato = String(req.body.nombre || '').trim().replace(/\s+/g, ' ');

        if (!categoriaRef) {
            return res.status(400).json({ success: false, message: 'La categoría es obligatoria' });
        }
        if (!nombreFormato) {
            return res.status(400).json({ success: false, message: 'El nombre del archivo es obligatorio' });
        }
        if (nombreFormato.length > 180) {
            return res.status(400).json({ success: false, message: 'El nombre del archivo es demasiado largo' });
        }

        const esCategoriaNumerica = /^\d+$/.test(categoriaRef);
        const [catRows] = await poolProteccionCivil.query(
            esCategoriaNumerica
                ? 'SELECT categoria_id, slug, nombre, drive_folder_id FROM pc_catalogo_categoria WHERE categoria_id = ? AND activo = 1 LIMIT 1'
                : 'SELECT categoria_id, slug, nombre, drive_folder_id FROM pc_catalogo_categoria WHERE slug = ? AND activo = 1 LIMIT 1',
            [esCategoriaNumerica ? Number(categoriaRef) : categoriaRef]
        );

        if (!catRows.length) {
            return res.status(404).json({ success: false, message: 'Categoría no encontrada' });
        }

        const categoria = catRows[0];
        if (categoria.slug !== 'pipc') {
            return res.status(400).json({
                success: false,
                message: 'Por ahora solo la categoría PIPC puede crear formatos desde plantilla. Para otras categorías usa la carga de archivo Excel.'
            });
        }

        const plantillaId = String(
            process.env.PIPC_FORMATO_PLANTILLA_DRIVE_ID
            || '1m_3kZo5qS4-IDp1xbJZJ72l7NeQZ4EXOMMv_g4PLXRM'
        ).trim();

        if (!(await driveService.verificarArchivoExiste(plantillaId))) {
            return res.status(409).json({
                success: false,
                message: 'No se encontró la plantilla base de PIPC en Google Drive'
            });
        }

        let carpetaCategoriaId = categoria.drive_folder_id || null;
        if (!carpetaCategoriaId) {
            carpetaCategoriaId = await resolverCarpetaCategoriaPCDrive(categoria.nombre);
            await poolProteccionCivil.query(
                'UPDATE pc_catalogo_categoria SET drive_folder_id = ?, fecha_actualizacion = NOW() WHERE categoria_id = ?',
                [carpetaCategoriaId, categoria.categoria_id]
            );
        }

        if (!carpetaCategoriaId) {
            // Preferir la carpeta PIPC conocida del catálogo
            carpetaCategoriaId = process.env.PC_CATALOGO_PIPC_FOLDER_ID
                || '1aQkjoiof3SzAY8D6za4FVmByyisIrrL1';
        }

        const nombreSinPrefijo = nombreFormato.replace(/^PIPC\s+/i, '').trim() || nombreFormato;
        const nombreArchivoDrive = `PIPC ${nombreSinPrefijo}`;

        const [existentes] = await poolProteccionCivil.query(
            `SELECT documento_id FROM pc_catalogo_documento
             WHERE categoria_id = ? AND activo = 1
               AND (
                    LOWER(TRIM(nombre)) = LOWER(?)
                 OR LOWER(TRIM(hoja_nombre)) = LOWER(?)
                 OR LOWER(TRIM(nombre)) = LOWER(?)
                 OR LOWER(TRIM(hoja_nombre)) = LOWER(?)
               )
             LIMIT 1`,
            [
                categoria.categoria_id,
                nombreArchivoDrive,
                nombreArchivoDrive,
                nombreSinPrefijo,
                nombreSinPrefijo
            ]
        );
        if (existentes.length) {
            return res.status(409).json({
                success: false,
                message: `Ya existe un formato activo con el nombre "${nombreArchivoDrive}"`
            });
        }

        const copia = await driveService.copiarGoogleSheetACarpeta(
            plantillaId,
            nombreArchivoDrive,
            carpetaCategoriaId
        );

        try {
            await driveService.reemplazarTextoEnGoogleSheet(
                copia.id,
                '{{nombre_formato}}',
                nombreSinPrefijo
            );
        } catch (replaceErr) {
            console.warn('[PC-CATALOGO] No se pudo reemplazar {{nombre_formato}}:', replaceErr.message);
            try {
                await driveService.eliminarArchivo(copia.id);
            } catch (delErr) {
                console.warn('[PC-CATALOGO] No se pudo revertir copia fallida:', delErr.message);
            }
            return res.status(500).json({
                success: false,
                message: 'Se creó la copia en Drive pero falló el reemplazo de {{nombre_formato}}'
            });
        }

        const [insertResult] = await poolProteccionCivil.query(
            `INSERT INTO pc_catalogo_documento
                (categoria_id, nombre, jurisdiccion, drive_file_id, drive_web_view_link, drive_download_link,
                 mime_type, size_bytes, fecha_actualizacion_drive, hoja_nombre, archivo_maestro_nombre, activo, fecha_actualizacion)
             VALUES (?, ?, 'General', ?, ?, ?, ?, ?, NOW(), ?, NULL, 1, NOW())
             ON DUPLICATE KEY UPDATE
                nombre = VALUES(nombre),
                drive_web_view_link = VALUES(drive_web_view_link),
                drive_download_link = VALUES(drive_download_link),
                mime_type = VALUES(mime_type),
                size_bytes = VALUES(size_bytes),
                fecha_actualizacion_drive = VALUES(fecha_actualizacion_drive),
                hoja_nombre = VALUES(hoja_nombre),
                archivo_maestro_nombre = NULL,
                activo = 1,
                fecha_actualizacion = NOW()`,
            [
                categoria.categoria_id,
                nombreArchivoDrive,
                copia.id,
                copia.webViewLink || null,
                copia.webContentLink || null,
                copia.mimeType || 'application/vnd.google-apps.spreadsheet',
                copia.size || null,
                nombreArchivoDrive
            ]
        );

        _lastSyncCatalogoPC = 0;

        res.json({
            success: true,
            message: 'Formato PIPC creado desde plantilla',
            documento: {
                documento_id: insertResult.insertId || null,
                categoria_id: categoria.categoria_id,
                categoria_slug: categoria.slug,
                nombre: nombreArchivoDrive,
                hoja_nombre: nombreArchivoDrive,
                drive_file_id: copia.id,
                drive_web_view_link: copia.webViewLink || null
            }
        });
    } catch (error) {
        handleError(res, error, 'Error al crear documento desde plantilla');
    }
});

// Reemplazar archivo de doc de catálogo en Google Drive (mismo nombre, nueva fecha)
app.post('/api/proteccion-civil/catalogo/documentos/:documentoId/reemplazar', requireAdminOrPC, (req, res, next) => {
    uploadDocumentoCatalogoPC.single('archivo')(req, res, (err) => {
        if (err) return res.status(400).json({ success: false, message: mensajeErrorUploadPC(err) });
        next();
    });
}, async (req, res) => {
    try {
        await poolProteccionCivilReady;
        const { documentoId } = req.params;

        if (!req.file) {
            return res.status(400).json({ success: false, message: 'No se recibió ningún archivo' });
        }

        const [rows] = await poolProteccionCivil.query(
            'SELECT nombre, drive_file_id, mime_type FROM pc_catalogo_documento WHERE documento_id = ? AND activo = 1 LIMIT 1',
            [documentoId]
        );

        if (!rows.length || !rows[0].drive_file_id) {
            return res.status(404).json({ success: false, message: 'Documento no encontrado en el catálogo' });
        }

        const { nombre, drive_file_id } = rows[0];

        const resultado = await driveService.reemplazarArchivoEnDrive(
            drive_file_id, req.file.buffer, req.file.mimetype, nombre
        );

        await poolProteccionCivil.query(
            `UPDATE pc_catalogo_documento SET
                mime_type = ?,
                size_bytes = ?,
                drive_web_view_link = ?,
                drive_download_link = ?,
                fecha_actualizacion_drive = NOW(),
                fecha_actualizacion = NOW()
             WHERE documento_id = ?`,
            [
                resultado.mimeType || req.file.mimetype,
                resultado.size ? Number(resultado.size) : req.file.size,
                resultado.webViewLink || null,
                resultado.webContentLink || null,
                documentoId
            ]
        );

        res.json({
            success: true,
            message: `Archivo "${nombre}" reemplazado correctamente en Google Drive`,
            driveFileId: drive_file_id
        });
    } catch (error) {
        handleError(res, error, 'Error al reemplazar archivo del catálogo');
    }
});

// Eliminar documento del catálogo (borra de Drive + marca inactivo en BD)
app.delete('/api/proteccion-civil/catalogo/documentos/:documentoId', requireAdminOrPC, async (req, res) => {
    try {
        await poolProteccionCivilReady;
        const { documentoId } = req.params;

        const [rows] = await poolProteccionCivil.query(
            'SELECT nombre, drive_file_id FROM pc_catalogo_documento WHERE documento_id = ? AND activo = 1 LIMIT 1',
            [documentoId]
        );

        if (!rows.length) {
            return res.status(404).json({ success: false, message: 'Documento no encontrado' });
        }

        const { nombre, drive_file_id } = rows[0];

        // Eliminar de Google Drive si tiene archivo
        if (drive_file_id) {
            try {
                await driveService.eliminarArchivo(drive_file_id);
            } catch (driveErr) {
                // silenced
            }
        }

        // Eliminar registro de la BD
        await poolProteccionCivil.query(
            'DELETE FROM pc_catalogo_documento WHERE documento_id = ?',
            [documentoId]
        );

        res.json({ success: true, message: `Documento "${nombre}" eliminado correctamente` });
    } catch (error) {
        handleError(res, error, 'Error al eliminar documento del catálogo');
    }
});

app.get('/api/proteccion-civil/catalogo/documentos/:documentoId/descargar', requireAdminOrPC, async (req, res) => {
    try {
        await poolProteccionCivilReady;
        const { documentoId } = req.params;

        const [rows] = await poolProteccionCivil.query(
            `SELECT nombre, drive_file_id, mime_type
             FROM pc_catalogo_documento
             WHERE documento_id = ? AND activo = 1
             LIMIT 1`,
            [documentoId]
        );

        if (!rows.length || !rows[0].drive_file_id) {
            return res.status(404).json({ success: false, message: 'Documento de catálogo no encontrado' });
        }

        const doc = rows[0];
        const esExcel = esArchivoExcelCatalogo(doc.mime_type, doc.nombre);
        const fileBuffer = esExcel
            ? await driveService.exportarArchivoXLSX(doc.drive_file_id)
            : await driveService.descargarArchivo(doc.drive_file_id);
        const fileName = String(doc.nombre || 'documento').replace(/[^a-zA-Z0-9._\- ]/g, '_');
        const contentType = esExcel
            ? 'application/vnd.openxmlformats-officedocument.spreadsheetml.sheet'
            : (doc.mime_type || 'application/octet-stream');

        res.setHeader('Content-Type', contentType);
        res.setHeader('Content-Disposition', `attachment; filename="${fileName}"`);
        res.send(fileBuffer);
    } catch (error) {
        handleError(res, error, 'Error al descargar documento del catálogo');
    }
});


