// CONTROL RESOLUTIVOS PIPC (SP-F-29) — BD satélite + Google Sheets
// =====================================================
const pcResolutivosService = require('./pcResolutivosService');

app.get('/api/proteccion-civil/empresas/:empresaId/resolutivo-contexto', requireAdminOrPC, async (req, res) => {
    try {
        const empresaId = Number(req.params.empresaId);
        const documentoAsignacionId = Number(req.query.documento_asignacion_id || 0) || null;

        const [empresaRows] = await pool.query(
            `SELECT empresa_id, nombre_empresa, ciudad, estado
             FROM empresa WHERE empresa_id = ? AND activo = TRUE LIMIT 1`,
            [empresaId]
        );
        if (!empresaRows.length) {
            return res.status(404).json({ success: false, message: 'Empresa no encontrada' });
        }
        const empresa = empresaRows[0];

        let nombreAsignacion = null;
        if (documentoAsignacionId) {
            const [asigRows] = await poolProteccionCivil.query(
                `SELECT documento_id, nombre_documento FROM documento_proteccion_civil
                 WHERE documento_id = ? AND empresa_id = ? LIMIT 1`,
                [documentoAsignacionId, empresaId]
            );
            if (asigRows.length) {
                nombreAsignacion = asigRows[0].nombre_documento;
            }
        }

        await poolBiznagaSgcReady;
        await pcResolutivosService.asegurarTablaPcControlResolutivos(poolBiznagaSgc);

        let yaRegistrado = false;
        if (documentoAsignacionId) {
            yaRegistrado = await pcResolutivosService.resolutivoYaCompletado(
                poolBiznagaSgc, empresaId, documentoAsignacionId
            );
        }

        const responsable = await pcResolutivosService.resolverNombreResponsableUsuario(
            pool,
            req.user?.id,
            null
        );

        res.json({
            success: true,
            empresa: {
                empresa_id: empresa.empresa_id,
                nombre_empresa: empresa.nombre_empresa,
                municipio: empresa.ciudad || '',
                estado: empresa.estado || ''
            },
            asignacion: nombreAsignacion ? {
                documento_asignacion_id: documentoAsignacionId,
                nombre: nombreAsignacion
            } : null,
            responsable,
            responsable_usuario_id: req.user?.id || null,
            tipos_tramite: pcResolutivosService.TIPOS_TRAMITE_VALIDOS,
            ya_registrado: yaRegistrado,
            sheet: {
                file_id: pcResolutivosService.PC_SPF29_SHEET_ID,
                data_start_row: pcResolutivosService.PC_SPF29_DATA_START_ROW
            }
        });
    } catch (error) {
        handleError(res, error, 'Error al obtener contexto de resolutivo');
    }
});

app.post('/api/proteccion-civil/empresas/:empresaId/registrar-resolutivo', requireAdminOrPC, async (req, res) => {
    try {
        const empresaId = Number(req.params.empresaId);
        const {
            documento_asignacion_id,
            nombre_asignacion,
            tipo_tramite,
            fecha_aprobacion,
            fecha_vencimiento
        } = req.body || {};

        const responsable = await pcResolutivosService.resolverNombreResponsableUsuario(
            pool,
            req.user?.id,
            null
        );

        await poolBiznagaSgcReady;

        const resultado = await pcResolutivosService.registrarResolutivoPipc({
            poolSgc: poolBiznagaSgc,
            poolBiznaga: pool,
            poolPC: poolProteccionCivil,
            empresaId,
            documentoAsignacionId: documento_asignacion_id ? Number(documento_asignacion_id) : null,
            nombreAsignacion: nombre_asignacion || null,
            tipoTramite: tipo_tramite,
            fechaAprobacion: fecha_aprobacion,
            fechaVencimiento: fecha_vencimiento,
            responsable,
            responsableUsuarioId: req.user?.id || null
        });

        let asignacionFinalizada = null;
        if (documento_asignacion_id) {
            try {
                asignacionFinalizada = await finalizarAsignacionPcPadreAprobada(
                    poolProteccionCivil,
                    Number(documento_asignacion_id)
                );
            } catch (finErr) {
                console.warn('[PC-RESOLUTIVO] No se pudo finalizar asignación tras registrar resolutivo:', finErr.message);
            }
        }

        res.json({
            success: true,
            message: resultado.actualizado
                ? `Resolutivo actualizado (ítem ${resultado.item}) en base ${DB_NAME_SGC}`
                : (resultado.sync_sheets
                    ? `Resolutivo registrado (ítem ${resultado.item}) en SP-F-29 y base ${DB_NAME_SGC}`
                    : `Resolutivo registrado (ítem ${resultado.item}) en base ${DB_NAME_SGC}`),
            resolutivo: resultado,
            asignacion_finalizada: asignacionFinalizada
        });
    } catch (error) {
        if (error.code === 'RESOLUTIVO_YA_REGISTRADO') {
            return res.status(409).json({ success: false, message: error.message });
        }
        handleError(res, error, 'Error al registrar resolutivo PIPC');
    }
});

