const ambientalService = require('./ambientalService');
const ambientalDriveService = require('./ambientalDriveService');
const ambientalAnexoService = require('./ambientalAnexoService');

async function procesarAnexoOficioSiAplica(db, oficio, file) {
    if (!file || !oficio) return oficio;
    if (oficio.documento_drive_id) {
        await ambientalAnexoService.eliminarAnexoOficio(oficio.documento_drive_id).catch(() => {});
    }
    const subido = await ambientalAnexoService.subirAnexoOficio(
        file.buffer,
        file.mimetype,
        file.originalname,
        oficio.empresa,
        oficio.numero_oficio
    );
    return ambientalService.actualizarDocumentoOficio(db, oficio.oficio_id, {
        documento_url: subido.webViewLink || `https://drive.google.com/file/d/${subido.id}/view`,
        documento_nombre: subido.name,
        documento_drive_id: subido.id
    });
}

async function procesarAnexoTramiteSiAplica(db, tramite, file) {
    if (!file || !tramite) return tramite;
    if (tramite.documento_drive_id) {
        await ambientalAnexoService.eliminarAnexoOficio(tramite.documento_drive_id).catch(() => {});
    }
    const empresaNombre = tramite.empresa_nombre || 'SinEmpresa';
    const subido = await ambientalAnexoService.subirAnexoTramite(
        file.buffer,
        file.mimetype,
        file.originalname,
        empresaNombre,
        tramite.item,
        tramite.oficio,
        new Date(),
        tramite.clasificacion
    );
    return ambientalService.actualizarDocumentoTramite(db, tramite.tramite_id, {
        documento_url: subido.webViewLink || `https://drive.google.com/file/d/${subido.id}/view`,
        documento_nombre: subido.name,
        documento_drive_id: subido.id
    });
}

async function procesarContestacionTramiteSiAplica(db, tramite, file) {
    if (!file || !tramite) return tramite;
    if (tramite.contestacion_drive_id) {
        await ambientalAnexoService.eliminarAnexoOficio(tramite.contestacion_drive_id).catch(() => {});
    }
    const empresaNombre = tramite.empresa_nombre || 'SinEmpresa';
    const subido = await ambientalAnexoService.subirContestacionTramite(
        file.buffer,
        file.mimetype,
        file.originalname,
        empresaNombre,
        tramite.item,
        tramite.oficio,
        new Date(),
        tramite.clasificacion
    );
    return ambientalService.actualizarContestacionTramite(db, tramite.tramite_id, {
        contestacion_url: subido.webViewLink || `https://drive.google.com/file/d/${subido.id}/view`,
        contestacion_nombre: subido.name,
        contestacion_drive_id: subido.id
    });
}

function archivoAmbientalDesdeReq(req, fieldName) {
    if (req.file && fieldName === 'anexo') return req.file;
    const files = req.files;
    if (!files) return null;
    if (Array.isArray(files)) {
        return files.find((f) => f.fieldname === fieldName) || null;
    }
    const lista = files[fieldName];
    return Array.isArray(lista) && lista.length ? lista[0] : null;
}

const uploadAmbientalTramiteDocs = uploadDocumento.fields([
    { name: 'anexo', maxCount: 1 },
    { name: 'contestacion', maxCount: 1 }
]);

function datosOficioDesdeBody(body) {
    return {
        numero_oficio: Number(body?.numero_oficio),
        empresa: String(body?.empresa || '').trim(),
        motivo: String(body?.motivo || '').trim()
    };
}

function datosTramiteDesdeBody(body) {
    const fechaRaw = body?.fecha_vencimiento;
    const fecha = fechaRaw === undefined || fechaRaw === null || String(fechaRaw).trim() === ''
        ? null
        : String(fechaRaw).trim().slice(0, 10);
    return {
        item: Number(body?.item),
        oficio: String(body?.oficio || '').trim(),
        accion_realizar: String(body?.accion_realizar || '').trim(),
        responsable: String(body?.responsable || 'Biznaga').trim(),
        fecha_vencimiento: fecha,
        clasificacion: String(body?.clasificacion || '').trim(),
        estatus: String(body?.estatus || 'abierto').trim(),
        observaciones: String(body?.observaciones || '').trim(),
        empresa_id: body?.empresa_id,
        empresa_nombre: String(body?.empresa_nombre || '').trim()
    };
}

