app.put('/api/ambiental/tramites/:tramiteId', requireAdminOrAmbiental, uploadAmbientalTramiteDocs, async (req, res) => {
    try {
        const db = await poolAmbientalReady();
        const tramiteId = Number(req.params.tramiteId);
        const previo = await ambientalService.obtenerTramitePorId(db, tramiteId);
        if (!previo) {
            return res.status(404).json({ success: false, message: 'Trámite no encontrado' });
        }
        const datos = datosTramiteDesdeBody(req.body);
        let tramite = await ambientalService.actualizarTramite(db, tramiteId, datos);
        if (!tramite) {
            return res.status(404).json({ success: false, message: 'Trámite no encontrado' });
        }

        const claseAnt = ambientalAnexoService.normalizarClasificacion(previo.clasificacion);
        const claseNueva = ambientalAnexoService.normalizarClasificacion(tramite.clasificacion);
        const oficioAnt = String(previo.oficio || '').trim();
        const oficioNuevo = String(tramite.oficio || '').trim();
        if (claseAnt !== claseNueva || oficioAnt !== oficioNuevo) {
            try {
                await ambientalAnexoService.reubicarCarpetaOficioTramite({
                    empresa: tramite.empresa_nombre || previo.empresa_nombre || 'SinEmpresa',
                    oficioAnterior: oficioAnt || previo.oficio,
                    oficioNuevo: oficioNuevo || tramite.oficio,
                    item: tramite.item || previo.item,
                    clasificacionAnterior: claseAnt,
                    clasificacionNueva: claseNueva
                });
            } catch (err) {
                console.warn('[AMB] No se pudo reubicar carpeta Drive del trámite:', err.message);
            }
        }

        tramite = await procesarAnexoTramiteSiAplica(db, tramite, archivoAmbientalDesdeReq(req, 'anexo'));
        tramite = await procesarContestacionTramiteSiAplica(db, tramite, archivoAmbientalDesdeReq(req, 'contestacion'));
        res.json({ success: true, tramite });
    } catch (error) {
        if (error.code === 'ER_DUP_ENTRY') {
            return res.status(409).json({ success: false, message: 'Ya existe un trámite con ese ítem' });
        }
        if (error.code === 'VALIDACION') {
            return res.status(400).json({ success: false, message: error.message });
        }
        handleError(res, error, 'Error al actualizar trámite ambiental');
    }
});

