const ambientalTramiteArchivosService = require('./ambientalTramiteArchivosService');
const MAX_AMB_TRAM_ARCHIVOS = 80;
const uploadAmbTramiteArchivos = multer({
    // Evita mojibake (medición → mediciÃ³n) al parsear filename UTF-8 del navegador.
    defParamCharset: 'utf8',
    storage: multer.diskStorage({
        destination: (req, file, cb) => cb(null, uploadTmpDir),
        filename: (req, file, cb) => {
            const safe = String(file.originalname || 'archivo').replace(/[^a-zA-Z0-9._-]/g, '_');
            cb(null, `amb_tram_${Date.now()}_${safe}`);
        }
    }),
    limits: { fileSize: 512 * 1024 * 1024, files: MAX_AMB_TRAM_ARCHIVOS }
});

async function limpiarTmpAmbTram(files) {
    for (const f of (Array.isArray(files) ? files : [])) {
        try { await fs.promises.unlink(f.path); } catch (_) { /* ignore */ }
    }
}

