app.post(
    '/api/ambiental/tramites/:tramiteId/archivos',
    requireAdminOrAmbiental,
    (req, res, next) => {
        uploadAmbTramiteArchivos.array('archivos', MAX_AMB_TRAM_ARCHIVOS)(req, res, (err) => {
            if (err) {
                return res.status(400).json({
                    success: false,
                    message: err.code === 'LIMIT_FILE_COUNT'
                        ? `Máximo ${MAX_AMB_TRAM_ARCHIVOS} archivos por carga.`
                        : (err.message || 'No se pudo procesar la subida.')
                });
            }
            next();
        });
    },
    async (req, res) => {
        const files = Array.isArray(req.files) ? req.files : [];
        try {
            const db = await poolAmbientalReady();
            const tramiteId = Number(req.params.tramiteId);
            const tramite = await ambientalService.obtenerTramitePorId(db, tramiteId);
            if (!tramite) {
                return res.status(404).json({ success: false, message: 'Trámite no encontrado' });
            }
            if (!String(tramite.oficio || '').trim()) {
                return res.status(400).json({
                    success: false,
                    message: 'El trámite necesita un oficio antes de subir archivos.'
                });
            }
            if (!files.length) {
                return res.status(400).json({ success: false, message: 'No se recibió ningún archivo.' });
            }

            const ambito = String(req.body?.ambito || 'documento');
            let carpetasLista = [];
            try {
                const raw = req.body?.carpetasRelativasJson;
                if (raw) {
                    const parsed = typeof raw === 'string' ? JSON.parse(raw) : raw;
                    if (Array.isArray(parsed)) carpetasLista = parsed;
                }
            } catch (_) { /* ignore */ }

            const usuario = req.user?.usuario || req.user?.email || req.user?.nombre || '';
            const documentos = [];
            const errores = [];

            for (let i = 0; i < files.length; i++) {
                const file = files[i];
                const carpetaRelativa = ambientalTramiteArchivosService.sanitizarCarpetaRelativa(
                    carpetasLista[i] != null ? carpetasLista[i] : ''
                );
                try {
                    const buffer = await fs.promises.readFile(file.path);
                    const doc = await ambientalTramiteArchivosService.subirArchivo(db, tramite, {
                        ambito,
                        buffer,
                        nombreArchivo: file.originalname,
                        mimeType: file.mimetype,
                        carpetaRelativa,
                        usuario
                    });
                    documentos.push(doc);
                } catch (err) {
                    errores.push({
                        nombre: file.originalname || 'archivo',
                        error: err?.message || String(err)
                    });
                }
            }

            const exitosos = documentos.length;
            return res.json({
                success: errores.length === 0,
                partial: errores.length > 0 && exitosos > 0,
                message: errores.length === 0
                    ? `${exitosos} archivo(s) subido(s).`
                    : `${exitosos} de ${exitosos + errores.length} archivo(s) subido(s).`,
                exitosos,
                fallidos: errores.length,
                archivos: documentos,
                errores
            });
        } catch (error) {
            handleError(res, error, 'No se pudieron subir los archivos');
        } finally {
            await limpiarTmpAmbTram(files);
        }
    }
);

