app.post('/api/ambiental/sp-f-28/guardar-drive', requireAdminOrAmbiental, async (req, res) => {
    try {
        const db = await poolAmbientalReady();
        const empresaId = req.body?.empresa_id;
        const tieneEmpresa = empresaId !== undefined && empresaId !== null && empresaId !== '';
        const tramites = Array.isArray(req.body?.tramites) ? req.body.tramites : null;
        const meta = req.body?.meta || null;
        if (meta) {
            if (tieneEmpresa) {
                await ambientalService.guardarMetaSpF28Empresa(db, empresaId, meta);
            } else {
                await ambientalService.guardarMetaSpF28(db, meta);
            }
        }
        if (tramites?.length) {
            await ambientalService.actualizarTramitesLote(db, tramites);
        }
        const payload = tieneEmpresa
            ? await ambientalDriveService.guardarSpF28Empresa(db, empresaId)
            : await ambientalDriveService.guardarSpF28(db);
        const lista = await ambientalService.listarTramites(db, tieneEmpresa ? { empresa_id: empresaId } : {});
        const estadisticas = await ambientalService.estadisticasTramites(db, tieneEmpresa ? empresaId : null);
        const metaSpF28 = tieneEmpresa
            ? await ambientalService.obtenerMetaSpF28Empresa(db, empresaId)
            : await ambientalService.obtenerMetaSpF28(db);
        res.json({
            success: true,
            message: 'SP-F-28 guardado y sincronizado con Drive.',
            ...payload,
            tramites: lista,
            estadisticas,
            metaSpF28
        });
    } catch (error) {
        handleError(res, error, 'No se pudo guardar SP-F-28 en Drive');
    }
});

