function responderErrorRrhhColaboradores(res, error, fallback) {
    const status = Number(error?.statusCode || error?.status || error?.code) || 500;
    if (status >= 400 && status < 500) {
        return res.status(status).json({
            success: false,
            message: error.message || fallback
        });
    }
    return handleError(res, error, fallback);
}

function enviarArchivoRrhhColaborador(res, archivo, { descargar = false } = {}) {
    const nombreSeguro = String(archivo.filename || 'archivo')
        .replace(/[\r\n"\\/:*?<>|]+/g, '_')
        .replace(/[^a-zA-Z0-9._\- \u00C0-\u024F]+/g, '_')
        || 'archivo';
    const disposition = descargar ? 'attachment' : 'inline';
    res.setHeader('Content-Type', archivo.contentType || 'application/octet-stream');
    res.setHeader('Content-Disposition', `${disposition}; filename="${nombreSeguro}"`);
    const isImage = String(archivo.contentType || '').startsWith('image/');
    res.setHeader('Cache-Control', isImage && !descargar ? 'private, max-age=1800' : 'private, max-age=120');
    if (!descargar && (String(archivo.contentType).startsWith('image/') || archivo.contentType === 'application/pdf')) {
        res.removeHeader('X-Frame-Options');
        const frameAncestors = (process.env.CORS_ORIGINS || 'http://localhost:4200,http://localhost:4201')
            .split(',')
            .map((s) => s.trim())
            .filter(Boolean)
            .join(' ');
        res.setHeader('Content-Security-Policy', `frame-ancestors 'self' ${frameAncestors}`);
    }
    return res.send(Buffer.from(archivo.buffer));
}

